MAX_GLOB_RESULTS = 50
LOG_FILE = os.path.join(tempfile.gettempdir(), "supertool-calls.log")
GREP_FILE_INCLUDES = ("*.php", "*.xml", "*.py", "*.js", "*.ts", "*.md")
_GREP_EXTENSIONS_EFFECTIVE: Tuple[str, ...] | None = None

def _match_glob(path: str, pattern: str) -> bool:
    """fnmatch with brace expansion: `*.{a,b,c}` → match if any of `*.a / *.b / *.c`.

    fnmatch.fnmatch doesn't understand `{a,b,c}` alternatives. This helper
    expands them once (one level, no nesting) and tries each alternative.
    Patterns without braces fall through to plain fnmatch unchanged.
    """
    import fnmatch
    if not pattern:
        return True
    if "{" not in pattern or "}" not in pattern:
        return fnmatch.fnmatch(path, pattern)
    # Expand a single brace group `{a,b,c}` into ["a", "b", "c"]. Multiple
    # brace groups in the same pattern aren't supported (not needed by current
    # consumers) — fall through to plain fnmatch in that case.
    open_i = pattern.index("{")
    close_i = pattern.index("}", open_i)
    if pattern.count("{") > 1 or pattern.count("}") > 1:
        return fnmatch.fnmatch(path, pattern)
    prefix = pattern[:open_i]
    suffix = pattern[close_i + 1:]
    alternatives = pattern[open_i + 1:close_i].split(",")
    for alt in alternatives:
        if fnmatch.fnmatch(path, f"{prefix}{alt.strip()}{suffix}"):
            return True
    return False


def _matches_any_glob(path: str, patterns: Any) -> bool:
    """True if `path` matches any glob in `patterns`.

    `patterns` may be a single glob string or a list of globs (skip if any
    matches). Falsy patterns (None, "", []) match nothing. Used by validator
    and formatter dispatch to honor a per-spec `exclude` glob.
    """
    if not patterns:
        return False
    if isinstance(patterns, str):
        patterns = [patterns]
    return any(_match_glob(path, p) for p in patterns if p)


def _expand_braces(pattern: str) -> List[str]:
    """Expand shell-style brace groups `{a,b,c}` into a list of patterns.

    Supports multiple groups (`*.{a,b}.{x,y}` → 4 patterns) and nesting
    (`{a,b{1,2}}` → `[a, b1, b2]`). Patterns without braces return `[pattern]`.
    Unbalanced braces are returned unchanged (treated as a literal).
    """
    if "{" not in pattern:
        return [pattern]
    open_i = pattern.index("{")
    depth = 0
    close_i = -1
    for i in range(open_i, len(pattern)):
        c = pattern[i]
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                close_i = i
                break
    if close_i == -1:
        return [pattern]
    prefix = pattern[:open_i]
    suffix = pattern[close_i + 1:]
    inner = pattern[open_i + 1:close_i]
    parts: List[str] = []
    depth = 0
    last = 0
    for i, c in enumerate(inner):
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
        elif c == "," and depth == 0:
            parts.append(inner[last:i])
            last = i + 1
    parts.append(inner[last:])
    out: List[str] = []
    seen = set()
    for alt in parts:
        for sub in _expand_braces(prefix + alt + suffix):
            if sub not in seen:
                seen.add(sub)
                out.append(sub)
    return out


# Default exclude-paths applied to all traversal ops (glob, grep, tree, map).
# Directories are pruned at the walk boundary — they are never opened. Files
# are dropped from the result, and dropping one *silently* is the thing this
# list must not do — see `_hidden_suffix` and `_is_disclosable_exclusion`.
#
# Three entry shapes, all honoured by `_is_excluded`:
#   "name/"   literal — a DIR or a FILE of that name. A single segment matches
#             at any depth; a multi-segment path is anchored to cwd.
#   "*.pem"   glob — fnmatched against the basename. Needed for shapes that are
#             not a fixed name (`id_rsa*`, `*.pem`).
#   "!name"   negation — un-excludes what it matches and wins over every other
#             entry, whatever the order.
#
# Split in two because the *disclosure count* distinguishes them, not because
# matching does: `_is_excluded` is handed the concatenation and cannot tell
# them apart. Noise is skipped in silence; a credential file is skipped and
# counted (#691).

# Build output, caches and VCS metadata. Deliberately NOT counted: nobody
# searching a repo meant these, they are documented, and a counter that fires
# on them is a number that is never zero — which is noise, not disclosure.
_NOISE_EXCLUDE_PATHS: Tuple[str, ...] = (
    ".git/", "node_modules/", ".svn/", ".hg/", ".idea/", ".vscode/",
    "__pycache__/", ".venv/", "venv/", "dist/", "build/",
    "phpstan-result-cache/", ".phpunit.cache/", ".rector/",
)

_SECRET_EXCLUDE_PATHS: Tuple[str, ...] = (
    # #146 / #691: credential dirs and files, kept out of glob/grep/tree/map so
    # a token cannot land in an LLM context as a side effect of a search nobody
    # aimed at it. #146 added the file entries below and documented that the
    # trailing slash covered files; for two years nothing called `_is_excluded`
    # on a file, so it did not. #691 wired it up.
    #
    # The boundary is deliberately narrow. A file earns a place here only when
    # holding a credential is its entire purpose: an exact name (`.netrc`) or an
    # unambiguous key-file shape (`*.pem`). No name-fragment heuristics —
    # `*secret*`, `*token*`, `*password*` hit source and test files constantly,
    # and a search that silently skips your own code is a worse failure than
    # the one this list exists to prevent.
    #
    # Directories.
    ".max/", ".ssh/", ".aws/", ".gnupg/", ".kube/", ".docker/",
    ".terraform/", ".chef/", ".npm/", "secrets/", "credentials/",
    # Environment files. `.env.*` covers `.local`, `.production`, `.staging`
    # and whatever a project invents next. The negations keep the committed
    # placeholders greppable — people read those to learn which keys exist,
    # and hiding them is the over-broad direction of this same defect.
    ".env/", ".env.*",
    "!.env.example", "!.env.sample", "!.env.template", "!.env.dist",
    "!.env.defaults", "!.env.schema",
    # Tool credential files.
    ".netrc/", "_netrc/", ".npmrc/", ".pypirc/", ".git-credentials/",
    ".pgpass/", ".my.cnf/", ".htpasswd/", ".dockercfg/",
    # Private keys and keystores.
    "id_rsa*", "id_dsa*", "id_ecdsa*", "id_ed25519*",
    "*.pem", "*.key", "*.p12", "*.pfx", "*.jks", "*.keystore", "*.ppk",
    # Supertool's own documented cwd token files (see presets/*/_auth.py). The
    # `.bluesky-handle` and `.hashnode-publication-id` siblings are public
    # identifiers, not credentials, and stay visible.
    ".hashnode-token/", ".devto-token/", ".bluesky-app-password/",
)

# Matching sees one flat list; only the disclosure count reads the split.
_DEFAULT_EXCLUDE_PATHS: Tuple[str, ...] = (
    _NOISE_EXCLUDE_PATHS + _SECRET_EXCLUDE_PATHS
)
_NOISE_EXCLUDE_SET = frozenset(_NOISE_EXCLUDE_PATHS)
WILDCARD_CHARS = re.compile(r"[*?\[]")
# Patterns for lines that are "blank or comment-only" across common languages
_COMPACT_SKIP = re.compile(
    r"^\s*$"           # blank lines
    r"|^\s*//"         # PHP/JS/TS single-line comments
    r"|^\s*#"          # Python/shell comments
    r"|^\s*\*"         # Javadoc/PHPDoc continuation lines
    r"|^\s*/\*"        # block comment open
    r"|^\s*\*/"        # block comment close
    r"|^\s*<!--"       # XML/HTML comment open
    r"|^\s*--!?>"      # XML/HTML comment close (--> and the spec's --!>)
)

# Config file — .supertool.json in project root (or parent dirs)
_CONFIG: Dict[str, Any] | None = None
_CONFIG_CHECKED = False

# Files the loader had to skip, reported once on stderr by main(). A config it
# cannot read is skipped rather than fatal — but skipping in silence means the
# user's ops are simply absent with nothing on screen to connect that to a
# file, so the reason is kept and surfaced (#418).
_CONFIG_WARNINGS: List[str] = []

# Absolute path of the .supertool.json the loader actually used, or None when
# the walk up from cwd found nothing. The loader always knew this and threw it
# away, which left the dispatcher unable to tell "your config does not enable
# that" from "you are not in a project at all" — two different problems for the
# person reading the error (#614).
_CONFIG_PATH: str | None = None

# MCP server specs parsed from _CONFIG["mcp"] — populated by _load_config()
_mcp_specs: Dict[str, dict] = {}

# Supertool install directory (where supertool.py actually lives, following symlinks).
# Normalised to forward slashes so the directory survives `shlex.split(posix=True)`
# which would otherwise eat Windows backslashes as escape sequences when
# `{supertool_dir}` is substituted into validator / formatter / notifier cmd
# templates. Windows accepts forward-slash paths everywhere; POSIX is unaffected.
_INSTALL_DIR = os.path.dirname(os.path.realpath(__file__)).replace(os.sep, "/")


# Shipped presets, indexed op name -> preset name. Populated lazily.
_SHIPPED_PRESET_OPS: Dict[str, str] | None = None

# The same pass's `syntax` strings, op name -> syntax line, for names that
# declare one. Filled by `_shipped_preset_ops()` because it already has the
# parsed JSON open and throwing it away cost a second read of every preset
# (#1524). Absent key means the entry has no `syntax`, which is a real answer.
#
# Not a second cache with its own lifetime: it is cleared and refilled inside
# the `_SHIPPED_PRESET_OPS` rebuild, so it is exactly as fresh as its sibling
# and cannot outlive it. That matters because #1322 is precisely the defect of
# a lazily-built index whose claimed lifetime was not the one it had — and a
# separate dict at module scope, absent from `conftest.RESET_GLOBALS`, would
# survive the per-test reset that returns `_SHIPPED_PRESET_OPS` to None.
_SHIPPED_PRESET_SYNTAX: Dict[str, str] = {}


def _shipped_preset_ops() -> Dict[str, str]:
    """Map every op declared by a shipped preset to the preset that declares it.

    Read from ``presets/*.json`` next to supertool.py, so it describes the
    *installed build* rather than whatever the cwd happens to enable. That is
    what makes it usable as evidence: when this index holds ``gl-mr``, the op
    demonstrably exists in this binary and its absence from the current call is
    a fact about where the caller is standing, not about the tool (#614).

    Deliberately not a registry of every op that exists anywhere. A custom op in
    another project's .supertool.json is genuinely unknowable from here and is
    never guessed at.

    Cached, and only consulted on the unknown-op path and by ``ops`` — a normal
    call never opens these files.
    """
    global _SHIPPED_PRESET_OPS
    if _SHIPPED_PRESET_OPS is not None:
        return _SHIPPED_PRESET_OPS
    index: Dict[str, str] = {}
    _SHIPPED_PRESET_SYNTAX.clear()
    preset_dir = os.path.join(_INSTALL_DIR, "presets")
    try:
        entries = sorted(os.listdir(preset_dir))
    except OSError:
        entries = []
    for fname in entries:
        if not fname.endswith(".json"):
            continue
        try:
            with open(os.path.join(preset_dir, fname), encoding="utf-8") as f:
                data = json.load(f)
        except (json.JSONDecodeError, OSError, UnicodeDecodeError):
            # A preset we cannot read contributes nothing. Same rule as the
            # config loader: an unreadable file is an absence, never a fatal —
            # and an index missing one preset still beats no index at all.
            continue
        if not isinstance(data, dict):
            continue
        preset_ops = {}
        for section in ("ops", "builtin-ops"):
            found = data.get(section)
            if isinstance(found, dict):
                preset_ops.update(found)
        if not preset_ops:
            continue
        for op_name, entry in preset_ops.items():
            # Deliberately NOT filtered against _BUILTIN_OPS. That filter stood
            # in for "a preset must not shadow a built-in", which `dispatch`
            # already guarantees structurally — `_resolve_custom_op` is reached
            # only on the fallthrough, after every built-in branch has
            # declined. Meanwhile it made a built-in documented in a preset
            # (`presets/lsp.json`, #2025) invisible to this index, so the #614
            # hint answered "no such op" for an op this binary dispatches.
            if not isinstance(op_name, str):
                continue
            if op_name in index:
                continue
            index[op_name] = fname[:-5]
            syntax = entry.get("syntax") if isinstance(entry, dict) else None
            if isinstance(syntax, str) and syntax.strip():
                _SHIPPED_PRESET_SYNTAX[op_name] = syntax.strip()
    _SHIPPED_PRESET_OPS = index
    return index


def _registry_syntax(name: str) -> str | None:
    """The op's own documented invocation form, or None when there is not one.

    Three states rather than two, per ``docs/validators.md`` "Declining instead
    of guessing": a syntax line, no registry entry at all (every built-in —
    `registry:paste` says so in as many words), and an entry that declares no
    `syntax` key. The last two both return None, because an empty string would
    render as a syntax line that teaches nothing, which is the shape of a clean
    answer standing in for an absent one.

    The loaded config first, then the shipped presets, because an override in
    `.supertool.json` is the form the caller will actually type here. Only
    consulted on the unknown-op path.
    """
    entry = (_load_config().get("ops") or {}).get(name)
    if isinstance(entry, dict):
        syntax = entry.get("syntax")
        if isinstance(syntax, str) and syntax.strip():
            return syntax.strip()
    _shipped_preset_ops()  # populates _SHIPPED_PRESET_SYNTAX
    return _SHIPPED_PRESET_SYNTAX.get(name)


# Ops that accept a repo target, op name -> how it is named. Populated lazily.
#   "op"      — honours a leading `repo:OWNER/NAME` op (#673)
#   "payload" — takes the target in its own payload instead
_REPO_TARGET_MODES: Dict[str, str] | None = None


def _repo_target_modes() -> Dict[str, str]:
    """Map every op that can be pointed at a repo to how it is pointed there.

    Read from the same shipped ``presets/*.json`` as ``_shipped_preset_ops``,
    for the same reason: it describes the installed build, so it is usable as
    evidence about what this binary can do rather than about what the cwd
    happens to enable.

    An op absent from this map cannot be repo-targeted at all. That absence is
    load-bearing — it is what lets a `repo:` op refuse a call it could only
    have affected half of, instead of being quietly dropped for the other ops.
    """
    global _REPO_TARGET_MODES
    if _REPO_TARGET_MODES is not None:
        return _REPO_TARGET_MODES
    modes: Dict[str, str] = {}
    preset_dir = os.path.join(_INSTALL_DIR, "presets")
    try:
        entries = sorted(os.listdir(preset_dir))
    except OSError:
        entries = []
    for fname in entries:
        if not fname.endswith(".json"):
            continue
        try:
            with open(os.path.join(preset_dir, fname), encoding="utf-8") as f:
                data = json.load(f)
        except (json.JSONDecodeError, OSError, UnicodeDecodeError):
            continue
        if not isinstance(data, dict):
            continue
        preset_ops = data.get("ops")
        if not isinstance(preset_ops, dict):
            continue
        for op_name, op_def in preset_ops.items():
            if not isinstance(op_name, str) or not isinstance(op_def, dict):
                continue
            declared = op_def.get("repo_target")
            if declared is True:
                modes.setdefault(op_name, "op")
            elif isinstance(declared, str) and declared:
                modes.setdefault(op_name, declared)
    _REPO_TARGET_MODES = modes
    return modes


def _repo_target_ops() -> set[str]:
    """Ops that honour a leading ``repo:OWNER/NAME`` directly."""
    return {op for op, mode in _repo_target_modes().items() if mode == "op"}


def _repo_reachable_ops() -> set[str]:
    """Every op a ``repo:`` op may sit beside without refusing the call (#1909).

    Broader than :func:`_repo_target_ops`: a ``payload``-mode op does not read
    ``SUPERTOOL_REPO`` itself, but it is still repo-scoped, so ``repo:`` may
    now supply its payload's own repo field when the payload is silent, and
    the op refuses on its own when the two are both set and disagree — see
    ``presets/_repo_target.py``'s ``resolve_or_conflict``. Only an op absent
    from ``_repo_target_modes()`` altogether has no repo dimension at all,
    and that is the one case still refused outright, by :func:`_repo_refusal`.
    """
    return set(_repo_target_modes())


#: A repo target is a path made of project-path segments and nothing else.
#: Both forges draw from the same character set, so one pattern serves both.
#: This is checked here rather than in the preset because the value is
#: substituted into an API path (`projects/<target>`) and handed to a CLI that
#: attaches a live token — `gl-api` already refuses a path that names a host
#: for that reason (#1035), and a target is one more way to write a path.
# A leading '-' is refused (#1040, #1487): a value validated here can reach a
# shipped op as a POSITIONAL argv element to `gh`/`glab`, in the slot where a
# `-`-prefixed token is read as a flag rather than a value. The callee
# rejecting an unknown flag today is not this validator's guarantee to borrow
# -- a call site moving, or a flag name colliding, is all it takes for that to
# stop holding.
_REPO_SEGMENT_RE = re.compile(r"\A[A-Za-z0-9._][A-Za-z0-9._-]*\Z")


def _repo_target_platform(ops: List[str]) -> str | None:
    """Which forge the repo-targetable ops in *ops* belong to.

    ``"github"``, ``"gitlab"``, ``"mixed"``, ``"unknown"`` (a repo-targetable
    op whose declaring preset is not one of the shipped forges, e.g. a
    project-defined op -- #1487), or None when the call names no targetable
    op at all. Derived from the shipped preset each op is declared in, not
    from its name prefix — the manifest is the registry, and a prefix is a
    convention that can be broken without anything failing.

    The pre-pass needs this because the two forges do not accept the same
    target shape (#676): GitHub is exactly ``OWNER/NAME``, GitLab allows
    ``GROUP/SUBGROUP/PROJECT``. Loosening for both would weaken the GitHub
    check, which is the alternative #676 names and rejects.
    """
    presets = _shipped_preset_ops()
    modes = _repo_target_modes()
    # Every op that has a repo dimension at all, not only the ones that take
    # it from this op. A `payload`-mode write op reconciles `repo:` against
    # its own payload field rather than being refused here (#1909), but it is
    # still evidence of which forge the call is about — reading only
    # `op`-mode ops let a GitLab project path through a GitHub-only call with
    # the shape never mentioned, and the reader sent to the wrong fix.
    found = {presets.get(a.split(":", 1)[0], "")
             for a in ops if a.split(":", 1)[0] in modes}
    if not found:
        return None
    if len(found) > 1:
        return "mixed"
    # `""` here is a project-defined op: repo-targetable (present in `modes`,
    # scanned from the SAME shipped presets/*.json), but not one
    # `_shipped_preset_ops()` has an entry for. That used to collapse into the
    # same `None` this function returns for "no repo-targetable op in this
    # call at all" (`next(iter(found)) or None`) -- one checker, two different
    # causes, one silent answer. Named `"unknown"` instead (#1487): the shape
    # check still falls back to the generic >=2-segments rule either way --
    # there is no way to know which forge's stricter rule a project op wants
    # -- but the "could not classify" state is now its own value rather than
    # an accidental falsy fallthrough.
    sole = next(iter(found))
    return sole if sole else "unknown"


def _repo_shape_error(value: str, platform: str | None) -> str | None:
    """Why *value* is not a usable repo target for *platform*, or None.

    Three states rather than two: a shape this cannot vouch for is refused
    with the reason, never accepted with a shrug and encoded on the way out.
    """
    segments = value.split("/")
    if (len(segments) < 2
            or any(s in (".", "..") or not _REPO_SEGMENT_RE.match(s)
                   for s in segments)):
        return (
            f"repo: expected OWNER/NAME (GitHub) or GROUP[/SUBGROUP]/PROJECT "
            f"(GitLab), got {value!r} — segments may hold only letters, "
            "digits, '.', '_' and '-' "
            "(e.g. repo:Digital-Process-Tools/claude-remember)\n"
        )
    if platform == "github" and len(segments) != 2:
        return (
            f"repo: {value!r} is a GitLab project path, and this call's "
            "repo-targetable ops are GitHub's — gh takes exactly OWNER/NAME "
            "(e.g. repo:Digital-Process-Tools/claude-remember)\n"
        )
    return None


def _repo_refusal(op: str) -> str:
    """Why this call cannot carry a ``repo:`` op alongside *op*.

    Only reached for an op absent from ``_repo_target_modes()`` altogether —
    no repo dimension at all. A ``payload``-mode op used to be refused here
    too, on the theory that "one place the target comes from" meant one
    *route*; #1909 narrowed that to one *resolved value* — the pre-pass now
    lets ``repo:`` sit beside a payload-mode op, exports it the same as for an
    ``op``-mode read, and the op itself reconciles the two (see
    ``presets/_repo_target.py``'s ``resolve_or_conflict``), refusing on its
    own only when both are set and disagree.
    """
    return (
        f"repo: {op!r} cannot be pointed at a repo, so a repo: op in this call "
        f"would apply to some ops and be silently ignored by this one. Drop "
        f"the repo: op, or give the repo-scoped ops a call of their own.\n"
    )


def _presets_not_loaded_here() -> List[str]:
    """Shipped preset names the active config does not enable, sorted."""
    config = _load_config()
    enabled = {p for p in (config.get("presets") or []) if isinstance(p, str)}
    return [p for p in sorted(set(_shipped_preset_ops().values()))
            if p not in enabled]


#: Line prefixes git writes into a file it could not merge. `|||||||` is the
#: diff3/zdiff3 style's base section and is here for the *line list*, not for
#: detection: every style emits `<<<<<<<` and `>>>>>>>`, so the conflict is
#: found either way. What it buys is that the list of lines to go and fix is
#: complete — one missing entry sends the reader back to the file.
_CONFLICT_MARKER_PREFIXES = ("<<<<<<<", "|||||||", "=======", ">>>>>>>")


def _skipped_config() -> Optional[Tuple[str, str]]:
    """(path, why) for a `.supertool.json` that is present and was not used.

    `_load_config` walks up from the cwd and *skips* any config it cannot
    parse, so when nothing above parses either, `_CONFIG_PATH` stays None. Both
    renders below then said "No .supertool.json was found" — one line under a
    stderr warning naming the file the same run had just skipped. Two lines of
    one render disagreeing about whether the config exists, and a reader who
    sees only the ERROR goes looking for a missing file that is present
    (#1162).

    The conflicted case is called out by name because it is circular: git
    writes markers into the file, the file stops parsing, and the ops that
    disappear are `git-conflicts`, `git-resolve` and `git-status` — precisely
    the ones for the situation that removed them. Naming the marker lines is
    the one fact `git-conflicts` would have supplied, from the code that can
    still supply it.

    Re-derived from disk rather than parsed back out of `_CONFIG_WARNINGS`:
    the warning is a formatted sentence, not a record, and this way the note
    describes the file as it is at message time and adds no module state.

    Returns None when there genuinely is no config — inventing a presence is
    the same defect mirrored.

    **Uncached, and repeated per unresolved op.** `_load_config` is guarded by
    `_CONFIG_CHECKED` and this is not, so `dispatch` calling
    `_unknown_op_message` once per unresolved op — and `batch` recursing per
    sub-op — means N walks for N unresolvable shipped-preset names in one call,
    where before there was a static string. That is a deliberate trade, not an
    oversight:

    * The walk cannot start unless `_CONFIG_PATH` is falsy, so every call from
      inside a project returns above on a cached `_load_config`. The cost is
      confined to an already-erroring path in a tree with no usable config, and
      `test_no_walk_happens_when_a_config_actually_loaded` is what keeps it
      there.
    * Caching it would need invalidating on `cwd:`, which retargets the working
      directory mid-call and has no hook to hang that on. A cached answer read
      after a chdir is a claim about the wrong tree — #678's shape, and a worse
      defect than the walk it saves.
    * The walk is bounded by the parent-chain depth (an `isfile` per level) and
      reads one file at most, at the moment the process is about to print an
      error and stop.

    If the repetition ever matters, the fix is to make `_unknown_op_message`
    take the note as an argument and have `dispatch` derive it once — not to
    cache this.

    The load is forced here rather than assumed of the caller. `_CONFIG_PATH`
    is None both when no config loaded *and* when none has been attempted yet,
    and `_unknown_op_message` reads it without triggering one — in a dispatch
    the config is always loaded first, by `_resolve_custom_op`, but a direct
    call is not a dispatch. Without this, a perfectly good `.supertool.json`
    was reported as "found and could not be loaded": the absence-produced-by-
    the-tool defect, inside the fix for it.
    """
    _load_config()
    if _CONFIG_PATH:
        return None
    d = os.path.abspath(os.getcwd())
    while True:
        candidate = os.path.join(d, ".supertool.json")
        if not os.path.isfile(candidate):
            # The name exists and is not a regular file. `_load_config` gates
            # on `isfile` too, so it walks straight past — the right behaviour
            # for a loader and the wrong sentence for a reader: "no
            # .supertool.json was found" about a name sitting in the cwd is
            # this issue's own defect, one `stat` over. `lexists` rather than
            # `exists`, so a dangling symlink is reported instead of resolving
            # to nothing and reading as absent.
            if os.path.isdir(candidate):
                return (candidate, "is a directory, not a file")
            if os.path.lexists(candidate):
                return (candidate, "is not a regular file")
        else:
            try:
                # errors="replace" on purpose: a config that is not UTF-8 is
                # one more way to be unusable, and raising here would take
                # down the message written to explain the failure.
                with open(candidate, encoding="utf-8", errors="replace") as f:
                    text = f.read()
            except OSError as exc:
                return (candidate,
                        f"could not be read ({exc.__class__.__name__})")
            marked = [n for n, line in enumerate(text.splitlines(), 1)
                      if line.startswith(_CONFLICT_MARKER_PREFIXES)]
            if marked:
                where = ", ".join(str(n) for n in marked[:8])
                more = "" if len(marked) <= 8 else f", +{len(marked) - 8} more"
                return (candidate,
                        f"holds git conflict markers (lines {where}{more}), "
                        f"so it does not parse")
            try:
                json.loads(text)
            except ValueError as exc:
                return (candidate, f"does not parse ({exc})")
            # Parsed on a second look, and the reason is deliberately NOT
            # named. Two different histories land here: the loader failed
            # downstream of the parse (a preset file, the mcp block), or its
            # strict-UTF-8 read raised `UnicodeDecodeError` on bytes this
            # re-read replaced. Naming either one would be a guess, and the
            # displayed string is the only claim that holds for both.
            return (candidate, "was found and could not be loaded")
        parent = os.path.dirname(d)
        if parent == d:
            return None
        d = parent


def _preset_disclosure() -> str:
    """One line naming the presets that are not loaded here — never their ops.

    ``ops`` from a non-project directory listed the file ops and stopped, and a
    reader takes that as the tool's whole capability (#614 — its filer did).
    Enumerating the hidden ops would roughly double the listing and get eaten
    from the tail by the SessionStart cap, so this names presets and a count and
    leaves ``cwd:`` as the way through. Empty string when nothing is hidden: the
    absence of the line is itself the signal that the listing is complete.
    """
    missing = _presets_not_loaded_here()
    if not missing:
        return ""
    missing_set = set(missing)
    n_ops = sum(1 for p in _shipped_preset_ops().values() if p in missing_set)
    names = ", ".join(missing)
    if _CONFIG_PATH:
        return (f"> {len(missing)} shipped presets ({names}) — {n_ops} ops — are not "
                f"loaded here: {_CONFIG_PATH} does not list them under "
                f'"presets". Add one there, or make the first op '
                f"'cwd:<project-path>'.")
    skipped = _skipped_config()
    if skipped:
        # Found and unusable is not absent (#1162). Naming `cwd:` here would
        # be worse than saying nothing: the config that is broken is the one
        # in the tree the caller is standing in.
        path, why = skipped
        return (f"> Built-in ops only. {path} {why}, so {len(missing)} shipped "
                f"presets ({names}) — {n_ops} ops — are not loaded here. Repair "
                f"that file and they come back.")
    return (f"> Built-in ops only. No .supertool.json was found from {os.getcwd()}, "
            f"so {len(missing)} shipped presets ({names}) — {n_ops} ops — are not "
            f"loaded here. Run from a project that enables them, or make the first "
            f"op 'cwd:<project-path>'.")


def _find_preset_file(name: str, project_dir: str) -> str | None:
    """Find a preset JSON file by name, checking three locations in order.

    Resolution order:
    1. {project_dir}/presets/{name}.json   — project-level
    2. ~/.config/supertool/presets/{name}.json — user-level
    3. {supertool install dir}/presets/{name}.json — shipped
    """
    candidates = [
        os.path.join(project_dir, "presets", f"{name}.json"),
        os.path.join(os.path.expanduser("~"), ".config", "supertool", "presets", f"{name}.json"),
        os.path.join(_INSTALL_DIR, "presets", f"{name}.json"),
    ]
    for path in candidates:
        if os.path.isfile(path):
            return path
    return None


_PLACEHOLDER_RE = re.compile(r"\{([a-z_]+)\}")


def _substitute_placeholders(template: str, values: Dict[str, str]) -> str:
    """Substitute {name} placeholders in a single left-to-right pass.

    Text inserted by a substitution is never rescanned, so an argument VALUE
    that happens to contain a placeholder token stays literal. Chained
    str.replace calls did rescan, which let a value expand a later
    placeholder inside itself and break the command's shell quoting.

    Unknown names are left untouched (e.g. {path}, resolved earlier by
    _resolve_preset_cmd).
    """
    return _PLACEHOLDER_RE.sub(
        lambda m: values[m.group(1)] if m.group(1) in values else m.group(0),
        template,
    )


def _resolve_preset_cmd(cmd: str, preset_dir: str) -> str:
    """Replace {path} placeholder with the preset's directory (trailing slash).

    Example: 'python3 {path}gitlab/issue.py {arg}'
    becomes: 'python3 /home/user/.local/supertool/presets/gitlab/issue.py {arg}'

    Normalises preset_dir to forward slashes — the cmd template flows through
    `shlex.split(posix=True)` which would otherwise eat Windows backslashes
    as escape sequences. Forward slashes work on every platform.
    """
    path_prefix = preset_dir.replace(os.sep, "/").rstrip("/") + "/"
    return cmd.replace("{path}", path_prefix)


#: Distinguishes "the project supplied no override" from "it supplied None".
_UNSET = object()


def _merge_op_def(base: Any, override: Any) -> Any:
    """The one rule for a project op-def landing on a preset op-def (#1356).

    Dict over dict merges key-by-key, so a project override can add or replace
    individual keys without restating the preset's `cmd`. Anything else
    replaces wholesale.

    Extracted from `_merge_presets` because the rule had escaped it. Three ops
    in this repo's own `.supertool.json` — `dashboard`, `radar`, `git-diff` —
    are partial overrides carrying one config key and no `cmd` or `syntax` at
    all, and a hand-rolled walk writing the obvious `ops[name] = entry`
    replaced the shipped definition with the stub. The op count is unchanged
    either way, so nothing looks wrong; the entry simply stops matching every
    filter downstream. #1350's containment audit lost `git-diff` — the op it
    was written about — out of its own population and printed a pass.

    So: one function, and `_op_registry` renders what it produced rather than
    recomputing it.
    """
    if _merges_key_by_key(base, override):
        merged = dict(base)
        merged.update(override)
        return merged
    return override


def _merges_key_by_key(base: Any, override: Any) -> bool:
    """Will this override merge into the base, or replace it outright?

    A predicate rather than an inlined `isinstance` pair because two callers
    ask it and they must never disagree: `_merge_op_def` decides what lands in
    the registry, `_record_op_sources` decides what the registry says happened.
    The first version asked only whether the *override* was a dict, so a dict
    landing on a preset that ships its op as a bare cmd string was recorded as
    a key-by-key merge — attributing surviving keys to a definition that had
    been replaced entirely.
    """
    return isinstance(base, dict) and isinstance(override, dict)


def _record_op_sources(config: Dict[str, Any],
                       op_presets: Dict[str, str],
                       preset_bases: Dict[str, Any],
                       project_ops: Dict[str, Any],
                       merged_ops: Dict[str, Any]) -> None:
    """Stamp where each merged op came from, for `_op_registry` to read.

    Written by the loader during the one walk that does the merging, never
    recomputed: a second walk is a second copy of the rule, which is the whole
    defect (#1356). Its presence is also the signal that provenance is *known* —
    a config that never passed through here reports "unknown", not "project".
    """
    sources: Dict[str, Dict[str, Any]] = {}
    for name in merged_ops:
        preset = op_presets.get(name)
        override = project_ops.get(name, _UNSET)
        if override is _UNSET:
            sources[name] = {"preset": preset, "project": False,
                             "overridden": []}
            continue
        if preset is None:
            overridden: Any = []
        elif _merges_key_by_key(preset_bases.get(name), override):
            overridden = sorted(override)
        else:
            # The shipped definition was replaced outright — either side being
            # a non-dict does it — so there is no per-key answer to give.
            # None, never [] — an empty list means "merged, changed nothing",
            # which is a different and true thing about a `{}` override.
            overridden = None
        sources[name] = {"preset": preset, "project": True,
                         "overridden": overridden}
    config["_op_sources"] = sources


#: Keys `_resolve_custom_op`'s launcher never exports as `SUPERTOOL_<KEY>` —
#: its own control fields, not config for the subprocess to read (#692,
#: #1347, #1357, #1672, #1675, #1757). `safety` and `repo_target` join the
#: list for #1757: both are metadata the CORE reads off the merged registry
#: entry to decide how to treat the op before ever spawning it (safety
#: classification; whether a leading `repo:OWNER/NAME` token is honoured) —
#: never something the subprocess itself consults. A tree-wide grep for
#: either env var name (`SUPERTOOL_SAFETY`, `SUPERTOOL_REPO_TARGET`) inside
#: a preset returns zero, the same signature `replaces`/`paths`/`exitStatus`
#: each had before they were added here. Module-level and shared with
#: `_op_config_key_collisions` below so the two can never disagree about
#: which keys actually become an env var: a set redeclared at each site would
#: let one drift and the other not, and the drift would be silent — exactly
#: the defect class this whole file exists to remove.
_OP_CONFIG_RESERVED_KEYS = {
    "cmd", "timeout", "description", "syntax", "example", "status",
    "restartMcp", "replaces", "paths", "exitStatus", "form", "hint",
    "safety", "repo_target",
}

#: Extra config keys whose value is a search path -- one or more directories
#: joined by `os.pathsep` -- resolved against the directory of the
#: `.supertool.json` that declared them, rather than exported verbatim (#2164).
#:
#: `presets/watch/sourcepath.CONFIG_KEY` is the one entry today. Anchoring
#: happens HERE, once, before the value is exported as an env var -- never
#: inside the preset that reads it back, which may be a detached, re-exec'd
#: poller with no reliable notion of "the directory this was typed in" (the
#: CWD argument `sourcepath.resolve()`'s own docstring makes, and still makes,
#: about a relative entry resolved late). The config file does not move, so
#: resolving once here and exporting an absolute path is what the poller
#: inherits and re-derives after any number of re-execs, unchanged.
_RELATIVE_SEARCH_PATH_KEYS = {"watch_sources_path"}


def _anchor_relative_search_path(raw: str, config_path: str) -> str:
    """Resolve each relative entry of a pathsep-joined search path `raw`
    against the REAL directory of `config_path`.

    An already-absolute entry is left exactly as declared, minus surrounding
    whitespace -- this only adds information, never removes it, so a value
    that was already fully usable is what it was before #2164. An entry that
    is empty (an operator's stray separator) is left alone too, for the same
    reason `sourcepath.resolve()` treats it as nothing declared rather than a
    refusal: there is nothing here to anchor.

    Each entry is stripped before its `isabs()` check, matching
    `sourcepath.resolve()`'s own `raw_entry.strip()` -- checking the
    UNSTRIPPED text would call a whitespace-padded absolute entry relative
    and join the anchor directory onto it, producing a path that exists
    nowhere and silently dropping the operator's real directory (review
    finding on #2164's own PR).

    The anchor is `os.path.dirname(os.path.realpath(config_path))`, not a
    plain `os.path.dirname` -- the same normalisation the three other sites
    in this file that derive "the directory containing the declaring config"
    already apply (`_mixed_tree_pair`, and two more; all key off
    `os.path.realpath(_CONFIG_PATH)`). `_CONFIG_PATH` is built from
    `os.path.abspath(os.getcwd())`, not `os.path.realpath`, so a symlink
    component in the path a future caller sets it from would otherwise let
    this function's anchor diverge from every other reader of the same
    config path in this file (review finding on #2164's own PR).
    """
    anchor = os.path.dirname(os.path.realpath(config_path))
    parts = raw.split(os.pathsep)
    resolved = []
    for part in parts:
        entry = part.strip()
        if entry and not os.path.isabs(entry):
            entry = os.path.normpath(os.path.join(anchor, entry))
        resolved.append(entry)
    return os.pathsep.join(resolved)


def _op_config_key_collisions(project_ops: Dict[str, Any]
                              ) -> Dict[str, List[str]]:
    """Env var names two DIFFERENT project-declared ops would both export (#1009).

    `ops.<op>.<key>` reaches that op's own subprocess as `SUPERTOOL_<KEY>` —
    the key alone, never namespaced by the op that declared it. Nothing stops
    a second op from picking the same key name for an unrelated setting, and
    the failure when that happens was silent: neither op errors, neither
    warns, and whichever op runs reads whatever value its OWN project entry
    happens to carry for that key. A live instance shipped as
    `hashnode_react.auto_force` / `hashnode_comment.auto_force`, two separate
    documented opt-ins, both landing on `SUPERTOOL_AUTO_FORCE` (#1009,
    2026-08-13 comment).

    Scoped to `project_ops` — the project's OWN "ops" section in
    `.supertool.json` — never to a preset's shipped defaults. A preset
    deliberately sharing one key across many ops on purpose (`REPO_TARGET`
    across every `gh-*`/`gl-*` op that targets a repo, `DEFAULT_LIMIT` across
    every list op) is the same shape as `SUPERTOOL_GIT_TIMEOUT`: one name,
    several readers, by design. Flagging that would refuse most of this
    repo's own shipped presets for behaviour that has always been correct —
    measured: 10 of the 18 non-reserved keys shipped presets declare are
    already read by 2+ ops on purpose.

    Same name is not enough even within `project_ops` — a first version of
    this checked only that, and `supertool 'ops:roster'` against this very
    repository's own `.supertool.json` immediately named `SUPERTOOL_WATCH_NAME`
    a collision: `channel`, `radar`, `unwatch`, `watch` and `watches` all
    declare `watch_name: "oss-supertool"`, one identifier repeated on purpose
    so the whole `watch` family points at the same channel. Refusing that
    would have broken every `watch` op in this repository's own config the
    moment this landed — exactly the breaking change this fix exists to
    avoid causing. So the signal is not "two ops named it the same"; it is
    "two ops named it the same AND disagree about the value" — the hashnode
    case (`auto_force: true` vs `auto_force: false`) disagrees, `watch_name`
    repeated verbatim does not. Values are compared via `json.dumps` with
    sorted keys so a dict or list config value compares by content, not
    identity; a value that cannot be JSON-encoded compares by `repr` rather
    than silently dropping out of the check.

    Returns `{env_var_name: [op_name, ...]}` for every name where two or more
    ops declare GENUINELY DIFFERING values, each list sorted and
    deduplicated and naming every op that touches the name — including one
    that happens to agree with another, so an operator fixing the disagreement
    sees the whole group rather than only the pair that disagrees. Empty when
    nothing collides, which covers both "only one op uses this key" and
    "several agree on one value".
    """
    by_env: Dict[str, List[Tuple[str, Any]]] = {}
    for op_name, entry in project_ops.items():
        if not isinstance(entry, dict):
            continue
        for key, value in entry.items():
            if not isinstance(key, str) or key in _OP_CONFIG_RESERVED_KEYS:
                continue
            by_env.setdefault(f"SUPERTOOL_{key.upper()}", []).append(
                (op_name, value))
    collisions: Dict[str, List[str]] = {}
    for env, pairs in by_env.items():
        ops_here = sorted({op for op, _ in pairs})
        if len(ops_here) < 2:
            continue
        fingerprints = set()
        for _, value in pairs:
            try:
                fingerprints.add(json.dumps(value, sort_keys=True))
            except TypeError:
                fingerprints.add(repr(value))
        if len(fingerprints) > 1:
            collisions[env] = ops_here
    return collisions


def _merge_presets(config: Dict[str, Any], project_dir: str) -> None:
    """Load and merge preset ops into config. Project ops win on conflict."""
    presets = config.get("presets")
    project_ops = config.get("ops", {})
    if not isinstance(project_ops, dict):
        project_ops = {}
    # Computed here, once, from `project_ops` alone — before any preset is
    # merged in — and stashed on every return path below (#1009). Anything
    # a preset contributes is deliberately out of scope; see the docstring.
    config["_op_config_collisions"] = _op_config_key_collisions(project_ops)
    if presets is not None and not isinstance(presets, list):
        # Declared and unusable is not the same as not declared. Nothing gets
        # merged either way, but here the config asked for ops that are now
        # absent — so the registry must not go on to report a complete set.
        config.setdefault("_preset_warnings", []).append(
            f'"presets" must be a list of preset names, got '
            f"{type(presets).__name__} — no preset ops were merged")
        _record_op_sources(config, {}, {}, project_ops, project_ops)
        return
    if not presets:
        # No presets to merge, so every op is the project's own — provenance
        # is fully known and must be stamped, or `_op_registry` cannot tell
        # this from a config that never reached the loader at all.
        _record_op_sources(config, {}, {}, project_ops, project_ops)
        return

    merged_ops: Dict[str, Any] = {}
    op_presets: Dict[str, str] = {}

    for name in presets:
        if not isinstance(name, str):
            continue
        preset_path = _find_preset_file(name, project_dir)
        if preset_path is None:
            # Store warning in a list so callers can report it
            config.setdefault("_preset_warnings", []).append(
                f"preset {name!r} not found"
            )
            continue
        try:
            with open(preset_path, encoding="utf-8") as f:
                preset_data = json.load(f)
        except (json.JSONDecodeError, OSError, UnicodeDecodeError) as exc:
            # UnicodeDecodeError is a ValueError, not an OSError, so it used to
            # slip this clause entirely: presets/git.json holds — and ✓, which
            # an ASCII locale cannot decode, and supertool died at startup with
            # a traceback over a file we ship (#418). Named rather than widened
            # to Exception — the merge below can raise TypeError or KeyError on
            # a malformed op-def, and that is a bug here that must stay loud.
            config.setdefault("_preset_warnings", []).append(
                f"preset {name!r}: failed to load {preset_path} "
                f"({exc.__class__.__name__}: {exc})"
            )
            continue

        preset_dir = os.path.dirname(preset_path)

        # A preset may also document ops it does NOT define: built-ins, whose
        # code is in this file and whose behaviour no manifest can change
        # (#2025). Those go in the manifest's own `builtin-ops` section and
        # merge into the config's, never into `ops`.
        #
        # The section matters, it is not bookkeeping. Four independent guards
        # sweep `config["ops"]` on the premise that a preset op is one the
        # preset *defines* — every entry resolves to a script (#1269), declares
        # a safety class (#1231), declares a path-containment boundary (#1287,
        # #1350), and is accounted for by the `replaces` census (#1384). A
        # doc-only entry satisfies none of those and must not: its script is
        # this module, its class is `_OP_SAFETY_BUILTIN`, its paths go through
        # the built-in chokepoint. Putting it in `ops` would mean teaching four
        # sweeps an exception apiece; putting it here means none of them ever
        # sees it, and the doc surfaces that read `builtin-ops` — `op_ops`,
        # `_help_entry`, `_configured_op_names`, `_build_at_file_registry` —
        # all reach it with no change at all.
        preset_builtin_docs = preset_data.get("builtin-ops")
        if preset_builtin_docs is not None and not isinstance(
                preset_builtin_docs, dict):
            # The whole `builtin-ops` SECTION being a non-table is the same
            # #2308 defect one level further up than the per-entry check
            # below: a preset manifest declaring `"builtin-ops": "oops"`
            # used to skip this whole branch silently, dropping the section
            # exactly as if the preset had never declared one at all
            # (oss:auditor's re-spawned self-review finding, since neither
            # the per-entry check nor `_preset_warnings` ever saw it).
            config.setdefault("_preset_warnings", []).append(
                f"preset {name!r}: builtin-ops is "
                f"{type(preset_builtin_docs).__name__}, not a table "
                f"— the whole section was dropped"
            )
        if isinstance(preset_builtin_docs, dict):
            merged_builtin_docs = dict(config.get("builtin-ops") or {})
            for doc_name, doc_def in preset_builtin_docs.items():
                if not isinstance(doc_name, str):
                    continue
                # The project's own config wins, by the same rule `ops` uses
                # — and key-for-key, through the same helper, for the same
                # reason: `builtin-ops` entries carry behaviour overrides
                # (`read.max_lines`, `grep.extensions`) as well as prose, so a
                # project setting one key would otherwise delete the preset's
                # whole entry and leave the op undocumented. That is #1356's
                # stub, one section over.
                project_entry = (config.get("builtin-ops") or {}).get(doc_name)
                merged_entry = (
                    _merge_op_def(doc_def, project_entry)
                    if project_entry is not None else doc_def)
                merged_builtin_docs[doc_name] = merged_entry
                if not isinstance(merged_entry, dict):
                    # The same defect `_get_op_int`/`_get_op_bool` fixed at the
                    # reader (#1332/#654) and `registry:OP` fixed at the
                    # disclosure surface (#2079), one layer further upstream:
                    # a `builtin-ops.<op>` entry that is not a table used to be
                    # stored here unchecked, with nothing recorded anywhere.
                    # Every runtime reader then fell back to its own default,
                    # identically to the key never having been set at all —
                    # this repository's own signature defect, an absence the
                    # tool produced read as an absence in the world.
                    config.setdefault("_preset_warnings", []).append(
                        f"preset {name!r}: builtin-ops.{doc_name} is "
                        f"{type(merged_entry).__name__}, not a table "
                        f"— every runtime reader will fall back to its "
                        f"default as if this key were never set"
                    )
                # Stamped by the loader, for the same reason `_op_sources` is:
                # "did this preset contribute anything?" is asked against the
                # provenance, never by re-walking the manifests, and a preset
                # whose whole contribution is documentation contributed. Kept
                # out of `_op_sources` itself, which answers about ops that
                # exist in `config["ops"]` — a row there for a name the
                # registry does not hold would be provenance for nothing.
                doc_sources = config.setdefault("_preset_doc_contributions", {})
                doc_sources.setdefault(name, []).append(doc_name)
            config["builtin-ops"] = merged_builtin_docs

        preset_ops = preset_data.get("ops", {})
        for op_name, op_def in preset_ops.items():
            # Resolve script paths relative to where the preset JSON lives
            if isinstance(op_def, dict) and "cmd" in op_def:
                op_def = dict(op_def)  # don't mutate original
                op_def["cmd"] = _resolve_preset_cmd(op_def["cmd"], preset_dir)
            elif isinstance(op_def, str):
                op_def = _resolve_preset_cmd(op_def, preset_dir)
            merged_ops[op_name] = op_def
            # Last preset wins the definition, so it wins the attribution too.
            # Preset-vs-preset is a wholesale replace, not a key merge.
            op_presets[op_name] = name

    # Project-level ops override preset ops, by the one shared rule. The
    # pre-override state is kept: whether an override merged or replaced is a
    # fact about the base it landed on, and after the loop that base is gone.
    preset_bases = dict(merged_ops)
    for op_name, op_def in project_ops.items():
        merged_ops[op_name] = _merge_op_def(merged_ops.get(op_name), op_def)
    config["ops"] = merged_ops
    _record_op_sources(config, op_presets, preset_bases, project_ops,
                       merged_ops)


def _config_trust_violation(candidate: str) -> Optional[str]:
    """Refuse a config file that is not the caller's own to control (#695).

    `.supertool.json` is executable data — `ops.<name>.cmd` runs a shell
    command the moment that op is invoked (see the "no execution at load
    time" contract in ``test_security_config.py``, which is the *only*
    thing that contract ever promised: it never claimed the file itself is
    safe to be writable by anyone else). A group- or world-writable config,
    or one owned by a different user than the one running supertool, can be
    rewritten by another local account between the moment it was reviewed
    and the moment an op it declares actually runs — the exact TOCTOU shape
    `ssh` refuses on `~/.ssh/config` and git refuses (via `safe.directory`)
    on a repo owned by someone else.

    POSIX-only: `st_uid` and the group/other write bits are meaningless on
    Windows (`os.stat().st_uid` is always 0 there), so this returns `None`
    — trusted — unconditionally on that platform rather than fabricate a
    check with no signal behind it.

    Returns the reason to skip, or `None` when the file is safe to read.
    Root (`st_uid` of the file owned by root, or the caller running as
    root) is treated as trusted, matching git's own `safe.directory` carve
    out for a root-owned tree.
    """
    if os.name != "posix":
        return None
    try:
        st = os.stat(candidate)
    except OSError as exc:
        return f"cannot stat: {exc}"
    caller_uid = os.getuid()
    if st.st_uid not in (caller_uid, 0) and caller_uid != 0:
        return (
            f"not owned by the current user (owner uid {st.st_uid}, "
            f"running as uid {caller_uid})"
        )
    if st.st_mode & (stat.S_IWGRP | stat.S_IWOTH):
        return f"group/world-writable (mode {stat.S_IMODE(st.st_mode):o})"
    return None


def _load_config() -> Dict[str, Any]:
    """Load .supertool.json from cwd or parents, stopping at the nearest
    ``.git`` ancestor. Cached.

    After loading, merges any preset ops declared in "presets" key and
    parses the optional "mcp" block into the module-level _mcp_specs dict.

    Trust boundary (#695): a config in this project is exactly as trusted
    as the project's own code — cloning a hostile repo and running any op
    already executes its validators, ops and presets, so a project-local
    `.supertool.json` adds no new attack surface *for the project that owns
    it*. What it must not do is reach OUTSIDE that project: before #695 the
    walk went all the way to `/` with no ownership check, so opening a
    subdirectory of an otherwise-untrusted tree (a shared `/tmp` extraction,
    a CI checkout dir with a stray ancestor config) could silently pick up
    a config that governs nothing the user actually opened. Two independent
    limits now apply, either one enough to stop a candidate that only the
    first check used to gate:

    * the walk itself stops once it reaches a directory containing `.git`
      — the repo root — rather than continuing past it; a caller not
      inside a git repo at all keeps the old to-`/` behaviour, since there
      is no repo boundary to stop at;
    * each candidate is checked with `_config_trust_violation` before it is
      opened — a file that is group/world-writable, or not owned by the
      caller (or root), is skipped exactly like a malformed one, with the
      reason recorded in `_CONFIG_WARNINGS` rather than silently ignored.
    """
    global _CONFIG, _CONFIG_CHECKED, _CONFIG_PATH, _mcp_specs
    if _CONFIG_CHECKED:
        return _CONFIG or {}
    _CONFIG_CHECKED = True
    d = os.path.abspath(os.getcwd())
    project_dir = d
    while True:
        candidate = os.path.join(d, ".supertool.json")
        if os.path.isfile(candidate):
            violation = _config_trust_violation(candidate)
            if violation is not None:
                _CONFIG_WARNINGS.append(f"skipped {candidate}: {violation}")
                if os.path.exists(os.path.join(d, ".git")):
                    break
                parent = os.path.dirname(d)
                if parent == d:
                    break
                d = parent
                continue
            try:
                with open(candidate, encoding="utf-8") as f:
                    _CONFIG = json.load(f)
                    # JSON `null` parses to None; bare scalars / lists parse
                    # to non-dict. _merge_presets needs a dict — coerce to
                    # empty to keep the rest of the loader honest.
                    if not isinstance(_CONFIG, dict):
                        # Adjacent to #2308/#2306, same signature defect one
                        # layer higher: this used to coerce to `{}` with
                        # nothing recorded, rendering a `.supertool.json`
                        # that parses but is a JSON array/string/number
                        # byte-identical to no config file existing at all.
                        # `presets/_publish_safety._supertool_config` fixed
                        # the identical shape for its own loader in this
                        # same commit (#2306); this is the sibling fix for
                        # the loader every other op goes through.
                        _CONFIG_WARNINGS.append(
                            f"{candidate} does not hold a JSON object (got "
                            f"{type(_CONFIG).__name__}) — ignoring it"
                        )
                        _CONFIG = {}
                    project_dir = d
                    _CONFIG_PATH = candidate
                    _merge_presets(_CONFIG, project_dir)
                    # Parse MCP server specs from the optional "mcp" block.
                    mcp_block = _CONFIG.get("mcp")
                    if isinstance(mcp_block, dict):
                        for srv_name, spec in mcp_block.items():
                            if isinstance(spec, dict) and "cmd" in spec:
                                _mcp_specs[srv_name] = spec
                    return _CONFIG
            except (json.JSONDecodeError, OSError, UnicodeDecodeError) as exc:
                # Skip and keep walking up, which is what this loop has always
                # done with a config it cannot use — but record why. A config
                # that is not UTF-8 raises UnicodeDecodeError, a ValueError,
                # which escaped the old clause and took startup down for every
                # op including the ones that never needed the config (#418).
                # Not `except Exception`: this try also covers _merge_presets
                # and the mcp block, and a TypeError out of either is a bug
                # that must not be swallowed as "bad config file".
                _CONFIG_WARNINGS.append(
                    f"skipped {candidate}: {exc.__class__.__name__}: {exc}"
                )
        if os.path.exists(os.path.join(d, ".git")):
            break
        parent = os.path.dirname(d)
        if parent == d:
            break
        d = parent
    _CONFIG = {}
    return _CONFIG


_MIXED_TREE_ENV = "SUPERTOOL_ALLOW_MIXED_TREE"


def _mixed_tree_pair() -> Optional[Tuple[str, str]]:
    """(core dir, other checkout) when two supertool trees answer one call (#678).

    `_load_config()` walks up from **cwd**, and `_find_preset_file` looks in
    `{project_dir}/presets/` first. So the config, the preset JSONs and the
    scripts they point at all come from wherever the caller is standing, while
    the core that parsed the ops came from the file that was invoked. Run a
    branch worktree's `supertool.py` from a master checkout and you get branch
    core + master presets in one process, with nothing on the receipt saying so
    — the code under test never executes and the answer still says `PASS`.

    The signal is deliberately narrow: the resolved project root is *itself a
    different supertool checkout*. The cheaper "the invoked supertool.py is not
    under the project root" was considered and rejected — that is the documented
    install (a clone symlinked onto `$PATH`, used from arbitrary project roots),
    so it would fire on essentially every legitimate invocation and teach
    everyone to ignore it. A project root that merely ships its own `presets/`
    is not a mix either: overriding a shipped preset is a documented feature.

    Uncached — two `stat` calls, and a cached verdict is one more thing to go
    stale in a reused daemon process (#680).

    The peer is compared by *directory*, not by file identity. Since #931 the
    invoked entry point is `supertool.py` while this code lives in
    `_supertool.py`, so `realpath(peer) == realpath(__file__)` can never hold
    and the check would report a mix on every single invocation made from
    inside any supertool checkout — including this one's own test suite.
    Same-install and same-directory are the same fact here, and the directory
    is the one that survives the split.
    """
    _load_config()
    if not _CONFIG_PATH:
        return None
    project_dir = os.path.dirname(os.path.realpath(_CONFIG_PATH))
    peer = os.path.join(project_dir, "supertool.py")
    try:
        if not os.path.isfile(peer):
            return None
        if os.path.dirname(os.path.realpath(peer)).replace(os.sep, "/") == _INSTALL_DIR:
            return None
    except OSError:
        return None
    return (_INSTALL_DIR, project_dir)


def _mixed_tree_allowed() -> bool:
    """True when the caller has declared the mix deliberate via env."""
    return (os.environ.get(_MIXED_TREE_ENV) or "").strip().lower() in (
        "1", "true", "yes", "on")


def _mixed_tree_note(pair: Tuple[str, str]) -> str:
    """One line naming both trees — used on stderr and on the stamped receipt."""
    core, other = pair
    return f"mixed supertool trees: core={core}/supertool.py presets={other}"


def _mixed_tree_decline(op: str, pair: Tuple[str, str]) -> str:
    """The third state for an op whose provenance is unknown (#678, #1942).

    Not a finding — nothing was found wrong with the op. An absence: the tool
    cannot say which version would answer, so it says that instead of printing a
    `PASS` indistinguishable from one the invoked build produced. Same contract
    as `docs/validators.md` §"Declining instead of guessing".

    Reused for two different callers: a config/preset op reached through
    `_resolve_custom_op` (which shells out — the wrong tree's *script* would
    have run), and, since #1942, a write-class builtin reached from
    `_dispatch_impl`'s own chokepoint (no subprocess — the wrong tree's
    *validators, formatters and hooks* would have run instead). `op` and
    `pair` say which call and which two trees either way; nothing below
    names which caller it was, on purpose, since the remedy is identical.

    The remedy branches on `op`'s own safety class (#2432). `cwd:{core}` is
    genuinely safe advice for a read-only op -- it only needs `core`'s
    presets/config to answer correctly, and nothing in `core` is touched. It
    is dangerous advice for anything else: `cwd:PATH` really does
    `os.chdir(PATH)` for the rest of the call (mirrors `cd PATH && ...`), so
    a write that follows `cwd:{core}` runs against `core`'s own checked-out
    branch -- not `other`'s -- with no further decline, because the mismatch
    that triggered THIS decline is exactly what `cwd:` just erased. A caller
    who wanted to push a worktree's branch and instead pushed the main
    clone's currently-checked-out branch is that bug, observed (#2432).
    """
    core, other = pair
    if _op_safety_class(op) == "read-only":
        fix = (
            f"Fix: run from {core}, or make the first op 'cwd:{core}'. To mix on "
            f"purpose, set {_MIXED_TREE_ENV}=1 — the receipt then carries the "
            f"pairing instead of a bare PASS.\n"
        )
    else:
        fix = (
            f"Fix: '{op}' is not read-only -- run it from INSIDE {other} with "
            f"'python3 supertool.py {op}...' instead. Do NOT use 'cwd:{core}' "
            f"here: that would silently retarget the write at {core}'s own "
            f"checked-out branch, not {other}'s (#2432). To mix on purpose "
            f"anyway, set {_MIXED_TREE_ENV}=1 — the receipt then carries the "
            f"pairing instead of a bare PASS.\n"
        )
    return (
        f"SKIPPED: '{op}' comes from a different supertool tree than the core "
        f"that is running.\n"
        f"  core:    {core}/supertool.py (the file you invoked)\n"
        f"  presets: {other} (resolved from this cwd — its .supertool.json and "
        f"presets/ would answer)\n"
        f"Declined rather than PASSing for a build the tool cannot name: the "
        f"code you meant to exercise would not have run, and the answer would "
        f"have looked exactly like a correct one (#678).\n"
        + fix
    )


def _is_compact() -> bool:
    """Check if compact mode is enabled in .supertool.json."""
    return bool(_load_config().get("compact", False))


def _notifier_debug_enabled() -> bool:
    """Env SUPERTOOL_NOTIFIER_DEBUG=1 wins over JSON `notifier_debug: true`."""
    env = os.environ.get("SUPERTOOL_NOTIFIER_DEBUG")
    if env is not None:
        return env.strip().lower() in ("1", "true", "yes", "on")
    return bool(_load_config().get("notifier_debug", False))


def _notifier_debug_log_path() -> str:
    """Override via SUPERTOOL_NOTIFIER_DEBUG_LOG; default /tmp/supertool-notifier-debug.log."""
    return os.environ.get("SUPERTOOL_NOTIFIER_DEBUG_LOG") or "/tmp/supertool-notifier-debug.log"


def plain_mode() -> bool:
    """True when ASCII-only output is requested via --plain or SUPERTOOL_PLAIN.

    Hooks, ``grep``, and CI parse op output with no UTF-8 / locale guarantees.
    The ``⚠``/``✓`` glyphs are nice UX for the model but a liability downstream:
    a C/POSIX-locale ``grep`` won't reliably match a multibyte glyph, and a
    cp1252 console crashes on it. Plain mode swaps every glyph for an ASCII
    marker (``[WARN]``/``[OK]``/``[FAIL]``) so machine consumers parse reliably.

    Set by the ``--plain`` CLI flag (which exports ``SUPERTOOL_PLAIN=1`` so it
    reaches preset subprocesses too) or directly via ``SUPERTOOL_PLAIN=1``.
    """
    return os.environ.get("SUPERTOOL_PLAIN", "").strip().lower() in (
        "1", "true", "yes", "on"
    )


# Glyph → ASCII marker map. Keys are the rich-mode glyphs; values the ASCII
# fallback emitted in plain mode. Centralised so every call site routes through
# mark() rather than hard-coding a glyph and a separate plain branch.
_PLAIN_MARKERS = {
    "⚠": "[WARN]",  # ⚠
    "✓": "[OK]",    # ✓
    "✗": "[FAIL]",  # ✗
    "ℹ": "[INFO]",  # ℹ
    "↳": "->",      # ↳ — sub-line continuation
}


def mark(glyph: str) -> str:
    """Return ``glyph`` in rich mode, or its stable ASCII marker in plain mode.

    Unknown glyphs pass through unchanged so callers can't silently emit a
    non-ASCII character that plain mode was supposed to strip.
    """
    if plain_mode():
        return _PLAIN_MARKERS.get(glyph, glyph)
    return glyph


def _reconfigure_stdout_utf8() -> None:
    """Force stdout/stderr to UTF-8 so ops never crash on a non-UTF-8 console.

    Windows defaults stdout to cp1252, which can't encode the glyphs ops print
    and raises ``UnicodeEncodeError`` (returncode 1) — caught in CI on git-diff.
    This is cheap insurance even when plain mode is on (a stray glyph in user
    content shouldn't crash the process). No-op on Pythons / streams without
    ``reconfigure`` (< 3.7 or wrapped streams).
    """
    for stream in (sys.stdout, sys.stderr):
        reconfigure = getattr(stream, "reconfigure", None)
        if reconfigure is None:
            continue
        try:
            reconfigure(encoding="utf-8")
        except (ValueError, OSError):
            pass


# `errors="replace"` (#501) leaves U+FFFD wherever a child process's output was
# not valid UTF-8. Where supertool only *displays* that output, mojibake is the
# right trade against a traceback that lands after half the answer is already
# on screen — that is #498's lesson and it is why the sweep is otherwise
# uniform. Where the decoded text becomes something else, it is not: bytes
# written back into the user's file, or a path handed to the filesystem, turn a
# crash into a wrong answer, which this repository has rated the worse failure
# every time it has come up (#414, #445, #454, #459, #477, #482, #345, #487,
# #263). Those seams call this and name what happened instead of proceeding.
_REPLACEMENT_CHAR = "\ufffd"


def _undecodable_at(text: str) -> int:
    """Offset of the first U+FFFD in ``text``, or ``-1`` when it decoded clean.

    A command whose output genuinely contains U+FFFD is indistinguishable from
    one whose output was mangled, and is refused too. That direction is the
    safe one: the caller declines and says why, rather than writing bytes it
    cannot vouch for.
    """
    return text.find(_REPLACEMENT_CHAR)


def _display_safe(text: str) -> str:
    """``text`` with lone surrogates rendered as U+FFFD — for output only.

    The edit ops read with ``errors="surrogateescape"`` so that bytes which are
    not valid UTF-8 round-trip through ``_atomic_write`` untouched (#1049,
    #1059). That puts lone surrogates in the buffer, and those receipts echo
    the buffer back — context lines, a diff hunk. A lone surrogate cannot be
    encoded to a UTF-8 stream, so the op wrote the right bytes and then died
    with ``UnicodeEncodeError`` on the way to saying so: a traceback, no
    receipt, over a file that did change.

    Display only. The bytes are already on disk and nothing here touches them,
    and mojibake in something only being *shown* is the trade this file makes
    everywhere else (see ``_REPLACEMENT_CHAR``). Ops that turn decoded text
    back into bytes or into a path still refuse instead of guessing.
    """
    try:
        text.encode("utf-8")
        return text
    except UnicodeEncodeError:
        pass
    try:
        return text.encode("utf-8", "surrogateescape").decode("utf-8", "replace")
    except UnicodeEncodeError:
        # A surrogate outside DC80..DCFF never came from a surrogateescape read
        # and has no original byte to go back to. Name it rather than drop it.
        return text.encode("utf-8", "backslashreplace").decode("utf-8")


# The one definition of a line boundary supertool uses, for every op that
# numbers lines (#1060): LF, CR and CRLF — what a caller counting lines in an
# editor, in `wc -l`, or in any line-oriented CLI will have counted.
#
# `str.splitlines()` additionally breaks on the eight characters listed below;
# `bytes.splitlines()` does not. `read` used the bytes version and
# `replace_lines` the str version, so a file holding any of them had two
# numberings: the read showed the target at line N, the write landed on a
# different line, and nothing reported a problem. Two independent splits is how
# that happened, so there is one function and both call sites use it.
_LINE_BREAK_PATTERN = r"\r\n|\r|\n"
_LINE_BREAK_RE_STR = re.compile(_LINE_BREAK_PATTERN)
_LINE_BREAK_RE_BYTES = re.compile(_LINE_BREAK_PATTERN.encode("ascii"))

# The characters `str.splitlines()` treats as boundaries and this definition
# does not. Present in a file, they mean some other tool numbers its lines
# differently from supertool — which is disclosed, not resolved.
# Spelled with `chr()` rather than as literals: four of the eight are invisible
# and two of them (U+2028, U+2029) are line breaks to half the tools that would
# ever display this file, which is the property being described.
_AMBIGUOUS_LINE_BREAKS = tuple(chr(c) for c in (
    0x0B, 0x0C, 0x1C, 0x1D, 0x1E, 0x85, 0x2028, 0x2029))


def _split_lines_keepends(data: Any) -> Any:
    """Split `data` (str or bytes) into lines, keeping the line endings.

    Matches `bytes.splitlines(keepends=True)` for both types — the conservative
    definition above. Returns a list of the same type it was given.

    The bytes branch delegates to that builtin rather than re-implementing it:
    `bytes.splitlines` *is* this definition, it is ~7x faster than the regex on
    a megabyte, and `read` runs it on every call. The two branches are one
    contract with two implementations, which is only safe because
    `test_line_split_helper_is_the_conservative_definition` pins them against
    the same expectation — including the eight characters they must both
    refuse to split on.
    """
    if isinstance(data, bytes):
        return data.splitlines(keepends=True)
    rx = _LINE_BREAK_RE_STR
    out = []
    pos = 0
    for m in rx.finditer(data):
        out.append(data[pos:m.end()])
        pos = m.end()
    if pos < len(data):
        out.append(data[pos:])
    return out


def _split_lines(data: Any) -> Any:
    """`_split_lines_keepends` with the endings stripped."""
    keep = _split_lines_keepends(data)
    if isinstance(data, bytes):
        return [ln.rstrip(b"\r\n") for ln in keep]
    return [ln.rstrip("\r\n") for ln in keep]


def _line_break_ambiguity_note(data: Any) -> str:
    """A line naming the characters in `data` another tool would split on.

    Empty for the overwhelming majority of files. When it is not, the caller
    may be holding a line number counted under the other definition, and saying
    so is the point: the alternative is picking one in silence and letting a
    line-addressed edit land somewhere the reader never saw (#1060).
    """
    if isinstance(data, bytes):
        present = [c for c in _AMBIGUOUS_LINE_BREAKS
                   if c.encode("utf-8") in data]
    else:
        present = [c for c in _AMBIGUOUS_LINE_BREAKS if c in data]
    if not present:
        return ""
    names = ", ".join(f"U+{ord(c):04X}" for c in present)
    return (f"note: contains {names} — supertool numbers lines by LF / CRLF / "
            f"CR only, so a tool that also breaks on these (Python's "
            f"str.splitlines, some editors) numbers this file differently. "
            f"supertool's reads and its line-addressed edits agree with each "
            f"other.\n")


def _notifier_log(msg: str) -> None:
    """Append a timestamped line to the notifier debug log when enabled. Silent otherwise."""
    if not _notifier_debug_enabled():
        return
    try:
        with open(_notifier_debug_log_path(), "a", encoding="utf-8") as f:
            ts = datetime.now().isoformat(timespec="milliseconds")
            f.write(f"[{ts}] {msg}\n")
    except OSError:
        pass


def _parallel_workers() -> int:
    """Max worker count for parallel batched ops. 0 = sequential.

    Env `SUPERTOOL_PARALLEL` wins over JSON. Accepts:
      int N      → up to N workers (0 disables)
      true/false → 4 / 0 (back-compat with bool config)
    Default: 0 (off).
    """
    env = os.environ.get("SUPERTOOL_PARALLEL")
    raw: object = env if env is not None else _load_config().get("parallel", 0)
    if isinstance(raw, bool):
        return 4 if raw else 0
    if isinstance(raw, int):
        return max(0, raw)
    if isinstance(raw, str):
        s = raw.strip().lower()
        if s in ("true", "yes", "on"):
            return 4
        if s in ("false", "no", "off", ""):
            return 0
        # `SUPERTOOL_PARALLEL=x` used to return 0 — indistinguishable from not
        # setting it at all, so a caller who asked for parallelism silently got
        # none. `=-4` did the same through `max(0, ...)`. Both now say so (#654).
        # Only an *env* value is reported: the int branch above is reachable only
        # from JSON config, which is not what this message would be naming.
        try:
            n = int(s)
        except ValueError:
            if env is not None:
                _env_notice(f"note: SUPERTOOL_PARALLEL={raw!r} is not a whole number "
                            f"or true/false - ignoring it and using 0 (sequential).")
            return 0
        if n < 0:
            if env is not None:
                _env_notice(f"note: SUPERTOOL_PARALLEL={raw!r} is below the minimum of 0 "
                            f"- ignoring it and using 0 (sequential).")
            return 0
        return n
    return 0


#: Messages already emitted this process — see `presets/_env.py`. `_get_op_int`
#: is consulted several times for a single `read`, so without this one bad
#: `SUPERTOOL_READ_MAX_LINES` would print the same line six times above the
#: output it is warning about.
_ENV_ANNOUNCED: "set[str]" = set()


def _env_notice(text: str) -> None:
    """One line, on stdout, flushed, at most once per distinct message.

    Not stderr: `_run_custom_op` returns a successful subprocess's stdout and
    drops its stderr, and falling back to a default *is* success — so a notice
    on stderr is a notice nobody receives (#654).
    """
    if text in _ENV_ANNOUNCED:
        return
    _ENV_ANNOUNCED.add(text)
    print(text)
    sys.stdout.flush()


def _env_int(name: str, default: int, *, minimum: "Optional[int]" = None) -> int:
    """Read `name` as an int, or say why it could not be and what is in force.

    Deliberately duplicated from `presets/_env.py` rather than imported.
    `supertool.py` is a single self-contained file — importing a preset helper
    would make core dispatch fail wherever `presets/` was not shipped alongside,
    which is a larger blast radius than the fifteen lines it saves. The two
    copies are kept in step by `tests/test_env_knob_parsing_654.py`, which
    asserts the same contract against both.

    Unset is silent. Set-but-unusable is announced and falls back to `default`.
    `minimum` is a validated floor, not a clamp — see `presets/_env.py` for why
    a negative is refused rather than quietly rounded up.
    """
    raw = os.environ.get(name)
    if raw is None:
        return default
    try:
        value = int(raw)
    except (TypeError, ValueError):
        _env_notice(f"note: {name}={raw!r} is not a whole number "
                    f"- ignoring it and using {default}.")
        return default
    if minimum is not None and value < minimum:
        _env_notice(f"note: {name}={raw!r} is below the minimum of {minimum} "
                    f"- ignoring it and using {default}.")
        return default
    return value


def _env_float(name: str, default: float, *, minimum: "Optional[float]" = None) -> float:
    """`_env_int` for the knobs measured in seconds. Same contract."""
    raw = os.environ.get(name)
    if raw is None:
        return default
    try:
        value = float(raw)
    except (TypeError, ValueError):
        _env_notice(f"note: {name}={raw!r} is not a number "
                    f"- ignoring it and using {default}.")
        return default
    if value != value:  # NaN is below every bound and equal to none, including itself
        _env_notice(f"note: {name}={raw!r} is not a usable number "
                    f"- ignoring it and using {default}.")
        return default
    if minimum is not None and value < minimum:
        _env_notice(f"note: {name}={raw!r} is below the minimum of {minimum} "
                    f"- ignoring it and using {default}.")
        return default
    return value


def _get_op_int(op_name: str, key: str, default: int) -> int:
    """Read an integer setting from builtin-ops.<op_name>.<key>, with fallback.

    Env var SUPERTOOL_<OP>_<KEY> takes precedence over JSON config.
    Example: SUPERTOOL_READ_ABSTRACT_THRESHOLD_BYTES=12000

    The env override used to fail closed in silence: a non-numeric or
    non-positive `SUPERTOOL_READ_MAX_LINES` fell through to config and read
    exactly like no override at all, so a caller who had set a cap could not
    tell it had been discarded (#654). It now names the variable, the value, and
    the limit actually in force — resolved first, so the number printed is the
    one that will be used rather than a guess at it.

    The *config* side did the same thing and said nothing at all, for another
    thirty-odd releases (#1332). A `builtin-ops.<op>.<key>` that is not a
    positive whole number is still refused — a `"max_lines": 0` honoured as
    "return no lines" would be a silent empty read, which is worse than the
    misconfiguration — but it is now announced through the same notice. A
    switch belongs on `_get_op_bool`, where `0` means off, not here.
    """
    env_key = f"SUPERTOOL_{op_name.upper()}_{key.upper()}"
    env_val = os.environ.get(env_key)
    cfg = _load_config()
    op_cfg = cfg.get("builtin-ops", {}).get(op_name, {})
    # A `builtin-ops.<op>` entry that is not a table is `_merge_presets`'s
    # own #2308 finding -- it now records a `_preset_warnings` entry naming
    # exactly this shape, but the unconditional `.get(key)` this guard
    # replaces crashed with `AttributeError` on the string/list/etc it
    # merged in unchecked, which is worse than the "fell back to its
    # default" this function's own docstring already promised (caught in
    # self-review, both spawned reviewers independently found the same
    # crash; `_get_op_bool` right below already carried this same guard).
    val = op_cfg.get(key) if isinstance(op_cfg, dict) else None
    fallback = default
    if val is not None:
        # `isinstance(True, int)` is True, so a JSON `true` used to read as the
        # threshold 1 — a one-line `read`, which is not what anyone writing it
        # meant. And a configured `0` was indistinguishable from an absent key,
        # so the helper's own default won in silence (#1332).
        #
        # It still wins: honouring `"max_lines": 0` would turn a loud
        # misconfiguration into a silent empty read, which is the worse of the
        # two failures. What changed is that the substitution is now SAID. The
        # helper already named a bad env value and said nothing about a bad
        # config one; a caller who wrote a deliberate `0` in `.supertool.json`
        # could not tell from any output that it had been discarded.
        #
        # A switch does not belong here at all — `_get_op_bool` is the helper
        # where `0` means off.
        if isinstance(val, int) and not isinstance(val, bool) and val > 0:
            fallback = val
        else:
            _env_notice(
                f"note: builtin-ops.{op_name}.{key}={val!r} is not a positive "
                f"whole number - ignoring it and using {default}. "
                f"({op_name}.{key} is a threshold; 0 is not an off switch.)")
    if env_val:
        try:
            n = int(env_val)
        except ValueError:
            _env_notice(f"note: {env_key}={env_val!r} is not a whole number "
                        f"- ignoring it and using {fallback}.")
            return fallback
        if n > 0:
            return n
        _env_notice(f"note: {env_key}={env_val!r} is below the minimum of 1 "
                    f"- ignoring it and using {fallback}.")
    return fallback


#: The spellings a hand-written `.supertool.json` or an env var may use for a
#: switch. `_get_op_int` accepts neither, which is the whole of #1332.
_BOOL_TRUE = ("1", "true", "yes", "on")
_BOOL_FALSE = ("0", "false", "no", "off")


def _coerce_bool(raw: Any) -> "Optional[bool]":
    """`raw` as a bool, or None when it is not a boolean value at all.

    None is the third state: "this was set, and it is not readable as on or
    off" is different from "this was not set", and only the caller knows which
    default that falls back to.
    """
    if isinstance(raw, bool):
        return raw
    if isinstance(raw, int):
        return raw != 0
    if isinstance(raw, str):
        s = raw.strip().lower()
        if s in _BOOL_TRUE:
            return True
        if s in _BOOL_FALSE:
            return False
    return None


def _get_op_bool(op_name: str, key: str, default: bool) -> bool:
    """Read a switch from builtin-ops.<op_name>.<key>. `0` means off.

    The sibling of `_get_op_int`, and the reason it exists: that helper is a
    positive-threshold reader (`val if isinstance(val, int) and val > 0`), so a
    configured `0` reads as an absent key and the default wins. For `max_lines`
    or `count_ceiling` that is right — a zero there is meaningless. For a flag
    whose default is ON it makes the documented off-switch inert, which is how
    `read.elide: 0` shipped into three documentation sites and did nothing
    (#1332).

    Env `SUPERTOOL_<OP>_<KEY>` takes precedence, same as `_get_op_int`. A value
    that is set but unreadable is announced with the state actually in force,
    rather than silently becoming the default.
    """
    env_key = f"SUPERTOOL_{op_name.upper()}_{key.upper()}"
    env_val = os.environ.get(env_key)
    cfg = _load_config()
    op_cfg = cfg.get("builtin-ops", {}).get(op_name, {})
    val = op_cfg.get(key) if isinstance(op_cfg, dict) else None
    fallback = default
    if val is not None:
        coerced = _coerce_bool(val)
        if coerced is None:
            _env_notice(f"note: builtin-ops.{op_name}.{key}={val!r} is not a "
                        f"true/false value - ignoring it and using {default}.")
        else:
            fallback = coerced
    if env_val:
        coerced = _coerce_bool(env_val)
        if coerced is None:
            _env_notice(f"note: {env_key}={env_val!r} is not a true/false value "
                        f"- ignoring it and using {fallback}.")
        else:
            return coerced
    return fallback


def _grep_file_includes() -> Tuple[str, ...] | None:
    """Return effective grep file extensions. Cached.

    Reads builtin-ops.grep.extensions from .supertool.json.
    - No config / empty list → None (search all files)
    - Config with extensions → only those patterns
    """
    global _GREP_EXTENSIONS_EFFECTIVE
    if _GREP_EXTENSIONS_EFFECTIVE is not None:
        return _GREP_EXTENSIONS_EFFECTIVE if _GREP_EXTENSIONS_EFFECTIVE != ("*",) else None
    cfg = _load_config()
    builtin_ops = cfg.get("builtin-ops", {})
    op_cfg = builtin_ops.get("grep", {})
    # Same #2308 guard as `_get_op_int` just above, and for the identical
    # reason: a `builtin-ops.grep` entry that is not a table used to crash
    # `.get("extensions", ...)` with `AttributeError` rather than fall back.
    exts = op_cfg.get("extensions", []) if isinstance(op_cfg, dict) else []
    if exts and isinstance(exts, list):
        valid = tuple(sorted(e for e in exts if isinstance(e, str) and e.startswith("*.")))
        if valid:
            _GREP_EXTENSIONS_EFFECTIVE = valid
            return valid
    # Default: search all files
    _GREP_EXTENSIONS_EFFECTIVE = ("*",)  # sentinel for "no filter"
    return None


def _get_exclude_paths(op_name: str, no_exclude: bool = False) -> Tuple[str, ...]:
    """Return the effective set of exclude-path prefixes for a traversal op.

    Merges _DEFAULT_EXCLUDE_PATHS with any project-level exclude-paths defined
    under ops.<op_name>.exclude-paths in .supertool.json (additive union).
    Returns an empty tuple when no_exclude=True (per-call escape hatch).
    """
    if no_exclude:
        return ()
    defaults = set(_DEFAULT_EXCLUDE_PATHS)
    cfg = _load_config()
    project_paths = cfg.get("ops", {}).get(op_name, {})
    if isinstance(project_paths, dict):
        extra = project_paths.get("exclude-paths", [])
        if isinstance(extra, list):
            for p in extra:
                if isinstance(p, str) and p:
                    defaults.add(_normalise_exclude_entry(p))
    return tuple(sorted(defaults))


def _normalise_exclude_entry(entry: str) -> str:
    """Normalise one `exclude-paths` entry to the shape `_is_excluded` expects.

    A literal gets a trailing slash so it prefix-matches. A glob and a negation
    are returned untouched: appending `/` to `*.key` produced `*.key/`, which
    fnmatches nothing and no longer looks like a glob either — so a wildcard in
    a project config was a silent no-op, failing in exactly the direction this
    setting exists to prevent (#691).
    """
    if entry.startswith("!") or WILDCARD_CHARS.search(entry):
        return entry
    return entry if entry.endswith("/") else entry + "/"


def _is_excluded(rel_path: str, exclude_paths: Tuple[str, ...]) -> bool:
    """Return True if rel_path matches any of the exclude entries.

    Answers for **files as well as directories**. Callers that walk must ask
    about both: pruning `dirs[:]` alone is how `.env/` sat on the default list
    from #146 to #691 while `grep` printed the contents of every `.env` in the
    tree. There is nothing wrong with the matching here — it was simply never
    asked about a file.

    Four entry shapes (`.gitignore` semantics):
      1. **Prefix match** — `rel_path` literally starts with the entry (catches
         a `node_modules/` at the project root).
      2. **Component match** — a single-segment entry (`__pycache__/`, `.git/`)
         matches that name appearing ANYWHERE in the path (catches nested
         `presets/devto/__pycache__/foo.pyc`). The trailing `/` is not a
         directory assertion: `rel_path` gets one appended before comparison,
         so `.env/` matches a FILE named `.env` and a DIR named `.env/` alike.
      3. **Glob** — an entry containing `*`, `?` or `[` is fnmatched against the
         basename and against the whole relative path (`*.pem`, `id_rsa*`).
      4. **Negation** — an entry starting with `!` un-excludes what it matches
         and wins over every other entry regardless of order, so `.env.*` can
         be listed without hiding the committed `.env.example`.

    Multi-segment prefixes (`Dvsi/dvsi-private/libs/`) keep prefix-only
    semantics — anchoring to repo root is the whole point of them.

    rel_path should be relative to cwd and use os.sep. Comparison normalises
    separators and strips a leading './'.
    """
    if not exclude_paths:
        return False
    import fnmatch
    # Normalise to forward-slashes for consistent prefix matching
    normalised = rel_path.replace(os.sep, "/")
    # Strip leading "./" produced by os.path.join(".", name) or relpath at cwd
    if normalised.startswith("./"):
        normalised = normalised[2:]
    bare_path = normalised.rstrip("/")
    if not normalised.endswith("/"):
        normalised += "/"
    basename = bare_path.rsplit("/", 1)[-1]
    # Component set for the "matches anywhere" check (skip empties).
    components = {c for c in bare_path.split("/") if c}

    def _glob_hit(pattern: str) -> bool:
        return (fnmatch.fnmatch(basename, pattern)
                or fnmatch.fnmatch(bare_path, pattern))

    # Negations first, and they are final — an entry cannot be re-excluded by a
    # later pattern, so the answer never depends on tuple order (the defaults
    # are `sorted()` before they get here).
    for entry in exclude_paths:
        if not entry.startswith("!"):
            continue
        pattern = entry[1:].rstrip("/")
        if not pattern:
            continue
        if WILDCARD_CHARS.search(pattern):
            if _glob_hit(pattern):
                return False
        elif pattern == basename or normalised.startswith(pattern + "/"):
            return False

    for entry in exclude_paths:
        if entry.startswith("!"):
            continue
        if WILDCARD_CHARS.search(entry):
            if _glob_hit(entry.rstrip("/")):
                return True
            continue
        if normalised.startswith(entry):
            return True
        # Single-segment prefixes also match anywhere in the path.
        bare = entry.rstrip("/")
        if "/" not in bare and bare in components:
            return True
    return False


def _is_disclosable_exclusion(
    rel_path: str, exclude_paths: Tuple[str, ...]
) -> bool:
    """Does this file's exclusion belong in the report's hidden count? (#691)

    The count is the entire justification for hiding a file at all: a `*.pem`
    sitting in a fixtures directory is survivable *because* the header says
    something was dropped. That holds only while the number discriminates, so
    entries that fire constantly and mean nothing have to stay out of it.

    `_hidden_suffix` already made this argument — for directories. Files
    versus directories was a *proxy* for the real line, which is noise versus
    credential, and the proxy holds only because almost every noise entry
    happens to be a directory. In a git **worktree** `.git` is a gitfile, not
    a directory, so the proxy broke precisely where the agent work happens:
    the counter read `1` on every call in the tree, about a pointer file
    nobody searched for. A reader learns to skip a number that is never zero,
    and then the call that says `2` because a real `.env` was hidden looks
    like all the others.

    Built-in noise entries are kept out of the count and still kept out of
    the result — nothing is hidden any less than before. A project's own
    `exclude-paths` entries always count: we cannot know whether one is noise
    or a credential, over-disclosure is the safe direction, and whoever added
    the pattern is the person most likely to want to know that it fired.
    """
    signal = tuple(p for p in exclude_paths if p not in _NOISE_EXCLUDE_SET)
    return bool(signal) and _is_excluded(rel_path, signal)


def _split_exclude_prefixes(
    exclude_paths: Tuple[str, ...],
) -> Tuple[Tuple[str, ...], Tuple[str, ...]]:
    """Split exclude prefixes into single-segment names and multi-segment paths.

    Single-segment ("node_modules/", ".git/") can be passed to grep's
    --exclude-dir.  Multi-segment ("Dvsi/dvsi-private/libs/") cannot — callers
    that delegate to grep should fall back to native walking when any
    multi-segment prefixes are present.

    Returns (singles, multis), each tuple of trimmed names without trailing "/".
    """
    singles: List[str] = []
    multis: List[str] = []
    for p in exclude_paths:
        trimmed = p.rstrip("/")
        if "/" in trimmed:
            multis.append(trimmed)
        else:
            singles.append(trimmed)
    return tuple(singles), tuple(multis)


def _grep_exclude_flags(exclude_paths: Tuple[str, ...]) -> List[str]:
    """Build the `--exclude` / `--exclude-dir` argv for the delegated grep.

    Two things the old `--exclude-dir`-only argv got wrong (#691):

    - **`--exclude-dir` cannot skip a file.** `.env/` means "a dir or a file
      named `.env`" everywhere else in supertool, so every literal entry now
      emits both flags. This alone is what stopped the delegated engine reading
      `.env` off disk at all.
    - **System grep has no negation.** `--exclude=.env.*` would hide
      `.env.example`, which the native walker shows — and which backend ran must
      never change the answer. So when the effective list carries any negation,
      wildcard entries are withheld from the argv entirely and left to the
      post-filter in `op_grep`. Literal entries still go through, which is where
      the traversal win lives (`node_modules`, `.git`).

    And one thing this argv got wrong in turn (#764): a file grep never opens
    is a file `_rtk_drop_excluded` never sees, so `rtk_dropped` stayed 0 and
    `_rtk_grep_report` printed no hidden clause. The disclosure #691 added was
    therefore inverted against usefulness — honest whenever the flags failed,
    silent whenever they worked, which is the fast path and the common one.

    So `--exclude=NAME` is emitted only for entries the report would not have
    counted anyway. A **disclosable** entry (anything off the built-in noise
    list — the same test `_is_disclosable_exclusion` applies) sends only
    `--exclude-dir=NAME`: the file comes back, the post-filter drops it,
    `dropped > 0`, and `op_grep` redoes the walk natively for a full and honest
    report. The cost is that second walk, paid only when a credential-shaped
    file actually matched the pattern — and already the status quo for the
    wildcard half, which the negation rule above withholds for its own reasons.
    A silent search is the worse surprise: the count is the entire
    justification for hiding a file without asking.

    `--exclude-dir` is kept in both cases. A pruned directory is not counted by
    the native walker either — it is never opened, so there are no files to
    count — and withholding it would cost the traversal win and buy no
    disclosure at all.

    Multi-segment entries are never expressible as a bare name; `op_grep`
    already refuses to delegate at all when one is present.
    """
    has_negation = any(p.startswith("!") for p in exclude_paths)
    negated = {p[1:].rstrip("/") for p in exclude_paths if p.startswith("!")}
    flags: List[str] = []
    for entry in exclude_paths:
        if entry.startswith("!"):
            continue
        bare = entry.rstrip("/")
        if not bare or "/" in bare or bare in negated:
            continue
        if WILDCARD_CHARS.search(bare) and has_negation:
            continue
        flags.append(f"--exclude-dir={bare}")
        if entry in _NOISE_EXCLUDE_SET:
            flags.append(f"--exclude={bare}")
    return flags


def _rtk_drop_excluded(
    rtk_out: str, exclude_paths: Tuple[str, ...]
) -> Tuple[str, int]:
    """Filter excluded paths out of a delegated grep's `path:lineno:content`.

    The authoritative guard on the delegated path, and deliberately not the
    only one: the argv flags are an optimisation, this is the guarantee. It
    runs the same `_is_excluded` the native walker runs, so an rtk release that
    rewrites the argv, or a system grep that ignores `--exclude`, still cannot
    put a credential in the output.

    Returns (kept_text, dropped_file_count).
    """
    if not exclude_paths:
        return rtk_out, 0
    cwd = os.getcwd()
    kept: List[str] = []
    dropped: set = set()
    for line in rtk_out.splitlines():
        m = re.match(r"^(.+?):\d+:", line)
        if m and _is_excluded(_safe_relpath(m.group(1), cwd), exclude_paths):
            dropped.add(m.group(1))
            continue
        kept.append(line)
    return "\n".join(kept) + ("\n" if kept else ""), len(dropped)


# Directories git ignores, keyed on (cwd, search root). One entry per walk
# root per process — a batch call runs many ops and must not re-shell per op.
_GIT_IGNORED_CACHE: Dict[Tuple[str, str], frozenset] = {}
_GIT_IGNORE_TIMEOUT = 10


def _gitignore_enabled() -> bool:
    """Whether walks prune gitignored directories. Default: true (#449).

    Off via `"gitignore": false` in .supertool.json, or SUPERTOOL_NO_GITIGNORE=1
    for one invocation. `no-exclude` on the op turns it off too, since that flag
    already means "show me everything".
    """
    if os.environ.get("SUPERTOOL_NO_GITIGNORE") == "1":
        return False
    return bool(_load_config().get("gitignore", True))


def _git_ignored_dirs(root: str) -> frozenset:
    """Directories under `root` that git ignores, as cwd-relative posix paths.

    Asks git rather than parsing `.gitignore` (#449). Negations (`!keep/`),
    nested ignore files, `.git/info/exclude` and the user's global excludes are
    all semantics we would otherwise have to reimplement, and getting any of
    them wrong hides files — the failure direction this repository has spent a
    week removing. `git ls-files --directory` also collapses an ignored tree to
    its top directory instead of listing it, so the answer costs one subprocess
    and never descends into what it is telling us to skip.

    **Only directories are collected.** Ignored *files* are left in the walk:
    the win here is pruning at the directory boundary, per-file filtering would
    buy little, and `_DEFAULT_EXCLUDE_PATHS` already covers the secret-file
    case (#146).

    Returns an empty set — meaning "no opinion", not "nothing to skip" —
    outside a repo, without git, on timeout, and, deliberately, when `root`
    itself is ignored. That last case is the whole guarantee: a caller who
    names `.claude/worktrees/foo` as the search root gets results, because
    every path under an ignored root is ignored and pruning there would return
    silence.
    """
    if not _gitignore_enabled() or not os.path.isdir(root):
        return frozenset()
    cwd = os.getcwd()
    key = (cwd, os.path.normpath(root))
    cached = _GIT_IGNORED_CACHE.get(key)
    if cached is None:
        cached = _compute_git_ignored_dirs(root, cwd)
        _GIT_IGNORED_CACHE[key] = cached
    return cached


def _run_git_ignore_query(root: str, args: List[str]) -> Any:
    """Run one git query under `root`; None when git is absent or misbehaves."""
    try:
        return subprocess.run(
            ["git", "-C", root, *args],
            capture_output=True, timeout=_GIT_IGNORE_TIMEOUT,
        )
    except (OSError, subprocess.SubprocessError):
        return None


def _compute_git_ignored_dirs(root: str, cwd: str) -> frozenset:
    """Uncached body of `_git_ignored_dirs`."""
    # check-ignore exits 1 for "not ignored", 0 for "ignored", 128 for "not a
    # repo" / any other failure. Only 1 authorises pruning: 0 means the caller
    # deliberately searched inside an ignored tree, 128 means we do not know.
    probe = _run_git_ignore_query(root, ["check-ignore", "-q", "--", os.path.abspath(root)])
    if probe is None or probe.returncode != 1:
        return frozenset()
    listing = _run_git_ignore_query(root, [
        "ls-files", "-z", "--others", "--ignored", "--exclude-standard",
        "--directory", "--no-empty-directory",
    ])
    if listing is None or listing.returncode != 0:
        return frozenset()
    dirs = set()
    for entry in listing.stdout.decode("utf-8", "surrogateescape").split("\0"):
        # Trailing slash is git's marker for "this whole directory is ignored".
        # Entries without one are individual files, which we leave alone.
        if not entry.endswith("/"):
            continue
        rel = _strip_dot_slash(
            _safe_relpath(os.path.normpath(os.path.join(root, entry)), cwd)
        )
        if rel and rel != "." and not rel.startswith(".."):
            dirs.add(rel)
    return frozenset(dirs)


def _strip_dot_slash(path: str) -> str:
    """Normalise a relative path to forward slashes with no leading './'."""
    rel = path.replace(os.sep, "/")
    while rel.startswith("./"):
        rel = rel[2:]
    return rel


def _is_git_ignored(rel_root: str, name: str, ignored: frozenset) -> bool:
    """Whether `rel_root/name` is one of the directories git told us to skip."""
    if not ignored:
        return False
    return _strip_dot_slash(os.path.join(rel_root, name)) in ignored


def _under_git_ignored(rel_path: str, ignored: frozenset) -> bool:
    """Whether a file path sits inside any ignored directory.

    Used on the post-filter glob path, which has no walk boundary to prune at.
    """
    if not ignored:
        return False
    rel = _strip_dot_slash(rel_path)
    return any(rel == d or rel.startswith(d + "/") for d in ignored)


def _gitignore_residual(path: str, exclude_paths: Tuple[str, ...]) -> bool:
    """Whether git ignores a directory the built-in excludes would still walk.

    Gates rtk delegation (#449). rtk shells out to the system grep, whose
    `--exclude-dir` takes bare names and cannot express a nested path like
    `.claude/worktrees/`, so a delegated grep would return the very copies the
    native walker prunes — and which backend ran must never change the answer.
    The test is *residual*, not "is anything ignored": a repo whose ignore set
    is `node_modules/` alone is already fully covered by
    `_DEFAULT_EXCLUDE_PATHS`, and nobody should lose delegation over it.
    """
    if not exclude_paths:
        return False
    return any(
        not _is_excluded(rel, exclude_paths) for rel in _git_ignored_dirs(path)
    )


def _rtk_enabled() -> bool:
    """Check if RTK delegation is enabled in .supertool.json. Default: true."""
    return bool(_load_config().get("rtk", True))


# RTK integration — when rtk is installed, delegate read/grep/wc for compressed output
_RTK_PATH: str | None = None
_RTK_CHECKED = False


def _has_rtk() -> str | None:
    """Return rtk binary path if available, None otherwise. Cached.

    Honours ``SUPERTOOL_NO_RTK=1`` — used by tests that spawn supertool in a
    subprocess and need the unwrapped output format regardless of whether the
    user has rtk on their PATH.
    """
    global _RTK_PATH, _RTK_CHECKED
    if not _RTK_CHECKED:
        _RTK_CHECKED = True
        if os.environ.get("SUPERTOOL_NO_RTK") == "1":
            _RTK_PATH = None
        else:
            # #2611: a raw which() searches the current directory ahead of
            # every real PATH entry on Windows, so a repo-planted "rtk.exe"
            # would be resolved -- and then spawned by _rtk_run() below,
            # which passes no cwd= -- ahead of the real tool. Same class as
            # #2596/#2575, closed the same way: this file's own
            # _which_excluding_cwd() instead of a bare which().
            _RTK_PATH = _which_excluding_cwd("rtk")
    return _RTK_PATH


def _rtk_run(args: List[str], timeout: int = 30) -> str | None:
    """Run rtk command, return stdout or None on failure."""
    rtk = _has_rtk()
    if not rtk:
        return None
    try:
        result = subprocess.run(
            [rtk] + args, capture_output=True, text=True, timeout=timeout, encoding="utf-8", errors="replace"
        )
        if result.returncode == 0:
            return result.stdout
    except (subprocess.TimeoutExpired, OSError):
        pass
    return None


# #1786: a full-file `read:PATH` delegated to `rtk read` on a >150-line file
# came back with the file's real last line (`export = 1`) sandwiched between
# TWO elision-style footers -- `// ... 362 lines omitted` above it and
# `// ... 361 more lines (total: 512)` below it -- whose counts do not even
# sum to the file's own line count. Reproduced directly against `rtk` (not
# through supertool at all): `rtk read -n --max-lines 300 FILE` on any file
# over its window reliably renders this head-window-plus-tail-line-preview
# collision. That is a bug in `rtk`'s own compression
# (github.com/rtk-ai/rtk), not in anything this file computes --
# grep for "lines omitted" in this module finds nothing, because supertool
# never emits that phrase itself.
#
# What is this file's own bug: `render_file`'s RTK delegation trusted that
# render wholesale and returned it to the caller unchanged, so a third
# party's malformed output became supertool's own answer with nothing to
# tell the two apart. A caller who does not already know the file cannot
# tell a garbled compression from a correct one (the failure mode the issue
# itself named as the worst part). Two occurrences of the elision-marker
# shape bracketing real content is not a pattern any well-formed `rtk read`
# truncation produces -- a truncation cuts once -- so it is the signature
# checked for here.
#
# Anchored to rtk's own footer-line SHAPE, not a bare substring (self-review,
# #1786): a plain substring search matches this exact text sitting inside
# ordinary prose that merely discusses this bug -- confirmed against the
# real rtk 0.35.0 binary reading this very test file and the changelog
# fragment for #1786, both of which quote the marker text in their own
# docstrings/prose and neither of which rtk actually truncates. Every line
# `rtk -n` emits, including its own elision markers, is prefixed with
# `N <U+2502>` (the box-drawing vertical bar rtk uses as its column
# separator, never a plain `|`); a source line merely talking about the
# shape does not carry that exact prefix immediately before the marker,
# because it is prose or code, not rtk's own render. Requiring the whole
# line (after that prefix and optional indentation) to be nothing but the
# marker is what a genuine footer looks like and ordinary quoted text does
# not.
_RTK_ELISION_MARKER_RE = re.compile(
    r"(?m)^\s*\d+\s*" + "│"
    + r"\s*//\s*\.\.\.\s*\d+\s+(?:lines omitted|more lines(?:\s*\(total:\s*\d+\))?)\s*$")


def _rtk_output_looks_malformed(text: str, *, aggressive: bool = False) -> bool:
    """True if `text` carries the double-elision-marker corruption (#1786).

    A single elision marker is `rtk`'s ordinary "I truncated here" footer and
    is left alone. Two or more, in the same render, means real content sits
    between a head-truncation notice and a tail-preview notice that
    contradict each other's counts -- the shape reproduced in #1786 at
    `rtk`'s default and `minimal` levels, not a guess at what a well-formed
    render could also look like.

    `aggressive=True` disables the check entirely (#1786 self-review). Under
    `--level aggressive`, `rtk` legitimately compacts EACH function body it
    elides with its own marker -- reproduced directly: a six-function file
    at `--max-lines 10 --level aggressive` renders three `// ... N lines
    omitted` markers plus a final `// ... N more lines (total: M)` summary,
    four matches in one entirely correct render, because aggressive mode
    truncates per block rather than once. Counting markers cannot tell that
    apart from the corruption this function exists to catch, so the
    corruption check is scoped to the levels it was actually reproduced at.
    """
    if aggressive:
        return False
    return len(_RTK_ELISION_MARKER_RE.findall(text)) >= 2

# Built-in op names — custom ops/aliases with these names are ignored
_BUILTIN_OPS = {"read", "grep", "grep_around", "glob", "ls", "tail", "head", "wc", "check", "around", "map", "diff", "stat", "around_line", "tree", "replace", "replace_dry", "edit", "replace_lines", "paste", "append", "vi", "validate", "format", "validate_staged", "format_staged", "workspace", "resolve", "diag", "hover", "rename", "payload-lint"}

# Ops the dispatcher handles but that are absent from _BUILTIN_OPS, which is a
# shadowing blocklist ("custom ops with these names are ignored") and not a
# capability list. Kept separate so the blocklist's semantics are untouched.
_DISPATCH_ONLY_OPS = {
    "between", "vim", "batch", "gc", "help", "version",
    "ops", "ops-compact", "introduction", "output-format", "registry",
    "guard", "doctor", "init", "json-set",
}

# Valid from the CLI but never reaching dispatch(): main() honours and strips
# them before the op loop. They belong in any list a caller reads.
_MAIN_LEVEL_OPS = {"cwd", "repo"}


def _valid_op_names() -> List[str]:
    """Every op name this binary accepts regardless of config, sorted.

    The unknown-op error used to carry a hand-written list of 18 names while the
    dispatcher accepted 40+ — the tool under-reporting its own capability, which
    is exactly the defect #614 is about, one layer in. Derived from the sets
    dispatch really uses so it cannot rot again. ``vi`` is dropped: it lingers in
    _BUILTIN_OPS from before the op was renamed ``vim`` and no branch handles it.
    """
    return sorted((_BUILTIN_OPS | _DISPATCH_ONLY_OPS | _MAIN_LEVEL_OPS) - {"vi"})


# Ops whose intended target is a documented fact rather than a guess (#1303).
# Two entries, and both carry their evidence:
#
# `write` — the harness tool is called `Write`, and
# `.claude/jit-context/tools/00-manual/harness-tools-blocked.md`, which fires on
# every `Write` attempt in this repo, maps `Write` to `paste`. The tool taught
# the mapping in one place and forgot it in the other, so an agent reaching for
# `write:@-` got the whole builtin roster in alphabetical order, explaining none
# of it.
# `vi` — lingers in `_BUILTIN_OPS` from before the op was renamed `vim`, and no
# branch handles it; `_valid_op_names()` drops it for that reason.
# `gh-since-tag` — deleted in #1405, folded into `gh-prs` as the `merged-since=`
# filter. The strongest receipt available: the name did not drift, the op was
# removed into this one. It is the first entry whose target is a PRESET op
# rather than a builtin, which `_near_miss_ops` already supported — its
# candidate set is `_valid_op_names()` PLUS the loaded config's ops — while the
# table's pinning test measured targets against builtins alone. That test now
# admits shipped preset ops, from `_shipped_preset_ops()`, so it keeps exactly
# the guarantee it had: a target that is renamed or dropped still fails it.
#
# Additions belong here only with that kind of receipt. Anything inferable is
# inferred below instead, where the rule can be stated and argued with.
#
# **A synonym carries a NAME, not an invocation.** `write -> paste` is a whole
# answer because `paste` alone is what the caller wanted. `gh-since-tag ->
# gh-prs` is not: the board is the right op and `merged-since=TAG,state=merged`
# is the rest of the sentence, and this table has nowhere to put it.
#
# What closes that gap is `_synonym_invocation_note`, which prints the target's
# registry `syntax` under the suggestion. Until #1524 this comment claimed the
# gap was closed by the target's *description*, "which the unknown-op message
# already prints for a preset op" — it did not, and never had: `_near_miss_ops`
# pairs a candidate with a provenance label and nothing else, so the message
# read `Did you mean: gh-prs (preset 'github')`, and bare `gh-prs` is every open
# PR on the repo — a different board from the release gate. A false claim in a
# change's own prose, used as the argument for relaxing the rule stated one
# paragraph above it; the rule was fine, the receipt was invented.
_OP_SYNONYMS = {"write": "paste", "vi": "vim", "gh-since-tag": "gh-prs"}

# The ops that bring a file into existence, in the order a refusal should offer
# them (#1334, #1372). `paste` writes a whole file and its parent dirs; `append`
# creates too, and extends when the file is already there.
#
# Hand-written, and there is no derived alternative to reach for. `replaces` —
# the registry key the raw-command guard quotes so its advice cannot go stale
# (#1376) — maps a raw *shell command* onto an op, and only preset and project
# ops carry one. Every name here is a built-in, and a built-in has no registry
# entry at all: `registry:paste` answers "'paste' is a built-in, not a preset or
# project op, so it has no registry entry". `help:paste` reads `.supertool.json`
# and returns nothing outside a project. So there is no shipped source for these
# descriptions, and a hand-written tuple is the honest answer rather than the
# lazy one.
#
# What stops it rotting is the same thing that pins `_OP_SYNONYMS`: a test
# enumerating both tables against `_valid_op_names()`, which fails the day a
# named target is renamed or dropped.
_CREATING_OPS = ("paste", "append")


def _create_instead_hint() -> str:
    """The "there is nothing here to edit" clause, naming both causes.

    Deliberately does NOT choose between them. `file not found` from a write op
    has two causes and only one wants a creating op: a caller who meant to
    create, and a caller who typo'd a path to a file that does exist. For the
    second, taking the suggestion writes a new file at the wrong path and leaves
    the real one unedited — strictly worse than the refusal, which is #1424's
    `misdirects` class. So both readings are stated and the `tried:` line above
    is what the caller decides on.
    """
    return (
        f"to create it instead: {_CREATING_OPS[0]}:::PATH:::CONTENT writes a "
        f"whole file and its parent dirs, {_CREATING_OPS[1]} creates or "
        f"extends. If the path is a typo, either would write a second file and "
        f"leave the real one unedited — check `tried:` above first."
    )

# Below four characters, one edit is not a typo signal. `lsx` is one edit from
# `ls`, `dif` from `diff`, `hea` from `head` and `heap`; suggesting on that is
# how a refusal sends its reader one round-trip FURTHER from the answer than
# silence would. Whole-segment matches (`worktrees` -> `git-worktrees`) have no
# length floor, because a shared segment is not a coincidence.
_NEAR_MISS_MIN_LEN = 4

# Three at most. A ranked list long enough to need reading is the wall of names
# this exists to replace.
_NEAR_MISS_MAX = 3


def _within_one_edit(a: str, b: str) -> bool:
    """True when `a` becomes `b` in one insert, delete, substitute or swap.

    Optimal string alignment distance <= 1, decided directly rather than by
    building a matrix. The transposition arm is not decoration: `raed` for
    `read` is two substitutions to Levenshtein and one typo to a human, and
    adjacent-key swaps are the commonest miss there is.
    """
    if a == b:
        return False
    la, lb = len(a), len(b)
    if abs(la - lb) > 1:
        return False
    if la == lb:
        diff = [i for i in range(la) if a[i] != b[i]]
        if len(diff) == 1:
            return True
        return (len(diff) == 2 and diff[1] == diff[0] + 1
                and a[diff[0]] == b[diff[1]] and a[diff[1]] == b[diff[0]])
    short, long_ = (a, b) if la < lb else (b, a)
    i = j = 0
    skipped = False
    while i < len(short) and j < len(long_):
        if short[i] == long_[j]:
            i += 1
            j += 1
        elif skipped:
            return False
        else:
            skipped = True
            j += 1
    return True


def _near_miss_ops(op: str) -> List[Tuple[str, str]]:
    """Names worth putting in front of a caller who typed `op`, and why each.

    Empty is a real answer and the common one. The bar is not "suggest
    something" — a wrong name costs the reader a round-trip they would not have
    spent on silence, and #1424's `misdirects` class is what that looks like
    when the named remedy is worse than the refusal. So every rule here is one
    that cannot fire on a coincidence, and a miss under all of them prints
    nothing rather than the least-bad candidate.

    The candidate set is what is loaded in THIS process — builtins plus the
    project's and presets' ops — because that is the set the caller may
    immediately use, and it is already in memory. Shipped-but-not-enabled
    presets are a second tier and are labelled as such: naming one without
    saying it is not loaded here would answer a question the caller did not ask.
    """
    typed = op.strip().lower()
    if not typed:
        return []
    loaded: Dict[str, str] = {name: "builtin" for name in _valid_op_names()}
    config = _load_config()
    sources = config.get("_op_sources") or {}
    for name in (config.get("ops") or {}):
        preset = (sources.get(name) or {}).get("preset")
        loaded[name] = f"preset '{preset}'" if preset else "project op"

    hits: List[Tuple[str, str]] = []
    seen = set()

    def _add(name: str, why: str) -> None:
        if name == op or name in seen:
            return
        seen.add(name)
        hits.append((name, why))

    # Case first, and alone. `Read:x` differs from `read` by something that is
    # certainly not a typo of a third op, and the distance rule cannot see that:
    # lowercased it is distance 0, which the "not a suggestion for itself" guard
    # discards, leaving `head` at distance 1 as the top candidate. Returning here
    # rather than falling through — once the name is known, a runner-up is noise.
    by_lower = {name.lower(): name for name in loaded}
    if typed in by_lower:
        _add(by_lower[typed], loaded[by_lower[typed]])
        return hits[:_NEAR_MISS_MAX]

    # A synonym is a documented mapping, not a guess, so it fires whether or not
    # the target is loaded here. It used to require `target in loaded`, which
    # made the table silently conditional on the caller's cwd: outside any
    # project `gh-since-tag` produced NO suggestion at all — the deletion #1405
    # went to some lengths not to leave as a hole, reopened by an `in` (#1524).
    target = _OP_SYNONYMS.get(typed)
    if target in loaded:
        _add(target, loaded[target])
    elif target in _shipped_preset_ops():
        _add(target, f"preset '{_shipped_preset_ops()[target]}', not loaded here")
    for name in sorted(loaded):
        if name.lower().endswith("-" + typed):
            _add(name, loaded[name])
    if len(typed) >= _NEAR_MISS_MIN_LEN:
        for name in sorted(loaded):
            if _within_one_edit(typed, name.lower()):
                _add(name, loaded[name])
    if not hits:
        for name, preset in sorted(_shipped_preset_ops().items()):
            if name in loaded:
                continue
            if name.lower().endswith("-" + typed) or (
                    len(typed) >= _NEAR_MISS_MIN_LEN
                    and _within_one_edit(typed, name.lower())):
                _add(name, f"preset '{preset}', not loaded here")
    return hits[:_NEAR_MISS_MAX]


def _cwd_retargets_note(op: str) -> str:
    """`cwd:` moves what the op ACTS on, not only where its config is read.

    The half of #1554 that is worse than the one filed. The guard blocks a raw
    `git commit` and names `git-commit`; the op is unavailable in a directory
    with no `.supertool.json` above it, and this message then offers
    `cwd:<project-path>`. Obeyed literally by someone standing in a throwaway
    repository under a scratchpad path — the #1536 agent's situation, three
    times in one run — that runs the op against a *different repository*.
    Measured: `cwd:<project>` followed by `git-status` reported the project's
    branch and working tree, not the caller's.

    So the escape hatch is kept and its scope is stated. A remedy that merely
    fails again costs a round-trip; one that succeeds somewhere else is the
    `misdirects` class proper, and this is the one line that separates them.
    """
    return (
        f"       'cwd:' moves the directory the op ACTS on as well as the one "
        f"its config is read from, so it is\n"
        f"       the fix only when the work is in that project — never a way "
        f"to run '{op}' against THIS\n"
        f"       directory. For a repository no project covers, this op has no "
        f"route to it (#1554).\n"
    )


def _synonym_invocation_note(op: str, named: List[str]) -> str:
    """The rest of the sentence, for the one candidate that is not a guess.

    `_OP_SYNONYMS` maps a NAME onto a NAME. `gh-since-tag -> gh-prs` needs more
    than that — bare `gh-prs` is every open PR on the repo, while the name the
    caller typed was the release gate, `gh-prs:merged-since=TAG,state=merged`.
    Answering with the bare name hands over a different board, which is #1424's
    `misdirects` class: a remedy that succeeds at the wrong question costs more
    than the refusal did (#1524).

    **Only the synonym route, never a distance guess.** The table above is ops
    "whose intended target is a documented fact rather than a guess", and that
    is exactly what pays for the extra line. `gh-prr` yields two candidates from
    edit distance; a syntax line each would put ~500 characters of filter
    grammar above a roster #1222 already fought to keep readable, to elaborate
    on names the tool is only guessing at.

    Empty when the target has no registry `syntax` — every built-in, so
    `write -> paste` and `vi -> vim` are unchanged and stay the whole answers
    the table argues they are.

    **The `syntax` field is printed WHOLE, so what is in it is what a reader
    pays for.** For `gh-prs` that used to be 243 characters — the filter
    grammar, then a sentence, so the invocation the caller needed began around
    character 255 of the rendered line. The obvious repair was to split on the
    `  --  ` separating the two halves, and it was refused as an inference from
    **one** field: 86 ops declared a `syntax`, exactly 1 contained that
    separator, and the distribution was min 7 / median 29 / p90 66 / max 243.

    #1590 fixed the field instead of the render. The narration left for
    `description`, which already carried it word for word; the invocation
    stayed, as the second of two ` | `-separated forms — the shape 4 other
    fields already use for an alternate invocation. So this function is
    unchanged and its output is 63 characters shorter, and the convention it
    relies on is pinned across the whole corpus by
    `tests/test_syntax_is_grammar_not_prose_1590.py`: no `syntax` carries an
    issue reference, a `  --  ` clause, or more than 200 characters.
    """
    target = _OP_SYNONYMS.get(op.strip().lower())
    if not target or target not in named:
        return ""
    syntax = _registry_syntax(target)
    if not syntax:
        return ""
    return (f"       '{op}' was an invocation; '{target}' is only a name. "
            f"Syntax: {syntax}\n")


def _batch_op_head(arg: str) -> str:
    """The op NAME `dispatch()` would resolve `arg` to, without running it.

    Mirrors the two ways `_dispatch_impl` splits an arg before it looks the
    name up: a `:::` opener splits there, everything else splits on the
    first `:` via `_split_arg`. The `:::no-exclude` suffix and the `@payload`
    routing that come after in `_dispatch_impl` never change which NAME is
    being asked for, so neither is reproduced here -- this only answers the
    one question #2122's pre-validation needs.
    """
    if arg.endswith(_NO_EXCLUDE_SUFFIX):
        arg = arg[: -len(_NO_EXCLUDE_SUFFIX)]
    if re.match(r"^([a-zA-Z_][a-zA-Z0-9_-]*):::", arg):
        parts = arg.split(":::")
    else:
        parts = _split_arg(arg)
    return parts[0] if parts else ""


def _op_is_unroutable(op: str) -> bool:
    """True only for a NAME `_dispatch_impl` cannot resolve to any handler.

    Deliberately narrower than "will succeed" (#2122's own must-not-fire
    case): a shipped preset op this config does not enable still routes
    here, because dispatch answers it with its own explanatory ERROR
    ("unavailable here, not unknown") rather than the plain unknown-op one --
    the op's EXISTENCE is a documented fact about this binary even when its
    availability here is not. A custom op whose command later fails to
    spawn, or a builtin given the wrong number of arguments, is a RUNTIME
    failure and is not knowable before anything runs; only the naming
    question is, which is the only question pre-validation is allowed to
    ask (`_unknown_op_message`'s own docstring: a typo and a custom op we
    never saw stay unknown, on purpose -- the same rule applies here).
    """
    if op in _BUILTIN_OPS - {"vi"} or op in _DISPATCH_ONLY_OPS or op in _MAIN_LEVEL_OPS:
        return False
    config = _load_config()
    # `isinstance(..., dict)`, not a truthiness check: a project config whose
    # `"ops"` is a bare string survives `_merge_presets` uncoerced on both of
    # its early-return paths, and `op in "some-string"` is a Python SUBSTRING
    # test -- `foo` would read as routable against `"xyzfooabc"` and be waved
    # through the very guard this function exists to be. A malformed config
    # must degrade this check to "not a custom op", never to "yes, routable".
    ops = config.get("ops")
    if isinstance(ops, dict) and op in ops:
        return False
    aliases = config.get("aliases")
    if isinstance(aliases, dict) and op in aliases:
        return False
    if op in _shipped_preset_ops():
        return False
    return True


def _batch_prevalidation_refusal(argv: List[str]) -> "Optional[str]":
    """Refuse a whole multi-op call before any member runs, if one member's
    op name is unroutable (#2122).

    Every positional argument is an op, so a mistyped option (`--offset`)
    becomes a batch member of its own. Before this existed, the refusal was
    already correct -- an ERROR and exit 1 for every such member -- but it
    arrived only after every EARLIER member had already run to completion,
    so a one-character slip after an unbounded `read:` bought the largest
    possible read and explained, afterwards, that it should not have.

    Mirrors the raw-command guard's own rule for a call it refuses: a
    refusal covers the whole call, never only the part that named it. A
    batch is one call; running a prefix of it that the caller did not mean
    is the worst available outcome -- work is done, output is spent, and
    the caller has to reconstruct which half happened.

    Returns `None` when every member routes (the ordinary case, and the
    only one #1234's own batch -- a real `grep` op that fails at RUNTIME on
    its argument -- must still take, unchanged).
    """
    if len(argv) < 2:
        return None
    bad = [(i, a, _batch_op_head(a)) for i, a in enumerate(argv)
           if _op_is_unroutable(_batch_op_head(a))]
    if not bad:
        return None
    msg = (
        f"ERROR: batch refused before running: {len(bad)} of {len(argv)} "
        "members are not a routable op name.\n"
        "A batch validates every member's op name before any of them runs "
        "-- a member nobody can route means the caller did not get the "
        "batch they meant, and running the ops ahead of it is the worst "
        "available outcome (#2122).\n"
    )
    for i, raw, op in bad:
        if op.startswith("-"):
            # The op this flag was meant as an argument TO is the nearest
            # earlier member that actually routes — not simply `argv[i-1]`.
            # In this issue's own headline example the member before
            # `--limit` is `900`, itself unroutable, and naming it produced
            # `900:PATH:...` one line under "unknown operation: 900": a
            # remedy contradicting the diagnosis directly above it.
            prev_op = ""
            for j in range(i - 1, -1, -1):
                candidate = _batch_op_head(argv[j])
                if not _op_is_unroutable(candidate):
                    prev_op = candidate
                    break
            hint = (f"; ops take their arguments positionally, e.g. "
                    f"{prev_op}:PATH:...\n" if prev_op else
                    "; ops take their arguments positionally, not as "
                    "flags\n")
            msg += f"  [{i}] {raw!r} looks like a flag" + hint
        else:
            msg += f"  [{i}] {raw!r} -- unknown operation: {op}\n"
            # The per-member half of the help a single-op call gets (#614's
            # `Did you mean` and its synonym note). Refusing the batch
            # earlier must not buy the caller a THINNER diagnosis than the
            # same typo would have got on its own.
            for line in _unknown_op_message(op).splitlines():
                if line.startswith(("Did you mean:", "       ")):
                    msg += f"      {line.strip()}\n"
    # The roster once, not once per member: it is the same 40+ names every
    # time, and a batch of four typos would otherwise print it four times —
    # spending on a refusal exactly the output this issue exists to save.
    for line in _unknown_op_message(bad[0][2]).splitlines():
        if line.startswith(("Valid operations:", "Plus ")):
            msg += line + "\n"
    return msg


def _unknown_op_message(op: str) -> str:
    """Answer "can I do this?" in three states, not two (#614).

    ``docs/validators.md``'s "Declining instead of guessing" one layer out: a
    checker that cannot act must distinguish *no such thing* from *not from
    here*, because emitting the first when it means the second is an absence the
    tool produced being read as an absence in the world. It cost this repo's
    heaviest user two debugging detours in one evening — ``unknown operation:
    gh-job`` read as "the installed build predates that op", and several turns
    went into hand-rolled ``gh api`` calls that worked, so nothing looked broken.

    The only absence namable honestly is a shipped preset op: it ships beside
    supertool.py, so its existence is a fact about this binary. Everything else —
    a typo, a custom op from a config we never saw — stays *unknown*, on purpose.
    Hedging every miss into "maybe you need a project root" would trade a correct
    message for a guess, which is the same bad trade in the other direction.
    """
    preset = _shipped_preset_ops().get(op)
    if preset is not None:
        # Every branch below reads `_CONFIG_PATH`, which is None both when no
        # config loaded and when none has been attempted. A dispatch always
        # loads one first (`_resolve_custom_op`); a direct call to this
        # function does not, and the difference decided which sentence a
        # caller got about a config that was sitting there and fine (#1162).
        _load_config()
        if _CONFIG_PATH:
            return (
                f"ERROR: op '{op}' is unavailable here, not unknown — it is provided "
                f"by the shipped preset '{preset}', which {_CONFIG_PATH} does not "
                f"enable.\n"
                f'       Fix: add "{preset}" to that file\'s "presets" list, or make '
                f"this call's first op 'cwd:<project-path>' pointing at a project "
                f"that already enables it.\n"
                + _cwd_retargets_note(op)
                + f"       'ops' lists what is loaded here.\n"
            )
        skipped = _skipped_config()
        if skipped:
            # A config that is present and unusable is not a config that is
            # absent (#1162), and the remedies for absence are both dead here.
            # `cwd:<other-project>` retargets the working directory, so a git
            # op would report *that* repo's conflicts — #678's shape arriving
            # through the remedy line — and there is no other root to move to:
            # the broken file is in the tree the caller is standing in.
            path, why = skipped
            conflicted = "conflict markers" in why
            fix = (f"       Fix: resolve the markers in {path}, then re-run. "
                   f"The ops that would have helped are the ones it removed, "
                   f"so until then this is a raw-git repair.\n"
                   if conflicted else
                   f"       Fix: repair {path}, or make this call's first op "
                   f"'cwd:<project-path>' pointing at a project that enables "
                   f"'{preset}'.\n")
            return (
                f"ERROR: op '{op}' is unavailable here, not unknown — it is "
                f"provided by the shipped preset '{preset}'.\n"
                f"       {path} {why}, so no preset ops and no project ops are "
                f"loaded — only the built-ins.\n"
                + fix
                + ("" if conflicted else _cwd_retargets_note(op))
                + f"       'ops' lists what is loaded here.\n"
            )
        return (
            f"ERROR: op '{op}' is unavailable here, not unknown — it is provided by "
            f"the shipped preset '{preset}'.\n"
            f"       No .supertool.json was found from {os.getcwd()} or any parent, "
            f"so no preset ops and no project ops are loaded — only the built-ins.\n"
            f"       Fix: run it from a project that enables the '{preset}' preset, "
            f"or make this call's first op 'cwd:<project-path>'.\n"
            + _cwd_retargets_note(op)
            + f"       'ops' lists what is loaded here.\n"
        )
    msg = f"ERROR: unknown operation: {op}\n"
    # Above the roster, not instead of it (#1222). The suggestion can still be
    # wrong; the list cannot, and a reader who has to scroll past 44 names to
    # reach a candidate has been charged for both.
    near = _near_miss_ops(op)
    if near:
        msg += ("Did you mean: "
                + ", ".join(f"{name} ({why})" for name, why in near) + "\n")
        msg += _synonym_invocation_note(op, [name for name, _ in near])
    msg += f"Valid operations: {', '.join(_valid_op_names())}\n"
    loaded = _load_config().get("ops") or {}
    if loaded:
        msg += (f"Plus {len(loaded)} project/preset ops loaded from "
                f"{_CONFIG_PATH or 'config'} — run 'ops' for the full list.\n")
    return msg


# The three safety classes a listing row can carry (#1231).
#
# **Every figure in this comment was wrong, and they were the argument.** It
# read "`ops` is 47,254 bytes and `ops-compact` 9,067 against a ~7,168-byte
# SessionStart cap, so the startup listing is truncated *today*". Measured on
# 2026-08-27: `ops` 3,740, `ops-compact` 16,100, cap 10,000. The `ops` figure
# was 12.6x high — it predates #1774 making the default listing signatures-only,
# and 47,254 is roughly what `ops:full` costs now. So the premise "signatures
# cannot fit" was false, and the conclusion drawn from it — hand every session
# names alone — outlived it by fifteen releases.
#
# #1877 corrected this same pair of numbers where they appear in
# `hooks/session-start.sh` and left this copy, which is the one the reader
# reaches from the code. `tests/test_render_size_claims_1877.py` grades the
# figures in that file; this comment is prose beside a constant and nothing
# graded it. That is the whole lesson: a measurement written into a comment is
# a measurement nothing re-runs, and the second copy is the one that survives.
#
# What stands unchanged is why the class exists at all. A bare signature is
# only safely actionable for an op you may probe: `between:F:747:820` answers
# "'820' was read as the path" and names the op that does take a range, so
# listing → call → the error teaches the form. You cannot probe `gh-pr-merge`,
# which merges. Hence the class, and hence it now rides on `ops` too (#2028)
# rather than only on the roster.
#
# Declared, never inferred. `_PARALLEL_SAFE_OPS` looks like a ready-made
# read-only set and is not one — it is a dispatch-safety set, and until #1244
# it carried `format_staged`, which runs formatters over every staged file and
# writes them. Deriving "read-only" from it here would have rendered a mutating
# op probe-safe: an error in the one direction that costs something.
#
# The two agree as of #1244 and a test now holds them together, so this is no
# longer a live contradiction. The rule survives the repair anyway: a class
# read off another set's membership is only ever as right as that set's last
# edit, and this table is the declaration site.
#
# "acts" is about consequence, not about spawning: nearly every preset op runs
# a python subprocess. `*_status_since` is the case that proves it — it reads a
# feed, which sounds read-only, and writes `~/.config/<service>/last_check` on
# success. One probe to learn the signature advances the watermark, and the
# next real briefing reports an empty window it silently consumed. That is this
# repo's own defect wearing a safety class, so those three are "acts".
_SAFETY_CLASSES = ("read-only", "writes", "acts")

# Marker rendered beside a name. Read-only is unmarked, and that is a positive
# claim rather than an absence: the fallback for an op whose class is not
# declared is "acts", so a missing class renders `!` and is never the quiet one.
_SAFETY_MARKERS = {"read-only": "", "writes": "*", "acts": "!"}

# Safety class of every built-in. A fact about this binary, so it lives beside
# the sets that declare the built-ins exist rather than in a project's
# `.supertool.json` — which may be absent, stale, or another project's.
_OP_SAFETY_BUILTIN: Dict[str, str] = {
    # read-only — call blind; the error message teaches the signature
    "around": "read-only", "around_line": "read-only", "between": "read-only",
    "check": "read-only", "cwd": "read-only", "diag": "read-only",
    "diff": "read-only", "glob": "read-only", "grep": "read-only",
    "grep_around": "read-only", "head": "read-only", "help": "read-only",
    "hover": "read-only", "introduction": "read-only", "ls": "read-only",
    "map": "read-only", "ops": "read-only", "ops-compact": "read-only",
    "output-format": "read-only", "read": "read-only",
    "guard": "read-only",
    "registry": "read-only", "repo": "read-only",
    "replace_dry": "read-only", "resolve": "read-only", "stat": "read-only",
    "tail": "read-only", "tree": "read-only", "validate": "read-only",
    "validate_staged": "read-only", "version": "read-only",
    "wc": "read-only", "workspace": "read-only", "doctor": "read-only",
    "payload-lint": "read-only",
    # writes — changes files in this tree
    "append": "writes", "batch": "writes", "edit": "writes",
    "format": "writes", "format_staged": "writes", "gc": "writes",
    "init": "writes", "json-set": "writes",
    "paste": "writes", "rename": "writes", "replace": "writes",
    "replace_lines": "writes", "vim": "writes",
}


# Caller-declared read-only mode (#1787). `ops:roster` has always classed
# every op unmarked/`*`/`!` -- the only place read and write are distinguished
# at all -- but until this, the classification was unenforceable: a caller who
# IS read-only by design (a review/audit agent whose whole remit is
# annotating a diff) had no way to say so and be held to it. The concrete
# incident, `claude-oss#251`: a review agent ran `radar` (classed `!`)
# against the live watch fleet it was auditing, mid-audit of that fleet's own
# healing logic. Nothing stopped it; it is knowable only because the agent
# reported itself.
#
# An env var, not a `.supertool.json` key: the flag is a property of ONE
# CALLER's intent for one invocation, not of the repo or the tree. The same
# worktree is dispatched into by a read-only audit agent and a normal writing
# session in the same tick, sometimes the same process tree -- a
# project-level toggle would gate every caller or none, and whichever
# session wrote it last would silently win for every sibling.
# `SUPERTOOL_ALLOW_MIXED_TREE` and `SUPERTOOL_ALLOW_OUTSIDE_CWD` beside it are
# the same shape: a per-process opt a config file cannot represent.
#
# And this constrains only the well-behaved (#1787's own third question). The
# raw-command guard hooks `Bash` only, and a caller who wants to write can
# always not call the op -- `Edit`/`Write` reach disk with no op, no
# validator, no rollback (#1671), exactly as the roster's own legend already
# says. Shipped anyway: the incident this answers was not an adversary, it
# was a cooperative agent one call away from meaning to be read-only and
# having no way to say so. A guardrail against your own mistake is not made
# worthless by a determined caller's ability to route around it -- `noclobber`
# and a shell `readonly` variable are the same shape, and neither claims to
# stop an attacker.
_READ_ONLY_ENV = "SUPERTOOL_READ_ONLY"


def _read_only_declared() -> bool:
    """True when the caller has declared this whole invocation read-only.

    Same truthy spellings as `_mixed_tree_allowed()` beside it, so one
    convention answers "is this env var set" everywhere in this file.
    """
    return (os.environ.get(_READ_ONLY_ENV) or "").strip().lower() in (
        "1", "true", "yes", "on")


def _op_is_recognized(op: str) -> bool:
    """True when `op` resolves to something dispatch actually runs -- a
    builtin, or a name this project's config declares under `"ops"` or
    `"aliases"` (#1787's own self-review). The read-only gate must not ask
    `_op_safety_class` about a name that fails this: an unrecognised name is
    not `read-only` either, so a naive gate declined it as a manufactured
    `!`-class op whose printed remedy -- "unset SUPERTOOL_READ_ONLY" -- could
    never fix a name that does not exist. `_op_gated_by_mixed_tree_write_check`
    below carries the identical carve-out for the identical reason (#1878).
    """
    if op in _valid_op_names():
        return True
    config = _load_config()
    for section in ("ops", "aliases"):
        entries = config.get(section)
        if isinstance(entries, dict) and op in entries:
            return True
    return False


def _op_is_preset_op(op: str) -> bool:
    """True when `op` is a project-declared preset/custom op -- present in
    this project's config under `"ops"` -- as opposed to a builtin.

    This is the population the generic `args`-list @payload route (#1165)
    applies to: a preset op's syntax is free-form (`gh-job:ID:grep:PATTERN`),
    so it cannot get a named-field `:::` registry entry the way `edit` or
    `git-commit` can, and had no @payload route of any kind. A builtin with
    no route has one for a specific, considered reason (it is read-only and
    reached through `_READ_OP_AT_FIELDS` instead, or its syntax legitimately
    has no ':::' fields) and must not silently gain one here.

    Deliberately not `_op_is_recognized`'s `"aliases"` branch: an alias
    expands to other ops before any of them run, so a payload aimed at the
    alias name itself would have nothing to receive it.
    """
    _ops_cfg = _load_config().get("ops")
    return isinstance(_ops_cfg, dict) and op in _ops_cfg


def _op_safety_class(op: str) -> str:
    """Safety class for ONE op name, without building the whole roster.

    Same precedence `_roster_classes()` applies across every name, extracted
    so the dispatch-time read-only gate below doesn't pay for classifying
    every loaded op to ask about the one about to run (#1787). Builtins are
    `_OP_SAFETY_BUILTIN` -- a project config cannot downgrade one, matching
    `_roster_classes()`'s own rule that class is a property of this binary.
    A preset/project op reads its declared `"safety"` off `.supertool.json`
    ("ops" then "aliases"); undeclared or a string-form cmd shorthand (no
    `"safety"` key to read) falls back to `"acts"`, the loudest class.

    Call `_op_is_recognized(op)` first: an op that fails it is not covered by
    either rule above, and this function still answers `"acts"` for it --
    correct for `_roster_classes()`, which only ever asks about names it is
    already enumerating, and wrong for a caller asking about an arbitrary
    string, which is exactly what an unrecognised name is.

    Deliberately ignores `"status"` (listing suppression): a builtin or
    preset op still dispatches when hidden from `ops`/`ops:roster`, and this
    gate has to answer about what actually runs, not about what is shown.
    """
    if op in _valid_op_names():
        return _OP_SAFETY_BUILTIN.get(op, "acts")
    config = _load_config()
    for section in ("ops", "aliases"):
        entries = config.get(section)
        if isinstance(entries, dict):
            info = entries.get(op)
            if isinstance(info, dict):
                declared = info.get("safety")
                return declared if declared in _SAFETY_CLASSES else "acts"
    return "acts"


def _read_only_decline(op: str, cls: str) -> str:
    """The refusal for a `*`/`!`-class op under SUPERTOOL_READ_ONLY=1 (#1787).

    Names the op and its class rather than a bare "denied" -- sub-question 2
    of the issue this answers, and the same third-state argument
    `_mixed_tree_decline` beside it makes: a caller reading this receipt must
    be able to tell "declined because I asked for read-only" from "failed for
    an unrelated reason" without cross-referencing anything else.

    `op` is flattened through `_flat_field(..., disclose_newline=True)`
    before it is printed -- the same treatment `_dispatch_impl`'s own header
    already gives it, and for the same reason: a colon-CLI op name can never
    carry a literal newline, but a `.supertool.json` `"ops"`/`"aliases"` KEY
    can (a JSON string permits one), and an unflattened name there could
    forge a `[result] …` line at column 0 (caught in self-review, #1787).
    """
    flat_op = _flat_field(op, disclose_newline=True)
    marker = _SAFETY_MARKERS.get(cls, "!")
    shown = marker or cls
    what = ("writes files in this tree" if cls == "writes"
            else "reaches outside this tree, or outlives the call")
    return (
        f"SKIPPED: '{flat_op}' is class `{shown}` ({cls}) -- it {what} -- and "
        f"{_READ_ONLY_ENV}=1 is set.\n"
        f"Declined rather than run: the caller asked to be held to "
        f"read-only, and acting anyway would be exactly the silent gap this "
        f"declaration exists to close (#1787).\n"
        f"Every op's class: `ops:roster`. To act anyway for this call, unset "
        f"{_READ_ONLY_ENV}.\n"
    )


# Read-only built-in ops. Two consumers, one predicate, because they ask the
# same question: `_main`'s ThreadPool gate, and the `_path_meta_bulk_drop()` in
# `dispatch`'s `finally` that keeps the repo-wide `git status` snapshot from
# outliving a write. Excludes mutating ops (replace, edit, replace_lines) and
# custom ops (could shell out to anything). `between` is included — pure file
# read.
#
# "Read-only" is the contract, not a description of whoever is currently in the
# set, and the difference cost something. Until #1244 this carried
# `format_staged`, which shells formatters over every staged file and rewrites
# them. Under SUPERTOOL_PARALLEL, `supertool 'format_staged' 'read:f.txt'`
# rendered the *pre*-format bytes — under `[complete file — no more lines]`,
# a positive completeness claim — while the post-format bytes were already on
# disk. The same call sequentially was right, so the answer depended on a
# performance switch.
#
# "Safe to run concurrently" was the tempting weaker reading and it is not
# available: parallel safety is a property of the whole set of ops in one call,
# and a writer is unsafe beside any reader of the same path. Membership is
# read-only or nothing.
#
# `_OP_SAFETY_BUILTIN` above declares the same fact for `ops` output, and
# tests/test_parallel_safe_writes_1244.py asserts the two cannot drift apart
# again — two sources for one truth is what filed this.
#
# It carried `blame` until #1285, three and a half months after b4099a5 moved
# that op to the git preset as `git-blame`: four registries needed the deletion
# and three did not get it. tests/test_registry_names_dispatch_1285.py holds
# every table here against the dispatcher now, because a name in this one with
# no dispatch branch is inert only by coincidence — the day a preset or config
# op is named `blame`, the row applies to it.
_PARALLEL_SAFE_OPS = {
    "read", "grep", "glob", "ls", "head", "tail", "wc", "stat",
    "map", "tree", "around", "around_line", "between", "diff",
    "version", "validate", "validate_staged", "workspace",
    "resolve", "diag", "hover", "help", "doctor", "payload-lint",
}


# #146: dispatch-level path containment. Each op has a known position(s) of its
# path arg(s) in `parts`. _safe_path enforces cwd containment unless
# SUPERTOOL_ALLOW_OUTSIDE_CWD=1 is set. Chokepoint coverage (render_file,
# _atomic_write) catches internal callers that bypass dispatch (alias expansion,
# test code calling op_X directly).
#
# At module scope since #1285, and not for tidiness: read by `dispatch` and by
# the drift guard that holds every op registry against the dispatcher. As a
# local literal it was unreadable from outside the function, so the one table
# whose rows say *which argument is a path* had no check on its membership.
_PATH_ARG_POSITIONS = {
    "read": (1,), "head": (1,), "tail": (1,), "wc": (1,),
    "stat": (1,), "around_line": (1,), "ls": (1,), "tree": (1,),
    "map": (1,), "validate": (1,), "format": (1,),
    "workspace": (1,), "diag": (1,),
    # grep_around:PATTERN:PATH — parts[2] and nothing else. True for
    # three-and-four-token calls: their trailing slots must parse as ints, so
    # a ':' in the pattern fails the call rather than moving the path. FALSE
    # for the two-token shape (#1842): there is no trailing int slot to fail
    # on, so `grep_around:PATTERN:PATH` moves the path exactly as `grep`
    # does, and answers rather than failing.
    "grep_around": (2,),
    # `grep` and `around` are deliberately absent: neither keeps its path
    # in a fixed slot. `_parse_grep_args`/`_parse_around_args` peel the
    # trailing ints and take `path = args[-1]`, so a ':' anywhere in the
    # PATTERN pushes the path past slot 2 and the gate saw a pattern
    # fragment instead — arbitrary read, contents and all (#1166). Read
    # from the other side it also over-contained: with a ':' in the
    # pattern, slot 2 IS a pattern fragment, so searching a local file for
    # an absolute-path string was refused while naming a file the caller
    # never asked to open. Both branches gate the path they computed.
    # `glob` is deliberately absent, and until #1366 the absence had no
    # note beside it — the only unexplained one in a table where `grep`,
    # `around` and `between` each say why. It read as a decision and was
    # an oversight: `glob` reached no gate at all, so `glob:/tmp/x/*.txt`
    # listed what `read:/tmp/x/f.txt` refused. Its slot 1 is a PATTERN,
    # not a path — magic components, `**`, brace groups — so this table
    # cannot gate it, and neither can #1287's `_resolve_custom_op`
    # declaration gate, which only ever sees preset ops. `op_glob` gates
    # the reach it computes and the matches it got, at the points it has
    # them; see `_glob_reach`.
    # hover:SYMBOL:FILE, rename:OLD:NEW:FILE, resolve:SYMBOL[:FROM_FILE]
    "hover": (2,), "rename": (3,), "resolve": (2,),
    # diff:PATH1:PATH2
    "diff": (1, 2),
    # `between` is deliberately absent: neither of its readings keeps its
    # path in a fixed slot. Symbol mode takes parts[-1] (a ':' in the
    # symbol pushes the path past slot 2, and nothing gated parts[3] —
    # #1163), `re:` mode joins parts[4:] (a ':' in the path leaves only
    # the first fragment gated). And slot 2 is the START *regex* in the
    # `re:` reading, so gating it refused a legitimate local slice while
    # naming a file the caller never asked for (#1164). Both branches
    # gate the path they computed, at the point they computed it.
    # check:PRESET:PATH — runs a custom op, path forwarded as {file}.
    "check": (2,),
    # mutating ops (also covered by _atomic_write chokepoint):
    "edit": (3,), "replace": (3,), "replace_dry": (3,),
    "replace_lines": (1,), "paste": (1,), "append": (1,), "vim": (1,),
}


def _is_parallel_safe(arg: str) -> bool:
    """Return True if the op name is in the read-only safe set.

    Detects op name from `op:...` or `op:::...` prefix. Anything else —
    custom ops, mutating ops, malformed args — is treated as unsafe.

    Callers use it for two different-looking questions — may these ops share a
    thread pool, and may the status snapshot survive this op — which are the
    same question about whether the op writes.
    """
    m = re.match(r"^([a-zA-Z_][a-zA-Z0-9_-]*)(:::|:|$)", arg)
    if not m:
        return False
    return m.group(1) in _PARALLEL_SAFE_OPS


# ---------------------------------------------------------------------------
# Custom ops and aliases — config-driven dispatch extensions
# ---------------------------------------------------------------------------

class SecurityError(Exception):
    """Raised when a path arg violates the cwd containment policy."""
    pass


# Hard cap on path length passed to _safe_path. Sized well above MAX_PATH (260)
# and the extended-length namespace (32767) is too permissive for an op arg —
# 4096 catches obvious abuse (1MB args from fuzz tests) while leaving every
# legitimate path well under the limit.
_MAX_SAFE_PATH_LEN = 4096

#: The opt-out sentence every containment refusal ends with. One constant
#: rather than one copy per refusal site: `glob` refuses without naming the
#: file it matched (#1366), so it cannot reuse `_safe_path`'s message wholesale
#: and would otherwise have retyped this — and a retyped remedy drifts out of
#: step with the knobs it names.
_ALLOW_OUTSIDE_HINT = (
    "For a one-off call, no config edit and no residue: prefix the call "
    "with `cwd:PATH` to move the boundary there for this call only "
    "(#1784). To allow it for every future call: set "
    "SUPERTOOL_ALLOW_OUTSIDE_CWD=1 (env), or add "
    '`"allow_outside_cwd": true` to .supertool.json.'
)


def _safe_path(p: str, *, allow_outside_cwd: Optional[bool] = None,
               root: Optional[str] = None, boundary: str = "cwd") -> str:
    """Resolve `p` and enforce repo-root containment (closes #146).

    Strict mode (default): the realpath of `p` must equal cwd or live under
    cwd. Symlinks crossing the boundary are rejected. `..` traversal that
    escapes cwd is rejected. Returns the resolved absolute path.

    `root` moves the boundary without moving the rule (#1287). The core's own
    boundary is the cwd and stays the default; a preset op that resolves its
    argument against something else — `claims` resolves a relative path against
    the repository root, so a cwd boundary would refuse `claims:docs/x.md` run
    from `docs/` — declares that root and gets the *same* check under it.
    `boundary` is only the word the refusal uses, so the message names the line
    the caller actually crossed. Parameterised rather than reimplemented: the
    one thing this repo has learned twice about containment is that a second
    copy of the rule drifts (#882, #889).

    Opt-out (any one is enough):
      1. `allow_outside_cwd=True` per-call kwarg
      2. `SUPERTOOL_ALLOW_OUTSIDE_CWD=1` env var (CI / one-off)
      3. `"allow_outside_cwd": true` in `.supertool.json` (project-pinned)

    Test suites set the env var via conftest.py so tmp_path-based fixtures
    keep working; production deployments leave it unset.

    Trust model note: lookup (3) reads from the project's `.supertool.json`,
    same trust level as the other knobs there (validators, custom ops,
    presets). A user cloning a hostile repo is already running its code via
    supertool validators / ops; in-config opt-out adds no new attack
    surface. The env var takes precedence for one-off overrides.

    `~` expansion happens via os.path.expanduser — a user-supplied
    `~/.ssh/id_rsa` is resolved to the real path BEFORE the cwd check, which
    is what catches the threat. `$VAR` expansion does NOT happen here (#1370):
    no op gated by THIS check ever expands `$` when it opens the file — every
    such op opens the literal, unexpanded path — so a check that expanded
    `$HOME` while the op opened the literal string `$HOME` refused a
    directory that never escaped cwd at all, only its expanded interpretation
    would have (had it existed). This is the same check/use mismatch #1300
    fixed for `~`, applied the other way: there, the fix was to make the
    *use* match the *check* (both expanded); here, `$` is a legal filename
    character that no op ever expands on open, so the coherent fix is to make
    the *check* match the *use* (neither expanded). One rule, applied
    uniformly, rather than a per-op special case that would drift
    `_containment_error` the way #1366's review specifically rejected for
    `glob`.

    One caller elsewhere in this file DOES still expand `$VAR`: the `cwd:PATH`
    CLI pre-pass (`os.path.expanduser(os.path.expandvars(...))` ahead of
    `os.chdir`). That is not a counter-example — `cwd:` never calls this
    function at all. It establishes a new boundary rather than checking
    against the existing one, so there is no check/use pair here to disagree
    with itself; the claim above is scoped to callers of `_safe_path`, not to
    every path-shaped argument this file ever reads.
    """
    if allow_outside_cwd is None:
        if os.environ.get("SUPERTOOL_ALLOW_OUTSIDE_CWD") == "1":
            allow_outside_cwd = True
        else:
            # Project config opt-in. Wrapped in try/except so a broken /
            # missing config never raises out of a path check.
            try:
                allow_outside_cwd = bool(_load_config().get("allow_outside_cwd"))
            except Exception:
                allow_outside_cwd = False
    # NUL byte rejection — os.path.* raises ValueError on embedded NULs which
    # would leak as an uncaught traceback. Reject early with a clean message.
    if "\x00" in p:
        raise SecurityError(f"path contains NUL byte: {p!r}")
    # Windows: paths longer than MAX_PATH (260) make _getfinalpathname raise
    # ValueError("path too long for Windows") from inside os.path.realpath.
    # Reject oversized paths up front with a clean SecurityError so dispatch
    # returns a clean "ERROR: ..." instead of an uncaught traceback. 4096 is
    # well above MAX_PATH (260) and extended-length (32767) workable values
    # — any real op path stays well under it.
    if len(p) > _MAX_SAFE_PATH_LEN:
        raise SecurityError(
            f"path too long ({len(p)} chars, max {_MAX_SAFE_PATH_LEN})"
        )
    expanded = os.path.expanduser(p)  # not expandvars — #1370
    try:
        abs_p = os.path.realpath(expanded)
    except (ValueError, OSError) as e:
        # Truncate path in the error message — matches existing SecurityError
        # style of not echoing arbitrarily-large user input back verbatim.
        shown = p if len(p) <= 120 else p[:120] + "…"
        raise SecurityError(f"path cannot be resolved: {shown!r} ({e})") from e
    if allow_outside_cwd:
        return abs_p
    # Windows: NTFS is case-insensitive (`C:\Users` == `c:\users`) and uses
    # backslash separators. `os.path.normcase` lowercases + normalises
    # separators on Windows; on POSIX it's a no-op so the check stays exact.
    # This also handles drive-letter case (`c:\` vs `C:\`) and forward-slash
    # variants (`C:/Users` vs `C:\Users`).
    abs_p_cmp = os.path.normcase(abs_p)
    base = os.path.realpath(root) if root else os.path.realpath(os.getcwd())
    root_cmp = os.path.normcase(base)
    if abs_p_cmp == root_cmp:
        return abs_p
    if not abs_p_cmp.startswith(root_cmp + os.sep):
        # %s for the root, %r for the caller's own string: on Windows a %r
        # doubles every separator, so a caller comparing the printed root
        # against a real one would never match (#1283). Named only when it is
        # NOT the cwd — the default message is load-bearing in a dozen tests
        # and gains nothing from echoing the directory the caller stands in.
        where = "" if root is None else f", root {base}"
        raise SecurityError(
            f"path escapes {boundary}: {p!r} (resolved to {abs_p!r}{where}). "
            + _ALLOW_OUTSIDE_HINT
        )
    return abs_p


def _containment_error(candidates: Iterable[str], *,
                       root: Optional[str] = None,
                       boundary: str = "cwd") -> Optional[str]:
    """The one containment gate every path-bearing route passes through.

    Returns the ``ERROR: …`` line to print, or ``None`` when every candidate is
    contained. Dispatch applies it positionally from ``_PATH_ARG_POSITIONS``;
    the ``@payload`` route applies it to the fields a payload names. **One rule,
    one implementation, several callers** — #882 was a second copy of this rule
    written beside the real one, and it covered the list form while missing the
    single-path one, so ``{"path":"/etc/hosts"}`` validated a file
    ``validate:/etc/hosts`` refuses. A third copy would drift the same way.

    ``""`` and ``"."`` are skipped because neither is a filename: one means no
    path was given, the other *is* cwd, and ``_safe_path`` allows both anyway
    — the skip saves a `realpath` and grants nothing.

    ``"full"`` and ``"raw"`` used to sit beside them and are a different thing
    entirely: they are names a repo can hold. They were read's mode tokens,
    which live at ``parts[2]``/``parts[3]`` — no ``_PATH_ARG_POSITIONS`` slot
    is ever one, so the skip never had a case to serve even on dispatch. What
    it did have was an effect: #884 moved it from the dispatch loop into this
    helper, and the ``@payload`` route, whose ``paths`` entries are always
    filenames, inherited it — a symlink named ``raw`` pointing outside the root
    then validated where an ordinary name was refused (#889). Parity held and
    was not the property wanted; the routes agreed on the wrong rule. Deleted
    rather than moved back or made a parameter: a skip that guards nothing and
    opens something is only the hole.

    Accepted risk, documented rather than closed (#896 F3): this realpaths
    each candidate ONCE, here, and the op that runs afterwards re-resolves
    the same string independently -- `open()`, `os.path.realpath()` inside
    the op body, whatever that op already does. A symlink swapped between
    this check's resolution and the op's own is the classic TOCTOU window:
    the containment gate validates one target, the op reads another. This is
    not a defect #892 (or any single PR) introduced -- it is the shape of
    "check, then act" wherever the check and the act are two separate
    syscalls, which is every route through this gate. Closing it for real
    means opening the file through an `O_NOFOLLOW`-style handle at check
    time and using THAT handle for the op, rather than a path string handed
    off to be resolved a second time -- a change to every op's own open
    path, not to this function, and out of proportion to a low-severity,
    narrow-window race that needs a second local account (or process)
    racing the exact candidate path between two syscalls. Named here so the
    gap is on the record rather than pretended closed.
    """
    for candidate in candidates:
        if not candidate or candidate == ".":
            continue
        try:
            _safe_path(candidate, root=root, boundary=boundary)
        except SecurityError as exc:
            return f"ERROR: {exc}\n"
    return None


def _expand_home(p: str) -> str:
    """`~` / `~user` expansion, for a value the gate is about to clear.

    Not a new policy. `_safe_path` has expanded `~` since #146 — on the
    string it *checks*. What it never did was hand the expansion back, so
    every op re-used the caller's literal `~/x`, which `os.path.abspath`
    turns into `<cwd>/~/x` and which never exists (#1300). The gate approved
    one path and the op opened another.

    Deliberately narrower than `_safe_path`'s own normalisation:

    * **no `realpath`** — that resolves symlinks, and handing an op the
      symlink target would change what a write lands on and what every
      receipt prints, which is not what was filed;
    * **no `expandvars`** — a `$` is a legal character in a filename, so
      expanding one would break a file that reads fine today. `_safe_path`
      no longer expands `$VAR` either (#1370), so there is nothing here to
      hand back for it — the gate now checks the same literal string every
      op opens; `~` is the only shape that cannot name a real relative path
      and so is the only one this function still has to translate.

    Whatever the platform's `expanduser` makes of `~user` is what the op
    gets, and the two cannot disagree — POSIX leaves an unknown user exactly
    as typed, while `ntpath.expanduser` invents a home for any name by
    joining it onto the parent of `USERPROFILE` without checking it exists.
    Neither is normalised away here: the point of this function is that the
    string returned is the string opened, not that the two platforms answer
    the same.
    """
    if not isinstance(p, str) or not p.startswith("~"):
        return p
    return os.path.expanduser(p)


def _gate_paths(candidates: Iterable[str], *,
                root: Optional[str] = None,
                boundary: str = "cwd") -> Tuple[Optional[str], List[str]]:
    """`_containment_error`, plus the strings the caller must actually use.

    One return value, so a caller cannot check one string and open another —
    which is the whole of #1300. The expansion is applied *after* the check
    and is the same one the check itself performs, so this widens nothing:
    a `~` resolving outside the boundary is refused before the expanded
    value is ever produced for use. `test_a_tilde_path_outside_the_boundary_is_still_refused`
    pins that ordering.

    On refusal the caller gets the error and must not use the list; it is
    returned unconditionally only so the signature has one shape.
    """
    originals = list(candidates)
    err = _containment_error(originals, root=root, boundary=boundary)
    return err, [_expand_home(c) for c in originals]


#: Stands in for a whole magic path component while a glob pattern is gated.
#: An ordinary name with no separator and no metacharacter in it, so it moves
#: the cursor exactly one level down and nothing else.
_GLOB_MAGIC_STANDIN = "__supertool_glob_magic__"


def _glob_split(pattern: str) -> List[str]:
    """Path components, on either separator."""
    seps = "/" + (os.sep if os.sep != "/" else "")
    return re.split("[" + re.escape(seps) + "]", pattern)


def _glob_reach(pattern: str) -> str:
    """The deepest path a glob pattern can address, as an ordinary path.

    **No glob metacharacter can invent a separator.** `*`, `?` and `[...]`
    match within one component; `**` spans components but only ever downward.
    So a pattern's traversal is fully determined by the `/` separators and the
    `..` components already written in it, and replacing every magic component
    with a plain name loses nothing the boundary cares about.

    That is what makes gating the *pattern* sound where the two obvious
    answers are not (#1366). The literal prefix before the first magic
    character is empty in `*/../../etc/*`, so a prefix gate clears it. And
    filtering the expanded results turns a refusal into a shorter list, which
    is this repo's house defect: a population narrowed without saying so.

    **This is one of two reaches, not the reach** (#1392). Every magic
    component becomes exactly one level down, which is what `*` and `?` do and
    is the *shallowest* thing `**` does — see `_glob_reach_min` for the other
    end, which is the one an escape uses.
    """
    return "/".join(
        _GLOB_MAGIC_STANDIN if WILDCARD_CHARS.search(comp) else comp
        for comp in _glob_split(pattern)
    )


def _glob_reach_min(pattern: str) -> str:
    """The same pattern with every `**` expanded to **zero** components (#1392).

    `glob` expands `**` to zero-or-more levels; `_glob_reach` modelled it as
    exactly one. A `..` written after a `**` therefore climbed one level
    further than the gate believed, and a pattern carrying one `**` per `..`
    cleared the gate and then walked out — `**/../secrets/*` reads as
    `<one level down>/../secrets` (contained) and expands to `../secrets`.

    Zero is the extreme worth checking and the only one that needs checking:
    dropping a downward component can only move the cursor up, never down, so
    the all-zero expansion climbs at least as far as any other. Checking it
    alongside `_glob_reach` covers both ends of the range, and every expansion
    in between lands within them.
    """
    kept = [_GLOB_MAGIC_STANDIN if WILDCARD_CHARS.search(comp) else comp
            for comp in _glob_split(pattern) if comp != "**"]
    return "/".join(kept) or "."


def _glob_pattern_containment_error(pattern: str) -> Optional[str]:
    """`_containment_error` for a glob pattern, per brace branch.

    Braces are expanded here because `_expand_braces` runs *inside*
    `_glob_files`, i.e. after any gate on the pattern string: `{.,/etc}/host*`
    reads as one contained component and fans out into two patterns, only one
    of which the gate ever saw (#1366).

    The refusal is `_containment_error`'s own — same wording, same opt-out
    sentence, one implementation (#882, #889) — with the two echoed strings
    rewritten to the caller's spelling, so the message names a pattern rather
    than the stand-in this function substituted. Two things it does not
    reproduce exactly, both in the trailing `(resolved to …)` hint only — the
    pattern itself is echoed verbatim ahead of it: with braces the message
    names the offending *branch* rather than the whole typed string (the more
    useful of the two, since it says which alternative crossed the line), and
    every magic component renders as `*` whatever it was written as, because
    the stand-in has already replaced `?`, `[abc]` and `**` alike.
    """
    for sub in _expand_braces(pattern):
        for reach in (_glob_reach(sub), _glob_reach_min(sub)):
            err = _containment_error([reach])
            if err:
                return (err.replace(repr(reach), repr(sub))
                           .replace(_GLOB_MAGIC_STANDIN, "*"))
    return None


def _glob_results_escape(files: Iterable[str]) -> bool:
    """Did any matched file resolve outside the boundary?

    The one escape `_glob_reach` cannot predict: a wildcard component landing
    on a symlink that points out of the tree. The pattern is honest and the
    result is not, and only `realpath` on the match can tell.

    Returns a bare bool on purpose. The caller must refuse the **whole call**
    and must not name the offending file: dropping it would be the narrowed
    list this gate exists to avoid, and printing it would disclose the very
    path outside the boundary that the refusal is about.
    """
    for f in files:
        try:
            _safe_path(f)
        except SecurityError:
            return True
    return False


#: Registry keys whose value is a boundary this core knows how to enforce.
#: `cwd` is the core's own and the default everywhere else; `repo` is the
#: repository root, which is what `claims` resolves relative arguments against.
_PATH_BOUNDARIES = ("cwd", "repo")

#: Syntax-string components that mean "this argument is a filesystem path".
#: Matched per `_`-separated component so `MD_FILE`, `TEXT_OR_FILE_OR_file`
#: and `@FILE` all count, while `NUMBER_OR_BRANCH` and `PATTERN` do not.
_PATH_SYNTAX_COMPONENTS = frozenset(("PATH", "PATHS", "FILE", "FILES"))

_SYNTAX_TOKEN_RE = re.compile(r"[^A-Za-z0-9_]+")

#: The core's own path placeholders in a `cmd` template. `{file}` is
#: `parts[1]` — the FIRST token only, and since #873 a caller token neither it
#: nor `{arg}`/`{dir}` can reach is refused rather than dropped.
#: `{dir}` is its `os.path.dirname`. Both are substituted by
#: `_resolve_custom_op` below, so an op writing either has already told the
#: core which argument it means a filesystem path to be — a stronger signal
#: than a prose `syntax` string, and the one #1350 was filed about.
#:
#: `{arg}` is deliberately absent even though it substitutes the very same
#: `parts[1]`. Twenty shipped ops carry `{arg}` (24 until #873 moved three
#: multi-token ops to `{args}`, then `gh-run` for #1715); 8 of them name a path
#: in `syntax` and are already held by `_syntax_names_a_path`, leaving 12 that
#: pass a handle, a ref, a tag, an ID or a repo slug and take no path at all.
#: Promoting `{arg}` would refuse those 12 and gate nothing. `{file}` and
#: `{dir}` are the placeholders whose NAME is the claim; `{arg}` is the one
#: that declines to make it. An op that means a path and writes `{arg}` is
#: still ungated, and that is a naming problem in the op rather than a hole
#: the core can close without over-refusing.
#:
#: #1357 proposed a *lint* instead — flag `{arg}` beside a PATH-shaped
#: `syntax` — and it is not built, because the measurement says it reaches
#: nothing: all 8 such ops are already refused by the detector unless they
#: declare, or named in `_UNDECLARED_PATH_OPS`. It is also aimed at the wrong
#: half. The residue is an op that MEANS a path behind a `syntax` that does
#: not say so, and such an op is invisible to a lint keyed on the `syntax`
#: saying so. Pinned in `tests/test_arg_placeholder_and_paths_env_1357.py`.
_PATH_CMD_PLACEHOLDERS = ("{file}", "{dir}")

#: Placeholders that consume EVERY caller token — `parts[1:]`, all of it.
_ALL_ARGS_PLACEHOLDERS = ("{args}", "{argjoin}")

#: Placeholders that consume exactly `parts[1]` and nothing after it. `{dir}`
#: is its `os.path.dirname`, which is still that one token.
_ONE_ARG_PLACEHOLDERS = ("{file}", "{dir}", "{arg}")


def _unconsumed_arg_tokens(cmd_template: str, parts: List[str]) -> List[str]:
    """Caller tokens the `cmd` template has no placeholder to carry (#873).

    The op string is split on every ':' before it gets here, so `parts` holds
    everything the caller typed. What reaches the subprocess is whatever the
    template asks for, and a template writing only `{file}`/`{dir}`/`{arg}`
    asks for `parts[1]` — `op:all:dry` used to run as `argv == ["all"]` with
    no warning, no error and no mention in the receipt. `:dry` was a safety
    flag in the filed case: the op pushed for real while its caller read the
    receipt as a dry run.

    Returns [] when nothing is lost, which includes the case where every
    unconsumed token is empty — `op:all:` carries no text to lose, and
    refusing a bare trailing separator would be noise rather than disclosure.

    **A template with NO argument placeholder at all** (#1532, split out of
    #873 deliberately, priced and declined until now) is held to the same
    rule: nothing in `parts[1:]` can ever reach the subprocess, so every one
    of those tokens is unconsumed, not just `parts[2:]`. `op:x` against
    `"cmd": "make lint"` used to drop `x` exactly as silently as the
    single-placeholder case #873 already refuses. Measured population is 4
    shipped ops (`git-conflicts`, `mcp_status`, `mcp_stop_all`, `watches`,
    pinned in `tests/test_custom_op_dropped_tokens_873.py`) plus whatever a
    project's own `.supertool.json` defines — a much smaller net than #873
    feared, because the pinned population is exactly 4, not an unbounded
    fraction of the registry.
    """
    if any(p in cmd_template for p in _ALL_ARGS_PLACEHOLDERS):
        return []
    if any(p in cmd_template for p in _ONE_ARG_PLACEHOLDERS):
        extra = list(parts[2:])
        return extra if any(extra) else []
    extra = list(parts[1:])
    return extra if any(extra) else []


def _declared_path_slots(entry: Any) -> List[int]:
    """The argument positions this registry entry declares as paths (#1560).

    Read-only, and deliberately tolerant: a malformed `"paths"` yields `[]`
    here rather than a second copy of the refusal, because
    `_preset_path_containment` runs first at dispatch and an op whose
    declaration does not parse never reaches a message that quotes it. What
    this answers is the one question a refusal needs — "is there a containment
    claim, and over which positions" — so the message cannot describe a
    boundary the gate does not enforce.
    """
    if not isinstance(entry, dict):
        return []
    decl = entry.get("paths")
    if not isinstance(decl, dict) or not isinstance(decl.get("args"), list):
        return []
    return [i for i in decl["args"]
            if isinstance(i, int) and not isinstance(i, bool) and i >= 0]


def _dropped_tokens_refusal(
        op: str, entry: Any, cmd_template: str, dropped: List[str]) -> str:
    """Name the text that will not be passed, and what would pass it.

    Refused rather than passed through: widening a single-token placeholder to
    the whole remainder would interpolate `parts[2:]` into `{file}`, a slot the
    `"paths"` declaration gates at index 1 only — a second path arriving
    downstream of the containment check, which is #1135's shape. It would also
    change what every existing `{arg}` op receives. `{args}` is already the
    pass-through, so the fix is to say which one the template asked for.

    **And for an op that declares `"paths"`, that pass-through is not offered**
    (#1560). The paragraph above is the reason this function will not widen the
    placeholder internally, and the message used to hand the operator the same
    manoeuvre in one line, with no word about extending the declaration
    alongside it. Measured on a fixture op declaring
    `{"args": [1], "root": "cwd"}`: `showit:../outside.txt` is refused at
    position 1, and after obeying the advice `showit:a.txt:../outside.txt`
    printed the file. So the remedy performed exactly what the refusal declined
    to — the `misdirects` shape, and the reader most likely to obey a refusal
    verbatim is an agent, immediately.

    What replaces it is the third state rather than a reworded one-liner: the
    declaration would have to name every position the widened template can
    receive, and `args` is a fixed index list while `{args}` takes an unbounded
    tail, so it contains that tail only up to the highest index it names. There
    is no one-line `cmd` change that keeps such an op contained, and saying so
    is more use than a remedy that reads as freshly checked. Pinned in
    `tests/test_payload_key_and_misdirect_refusals_1551_1554_1560.py`.
    """
    sep = _ARG_SEP[0] or ":"
    used = [p for p in _ONE_ARG_PLACEHOLDERS if p in cmd_template]
    reach = (f"substitutes {', '.join(used)}, which is the FIRST argument token "
             f"and nothing after it"
             if used else
             "substitutes no argument placeholder, so no argument token reaches it")
    syntax = entry.get("syntax") if isinstance(entry, dict) else None
    lines = [
        f"ERROR: op {op!r} was given {len(dropped)} argument token(s) its cmd "
        f"cannot reach: {sep.join(dropped)!r}.",
        f"       The template {reach}.",
        "       Refused rather than dropped (#873): a discarded ':dry' once ran "
        "an op in live mode",
        "       while its receipt read as a dry run.",
    ]
    gated = _declared_path_slots(entry)
    if gated:
        positions = ", ".join(str(i) for i in gated)
        lines += [
            "       Widening the cmd to {args} or {argjoin} is NOT the remedy "
            "here: this op declares",
            f'       "paths": {{"args": [{positions}]}}, so only argument '
            f"position(s) {positions} are containment-checked,",
            "       and a template that consumes the whole tail hands every "
            "later position to the child",
            "       unchecked (#1135, #1560). Extending that `args` list "
            "alongside it is necessary and not",
            "       sufficient — it is a fixed index list, so it holds an "
            "unbounded {args} tail only up to",
            "       the highest index it names. There is no one-line cmd "
            "change that keeps this op contained.",
            "       What IS checked is the first token: carry several fields "
            "inside it, separated by ',' or '|'.",
        ]
    else:
        lines += [
            "       To take every token, write {args} (one shell-quoted argv "
            "word per token) or",
            "       {argjoin} (every token rejoined with ':::' as a single "
            "argument) in the cmd.",
            "       To carry several fields inside the first token, separate "
            "them with ',' or '|'.",
        ]
    if isinstance(syntax, str) and syntax:
        lines.append(f"       This op documents: {syntax}")
    return chr(10).join(lines) + chr(10)

#: Preset ops that name a path and predate the declaration (#1287). **This set
#: only ever shrinks.** It is not a policy — it is a debt register: 33 shipped
#: PRESET ops name a path, 14 declare a boundary (#227 added `youtube_comment`,
#: the same `{"args": []}` shape as the ops below it -- its `file://PATH` sits
#: inside a pipe-separated field, not in an argument slot, so the containment
#: that matters is `safe_resolve_body_path`. `bluesky_publish` is the identical
#: shape sitting in the register, which is the difference a grandfather clause
#: makes and not a difference in the ops; #1796 added `gh-job` and
#: `gl-job` to the declared side, both `"paths": {"args": []}` — the `gl-api`
#: precedent, since PATH there names an artifact's own path or a GitLab API
#: route rather than anything on this filesystem; #532 added `worktree`, the
#: same `"paths": {"args": []}` shape again, since PATH there deliberately
#: points outside cwd; #2593 added `youtube_reply`, the identical
#: `{"args": []}` shape as `youtube_comment` right above it -- its own
#: `file://PATH` sits inside the same pipe-separated field, so named and
#: declared each moved by one again), these 19 do not. It opened
#: at
#: 20 — see the #1351 note below for the one it has lost. Counting this repo's
#: own `.supertool.json` as well used to add one to each of those first two
#: numbers, the extra being `oss_train`, deleted in #1472; the two scopes now
#: agree at 31 and 12. All
#: four numbers are pinned in
#: `tests/test_cmd_placeholder_path_detector_1350.py` so this comment cannot
#: drift again.
#: Refusing them at the time would have broken every one of them in the same
#: release that introduced the rule, so they are grandfathered *by name*,
#: which means a
#: newly written op cannot inherit the old default by being written after it —
#: it is refused at dispatch and red in
#: `tests/test_preset_path_chokepoint_1287.py` until it declares.
#:
#: It has shrunk once, to 19: `gl-api` now declares `{"args": []}` for real
#: (#1351). It was the op `_syntax_names_a_path`'s docstring held up as the
#: worked example of the declared pattern while sitting in this register — the
#: guard citing a member of the set it exists to empty.
#:
#: Several of these cannot be expressed as a `parts` index at all: the publish
#: ops carry their file inside a `|`-separated blob, `git-commit` takes a
#: `:::`-separated tail, `git-resolve` a comma list. Draining the register is
#: therefore per-op work, not a sweep, and the ops living in files with open
#: PRs (`presets/git*`, `presets/github*`, `presets/gitlab*`) were left alone
#: here on purpose rather than overlooked.
_UNDECLARED_PATH_OPS = frozenset((
    "bluesky_publish",
    "devto_comment",
    "devto_publish",
    "gh-batch-follow",
    "gh-batch-star",
    "gh-issue-create",
    "gh-pr",
    "gh-pr-create",
    "git-blame",
    "git-commit",
    "git-diff",
    "git-investigate",
    "git-resolve",
    "git-trail",
    "git-worktrees",
    "gl-issue-create",
    "hashnode_comment",
    "hashnode_publish",
    "hashnode_reply",
))


def _syntax_names_a_path(syntax: str) -> bool:
    """Does this op's registry syntax string name a filesystem path argument?

    The detector, not the declaration. The registry's `syntax` is already
    parsed rather than merely displayed, and it is the one field every op
    fills in, so it is what tells the core that an op *should* have declared a
    boundary. It cannot say *where* the path is — `TITLE|MD_FILE|CANONICAL`
    hides one inside a pipe-separated blob — which is exactly why the position
    is declared explicitly in `paths` and this function only ever produces the
    question, never the answer.

    Over-detection is the safe direction and it happens: `gl-api:PATH` is an
    API route, not a file. That op answers with `"paths": {"args": []}` — a
    declaration that no argument here is a filesystem path, which is a claim
    someone made rather than a default nobody noticed. It only became true in
    #1351: for one release `gl-api` was cited here as the declared example
    while sitting in `_UNDECLARED_PATH_OPS`, so the sentence teaching the next
    author what "declared" looks like pointed at an ungated op.

    It is also not the only detector. `_cmd_names_a_path` reads the `cmd`
    template for the core's `{file}` / `{dir}` placeholders, and
    `_entry_names_a_path` is the OR of the two — see #1350. The two are not
    ranked: of the 24 shipped ops this function detects, zero carry either
    placeholder, so a `cmd`-supersedes-`syntax` detector would have disarmed
    the gate for every one of them.
    """
    if not isinstance(syntax, str):
        return False
    for token in _SYNTAX_TOKEN_RE.split(syntax):
        for component in token.split("_"):
            if component in _PATH_SYNTAX_COMPONENTS:
                return True
    return False


def _cmd_names_a_path(cmd: Any) -> Optional[str]:
    """Which core path placeholder this `cmd` template substitutes, if any.

    Returns the placeholder rather than a bool so the refusal can name the
    signal that actually fired. An op with no `syntax` key was told it "names
    a path in its syntax ()", which reads as a bug in the guard rather than a
    demand on the op.
    """
    if not isinstance(cmd, str):
        return None
    for placeholder in _PATH_CMD_PLACEHOLDERS:
        if placeholder in cmd:
            return placeholder
    return None


def _entry_names_a_path(entry: Any) -> Optional[str]:
    """Why this op is being asked to declare a boundary, or `None` (#1350).

    The whole detector, in one place, returning the phrase the refusal prints.
    Two signals, OR'd, neither superseding the other:

    * the `syntax` string names a `PATH`/`FILE` component — 27 shipped ops;
    * the `cmd` template substitutes `{file}` or `{dir}` — **no shipped op
      today.** `oss_train` was the one and #1472 deleted it, so this arm's
      live instance is a fixture: a real `.supertool.json` driven through
      `dispatch()` in `tests/test_cmd_placeholder_path_detector_1350.py`.
      Zero shipped instances is not zero coverage, and it must not be read as
      permission to drop the arm — the arm is what asks an op with no
      `syntax` at all to declare, which is where the hole was.

    Before this, only the first was read, so an op with no `syntax` key at all
    took the `return None` arm: no declaration demanded, no check run, and a
    verdict indistinguishable from declared-clean. That is #1287's own rule
    answering "no path here" where it meant "I could not tell" — the two-state
    shape the rule exists to refuse, inside the rule.

    A bare-string op entry (`{"ops": {"lint": "php -l {file}"}}`) never reaches
    here: `_preset_path_containment` returns early on a non-dict. A string has
    no `paths` key and so no way to answer the demand, and the answer is to
    write the op as an object — `docs/contributing.md` has the reasoning.
    """
    if not isinstance(entry, dict):
        return None
    syntax = entry.get("syntax", "")
    if _syntax_names_a_path(syntax):
        return f"names a path in its syntax ({syntax})"
    placeholder = _cmd_names_a_path(entry.get("cmd", ""))
    if placeholder is not None:
        return (f"substitutes the core's {placeholder} path placeholder in "
                f"its cmd")
    return None


def _path_boundary_label(boundary: str) -> str:
    """How a boundary is named in a refusal.

    A function rather than a module-level dict: #397's register in
    `tests/test_state_reset_and_lint_timeout.py` accounts for every mutable
    global in this file, and a constant lookup table is still a mutable global.
    Two strings rather than one word because "path escapes cwd" is already in a
    dozen tests and dozens of transcripts, and the repo one has to read as a
    sentence.
    """
    return "the repository root" if boundary == "repo" else "cwd"


def _repo_root_for_containment() -> str:
    """Nearest ancestor of cwd holding a `.git`, else cwd.

    `.git` is tested with `exists`, not `isdir`: in a linked worktree it is a
    *file* pointing at the common dir, and this repo's own agents work almost
    exclusively in worktrees.

    No subprocess. `git rev-parse --show-toplevel` is what `presets/claims`
    uses and the two agree everywhere it matters; spawning git on every gated
    call to learn something a directory walk already knows would put a process
    launch in front of every preset op that takes a path. Where they could
    disagree — `GIT_WORK_TREE` pointing elsewhere — the core has already
    scrubbed those variables out of the environment (#692, #714).

    Falling back to cwd rather than to `/` is deliberate: a narrower boundary
    refuses more, and the failure mode of guessing wide is the bug this whole
    chokepoint exists to close.
    """
    d = os.path.realpath(os.getcwd())
    while True:
        if os.path.exists(os.path.join(d, ".git")):
            return d
        parent = os.path.dirname(d)
        if parent == d:
            return os.path.realpath(os.getcwd())
        d = parent


def _undeclared_path_refusal(op: str, signal: str) -> str:
    """What an op that takes a path and declares no boundary gets (#1287).

    A refusal, not a `skipped`. The three-state rule this repo applies
    everywhere else — `ok`, a finding, `skipped` — has no third state here,
    because a path argument that reaches no check is not a check that could
    not run. It is an unchecked read, and it renders identically to a checked
    one.
    """
    return (
        f"ERROR: op {op!r} {signal} and declares "
        f"no containment boundary.\n"
        f'       Add "paths": {{"args": [1], "root": "cwd"}} to its registry '
        f"entry — \"args\" lists the\n"
        f"       argument positions that are filesystem paths, \"root\" is "
        f'"cwd" (the core\'s boundary)\n'
        f'       or "repo" (the repository root, for an op that resolves '
        f'relative paths against it).\n'
        f'       "args": [] declares that no argument here is a filesystem '
        f"path.\n"
    )


def _preset_path_containment(
        op: str, entry: Any, parts: List[str]) -> Optional[str]:
    """The universal half of #1287: one chokepoint, a declared boundary.

    Every preset and custom op reaches `_resolve_custom_op`, so that is where
    a path argument can be gated once instead of per-op. What the core cannot
    supply is the *boundary*: `_PATH_ARG_POSITIONS` imposes the cwd on every
    builtin, and imposing it on presets too would refuse `claims:docs/x.md`
    run from `docs/` — a call that works today and should, because `claims`
    resolves relative arguments against the repository root.

    So the op declares both, and the core enforces both:

        "paths": {"args": [1], "root": "repo"}

    Returns the `ERROR: …` line to print, or `None` to let the op run.

    **Mutates `parts` in place** on the declared path, writing back the gate's
    own `~` expansion into each declared slot (#1300). In place because the
    caller substitutes `{file}` / `{args}` from that same list immediately
    after, and a preset op handed the literal `~/x` passes it to a child
    process with no shell to expand it — `cat: ~/t.txt: No such file or
    directory`, measured. Only the declared branch does this: an op in
    `_UNDECLARED_PATH_OPS` reaches no check, so there is nothing for an
    expansion to sit behind and it keeps the literal, exactly as `glob` does.
    """
    if not isinstance(entry, dict):
        return None
    decl = entry.get("paths")
    if decl is None:
        if op in _UNDECLARED_PATH_OPS:
            return None
        signal = _entry_names_a_path(entry)
        if signal is None:
            return None
        return _undeclared_path_refusal(op, signal)
    if (not isinstance(decl, dict) or not isinstance(decl.get("args"), list)
            or not all(isinstance(i, int) and not isinstance(i, bool) and i >= 0
                       for i in decl["args"])):
        # Negative indices are refused rather than resolved Python-style. They
        # would read as "the last argument", which is a real shape — `between`
        # symbol mode takes `parts[-1]` — but the core cannot honour it here:
        # `parts[-1]` on a bare `op` call is the op NAME, so the declaration
        # would gate a token that is never a path and skip the one that is.
        # Refused loudly because the alternative found in review was worse:
        # an out-of-range index was silently filtered out of the generator
        # below, so a typo'd declaration ran the op completely unchecked while
        # looking exactly like a declared one.
        return (
            f'ERROR: op {op!r} has a malformed "paths" declaration — expected '
            f'{{"args": [<non-negative int>, ...], "root": "cwd"|"repo"}}.\n'
        )
    boundary = decl.get("root", "cwd")
    if boundary not in _PATH_BOUNDARIES:
        return (
            f'ERROR: op {op!r} declares an unknown path root {boundary!r} — '
            f'expected one of: {", ".join(_PATH_BOUNDARIES)}.\n'
        )
    slots = [i for i in decl["args"] if 0 <= i < len(parts)]
    err, gated = _gate_paths(
        (parts[i] for i in slots),
        root=_repo_root_for_containment() if boundary == "repo" else None,
        boundary=_path_boundary_label(boundary),
    )
    if err:
        return err
    for _i, _slot in enumerate(slots):
        parts[_slot] = gated[_i]
    return None


def _path_not_found(path: str, *, label: str = "path",
                     suggest: Optional[str] = None,
                     op: Optional[str] = None,
                     call_prefix: Optional[str] = None,
                     creates: bool = False) -> str:
    """The "not found" error, naming the path it actually tried (#624).

    `ERROR: file not found: src/foo.py` is true and useless: it cannot tell a
    typo from a cwd that drifted — a `cd` in an earlier shell call, which is
    the shape #624 was filed about. The absolute path tried separates the two
    at a glance, with no second `pwd` round-trip.

    When cwd sits under a project root that DOES hold the path, the root and
    the exact `cwd:` prefix that would reach it are named as well. Named, not
    used: auto-recovery (#363) already re-roots the unambiguous call, so every
    call that reaches here is one it declined — ambiguous by construction.
    Resolving it here would trade a loud wrong path for a quiet wrong root,
    which is the defect this tracker is about, not the fix.

    `suggest`, when given, replaces the generic `wrong CWD?` hint (#734).
    The cwd-drift explanation is a real default, but a caller that already
    knows a *specific*, more plausible mistake — e.g. `around` recognising
    its PATH argument as an all-digit token that looks like the LINE its
    sibling `around_line` wants — should say that instead of pointing at the
    one thing that provably did not cause this failure.

    `creates`, when set by a *write* op, appends the clause naming the ops that
    would have made the file (#1334, #1372). It renders on one arm only: the
    generic `wrong CWD?` fallback, where nothing more specific was identified.
    Where the project-root branch or a `suggest` fired, the cause is already
    known and is not "the file was never there" — offering `paste` beside a
    positively diagnosed cwd drift would send the caller to write a second copy
    under the wrong directory. Read ops never pass it: nothing was to be
    written, so there is no next step to name.

    `op` asks this helper to derive that suggestion itself, from the two
    shapes known to produce a joined-up filename: a comma list (#921) and a
    whitespace-separated path list (#1261). Derived here rather than at each
    call site because six ops reach this function and only `grep` had ever
    been wired to the first of the two — `read`, `around`, `around_line`,
    `map` and `replace`, the other five, answered both with `wrong CWD?`,
    the one cause that provably did not apply. `call_prefix` is the op call
    up to but excluding the path, used to print the batched repair; omit it
    where the path is not the op's last argument, since the printed call
    would then be one nobody can run.
    """
    if not path:
        return f"ERROR: {label} not found: {path}\n"
    if not suggest and op:
        suggest = (_comma_path_list_suggest(op, path)
                   or _multi_path_suggest(op, path, call_prefix)
                   or None)
    # `os.path.abspath` and nothing else. This line used to run its own
    # `expanduser`, so a `~/x` that the op had stat-ed literally was reported
    # as the expanded path — one that existed, and that the reader had just
    # listed. The receipt named a path the tool never touched (#1300). Ops
    # now receive the expansion from the containment gate, so the two agree;
    # where they cannot (an unknown `~user`), the literal is what is shown
    # because the literal is what was opened.
    tried = os.path.abspath(path)
    # Every path this helper *renders* is flattened; every path it *uses* is
    # not (#1019). The four lines below are the tool's own, at column 0, and a
    # filename is whatever the filesystem accepted — `str.splitlines()` breaks
    # on ten separators (#886), so `a<U+2028>[result] …` wrote a forged marker
    # line into the middle of a refusal. The stat, the abspath and the join
    # above still run on the real name, so the receipt keeps naming the path
    # that was actually opened (#1300).
    shown, shown_tried = (
        _flat_field(path, disclose_newline=True),
        _flat_field(tried, disclose_newline=True),
    )
    shown_cwd = _flat_field(os.getcwd(), disclose_newline=True)
    if not suggest and path.startswith("~") and os.path.expanduser(path) == path:
        # `cwd:` provably cannot fix this one: no working directory makes a
        # `~user` resolve. Same reasoning as #734 and #921 — a hint pointing
        # at the one cause that did not apply costs a round-trip and a wrong
        # conclusion.
        suggest = ("`~` was not expanded: no such user. Pass an absolute "
                   "path, or `~/` for your own home.")
    # Exists, wrong kind. Three states, not two: `edit:::a:::b:::docs` used to
    # answer `file not found: docs` about a directory sitting right there — an
    # absence this helper produced, read as an absence in the world — and every
    # line after it (cwd drift, and since #1334 the create clause) was advice
    # for a path that is not the problem. Found writing #1334's create clause,
    # which would otherwise have offered to `paste` a whole file over a
    # directory.
    if os.path.isdir(path):
        return (
            # `{path} is a directory` rather than #630's `{field} is a
            # directory, not a file: {path}`. That shape reads well there
            # because the label is a payload FIELD name (`body_file`); here it
            # is the generic noun "file", and "file is a directory, not a file"
            # is not a sentence.
            f"ERROR: {shown} is a directory, not a file\n"
            f"  tried: {shown_tried} (cwd: {shown_cwd})\n"
            f"  '{op or label}' takes a single file. `ls:{shown}` or "
            f"`tree:{shown}` lists what is in it.\n"
        )
    lines = [
        f"ERROR: {label} not found: {shown}",
        f"  tried: {shown_tried} (cwd: {shown_cwd})",
    ]
    root = None
    if not os.path.isabs(path):
        try:
            root = _project_root_above_cwd()
        except OSError:
            root = None
    if root and os.path.exists(os.path.join(root, path)):
        lines.append(
            f"  exists at "
            f"{_flat_field(os.path.join(root, path), disclose_newline=True)}"
            f" — prefix the call with "
            f"'cwd:{_flat_field(root, disclose_newline=True)}' to run it "
            f"from the project root"
        )
    elif suggest:
        lines.append(f"  {suggest}")
    else:
        lines.append(
            "  wrong CWD? Prefix the call with cwd:PATH to run it from "
            "elsewhere."
        )
        if creates:
            lines.append(f"  {_create_instead_hint()}")
    return "\n".join(lines) + "\n"


def _extract_env_prefix(cmd: str) -> Tuple[Dict[str, str], str]:
    """Split a leading `KEY=VAL KEY2=VAL2 ...` shell env-prefix off `cmd`.

    Returns ({KEY:VAL,...}, remaining_cmd_without_prefix). Mirrors POSIX shell
    semantics: a `KEY=VAL` token before the command sets KEY in the child's
    env. Stops at the first non-assignment token. Tokens are parsed via
    shlex.split, so quoted values (`KEY='one two'`) work.

    Needed because the argv-form fix (#145) broke shipped cmd templates that
    set env this way — `subprocess.run(shlex.split(cmd), shell=False)` treats
    the assignment as a literal argv[0], yielding ENOENT.
    """
    env: Dict[str, str] = {}
    tokens = shlex.split(cmd, posix=True)
    idx = 0
    # `\Z` with DOTALL, not `$`. Two effects, and the second is the wider one.
    # `$` matches before a final newline, so `FOO='bar<LF>' cmd` set FOO to
    # "bar" and dropped the newline the caller quoted on purpose — the
    # assignment still matched, so nothing said so. And without DOTALL a value
    # with a newline *inside* it matched nothing at all, so the whole token
    # fell through as argv[0] and the env was never set; POSIX sets it. Both
    # are the same character deciding where a value ends (#1188).
    # anchored-ok: DOTALL is the point. `(.*)` is meant to reach the true end
    # and keep a newline the caller quoted, so the `\Z` is not the #1241 no-op
    # it reads as -- it states the intent the flag already carries.
    _kv = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)=(.*)\Z", re.DOTALL)
    while idx < len(tokens):
        m = _kv.match(tokens[idx])
        if not m:
            break
        env[m.group(1)] = m.group(2)
        idx += 1
    if not env:
        return {}, cmd
    # Rebuild remaining cmd as shell-safe string so callers can keep using
    # shlex.split on it (the placeholder-substituted file path already
    # passed through shlex.quote upstream, so it survives a second pass).
    remaining = " ".join(shlex.quote(t) for t in tokens[idx:])
    return env, remaining




def _in_template_single_quotes(s: str, pos: int) -> bool:
    r"""Whether `pos` in shell-syntax string `s` sits inside a single-quoted
    span the string ITSELF opens -- the state `_expand_env` needs at each
    `$VAR` match to know whether splicing in `shlex.quote()`'d value would
    nest a second quote pair inside the template author's own (#2291).

    Deliberately narrower than a full POSIX tokenizer, in the same spirit
    as the docstring above it names as the larger alternative: it tracks
    single-quote and double-quote spans and backslash escapes OUTSIDE
    quotes accurately, but inside a double-quoted span it treats every
    backslash as consuming the next character, where POSIX only grants
    that to `\\`, `\"`, `` \` `` and `\$` -- a backslash immediately
    followed by an unescaped `"` in some OTHER escape context could
    therefore misjudge the state. No template shipped in this tree, or
    named in any issue, has that shape; a project-authored one that does
    is the same "differently-shaped value" caveat #2291's own docstring
    already carries for the untracked case, one level further in rather
    than a new gap this introduces.
    """
    in_single = False
    in_double = False
    i = 0
    while i < pos:
        c = s[i]
        if in_single:
            if c == "'":
                in_single = False
        elif in_double:
            if c == "\\":
                i += 2
                continue
            if c == '"':
                in_double = False
        else:
            if c == "\\":
                i += 2
                continue
            if c == "'":
                in_single = True
            elif c == '"':
                in_double = True
        i += 1
    return in_single


def _expand_env(s: str, env: Dict[str, str]) -> str:
    r"""Safe $VAR / ${VAR} expansion from env (no shell).

    Replaces $NAME and ${NAME} with values from env. Unknown vars are left
    literal (vs shell which silently empties them). Used at all argv-form
    dispatch sites (custom ops, validators, formatters, resolve) so users
    can keep cmd templates that rely on env-var expansion without invoking
    a shell.

    **Only ever hand this a SHIELDED string** — the output of
    `_shield_substitute`, never `_substitute_placeholders`. Its subject is the
    template a project wrote, not the argument a caller passed, and it has no
    way to tell them apart once they are one string. Passing it an assembled
    command is #1734: `git-commit:::chore: about $HOME:::f.txt` committed a
    real home directory, and a `$FAKE_TOKEN` in a subject put the token in the
    commit object. A sixth call site that skips the shield reintroduces that
    silently, because the substitution is invisible unless the variable
    happens to be defined on the machine that runs it.

    **Every substituted value is `shlex.quote`d (#2164 CI, four Windows-only
    failures on `tests/test_watch_sources_path_relative_2164.py`).** Every
    call site below builds its command by concatenating this function's
    output onto a template string, then feeds the WHOLE result to
    `shlex.split()` before spawning the child argv-form. A value inserted
    here unquoted is not "no shell" the way the docstring above promised —
    it is untrusted text handed to `shlex.split`'s own POSIX-mode escape
    grammar, where a bare backslash escapes (and drops) the next character.
    An anchored Windows path such as
    ``C:\\\\Users\\\\runneradmin\\\\...\\\\watch-sources``, exported as
    `SUPERTOOL_WATCH_SOURCES_PATH` and referenced as `$SUPERTOOL_WATCH_SOURCES_PATH`
    in a `cmd` template, came back with every single backslash removed —
    `C:UsersrunneradminAppDataLocalTemp...` — not doubled, not converted to
    `/`, consumed outright, because none of the characters that followed each
    backslash formed a real escape pair. `shlex.quote` wraps the value in
    single quotes -- an embedded single quote is closed out and re-opened
    (`'` becomes the four bytes `'"'"'`), never backslash-escaped, but that
    detail does not matter here: what matters is that POSIX `shlex.split`
    treats a backslash inside a single-quoted segment as a literal
    character, not an escape introducer -- matching the treatment
    `{file}`/`{dir}`/`{arg}` already get via `shlex.quote` at every one of
    this function's call sites, and the same reasoning #1734 applied to
    those placeholders one layer up. A defined variable whose value has no
    shell-special characters (the common case — plain words, existing
    shipped `cmd` templates) round-trips through `shlex.quote` unchanged, so
    this narrows nothing that worked before; a caller relying on a `$VAR`
    value being split into SEVERAL argv tokens by `shlex.split` gets it as
    one token instead, which is the same one-token guarantee `{file}` etc.
    already make and is what makes this expansion "no shell" in fact rather
    than only in the docstring.

    **Formerly a known gap, closed by #2291 for the single-quote case:**
    this quoting used to be blind to the template's OWN quoting. A template
    that already wraps a `$VAR` reference in its own single quotes -- the
    shipped example at `docs/notifiers.md`'s `bash -c '...$SLACK_WEBHOOK'`
    pattern -- got a SECOND, nested pair of quotes spliced in when that
    variable's value contained a space or other shell-special character,
    and `shlex.split` has no notion of nested quoting (POSIX shell does not
    either), so the value split back apart at the space, or raised
    `ValueError: No closing quotation` outright for an odd count of special
    characters. `_in_template_single_quotes` below now tracks that state and
    splices the value directly when it is already inside the template's own
    single-quote span, so this case no longer regresses.

    **Still open:** the identical shape inside the template's OWN DOUBLE
    quotes (`bash -c "echo $VAR"`) is untouched -- `_in_template_single_quotes`
    only tracks double-quote spans well enough to know it is not INSIDE a
    single-quote span there, not well enough to splice correctly into one.
    No template shipped in this tree, or named in any issue, uses that
    pattern; a project-authored one that does keeps today's (already
    imperfect, pre-#2291) behaviour. Fixing this needs the substitution to
    track double-quote-specific escaping rules too (POSIX grants a
    backslash real escape power there only before `\`, `"`, `` ` `` and
    `$`), which is a different, larger change than the one this docstring
    documents.
    """
    def _replace(m: "re.Match[str]") -> str:
        name = m.group(1) or m.group(2)
        if name not in env:
            return m.group(0)
        value = env[name]
        if _in_template_single_quotes(s, m.start()):
            # Already inside a single-quote span the TEMPLATE itself opened
            # (docs/notifiers.md's `bash -c '...$SLACK_WEBHOOK'` pattern) --
            # nothing but a literal `'` is special there, so wrapping the
            # value in ANOTHER quote pair (shlex.quote's job below) would
            # nest quotes `shlex.split` has no notion of (#2291). Splice the
            # value directly; a `'` inside it is broken out with the same
            # close-quote/literal-quote/reopen-quote idiom shlex.quote uses
            # internally, just without the wrapping pair this context
            # already provides.
            return value.replace("'", "'\"'\"'")
        return shlex.quote(value)

    return re.sub(
        r'\$\{([A-Za-z_][A-Za-z0-9_]*)\}|\$([A-Za-z_][A-Za-z0-9_]*)',
        _replace,
        s,
    )


def _shield_substitute(
    template: str, values: Dict[str, str],
) -> Tuple[str, Dict[str, str]]:
    """Substitute placeholders with inert tokens, so `_expand_env` cannot see
    the values (#1734).

    `_expand_env`'s subject is the **cmd template** — a project writing
    `$MY_TOOL_HOME` in its own `cmd` and having it resolved without a shell.
    It used to run over the *assembled* command instead, after `{args}` /
    `{arg}` / `{argjoin}` / `{file}` had been interpolated, so it could not
    tell the template's own text from the caller's data and rewrote both:

        git-commit:::chore: about $HOME:::f.txt
        → committed subject "chore: about /Users/<name>"

    `discloses`, and it survived because it is invisible unless the variable
    happens to be defined — an undefined one round-trips byte-exact, so the
    same message behaves differently on another machine. The commit that hit
    it was about to be pushed.

    Substituting a random per-call token first and restoring it after
    expansion, rather than expanding the template before substitution, is what
    keeps the *rest* of the pipeline byte-identical: `_extract_env_prefix`
    still sees a fully substituted string, so a `KEY={dir} cmd` prefix
    resolves as it always did, and an env value that happens to read `{args}`
    is still never re-substituted. Reordering the two would have changed both.

    Tokens are alphanumerics **bracketed by a dot**, which buys four properties
    the restore depends on. `shlex.quote` leaves `.` and `[A-Za-z0-9]` bare, so
    the requote inside `_extract_env_prefix` round-trips; `_expand_env` cannot
    match a token, having no `$`; `_extract_env_prefix`'s `KEY=VAL` test cannot
    match one, having no `=`; and the leading dot TERMINATES a variable name,
    which the bare-alphanumeric first version did not. `[A-Za-z0-9]` is a legal
    continuation of `[A-Za-z_][A-Za-z0-9_]*`, so `cmd $PREFIX{file}` expanded a
    name that ran into the token, found it undefined, and left `$PREFIX`
    literal — a silent regression, because leaving an unknown literal is the
    documented behaviour and nothing distinguishes the two cases. The nonce is
    per call, so no caller value can collide.
    """
    nonce = "STPH" + os.urandom(8).hex()
    tokens: Dict[str, str] = {}
    shield: Dict[str, str] = {}
    for i, name in enumerate(sorted(values)):
        token = f".{nonce}x{i}x."
        tokens[name] = token
        shield[token] = values[name]
    return _substitute_placeholders(template, tokens), shield


def _unshield(s: str, shield: Dict[str, str]) -> str:
    """Put the real placeholder values back into a COMMAND STRING.

    Called after `_expand_env` at every site. The values went in
    `shlex.quote`d and come back out that way, which is what the command
    string wants — `_unshield_env_value` is the variant for the other
    destination.
    """
    for token, value in shield.items():
        s = s.replace(token, value)
    return s


def _unshield_env_value(s: str, shield: Dict[str, str]) -> str:
    """Put the real values back into an ENV VALUE lifted by `_extract_env_prefix`.

    A command string keeps the `shlex.quote`ing; an environment value must not.
    `_extract_env_prefix` tokenises through `shlex.split`, so before shielding
    it stripped the quotes as it lifted `KEY={dir}` — the child got
    ``MYDIR=my dir``. Restoring the quoted form into the value handed it
    ``MYDIR='my dir'``, apostrophes included, for any value `shlex.quote`
    actually quotes. That is invisible for a value needing no quoting, which
    is why the first `{dir}` test round-tripped by accident (#1734 review).

    Re-tokenising the restored value reproduces the pre-shield bytes exactly,
    since the whole assignment was one shlex token by construction. A value
    that will not tokenise is returned as-is rather than dropped: a mangled
    env var is recoverable, a missing one is a silent behaviour change.
    """
    restored = _unshield(s, shield)
    if restored == s:
        return restored  # held no token; never went through shlex.quote
    try:
        parts = shlex.split(restored)
    except ValueError:
        return restored
    return parts[0] if len(parts) == 1 else restored


# Git's repo pointers. Any of these, set anywhere in the parent environment,
# overrides discovery-from-cwd and points a git command at the repository they
# name instead — so an op run from repoB acts on repoA (#692). Proven: a
# `git-commit` with cwd=repoB and GIT_DIR=repoA/.git wrote the commit into
# repoA, and the receipt named no repository at all.
#
# Not hypothetical, and not something the caller has to do to themselves: git
# exports GIT_DIR to every hook it runs, and `.githooks/pre-commit` invokes
# `./supertool 'git-diff:staged'`. This repo hands supertool a leaked git
# environment as a matter of routine.
#
# #416 learned this once and fixed it for the TEST RUNNER (`.githooks/pre-push`
# unsets them before pytest; `tests/conftest.py` again before every test). The
# ops never got the same treatment. This is the same list, kept in one place —
# conftest imports it from here, and a test pins the hook's `unset` line to it,
# because three copies of one lesson is how the ops came to be missed.
#
# Membership rule: does the variable change WHICH repository, index, or refs a
# git command reads or writes? GIT_COMMON_DIR and GIT_NAMESPACE do and were not
# in #416's five — the first redirects config and refs for a worktree, the
# second redirects every ref a push writes. GIT_CEILING_DIRECTORIES and
# GIT_DISCOVERY_ACROSS_FILESYSTEM do not: they only restrict discovery, so the
# worst they cause is finding no repo rather than the wrong one, and people set
# them deliberately on slow network mounts. Scrubbing those would make
# supertool disagree with the user's own shell about where they are.
GIT_ENV_VARS = (
    "GIT_DIR",
    "GIT_WORK_TREE",
    "GIT_COMMON_DIR",
    "GIT_INDEX_FILE",
    "GIT_OBJECT_DIRECTORY",
    "GIT_ALTERNATE_OBJECT_DIRECTORIES",
    "GIT_NAMESPACE",
)

# What `_main` removed from `os.environ` on the way in, so the notice can name
# it after the cwd has settled — the scrub happens before argv is parsed, the
# cwd it acted under is only known after `cwd:`/auto-root.
#
# Per-run scratch, filled in place rather than rebound: a daemon reuses the
# process, and a leak list left over from an earlier call would print a notice
# on a later clean one — #680's lesson about `_SKIP_COUNT`, same shape (#714).
_LEAKED_GIT_ENV: List[str] = []


def scrub_git_env(env: MutableMapping[str, str]) -> List[str]:
    """Delete git's repo pointers from `env`; return the names removed.

    `env` is `os.environ` itself at the one call site (#714), not a copy: a
    `del` there unsets the variable for this process AND for every child it
    spawns, which is what makes the guard total. Typed as a MutableMapping
    rather than a Dict because `os._Environ` is not a dict.
    """
    removed = [name for name in GIT_ENV_VARS if name in env]
    for name in removed:
        del env[name]
    return removed


def _git_env_notice(removed: List[str]) -> str:
    """One line naming what was scrubbed, or "" when nothing was.

    Scrubbed rather than refused: refusing would break the caller this repo
    creates itself — `.githooks/pre-commit` runs `git-diff:staged` under git's
    exported GIT_DIR, and a commit hook that aborts because supertool declined
    is a worse outcome than one that reads the right repo. But scrubbed
    LOUDLY. A silent scrub makes the tool ignore something the caller may have
    set on purpose and say nothing about it — the same "quiet where a loud
    answer belonged" that made the original bug invisible, just pointing the
    other way. The line costs one row of output and is the only thing that
    tells a caller their environment is leaking.

    Said once per call rather than once per op (#714). The scrub is now a
    property of the process, so repeating the line under each of six reads
    would describe one event six times.
    """
    if not removed:
        return ""
    return (
        f"scrubbed inherited git env: {', '.join(removed)} — this call acted "
        f"on the repo at {os.getcwd()}, not the one those variables named "
        f"(#692, #714)\n"
    )


def _declared_value_exits(entry: object) -> FrozenSet[int]:
    """Exit codes this op declares are ANSWERS, not verdicts about the op (#1672).

    `git-worktrees` compresses its occupancy verdict into the process exit
    status — `0 = idle, 1 = occupied, 2 = cannot tell` — and says so in the line
    immediately above the batch footer. The dispatcher read every non-zero child
    exit as a refusal, so three correct answers each rendered `FAIL` and the
    footer said `all 3 refused`, one line under the op's own `the op itself did
    not fail`.

    Not #1291, and not fixable where #1297 fixed that one: dispatch is right that
    the exit was non-zero, and cannot know that for this op non-zero is not
    failure. That is a property of the op, so it is declared where the op's other
    properties are — beside `paths` and `safety` in the registry.

    Tolerant like `_preset_path_decl`: a malformed declaration yields no codes,
    which is the behaviour that predates this and counts every non-zero as a
    refusal. Wrong in the loud direction rather than the quiet one.
    """
    if not isinstance(entry, dict):
        return frozenset()
    decl = entry.get("exitStatus")
    if not isinstance(decl, dict):
        return frozenset()
    values = decl.get("values")
    if not isinstance(values, list):
        return frozenset()
    # `bool` is an `int` in Python and `true` is legal JSON in that slot.
    return frozenset(v for v in values
                     if isinstance(v, int) and not isinstance(v, bool))


def _declared_clean_exits(entry: object) -> frozenset:
    """Which of an op's declared value exits mean "nothing to worry about" (#1705).

    A value-exit scheme spends the exit integer on an answer, and #1672 spent
    it without saying what `0` still had to mean. It kept meaning "the op did
    not fail" and stopped meaning "clear to proceed": `git-worktrees` answered
    `occupied` and supertool exited 0, so `supertool 'git-worktrees:P' && rm -rf
    P` — the consumer shape #1282 records — passed the guard on the one answer
    that exists to stop it.

    So the meaning of each value is the op's to state. `"clean": [0]` beside
    `"values"` names the ones a caller may proceed on; every other declared
    value is an answer supertool will not certify, and it reaches the process
    exit through `_UNCLEAN_VALUE_EXITS` without becoming a refusal.

    `0` is always clean and cannot be declared away here: exit 0 is never read
    as a value exit in the first place (`_resolve_custom_op` gates on non-zero),
    so listing it is documentation and omitting it changes nothing. A malformed
    or missing declaration therefore collapses to `{0}` — tolerant like
    `_declared_value_exits` above, and wrong in the loud direction, since the
    failure mode of guessing here is a caller proceeding on `occupied`.
    """
    if not isinstance(entry, dict):
        return frozenset({0})
    decl = entry.get("exitStatus")
    if not isinstance(decl, dict):
        return frozenset({0})
    clean = decl.get("clean")
    if not isinstance(clean, list):
        return frozenset({0})
    return frozenset({0}) | frozenset(
        v for v in clean if isinstance(v, int) and not isinstance(v, bool))


def _preset_declares_error(body: str) -> bool:
    """Did an op that gave up its exit integer state a failure in its body?

    The other half of the `exitStatus` bargain (#1672). Declaring the exit code
    a value spends the channel a refusal was travelling on, so the failure has to
    arrive somewhere else — and both replacements are conventions this repo
    already runs on: a line at column 0 beginning `ERROR: ` (the refusal form
    `_op_body_failed` reads at the head of every builtin's return), and anything
    on stderr, which is where a traceback lands when a crash exits with a code
    that happens to be declared.

    Any line, not just the first: a preset prints its board before it can know
    that a probe inside it went silent, and `git-worktrees` puts a foreign-copy
    note above its own `ERROR:` arm. Reading the op's own lines rather than the
    rendered receipt is what keeps this out of #1291's territory — and the ops
    that can declare `exitStatus` are ours, so "nothing a stranger named reaches
    column 0" is a guarantee the op makes (`git-worktrees` flattens every
    untrusted field for exactly this reason) rather than one assumed of it.
    """
    return any(line.startswith("ERROR: ") for line in body.splitlines())


def _op_config_collision_refusal(op: str, entry: Any,
                                  config: Dict[str, Any]) -> str | None:
    """ERROR text when `op`'s own config would export a colliding env var (#1009).

    Only ever fires for a key `op` ITSELF declared in the project's "ops"
    section: `config["_op_config_collisions"]` was built from `project_ops`
    alone (`_op_config_key_collisions`), so an op that merely inherits a
    preset's shared vocabulary key (`REPO_TARGET`, `DEFAULT_LIMIT`, ...) is
    never named here — only two ops that picked the same name independently,
    in the same project's own config, for genuinely differing values. A
    value deliberately repeated across a family of ops (this repo's own
    `watch_name: "oss-supertool"` on `channel`/`radar`/`unwatch`/`watch`/
    `watches`) is never a collision at all, so it never reaches this
    function's `collisions` lookup in the first place.
    """
    if not isinstance(entry, dict):
        return None
    collisions = config.get("_op_config_collisions")
    if not isinstance(collisions, dict) or not collisions:
        return None
    for key in entry:
        if not isinstance(key, str) or key in _OP_CONFIG_RESERVED_KEYS:
            continue
        env_key = f"SUPERTOOL_{key.upper()}"
        others = collisions.get(env_key)
        if others and op in others:
            rest = ", ".join(o for o in others if o != op)
            return (
                f"ERROR: `ops.{op}.{key}` in .supertool.json reaches this op "
                f"as `{env_key}`, and `ops.{rest}` declares the same key "
                f"name in the same file. Both would read one shared "
                f"variable with no way for either op to tell whose value it "
                f"got (#1009). Rename one — e.g. "
                f"`{op.replace('-', '_')}_{key}` — or drop the duplicate.\n"
            )
    return None


def _resolve_custom_op(op: str, parts: List[str]) -> str | None:
    """Try to run op as a custom command from config["ops"].

    Runs argv-form (shell=False) — shell metachars in the cmd template are
    literal tokens, not shell operators. `$VAR` / `${VAR}` expansion from
    the op's env is performed by supertool (see _expand_env below), no shell,
    and it reaches THE TEMPLATE ONLY: an argument interpolated through
    `{file}`/`{dir}`/`{arg}`/`{args}`/`{argjoin}` is caller data and is
    shielded from it (#1734).

    Returns formatted output string on match, None if op is not a custom op.
    """
    config = _load_config()
    ops = config.get("ops")
    if not ops or op not in ops:
        return None
    # Cleared before anything can return, so a frame whose op declined without
    # running never inherits the previous frame's verdict. `None` is the third
    # state and it is load-bearing: "did not run" must not read as "failed",
    # and it must certainly not read as "succeeded".
    _CUSTOM_OP_OK[0] = None

    # #678 — this op is defined by whatever tree the cwd resolved to, which is
    # not necessarily the tree this core came from. Decide before running it:
    # once the subprocess has answered, its output is indistinguishable from
    # the right one.
    _mixed = _mixed_tree_pair()
    if _mixed is not None and not _mixed_tree_allowed():
        _bump_counter(_SKIP_COUNT, "cnt_skip")
        return _mixed_tree_decline(op, _mixed)

    entry = ops[op]
    if isinstance(entry, str):
        cmd_template = entry
        timeout = config.get("timeout", 60)
    elif isinstance(entry, dict):
        cmd_template = entry.get("cmd", "")
        timeout = entry.get("timeout", config.get("timeout", 60))
    else:
        return f"ERROR: invalid config for custom op {op!r}\n"

    if not cmd_template:
        return f"ERROR: empty command for custom op {op!r}\n"

    # #1009 — before anything else runs: two ops that each declared their own
    # `ops.<op>.<key>` and landed on the same `SUPERTOOL_<KEY>` got no warning
    # before this, only whichever value its own entry happened to carry. Above
    # the subprocess for the same reason the containment gate below is —
    # once a colliding value has been read, the run it produced is
    # indistinguishable from a correctly configured one.
    _collision = _op_config_collision_refusal(op, entry, config)
    if _collision:
        return _collision

    # #1287 — the universal path chokepoint for preset and custom ops. Builtins
    # have had `_PATH_ARG_POSITIONS` in `_dispatch_impl` since #146; no preset
    # op was ever in it, so a preset op with a path argument enforced
    # containment itself or not at all, and "not at all" was the default for a
    # newly written one. #1283 was one instance of that, not the class.
    #
    # Above the subprocess, not inside it: an out-of-boundary read has already
    # happened by the time any of the op's output could be filtered.
    # Not counted as a skip. `_mixed_tree_decline` above is a skip because it
    # is one — the op could not be run safely and nobody was refused anything.
    # This is the builtin containment gate's twin, which returns its ERROR and
    # touches no counter, and the whole argument of #1287 is that an unchecked
    # path is a refusal rather than a check that could not run.
    _paths = _preset_path_containment(op, entry, parts)
    if _paths:
        return _paths

    # #873 — a token the template cannot carry is refused, not discarded. Kept
    # DOWNSTREAM of the containment gate above on purpose: this adds no path
    # slot and moves none, and a call that both escapes the boundary and drops
    # a token must still report the escape, which is the more severe of the
    # two. Above the subprocess for the same reason as the gate — once the op
    # has run under an argument list nobody asked for, the damage is done and
    # its output is indistinguishable from the one the caller meant.
    _dropped = _unconsumed_arg_tokens(cmd_template, parts)
    if _dropped:
        return _dropped_tokens_refusal(op, entry, cmd_template, _dropped)

    # Build the command — substitute {file}, {dir}, {arg}, {args}, {argjoin},
    # {python} in ONE pass. Chained str.replace calls would rescan the text a
    # previous pass just inserted, so an ARGUMENT VALUE containing a later
    # placeholder token (a commit message mentioning {argjoin}) got expanded
    # inside its own shlex.quote'd value — shattering the quoting and leaking
    # the value's words into argv. One pass never looks at inserted text.
    file_arg = parts[1] if len(parts) > 1 else ""
    dir_arg = os.path.dirname(file_arg) if file_arg else "."
    # {argjoin}: parts[1:] rejoined with ':::' as a single shell-quoted arg.
    # Lets the receiving script split fields itself when they contain colons
    # (e.g. XPath like .//ns:tag or [position()=1]).
    arg_join = ":::".join(parts[1:]) if len(parts) > 1 else ""
    # Shielded (#1734): every value below is CALLER DATA, and `_expand_env`
    # further down used to rewrite a `$NAME` inside one — so a commit message
    # naming `$HOME` was committed with the home directory in it. The values
    # are restored after the expansion, so the template keeps its own `$VAR`
    # feature and the caller's bytes reach the op untouched.
    cmd, _shield = _shield_substitute(cmd_template, {
        "python": _python_token(),
        "file": shlex.quote(file_arg),
        "dir": shlex.quote(dir_arg),
        "arg": shlex.quote(file_arg),
        "args": " ".join(shlex.quote(p) for p in parts[1:]) if len(parts) > 1 else "",
        "argjoin": shlex.quote(arg_join),
    })

    # Pass extra config keys as SUPERTOOL_ env vars
    # `replaces` is reserved because it is metadata for the raw-command guard
    # (#1347), read by the hook and never by the op's own subprocess. Without
    # it every gh-* call would carry a JSON-encoded copy of its own mapping
    # table in SUPERTOOL_REPLACES, which nothing reads.
    # `paths` for the same reason and one more (#1357): it is the containment
    # declaration `_preset_path_containment` has already enforced by the time
    # this line runs, so the subprocess it would reach is the very process the
    # declaration constrains. That is the wrong direction for the information
    # to travel, and nothing reads SUPERTOOL_PATHS — a tree-wide grep returns
    # zero. Reserved rather than left exported with a note, because "our own
    # config, so harmless" is a judgement that has to be re-made by every
    # future reader instead of once, here.
    # `exitStatus` joins them for the same reason as `paths` (#1672): it is a
    # declaration the dispatcher acts on around the subprocess, so exporting it
    # into that subprocess is the wrong direction for the information to travel.
    # `safety` and `repo_target` join for #1757 — both are core-only metadata
    # (safety classification, whether a leading `repo:OWNER/NAME` token is
    # honoured) with no reader in any op's own subprocess.
    # Shared with `_op_config_key_collisions` — see that constant's docstring
    # for why the two must read the same set (#1009).
    _RESERVED_KEYS = _OP_CONFIG_RESERVED_KEYS
    # No scrub here any more (#714). #692 put one on this line because every
    # PRESET op is launched from it — true, and the reasoning holds, but this
    # is the launcher for half the op table. Built-ins never reach it, and core
    # spawns git in six of its own functions. `os.environ` is scrubbed once in
    # `_main` instead, so this copy is already clean and a preset stays covered
    # by being launched rather than by opting in.
    env = dict(os.environ)
    # Which separator produced the argv this op is about to receive (#946).
    # A preset that reconstructs the caller's input — git-commit's spilled
    # message refusal is the one that does — cannot otherwise tell ':::' from
    # ':' from a payload whose fields were never split, and rejoining on the
    # wrong one hands back a suggestion that silently rewrites the message.
    env["SUPERTOOL_ARG_SEP"] = _ARG_SEP[0]
    if isinstance(entry, dict):
        for k, v in entry.items():
            if k not in _RESERVED_KEYS:
                # A relative entry in a search-path key (`watch_sources_path`)
                # is anchored to the declaring config file's directory before
                # export, so what the subprocess inherits — and what a poller
                # re-derives after any number of re-execs — is already an
                # absolute path (#2164). Only fires with a config file to
                # anchor against; a value with none (arrived through the raw
                # environment with no `.supertool.json` at all — `_CONFIG_PATH`
                # is unset) is untouched and keeps the absolute-only rule
                # `sourcepath.resolve()` itself still enforces.
                if (k in _RELATIVE_SEARCH_PATH_KEYS and isinstance(v, str)
                        and _CONFIG_PATH):
                    v = _anchor_relative_search_path(v, _CONFIG_PATH)
                # Strings pass through verbatim (e.g. CSV "error_patterns").
                # Non-scalars (lists/dicts, e.g. "job_patterns") are JSON-encoded
                # so the receiving preset can json.loads them back — str() would
                # emit a Python repr that json.loads can't parse.
                env[f"SUPERTOOL_{k.upper()}"] = v if isinstance(v, str) else json.dumps(v)

    _prefix_env, cmd = _extract_env_prefix(cmd)
    # Unshield the prefix VALUES too: `KEY={dir} cmd` puts caller data in one,
    # and it has to reach the child's environment as the real path (#1734).
    _prefix_env = {k: _unshield_env_value(v, _shield) for k, v in _prefix_env.items()}
    env.update(_prefix_env)
    cmd = _unshield(_expand_env(cmd, env), _shield)

    t0 = time.monotonic()
    try:
        # argv-form (shell=False) — shell metachars in the template become
        # literal tokens, not shell operators. Placeholder values are still
        # shlex.quote'd above so values containing spaces survive shlex.split.
        # encoding is pinned rather than left to the locale: presets print
        # ✓/✗/⚠ as UTF-8, and a cp1252 default decodes those three bytes into
        # three wrong characters, so the receipt renders mojibake for an op
        # that worked. errors="replace" keeps a preset emitting genuinely
        # undecodable bytes from taking the whole run down with it.
        result = subprocess.run(
            shlex.split(cmd), shell=False, capture_output=True, text=True, timeout=timeout,
            encoding="utf-8", errors="replace", env=env,
        )
        elapsed = _elapsed_since(t0)
        output = result.stdout
        # A declared value exit is an answer, so the verdict comes from the two
        # channels the declaration leaves the op (#1672). Only for a NON-ZERO
        # code: exit 0 has always been a pass here whatever it printed, and
        # widening that is a different change with a different blast radius.
        _value_exit = (result.returncode != 0
                       and result.returncode in _declared_value_exits(entry))
        _failed = result.returncode != 0
        if _value_exit:
            _failed = bool(result.stderr.strip()) or _preset_declares_error(output)
        _CUSTOM_OP_OK[0] = not _failed
        # #1705 — the answer is not a refusal (that is #1672, and it stands),
        # but an answer the op does not declare clear-to-proceed must not leave
        # the process exiting 0. It travels the same road as a skipped write and
        # a rolled-back edit: a per-call list `_main` reads as a delta, never
        # `_mark_op_failure`, so the receipt keeps saying PASS and the batch
        # footer keeps not saying `refused`.
        _unclean_value = (
            _value_exit and not _failed
            and result.returncode not in _declared_clean_exits(entry))
        if _unclean_value:
            _UNCLEAN_VALUE_EXITS.append(f"{op} exited {result.returncode}")
        if _failed:
            if result.stderr:
                output += result.stderr
            return f"FAIL ({elapsed:.2f}s)\n{output}"
        # A deliberate mix still never prints a bare PASS — the verdict line
        # carries which two trees produced it (#678).
        _stamp = f" [{_mixed_tree_note(_mixed)}]" if _mixed is not None else ""
        # PASS beside a non-zero child exit has to say why it is one, on the
        # verdict line, or the reader is left to reconcile it against the op's
        # own exit note further down (#1496's rule, #1672's case).
        _value_note = (f" [exit {result.returncode} is this op's answer, not a "
                       f"verdict — its registry entry declares the exit code a "
                       f"value]") if _value_exit else ""
        # And when that value is not one the op declares clear to proceed, the
        # same line has to carry why supertool itself exits non-zero — a single
        # op prints no batch tally, so this is the only place a reader gets it.
        if _unclean_value:
            _value_note = (f" [exit {result.returncode} is this op's answer, not "
                           f"a verdict — its registry entry declares the exit "
                           f"code a value, and not one it declares clear to "
                           f"proceed. The op did not fail; supertool exits "
                           f"non-zero so a `&&` guard does not read this answer "
                           f"as permission]")
        return (f"PASS ({elapsed:.2f}s){_stamp}{_value_note}\n"
                f"{output}{_maybe_restart_mcp(entry)}")
    except subprocess.TimeoutExpired as e:
        # Not `_elapsed_since`: the freeze it applies zeroes the one number
        # this line exists to report (#727).
        return (f"{_timeout_verdict_line(t0, timeout)}\n"
                f"{_timeout_partial_output(e)}")
    except OSError as e:
        return f"FAIL: {e}\n"


def _timeout_partial_output(exc: subprocess.TimeoutExpired) -> str:
    """Whatever the killed command printed before the clock ran out.

    Dropping it costs the caller the only evidence of how far the op got — for
    an op that mutates remote state (a push), the difference between "retry" and
    "already landed" was sitting in that discarded buffer (#399).
    """
    chunks = []
    for stream in (exc.stdout, exc.stderr):
        if not stream:
            continue
        text = stream.decode("utf-8", "replace") if isinstance(stream, bytes) else stream
        if text.strip():
            chunks.append(text if text.endswith("\n") else text + "\n")
    if not chunks:
        return ""
    return "--- partial output before timeout ---\n" + "".join(chunks)


def _maybe_restart_mcp(entry: object) -> str:
    """SIGTERM the warm MCP daemons a custom op asks to restart via `restartMcp`.

    A custom op that invalidates state the warm LSP daemons cache (autoload map,
    PHPStan result cache, etc.) can declare `restartMcp` so the daemons are
    stopped after the cmd succeeds; the next op that touches each server
    cold-starts a fresh daemon that re-reads the cleared state. Accepts:
      true       -> every server in the config "mcp" block
      ["a","b"]  -> only those servers
      "name"     -> a single server
    Names not present in the config "mcp" block are reported separately instead
    of being counted as restarted, so the status line never claims to have
    stopped a daemon that was never configured. Returns a one-line status suffix
    (empty when nothing to restart). Best-effort like the new-file path — a stop
    failure never fails the op.

    A stop that failed is reported as failed rather than counted as a restart
    (#547). This is the one caller that already asserts an outcome out loud, so
    the honest version costs no new noise — only the false claim goes away. A
    daemon that would not die keeps answering from the index it captured before
    the op cleared the state, which is exactly what `restartMcp` exists to
    prevent, so the reader needs to know it did not happen.
    """
    if not isinstance(entry, dict):
        return ""
    spec = entry.get("restartMcp")
    if not spec:
        return ""
    if spec is True:
        names = list(_mcp_specs.keys())
    elif isinstance(spec, list):
        names = [str(n) for n in spec]
    else:
        names = [str(spec)]
    known = [n for n in names if n in _mcp_specs]
    unknown = [n for n in names if n not in _mcp_specs]
    restarted, failed = [], []
    for name in known:
        outcome = _mcp_stop_server(name)
        (restarted if outcome.ok else failed).append(name)
    # Through `_flat_keys`, like the payload-key refusals of #1583, and for the
    # same mechanism: a server name is an arbitrary JSON string, `restartMcp`
    # accepts it verbatim, and `', '.join` would put a line of that string's
    # choosing at column 0 inside a line supertool signs — a second
    # `mcp: restarted 9 daemon(s)` the tool never said. Lower severity than
    # #1583's, and named rather than assumed: these come from
    # `.supertool.json`, which #146's trust note places at the same level as
    # the validators and custom ops it declares alongside them. Done anyway
    # because the alternative is one call cheaper and the reasoning has to be
    # re-derived by every reader who checks (#1489 release audit).
    note = ""
    if restarted:
        note += (f"mcp: restarted {len(restarted)} daemon(s) "
                 f"({_flat_keys(restarted)})\n")
    if failed:
        note += (f"mcp: FAILED to stop {len(failed)} daemon(s) ({_flat_keys(failed)})"
                 f" — they may still answer from a stale index"
                 f" (SUPERTOOL_DEBUG=1 for the reason)\n")
    if unknown:
        note += f"mcp: unknown server(s) ignored ({_flat_keys(unknown)})\n"
    return note


_IN_ALIAS = False  # recursion guard — prevents alias-from-alias expansion


def _resolve_alias(op: str, parts: List[str]) -> str | None:
    """Try to expand op as an alias from config["aliases"].

    Returns concatenated output of all expanded ops, None if not an alias.
    Aliases expand to ops (built-in or custom) but NOT to other aliases.
    """
    global _IN_ALIAS
    if _IN_ALIAS:
        return None  # block recursive alias expansion

    config = _load_config()
    aliases = config.get("aliases")
    if not aliases or op not in aliases:
        return None

    alias_def = aliases[op]
    if not isinstance(alias_def, dict):
        return f"ERROR: alias {op!r} must be an object with 'ops' key\n"

    op_list = alias_def.get("ops", [])
    if not isinstance(op_list, list):
        return f"ERROR: alias {op!r} 'ops' must be a list\n"

    if not op_list:
        return ""

    # Replace {file}, {dir}, {arg}, and {args} placeholders in each expanded op
    file_arg = parts[1] if len(parts) > 1 else ""
    dir_arg = os.path.dirname(file_arg) if file_arg else "."
    all_args = " ".join(parts[1:]) if len(parts) > 1 else ""

    _IN_ALIAS = True
    try:
        output_parts: List[str] = []
        alias_values = {
            "file": file_arg, "dir": dir_arg,
            "arg": file_arg, "args": all_args,
        }
        for expanded_op in op_list:
            # Single pass — same reason as _resolve_custom_op: a path or
            # argument containing '{args}' must not expand itself.
            resolved = _substitute_placeholders(expanded_op, alias_values)
            output_parts.append(dispatch(resolved))
        return "".join(output_parts)
    finally:
        _IN_ALIAS = False


# ---------------------------------------------------------------------------
# Core operations (pure functions — all return the string to emit)
# ---------------------------------------------------------------------------

def _read_narrowing_hint(path: str) -> str:
    """The two ways out of a whole-file read that did not come back whole (#1811).

    A large `read:PATH` renders the file's **head** and stops. The head is the
    region least likely to be why the file was read, so the preview is often
    paid for and unusable — and until now the stop was disclosed with no way
    out attached: `... (N more lines)` named no remedy at all, and the byte-cap
    footer named only `read:PATH:OFFSET:LIMIT`, the one spelling this repo has
    three issues of evidence that callers read as START:END (#382, #1417,
    #1489). Naming the remedy where the caller is standing is what `between:`'s
    refusal already does: it suggests its own narrowing form at the moment it
    declines, rather than after the reader has paid.

    The preview is kept. Dropping it in favour of a structure block was the
    other candidate and loses more than it saves: the head is what tells the
    caller what kind of file this is, which is the input to writing the
    narrowing call these two lines ask for.
    """
    return (f"    ↳ that is the head of the file — for a region, "
            f"read:{path}:START-END; to find one, "
            f"read:{path}:::grep=PATTERN" + "\n")


def render_file(path: str, offset: int = 0, limit: int = 0,
                grep_filter: str = "", force_full: bool = False,
                range_form: bool = False, *,
                limit_defaulted: bool | None = None) -> str:
    """Emit a file's contents with line numbers, truncated at caps.

    Shared by read: and by grep/glob auto-promote branches.
    When grep_filter is set, only lines matching the regex are shown (with
    original line numbers preserved).
    When rtk is available and no special options are used, delegates to
    rtk read for compressed output.

    Enforces _safe_path containment (closes #146) — the path must resolve
    under cwd unless SUPERTOOL_ALLOW_OUTSIDE_CWD=1 is set. Catches read
    attempts against /etc/passwd, ~/.ssh/*, .max/*token*, etc.
    """
    try:
        _safe_path(path)
    except SecurityError as e:
        return f"ERROR: {e}\n"
    # Behind the check that just cleared it (#1300). Dispatch already hands
    # this an expanded path; the rebind is for the internal callers this
    # chokepoint exists to catch — alias expansion and direct `render_file`
    # calls — so the string opened is the string checked here too.
    path = _expand_home(path)
    # A caller who names no LIMIT alongside `grep=` is asking about the file,
    # not about the file's first `read.max_lines` lines (#1052). Recorded here,
    # before the default lands, because afterwards the two are indistinguishable.
    filter_scan_all = bool(grep_filter) and limit <= 0
    # Which of two bounds the window note will be naming (#1820). "The limit"
    # was one word for two facts: a LIMIT the caller typed, which is a window
    # they closed themselves and needs no action, and the `read.max_lines`
    # default below, which is the op's own cap on output standing in for a
    # bound nobody named — the one that hides the rest of the file. Recorded
    # here, before the default lands, because afterwards they are the same
    # integer (the same reason `filter_scan_all` is recorded on the line above).
    # `filter_scan_all` is excluded: it re-synthesises LIMIT to reach EOF, so
    # the bound that ends that read is the file, not either of these two.
    # Three states, not two, and the default is the third. `False` is a
    # positive claim — "the caller typed this bound" — and a call site that
    # pre-resolves `read.max_lines` into the LIMIT slot cannot be told from one
    # that typed 300, so a `False` default is inherited silently by exactly the
    # callers who know least. All three auto-read sites did that, and the
    # footer then told a `glob:PATH` caller `lines 1-300 are the whole window
    # asked for, nothing was cut` while the default had cut 100 lines and
    # nobody had asked for a window at all. `None` means the caller did not
    # say; neither verdict is printed, which is the honest answer rather than
    # the flattering one.
    if limit_defaulted is None and limit <= 0 and not filter_scan_all:
        limit_defaulted = True
    if limit <= 0:
        limit = _get_op_int("read", "max_lines", MAX_READ_LINES)
    if not path or not os.path.isfile(path):
        return _path_not_found(path, label="file", op="read",
                               call_prefix="read")

    # #1786: set before the branch below runs, so the native path further
    # down can tell "rtk was never tried" from "rtk was tried and its output
    # was discarded as malformed" -- both leave `rtk_out` unset, but only the
    # second is worth disclosing to the caller.
    rtk_malformed = False
    # RTK delegation — simple reads without offset/filter/limit changes
    if not grep_filter and offset == 0 and limit == _get_op_int("read", "max_lines", MAX_READ_LINES) and _rtk_enabled() and _has_rtk():
        rtk_args = ["read", "-n", "--max-lines", str(_get_op_int("read", "max_lines", MAX_READ_LINES))]
        rtk_used_aggressive = _is_compact()
        if rtk_used_aggressive:
            rtk_args += ["--level", "aggressive"]
        rtk_args.append(path)
        rtk_out = _rtk_run(rtk_args)
        # #1786: rtk's own compression can render a real content line
        # sandwiched between two contradicting elision markers -- a bug in
        # `rtk` itself (see `_rtk_output_looks_malformed`'s docstring), not
        # in this module. Trusting that wholesale turned a third party's
        # corruption into a plausible-looking answer about the file; a
        # malformed render is discarded here and the call falls through to
        # the native renderer below instead, which is disclosed rather than
        # silently swapped in. `aggressive=` is threaded through rather than
        # re-derived: `--level aggressive` legitimately renders several
        # elision markers in one correct output (one per compacted function
        # body), which the detector must not mistake for this corruption.
        rtk_malformed = rtk_out is not None and _rtk_output_looks_malformed(
            rtk_out, aggressive=rtk_used_aggressive)
        if rtk_out is not None and not rtk_malformed:
            # rtk renders the body, but the line-numbering disclosure is
            # supertool's own contract and rtk knows nothing about it. A
            # delegated read that stays silent is the same silence #1060 is
            # about, one layer down.
            _more = ""
            try:
                with open(path, "rb") as _probe:
                    _raw = _probe.read()
                _ambiguity = _line_break_ambiguity_note(_raw)
                # The delegated branch is the one that fires by default where
                # #1811 was reported, and it returned rtk's render unchanged —
                # so the narrowing advice added to supertool's own footers
                # below would never have reached that caller. rtk owns the
                # preview and its own "N more lines" footer; it knows nothing
                # about supertool's call forms, which is the same argument the
                # line-numbering disclosure above is here for.
                #
                # The gate is supertool's own bounds, not a parse of rtk's
                # output: a file over either cap could not have come back whole
                # from a whole-file read under any renderer. That under-fires
                # where rtk compresses a file supertool would have returned
                # intact — the safe direction, since a hint printed on a
                # complete read is advice nobody reads.
                if (len(_split_lines_keepends(_raw))
                        > _get_op_int("read", "max_lines", MAX_READ_LINES)
                        or len(_raw)
                        > _get_op_int("read", "max_bytes", MAX_READ_BYTES)):
                    _more = _read_narrowing_hint(path)
            except OSError:
                _ambiguity = ""
            return _ambiguity + rtk_out + _more + "\n"

    try:
        size = os.path.getsize(path)
        with open(path, "rb") as f:
            data = f.read()
    except OSError as e:
        return f"ERROR: could not read {path}: {e}\n"
    # One definition of a line, shared with the ops that edit *by* line number
    # (#1060). `bytes.splitlines` already was this definition; going through the
    # helper is what stops the two sides drifting apart a second time.
    raw_lines = _split_lines_keepends(data)

    line_count = len(raw_lines)
    if filter_scan_all:
        # A filter is not a window. `read.max_lines` bounds how much is
        # *emitted*; applying it to how much is *searched* made the inline
        # filter answer `(no lines matching X)` about a file whose only match
        # sat at line 328 of 351 — a confident negative produced by the default
        # LIMIT, not by the file (#1052). The byte cap below still bounds the
        # output, and a filtered read emits only the lines that matched.
        limit = max(0, line_count - offset)
    out = [f"({line_count} lines, {size} bytes{_read_freshness_note(path)})"
           f"{_path_meta_suffix(path, b''.join(raw_lines[:64]))}\n"]
    if rtk_malformed:
        # #1786: disclosed rather than silently swapped in -- the caller
        # gets the native render either way, but only this line says the
        # first attempt was thrown away and why.
        out.append(
            "(rtk's compressed read looked malformed for this file -- "
            "falling back to the built-in renderer; #1786)\n")
    _ambiguity = _line_break_ambiguity_note(data)
    if _ambiguity:
        out.append(_ambiguity)
    bytes_emitted = 0
    printed = 0
    end = min(offset + limit, line_count)
    # When invoked outside Claude Code, the 25KB hook limit doesn't apply —
    # so `:full` from a human shell should return the whole file uncapped.
    in_claude = os.environ.get("CLAUDE_CODE_ENTRYPOINT", "") != ""
    byte_cap = _get_op_int("read", "max_bytes", MAX_READ_BYTES)
    apply_byte_cap = in_claude or not force_full
    # Two separate lifts, and they were one flag. `full` removes the DEFAULT
    # line cap; it does not remove a window the caller typed. Without the
    # `range_form` guard, `read:f:2-4:full` from a human shell returned lines
    # 2..EOF — and the window note, keyed off the same flag, relabelled it
    # `range 2-8 (START-END form)` and then said the stop had no reason it could
    # name. That is this lane's defect one level worse than a drop: the
    # discarded END laundered by the line written to disclose it. The byte cap
    # stays lifted, which is the rest of what `full` means, so
    # `read:BIG:1-5000:full` still comes back whole (#1582).
    lift_line_cap = not apply_byte_cap and not range_form
    if lift_line_cap:
        end = line_count  # ignore line cap too when human asks for full file

    filter_regex = None
    filter_literal_why = ""
    if grep_filter:
        try:
            filter_regex = re.compile(grep_filter)
        except re.error as e:
            # The fallback is right — an unusable regex should not fail a read.
            # The silence was not: the literal search's zero was rendered in the
            # same words as a real absence, so a rejected pattern read as a
            # missing string (#1052).
            filter_regex = re.compile(re.escape(grep_filter))
            filter_literal_why = str(e)

    compact = not filter_regex and _is_compact()
    matched_any = False
    # `printed` counts *emitted* lines; the two `continue`s below advance the
    # read without incrementing it. `offset + printed` is therefore neither
    # where reading stopped nor how much of the file is left, and every count
    # in this render that was derived from it named a line that was not the
    # last one shown (#945). `last_scanned` is the 1-based index of the last
    # line the loop actually looked at, which is the only honest answer to
    # both questions.
    last_scanned = offset
    capped = False
    for i in range(offset, end):
        last_scanned = i + 1
        try:
            line = raw_lines[i].decode("utf-8", errors="replace")
        except Exception:
            line = "<binary line>\n"
        if filter_regex and not filter_regex.search(line):
            continue
        if compact and _COMPACT_SKIP.match(line):
            continue
        matched_any = True
        numbered = f"{i + 1:>6}→{line}"
        out.append(numbered)
        bytes_emitted += len(numbered)
        printed += 1
        if apply_byte_cap and bytes_emitted >= byte_cap:
            capped = True
            break

    # The cap is tested AFTER a whole line has been emitted, so it never
    # truncates a line — it drops the ones that would have come next. When the
    # loop stopped at `end` there were none to drop, and calling that a
    # truncation contradicted `grep`'s byte-exact remedy in the very render it
    # sends the caller to (#1616).
    cap_cut = capped and last_scanned < end
    unsearched = 0
    # Collected rather than appended: every line in here is a note *about* the
    # scan, and it is inserted above the content at the end of this function.
    # See the insert below for why.
    filter_notes: List[str] = []
    if filter_regex:
        unsearched = line_count - (last_scanned - offset)
        if filter_literal_why:
            filter_notes.append(
                f"(the grep= pattern is not a usable regex — "
                f"{filter_literal_why}; searched for it as a literal "
                f"string instead)\n")
    if filter_regex and not matched_any:
        if unsearched > 0 and last_scanned <= offset:
            # The loop never ran, so `last_scanned` is still `offset` and the
            # range below would read `1001-1000` -- a span whose start is past
            # its end. The count was right and the range naming it was not, and
            # a disclosure that reads as nonsense is not read (PR #1057
            # review).
            filter_notes.append(
                f"(no lines matching {grep_filter!r} -- offset "
                f"{offset + 1} is past the end of this {line_count}-line "
                f"file, so no line was searched and this is not an answer "
                f"about the file)\n")
        elif unsearched > 0:
            # Three states, not two: found, not found, and did-not-look. The
            # old single line said the second when it meant the third (#1052).
            plural = "s" if unsearched != 1 else ""
            verb = "were" if unsearched != 1 else "was"
            filter_notes.append(
                f"(no lines matching {grep_filter!r} in lines "
                f"{offset + 1}-{last_scanned} of {line_count} — the other "
                f"{unsearched} line{plural} {verb} NOT searched, so this is "
                f"not an answer about the whole file)\n")
        else:
            filter_notes.append(
                f"(no lines matching {grep_filter!r} in any of "
                f"{line_count} lines)\n")
        # #1435, and only over the lines the loop actually read: the branch
        # above where `last_scanned == offset` has already said nothing was
        # searched, and "matches nothing here either" over an empty window
        # would contradict it with a second, more confident absence.
        if last_scanned > offset:
            def _filter_probe(inner: str) -> bool:
                rx = _compile_lenient(inner)
                for raw in raw_lines[offset:last_scanned]:
                    try:
                        candidate = raw.decode("utf-8", errors="replace")
                    except Exception:
                        continue
                    if rx.search(candidate):
                        return True
                return False

            filter_notes.append(_quote_pair_note(grep_filter, _filter_probe))
    elif filter_regex and cap_cut:
        # `cap_cut`, not `capped`: the cap is only what stopped the scan when
        # the loop broke before the window's own end. A limit that ended the
        # scan on a line that happened to carry the total over the cap left
        # lines unsearched too, and blaming the cap for them attributes the
        # limit's work to the wrong bound — the same misattribution #1616
        # removed one render over, found reviewing that fix.
        #
        # The byte cap breaks the scan loop, not just the emission: a filtered
        # read that matched and *then* hit the cap has stopped looking. This
        # used to fall through to the generic `elif capped:` wording below,
        # which offers `(R more lines)` — a phrase a reader can only take as
        # "R lines that did not match". That is the same absence-read-as-
        # presence #1052 was filed to remove, left standing in the one case
        # where the file is large enough for it to cost something (PR #1057
        # review).
        plural = "s" if unsearched != 1 else ""
        verb = "were" if unsearched != 1 else "was"
        if unsearched > 0:
            filter_notes.append(
                f"(the grep= filter searched lines {offset + 1}-"
                f"{last_scanned} of {line_count} and stopped there — the "
                f"output reached the {byte_cap}-byte cap, so the other "
                f"{unsearched} line{plural} {verb} NOT searched and this is "
                f"not an answer about the whole file — continue with "
                f"read:PATH:{last_scanned}:LIMIT:grep=PATTERN)\n")
        else:
            filter_notes.append(
                f"(the grep= filter searched all {line_count} lines; the "
                f"output reached the {byte_cap}-byte cap on line "
                f"{last_scanned}, the last line of the file)\n")
    elif filter_regex and unsearched > 0:
        plural = "s" if unsearched != 1 else ""
        verb = "were" if unsearched != 1 else "was"
        filter_notes.append(
            f"(the grep= filter searched lines {offset + 1}-{last_scanned} "
            f"of {line_count} — {unsearched} line{plural} outside that range "
            f"{verb} NOT searched)\n")
    elif cap_cut:
        remaining = line_count - last_scanned
        out.append(
            f"... (truncated at {_get_op_int('read', 'max_bytes', MAX_READ_BYTES)} bytes "
            f"— showed lines {offset + 1}-{last_scanned} of {line_count} "
            f"({remaining} more line{'s' if remaining != 1 else ''}) — "
            f"use read:PATH:OFFSET:LIMIT to get more)\n"
        )
        if offset == 0 and limit_defaulted is True and not force_full:
            out.append(_read_narrowing_hint(path))
    elif not filter_regex and last_scanned < line_count:
        # `... (N more lines)` on its own is #1820 all over again, in the one
        # shape the window note cannot reach: `_read_window_note` fires only
        # when `offset > 0`, and a range starting at line 1 has an offset of 0.
        # So `read:PATH:1-50` — asked for, delivered whole — and a plain
        # `read:PATH` the `read.max_lines` default cut at 50 closed with the
        # SAME bare footer, byte for byte. One caller has everything they
        # asked for and the other is missing 150 lines to a bound they never
        # set. Found by the audit of the first commit of this fix, which is
        # why it is a second hunk rather than part of the first.
        why = ""
        if limit_defaulted is True:
            why = (f" — the read.max_lines default of {limit} stopped the "
                   f"read here, not the file")
        elif limit_defaulted is False and last_scanned >= offset + limit:
            # `nothing was cut` is claimed only when nothing was suppressed.
            # Under compact mode blanks and comments ARE dropped from the
            # output, and this footer — unlike the window note — has no `held`
            # clause beside it to say so, so the bare phrase would be a false
            # claim standing alone. What stays true either way is which bound
            # ended the window, which is the fact #1820 is about.
            intact = "" if compact else ", nothing was cut"
            why = (f" — lines {offset + 1}-{last_scanned} are the whole window "
                   f"asked for{intact}; those {line_count - last_scanned} "
                   f"are simply below it")
        out.append(f"... ({line_count - last_scanned} more lines{why})\n")
        # #1811: this footer disclosed the stop and named no way out at all —
        # the weaker of the two, and the one a plain `read:PATH` on a long file
        # actually lands on. Gated on `limit_defaulted` rather than on
        # `offset == 0`: the caller this advice is for is the one who named no
        # window at all, and a caller who typed `read:PATH:1-50` has already
        # demonstrated they know the forms. Advice printed on every read is
        # advice nobody reads.
        if offset == 0 and limit_defaulted is True and not force_full:
            out.append(_read_narrowing_hint(path))
    elif not filter_regex and offset > 0:
        # `[complete file — no more lines]` after a windowed read was a plain
        # falsehood: lines 1-OFFSET were never emitted, and when OFFSET sits
        # past EOF *nothing* was emitted and the render still said the whole
        # file had been shown (#945). The empty case is left to the window
        # note, which is the only line that can honestly describe it.
        if printed:
            out.append(f"[end of file — lines 1-{offset} not shown]\n")
    elif not filter_regex:
        out.append("[complete file — no more lines]\n")
    if filter_notes:
        # Header position, above the content, for #955's reason rather than by
        # analogy with it: "Construction order is not render order, and a note
        # that arrives after the wrong window has already been paid for is
        # barely a note." That is an argument about what the reader has spent
        # by the time the correction reaches them, and it was made about this
        # same `out` list in this same function. A filtered read that emits
        # 20 KB of matches and only then admits 308 lines were never searched
        # charges for the wrong answer first and corrects it afterwards
        # (PR #1057 review).
        for note in reversed(filter_notes):
            out.insert(1, note)
    if offset > 0:
        # Inserted at index 1 — after the count header, before the first line
        # of content. Construction order is not render order, and a correction
        # the caller reads *after* paying for the wrong window is not a
        # disclosure (#945).
        window_note = _read_window_note(
            path, limit if not lift_line_cap else max(0, line_count - offset),
            offset, line_count, printed,
            last_scanned=last_scanned, capped=cap_cut, cap_reached=capped,
            byte_cap=byte_cap if apply_byte_cap else 0,
            limit_synthetic=lift_line_cap,
            limit_defaulted=limit_defaulted,
            range_form=range_form,
            skipped_by=("the grep= filter" if filter_regex
                        else "compact mode" if compact else ""))
        out.insert(1, window_note)
        # Repeated at the foot too, but only above FOOTER_ECHO_MIN_LINES
        # printed lines (#1777): the header copy is what a caller reading
        # top-down sees first, but a window long enough to fill the context
        # (`read:PATH:195:300`, a 189-line window in the reported case)
        # pushes it off-screen before the content it corrects is even
        # reached. The foot is what a caller who jumps to the tail of a long
        # read actually lands on, so the same correction has to be there too
        # -- the identical string, not a shortened restatement, so the two
        # copies cannot drift apart. Gated rather than unconditional: #1489
        # and #382 already pin "one disclosure, above the body" for a window
        # that fits on a screen (48 printed lines, neither test's window
        # anywhere near this one's problem size), and an unconditional
        # second copy broke that contract on CI for every offset>0 read,
        # however small (review round found after this PR opened).
        if printed > FOOTER_ECHO_MIN_LINES:
            out.append(window_note)
    out.append("\n")
    return "".join(out)


def _read_window_note(path: str, limit: int, offset: int,
                      line_count: int, shown: int, last_scanned: int = 0,
                      capped: bool = False, cap_reached: bool = False,
                      byte_cap: int = 0,
                      limit_synthetic: bool = False,
                      limit_defaulted: bool | None = None,
                      range_form: bool = False,
                      skipped_by: str = "") -> str:
    """One line naming the window the caller asked for and the window actually
    returned, emitted for every `read` with a non-zero OFFSET (#945).

    OFFSET is a *skip count*, so `read:f:19:1` renders line 20 and line 19 is
    absent from the output entirely. Nothing in the old render distinguished
    "here is line 19" from "here is a line near 19", so a caller quoting the
    result into a brief or an issue quoted the wrong line with full confidence.

    The window is disclosed rather than the semantics changed: `read:PATH:A-B`
    already spells 1-based inclusive addressing, and silently re-basing OFFSET
    would break every caller who had it right — trading a visible wrong answer
    for an invisible one.

    The correction fires for every non-range read with a non-zero OFFSET, and
    names TWO ranges: `read:PATH:{offset+1}-{offset+limit}` is the window that
    actually came back, and `read:PATH:{offset}-{offset+limit-1}` is the one a
    caller who read `:A:B` as START:END was after. Until #1417 only the second
    was offered, and only when LIMIT <= OFFSET, deferring the wider band to
    `_read_range_note` (#382 — deleted in #1489, which folded its clause into
    this line; only its gate survives, as `_range_note_fires`). That deferral
    was to a speaker itself gated — on overshoot, or LIMIT < 2*OFFSET — so
    `read:f:1:40` on a long file
    tripped neither and got no hint at all. That shape is #1138's own archetype
    and, measured over 5,598 real `read:PATH:N:M` calls in this machine's
    transcripts, 1,877 of them (34%) sat in the same hole.

    The parse is NOT changed, and the two candidates #1138 proposed were both
    measured before being declined: refusing `:N:M` outright hits all 5,549
    calls with a non-zero OFFSET, and re-reading it as START-END when N < M
    hits 3,208. Neither number is a rounding error, and a refusal that breaks a
    form callers legitimately use is a regression dressed as a fix.

    A window ends at one of FOUR bounds and the note names which: a LIMIT the
    caller typed, the `read.max_lines` default they did not (#1820 — one word
    was covering both, and they want opposite responses), the file ending, or
    the byte cap cutting it short. Naming the bound is not the same as saying
    whether it cost anything, so a window that ended at a caller-set bound with
    nothing dropped also says `nothing was cut`; EOF is excluded because it
    settles that in its own words below, and a real cap cut is the state the
    clause distinguishes from. The first
    version of this note computed the shortfall against the requested end and
    attributed all of it to EOF, so a 20KB truncation was announced as "the end
    of the file" at the top of a render whose own footer said 146 lines
    remained. When two reasons land on the same line the note says they
    coincide rather than picking the flattering one — an end it cannot
    attribute is declined, not guessed.

    `capped` and `cap_reached` are two different facts and were one flag until
    #1616. The cap is tested after a whole line has been emitted, so it drops
    the lines that would have followed and never truncates one: only when the
    loop stopped short of the window's own end did it cost anything, and that
    is `capped`. `cap_reached` alone — the output sits at the cap but the
    limit or EOF ended the read anyway — is disclosed as a fact and kept out
    of `reasons`, where it had been offered as a rival explanation for an end
    that was not in doubt.
    """
    req_start = offset + 1
    req_end = offset + limit
    if last_scanned < offset:
        last_scanned = offset + shown
    # "offset N + limit M = lines A-B" rather than "requested lines A-B":
    # LIMIT is often the 300-line default the caller never typed, and calling
    # that a request would be its own small untruth.
    # Which of the two grammars ran, named in the receipt rather than left to
    # be inferred from the numbers (#1414). `:A:B` and `:A-B` are one character
    # apart and return different windows, and until #1417 the only line that
    # spoke about the window described BOTH of them in OFFSET/LIMIT terms — so
    # a range call was reported in the vocabulary of the form it did not use.
    if range_form:
        asked = f"range {req_start}-{req_end} (START-END form)"
    else:
        asked = (f"offset {offset} + limit {limit} (OFFSET:LIMIT form) "
                 f"= lines {req_start}-{req_end}")
    if shown <= 0:
        if last_scanned > offset:
            skipped = last_scanned - offset
            by = f"{skipped_by} suppressed" if skipped_by else "nothing matched"
            return (f"window: {asked}; scanned lines {req_start}-"
                    f"{last_scanned} of {line_count} and emitted none — "
                    f"{by} all {skipped}\n")
        return (f"window: {asked}; returning nothing — the file has "
                f"{line_count} lines\n")
    hint = ""
    # The end of the window that actually came back, not the end that was asked
    # for. `req_end` overshoots whenever EOF or the byte cap cut the window
    # short, and offering it as "this window is read:PATH:A-B" would put a
    # claim of fact that is not a fact inside the line written to cure exactly
    # that (review of 58135ef: `read:f:8:5` on a ten-line file returned 9-10
    # and the hint named 9-13).
    got_end = last_scanned if last_scanned > offset else req_end
    # `range_form` says the caller typed `read:PATH:A-B`, whose OFFSET this
    # function only ever sees after the range was converted to one. Telling
    # that caller "OFFSET is a skip count" corrects a form they did not use,
    # and names A-1..B-1 — off by one against the lines they asked for. A
    # correct call being told it was wrong is why the range form reads as
    # non-existent even though it shipped in 0.19.0 (#983).
    if not range_form and offset > 0 and limit > 0:
        # Two spellings, and the receipt names both because they answer two
        # different questions: what came back, and what was probably meant.
        # Until #1417 only the second was offered and only when LIMIT <=
        # OFFSET, on the reasoning that `_read_range_note` (#382, since
        # deleted) owned the other band. It did not: #382 is itself gated on
        # overshoot or
        # LIMIT < 2*OFFSET, so `read:f:1:40` on a long file — #1138's own
        # archetype, and the commonest shape there is — satisfied neither gate
        # and was told nothing. A deferral to a speaker who is silent is the
        # house defect one level up: an absence produced by the tool, read as
        # an absence in the world.
        skipped_word = "line was" if offset == 1 else "lines were"
        hint = (f"; OFFSET is a skip count, so {offset} {skipped_word} skipped: "
                f"this window is read:{path}:{req_start}-{got_end}")
        # The FACT above fires always. The GUESS below — which lines the caller
        # was probably after — has two spellings and exactly one speaker.
        # Until #1489 the second belonged to `_read_range_note` (#382), which
        # printed it as a trailing `note:` UNDER the body: a correct sentence
        # arriving after the reader had already paid for the wrong window,
        # beside a `window:` line above the body that had already said
        # OFFSET:LIMIT. One question, one answer, and it goes where #1432 put
        # the rest of this disclosure.
        #
        # Which spelling is #382's gate, unchanged: an overshoot of EOF, or a
        # LIMIT that lands near its OFFSET rather than independent of it, is
        # the shape of an END misread as a LIMIT (`read:f:52:72` wanting lines
        # 52-72). Anything else is an ordinary skip-then-read, and the lines
        # that caller was after are OFFSET..OFFSET+LIMIT-1.
        if limit_synthetic:
            pass
        elif _range_note_fires(offset, limit, line_count):
            span = limit - offset + 1
            # The span of what was ASKED FOR, not of what came back: the byte
            # cap can cut the window short, and naming the lines returned here
            # would state a number the call did not produce (#1020).
            hint += (f" — this asked for {limit} lines from offset {offset}, "
                     f"which is OFFSET:LIMIT, not START:END; for lines "
                     f"{offset}-{limit} ({span} lines) use "
                     f"read:{path}:{offset}-{limit}")
        else:
            hint += (f" — for lines {offset}-{offset + limit - 1} use "
                     f"read:{path}:{offset}-{offset + limit - 1}")
    suppressed = (last_scanned - offset) - shown
    held = ""
    if suppressed > 0:
        held = (f", {shown} of those {last_scanned - offset} lines emitted "
                f"({skipped_by or 'a filter'} skipped {suppressed})")
    reasons = []
    if capped:
        reasons.append(f"cut short by the {byte_cap}-byte cap")
    if last_scanned >= line_count:
        reasons.append("the end of the file")
    limit_ended = (not limit_synthetic and limit > 0
                   and last_scanned >= req_end)
    if limit_ended:
        # Two different bounds had been sharing one word (#1820). A LIMIT the
        # caller typed is a window they closed themselves and there is nothing
        # to do about it; the `read.max_lines` default is the op's own cap on
        # output, standing in for a bound they never named, and it is the one
        # that hides the rest of the file. `read:PATH:10` reported the second
        # in the vocabulary of the first — a request the caller never made,
        # named back to them as theirs.
        if limit_defaulted is True:
            reasons.append(f"the read.max_lines default of {limit} lines was "
                           f"reached — you named no LIMIT, so this bound is "
                           f"the op's and {line_count - last_scanned} lines of "
                           f"the file are below it")
        else:
            reasons.append("the limit was reached")
    _EOF = "the end of the file"
    if not reasons:
        stops = f", stopping at line {last_scanned} for no reason this op can name"
    elif len(reasons) == 1:
        stops = f", stopping at line {last_scanned}: {reasons[0]}"
    elif _EOF in reasons:
        # #1342 — EOF and the limit landing on the same line was declined as
        # indistinguishable, one line under a header that prints the file's
        # total. `last_scanned >= line_count` decides it, and the two callers
        # this separates want different next actions: one wanted everything
        # from line N and has it, the other hit a cap and needs a wider window.
        # A decline emitted where the answer is on hand is the three-state
        # contract used as a shrug, and it erodes the declines that are real.
        #
        # The other reasons are still named — decisive is not the same as
        # silent, and a caller who set the limit is entitled to know it was
        # reached. What changes is that they are no longer offered as rival
        # explanations for a question the op can answer.
        others = [r for r in reasons if r != _EOF]
        stops = (f", stopping at line {last_scanned}: {_EOF}, and "
                 + " and ".join(others)
                 + f" at the same line — the file ending settles it, "
                 f"nothing follows line {last_scanned}")
    else:
        # Reached by nothing today, and said so rather than left to be
        # discovered: since #1616 `capped` means the loop stopped short of the
        # window's own end, which excludes both EOF and the limit, so the only
        # pair that can occur is EOF+limit and that is the branch above. This
        # is the shape a future fourth reason would take, not a live path — a
        # decline where more file remains and nothing on hand says which bound
        # would move first if the other were raised.
        stops = (f", stopping at line {last_scanned}: "
                 + " and ".join(reasons)
                 + " coincide here — which one ended the window cannot be told apart")
    if (limit_ended and limit_defaulted is False and not capped
            and _EOF not in reasons):
        # The third state, and the one this note never had (#1820). Every
        # clause above names which bound closed the window; none of them said
        # whether that bound cost the caller anything. So a window returned
        # WHOLE and a window the cap cut short both opened with `stopping at
        # line N: ...`, and the only way to tell them apart was to read again,
        # wider, and compare — one extra read of the reporter's file, spent
        # purely to learn that the first one had already answered.
        #
        # EOF is excluded because #1342's branch already settles it in its own
        # words (`nothing follows line N`); a second verdict beside it would be
        # two speakers on one question, which is what #1489 removed one clause
        # over. `capped` is excluded because it is the state this distinguishes
        # from.
        #
        # The claim is about the WINDOW, not about the lines: with a `grep=`
        # filter the emitted count is smaller than the scanned count, and the
        # `held` clause above is what speaks to that.
        stops += (" — the window ends here because it was asked to, "
                  "nothing was cut")
    if cap_reached and not capped:
        # The output IS at the cap, so a wider window will lose lines and the
        # caller is entitled to know. What it did NOT do is cost this call
        # anything: the cap is tested after a whole line is emitted, so it
        # drops following lines and never truncates one, and this window ended
        # at its own limit or at EOF regardless. Stated rather than dropped
        # into `reasons`, where it was offered as a rival explanation and made
        # `read:f:2-2` on a 25 KB line report itself truncated while returning
        # every byte — contradicting the byte-exact remedy `grep` prints to
        # send callers here (#1616).
        stops += (f" — the {byte_cap}-byte cap was reached on that line and "
                  f"dropped nothing; it stops whole lines and never truncates "
                  f"one, so these bytes are complete")
    return (f"window: {asked}; returning lines {req_start}-{last_scanned} "
            f"of {line_count}{held}{stops}{hint}\n")


_READ_RANGE_RE = re.compile(r"\d+-\d+")


def _range_note_fires(offset: int, limit: int, total: int) -> bool:
    """Does `read:PATH:A:B` look like a line range misread as OFFSET:LIMIT (#382)?

    `:A:B` is OFFSET:LIMIT, but it reads like START:END to anyone who has used
    `sed -n 'A,Bp'`, and the overshoot is quiet — the output just looks long.
    Requires LIMIT > OFFSET throughout — a real limit is seldom larger than the
    point it starts from — plus one of two independent tells:

    * OFFSET+LIMIT runs past EOF (#382's original gate), or
    * LIMIT < 2*OFFSET (#1020). The filed call was `read:PATH:5370:5460` on a
      19571-line file: it does NOT overrun, so #382's note stayed silent on the
      exact shape it was written for. What gives it away instead is that 5460
      sits just past 5370 — an END line lands NEAR its START, while an
      independent LIMIT does not. The doubling threshold keeps #382's own
      counter-example (`read:PATH:10:20`, a legitimate skip-then-read) quiet.

    Disclosure rather than refusal, because both readings are legitimate here
    and there is no gate that separates them without breaking working calls.
    Until #1489 this gate had a function of its own, `_read_range_note`, which
    printed the same disclosure a second time below the body; it now decides
    only which of `_read_window_note`'s two guesses is offered.
    """
    if offset <= 0 or limit <= 0 or limit <= offset or total <= 0:
        return False
    return not (offset + limit <= total and limit >= 2 * offset)


def _abstract_lang(path: str) -> str:
    """tree-sitter language name for PATH's extension, or "" when the abstract
    read has no language table for it.

    The gate used to be `path.endswith(".php")` while `_TS_LANG_MAP` already
    covered eighteen extensions (#670) — so a TypeScript or Python user got the
    raw file, which is the thing they already had."""
    lang = _TS_LANG_MAP.get(os.path.splitext(path)[1].lower(), "")
    return "" if lang in _ABSTRACT_READ_SKIP_LANGS else lang


# Languages whose symbol map is not a stand-in for their source. A signature
# list substitutes for a function body; a heading list does not substitute for
# the prose underneath it, so `read:` on a markdown file returns the document
# (#887). `map:` still builds the heading tree — this gate is read-only.
_ABSTRACT_READ_SKIP_LANGS: FrozenSet[str] = frozenset({"markdown"})


def _abstract_map(path: str, lang: str, size_bytes: int) -> Tuple[str, str]:
    """Symbol map for PATH, or the reason there isn't a usable one.

    Returns `(map, "")` on success and `("", reason)` when the caller should
    fall back to raw source. Two ways to fail, and the caller states which:

    - **No symbols.** The parser ran and found no definitions (a data-only
      module), or no parser matched at all. Returning that empty map would
      read as "this file has no code" — the absence of an answer wearing the
      shape of one. See docs/validators.md, "Declining instead of guessing".
    - **No saving.** A map that is not smaller than the bytes this read would
      otherwise emit is a worse answer than the source. Measured on 263 real
      files across 16 languages this fires on ~4% of them, so it is rare but
      not theoretical.
    """
    body = op_map(path)
    if _UNREADABLE_MARKER in body:
        # Its own arm, not the one below (#1680). "No symbols found" about a
        # file nothing opened is the defect this state exists to end, one layer
        # up in the caller — and the tree-sitter footnote under it would
        # explain which tier ran for a file no tier received a byte of.
        why = _map_unreadable_reason(path) or "the reason is no longer visible"
        return "", f"{_UNREADABLE_MARKER} {path}: {why} — no tier looked at it"
    if (body.startswith("ERROR:") or "(no symbols)" in body
            or _NO_PARSER_MARKER in body
            or "no supported files" in body):
        reason = f"no symbols found in {path} ({lang})"
        if not _has_tree_sitter():
            reason += " — tree-sitter is not installed, so only the regex tier ran"
        return "", reason
    map_bytes = len(body.encode("utf-8", errors="replace"))
    budget = min(size_bytes, _get_op_int("read", "max_bytes", MAX_READ_BYTES))
    if map_bytes >= budget:
        return "", (f"symbol map for {path} ({lang}) is {map_bytes} bytes, "
                    f"not smaller than the {budget} bytes this read emits")
    return body, ""


# ---------------------------------------------------------------------------
# #1329 — eliding a repeat read of a byte-identical file
# ---------------------------------------------------------------------------
# The op cannot observe whether the caller still holds the first copy. A
# re-read after a context compaction is the NORMAL case, not the edge case:
# the earlier result was evicted and the model is asking again precisely
# because it no longer has it. Nothing in this process can tell that apart
# from a redundant second ask, so the design does not try to. It bounds the
# damage instead, and every bound below is one of this repo's own rules:
#
#   - the elision is always ONE round-trip from the bytes, and the command
#     that returns them is printed in the line itself, not in the docs;
#   - it only fires inside a recency window measured from the last time
#     content was ACTUALLY returned — never bumped by an elision, or a file
#     polled every minute would be elided forever;
#   - a state file that cannot be read or written returns the content. An
#     unanswered cache is `skipped`, not silence;
#   - a file whose bytes changed is never elided, at any age. Repeat reads of
#     files that MOVED are the ones that carry information.
#
# Measured on the supertool corpus (`claude-log:cost`, #1252): unchanged
# re-reads are 0.0% of result bytes, because batching already prevents the
# pattern here. This is built for what it prevents, not for what it recovers.
_READ_ELIDE_KIND = "read-elide"
_READ_ELIDE_WINDOW_SECONDS = 900


def _read_elide_enabled() -> bool:
    """Whether a repeat read may be elided at all.

    Routed through `_get_op_bool`, not `_get_op_int`. That helper exists for
    positive-integer thresholds and reads a configured `0` as "unset",
    substituting its own default (`val if isinstance(val, int) and val > 0`).
    `read.elide` was the first boolean here whose default is ON, so through
    that helper `"elide": 0` was documented in three places and inert — a
    switch that reports the state it was asked for and does not enter it. It
    was read inline here as the narrow fix; #1332 gave the class a helper, so
    the next switch does not have to rediscover this.

    `SUPERTOOL_READ_NO_ELIDE` is kept and checked first: it is the documented
    per-call escape and it is negative-sense, which `_get_op_bool`'s
    `SUPERTOOL_READ_ELIDE` is not.
    """
    off = os.environ.get("SUPERTOOL_READ_NO_ELIDE", "")
    if off.strip() and off.strip() != "0":
        return False
    return _get_op_bool("read", "elide", True)


def _read_elide_window() -> float:
    return float(_get_op_int("read", "elide_window_seconds",
                             _READ_ELIDE_WINDOW_SECONDS))


def _read_elide_session_key() -> str:
    """Identity that two concurrent agents must never share.

    PPID is the session proxy `caller_tag` already uses — Claude Code does not
    expose session_id to Bash tools, only to hook stdin. Nine worktrees were
    live on this machine on 2026-08-11, so the resolved cwd is mixed in too:
    two agents that somehow share a parent still key separately per tree.
    The two failure directions are not symmetric — over-keying costs one file
    returned again, under-keying suppresses content the caller never saw — so
    the key is deliberately the narrower of the two.
    """
    # USER is POSIX; Windows sets USERNAME. Neither is load-bearing on its own
    # — PPID plus the resolved cwd already separate two agents — but a "?" for
    # every Windows caller would silently drop a component of the key.
    user = os.environ.get("USER") or os.environ.get("USERNAME") or "?"
    return "|".join((user, str(os.getppid()),
                     os.path.realpath(os.getcwd())))


def _read_elide_state_path(file_path: str) -> str:
    """One sidecar per (session, file), so concurrent supertool processes never
    read-modify-write a shared index."""
    # sha256, unlike the two path-only cache-name hashes below, because this
    # key carries USER: CodeQL flags a weak hash over identity-bearing input
    # (alert 11 on #1331). The digest is only a filename either way, but a
    # standing alert on a shipped line is a cost paid by every later reader.
    key = f"{_read_elide_session_key()}|{os.path.realpath(file_path)}"
    digest = hashlib.sha256(key.encode("utf-8")).hexdigest()
    return os.path.join(str(_cache_root() / _READ_ELIDE_KIND), digest)


def _read_elide_load(file_path: str) -> "Optional[Tuple[str, float, int]]":
    """(sha256, when content was last RETURNED, bytes) — or None for no record.

    OSError is deliberately not swallowed here: the caller has to be able to
    tell "no record" from "the cache could not answer", and both must end in
    the content being returned rather than in an elision.
    """
    with open(_read_elide_state_path(file_path), "r", encoding="utf-8") as fh:
        raw = fh.read().strip()
    parts = raw.split()
    if len(parts) != 3:
        return None
    try:
        return parts[0], float(parts[1]), int(parts[2])
    except ValueError:
        return None


def _read_elide_record(file_path: str, digest: str, size: int,
                       now: float) -> None:
    target = _read_elide_state_path(file_path)
    os.makedirs(os.path.dirname(target), exist_ok=True)
    tmp = f"{target}.{os.getpid()}.tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        fh.write(f"{digest} {now:.3f} {size}\n")
    os.replace(tmp, target)


def _read_elide_line(file_path: str, digest: str, size: int,
                     when: float) -> str:
    # "on disk", not "not returned": a >20KB file is byte-capped on the way
    # out (`apply_byte_cap = in_claude or not force_full`), so the file's size
    # and the bytes the first read actually handed over are not the same
    # number. Naming the file's size as the withheld amount would overstate it
    # on exactly the files where the cap bites.
    stamp = datetime.fromtimestamp(when).strftime("%H:%M:%S")
    return (f"[read elided — {file_path} is byte-identical to your read at "
            f"{stamp} (sha256 {digest[:12]}, {size:,} bytes on disk), so this "
            f"would return what you already have. If you no longer have it: "
            f"read:{file_path}:full]\n")


def _read_elide(path: str, offset: int, limit: int, grep_filter: str,
                force_full: bool, range_form: bool) -> str:
    """The elision line, or "" meaning "return the content".

    Records on every path that returns content, including `full` — after a
    forced read the caller demonstrably holds the bytes again.
    """
    if offset or limit or grep_filter or range_form:
        # A recorded whole-file read says nothing about a slice request, and
        # a slice must not arm an elision of the whole file.
        return ""
    if not _read_elide_enabled():
        return ""
    hasher = hashlib.sha256()
    size = 0
    try:
        with open(path, "rb") as fh:
            for chunk in iter(lambda: fh.read(65536), b""):
                hasher.update(chunk)
                size += len(chunk)
    except OSError:
        # Missing, a directory, unreadable — render_file owns that message.
        # (Windows raises PermissionError where POSIX raises
        # IsADirectoryError; both are OSError, which is why this catches the
        # base class rather than either name.)
        return ""
    digest = hasher.hexdigest()
    now = time.time()
    try:
        prior = _read_elide_load(path)
    except OSError:
        prior = None
    if (prior is not None and not force_full and prior[0] == digest
            and 0 <= now - prior[1] <= _read_elide_window()):
        return _read_elide_line(path, digest, prior[2], prior[1])
    try:
        _read_elide_record(path, digest, size, now)
    except OSError:
        pass  # A cache that cannot be written never suppresses content.
    return ""


def op_read(path: str, offset: int = 0, limit: int = 0,
            grep_filter: str = "", force_full: bool = False,
            range_form: bool = False) -> str:
    # `grep=` is a filter on a window rather than a search across a tree, and
    # until #1344 that difference was expressed by reaching neither the BRE
    # rewrite nor the saturation refusal — so `read:PATH:::grep=^|x` returned
    # the whole file under an ordinary header and the caller could only read
    # that as "every one of these lines matched". The gate decides; the route
    # only has to reach it. First statement in the op because a refused
    # pattern must not open the file.
    filter_note = ""
    if grep_filter:
        grep_filter, refusal, filter_note = _pattern_gate(grep_filter)
        if refusal:
            return refusal
    # Abstract mode — when enabled, read:PATH on a file in a language
    # tree-sitter knows, with no offset/limit/grep, returns the symbol map
    # (measured 3-18% of the source bytes, median ~5%). Skipped when:
    #   - the extension is not in _TS_LANG_MAP (no map to build)
    #   - file size <= threshold (small files fit raw in the cap, abstract
    #     buys nothing)
    #   - caller passes :full / :raw (force_full)
    #   - explicit offset/limit/grep
    #   - the map would be empty or no smaller than the raw read — those two
    #     fall back to source *and say so*, never silently
    skip_note = ""
    if (offset == 0 and limit == 0 and not grep_filter and not force_full
            and (_get_op_bool("read", "abstract", False)
                 or _get_op_bool("read", "php_abstract", False))):
        lang = _abstract_lang(path)
        threshold = _get_op_int("read", "abstract_threshold_bytes",
                                _get_op_int("read", "max_bytes", MAX_READ_BYTES))
        try:
            size_bytes = os.path.getsize(path)
        except OSError:
            size_bytes = 0
        if lang and size_bytes > threshold:
            body, reason = _abstract_map(path, lang, size_bytes)
            if body:
                line_count = 0
                try:
                    with open(path, "rb") as f:
                        # B007: the binding is read *after* the loop, which is
                        # the one shape the rule cannot see.
                        for line_count, _ in enumerate(f, 1):  # noqa: B007
                            pass
                except OSError:
                    pass
                return (body
                        + f"\n[abstract read — {lang}, {line_count} lines, "
                          f"{size_bytes} bytes raw — "
                          f"use read:{path}:full for content "
                          f"or read:{path}:::grep=PATTERN to filter]\n")
            skip_note = (f"[abstract read skipped — {reason}; "
                         f"showing raw source]\n")
    # `grep=` with no LIMIT is left at 0 so render_file can tell "the caller
    # named no window" from "the caller asked for 300 lines". Applying the
    # default here made the two identical, and the filter then searched only
    # the first 300 lines while reporting its zero as a fact about the file
    # (#1052).
    elision = _read_elide(path, offset, limit, grep_filter, force_full,
                          range_form)
    if elision:
        return elision
    # Recorded before the default lands, and passed rather than re-derived:
    # render_file applies the same default itself, but on this route it is
    # handed the resolved 300 and cannot tell it from a LIMIT the caller typed
    # (#1820). That is the identical shape as the `grep=` case the comment
    # above describes, one argument over.
    limit_defaulted = limit <= 0 and not grep_filter
    if limit <= 0 and not grep_filter:
        limit = _get_op_int("read", "max_lines", MAX_READ_LINES)
    body = render_file(path, offset, limit, grep_filter, force_full,
                       range_form, limit_defaulted=limit_defaulted)
    # `filter_note` above the header, for the reason the filter notes inside
    # render_file are: a disclosure the caller reads after paying for the
    # output is not a disclosure.
    return skip_note + filter_note + body + _read_edit_hint(path, body)


def _modify_hint_install_dir() -> str:
    """Directory holding `supertool` / `supertool.py`, for `_modify_hint`.

    Named and exposed on its own -- rather than inlined -- so a test can
    monkeypatch it the way `presets/_st_hint.py`'s own `install_dir` already
    is, and so this file's `__file__` (this module's own real path, not the
    entry point beside it) is resolved in exactly one place.
    """
    return os.path.dirname(os.path.realpath(__file__))


def _modify_hint_wrapper_is_runnable(path: str) -> bool:
    """Best-effort probe: is `path` runnable the way `./supertool` prints it?

    Mirrors `presets/_st_hint.py`'s `_wrapper_is_runnable` (#905/#1919):
    POSIX reads the execute bit directly; Windows has none, so the fallback
    there is a `#!` shebang -- every wrapper this project's own install
    instructions produce (README.md) is a symlink to `supertool.py`, itself
    `#!/usr/bin/env python3`.
    """
    if os.name == "nt":
        try:
            with open(path, "rb") as fh:
                return fh.read(2) == b"#!"
        except OSError:
            return False
    return os.access(path, os.X_OK)


def _modify_hint_quoted_interpreter() -> str:
    """`sys.executable`, quoted for the shell that will receive it if it must be.

    Mirrors `presets/_st_hint.py`'s `_quoted_interpreter` (#1017): an
    interpreter path with a space -- the ordinary Windows install, or any
    POSIX box whose user has one in `$HOME` -- must be quoted or the printed
    remedy asks the shell to run a program named `C:\\Program`.
    """
    exe = sys.executable
    if " " not in exe:
        return exe
    return chr(34) + exe + chr(34) if os.name == "nt" else shlex.quote(exe)


def _modify_hint(op: str) -> str:
    """A runnable supertool invocation for `op`, for `_read_edit_hint`'s footer.

    Duplicates `presets/_st_hint.py`'s `st_hint` (#905/#1012) rather than
    importing it: `presets/` ships no `__init__.py` and is a tree of
    subprocess-invoked scripts, not a package core can reach into, so this
    core module keeps its own copy of the small check the way it already
    does for `parse_remote` elsewhere in this file, rather than splicing
    `presets/` onto its own `sys.path` for one helper.

    Three states, exactly as `st_hint` has (#2120): `./supertool` only when
    a runnable wrapper genuinely sits on disk beside this file -- a
    gitignored symlink present in a clone, absent in a `git worktree`
    because git does not carry a symlink into one, which is exactly where a
    dispatched agent normally stands. `sys.executable supertool.py` when
    only the entry point is there -- the worktree case, and what this
    repo's own CLAUDE.md already tells a worktree caller to run. And an
    explicit "no runnable supertool found" when neither is, rather than
    printing either literal on a guess: a wrong prefix's failure
    (`No such file or directory`) reads as "the tool is not installed", not
    "one character of the suggestion was wrong", which spends the reader's
    trust before it spends their time.
    """
    root = _modify_hint_install_dir()
    quoted = chr(39) + op + chr(39)
    wrapper = os.path.join(root, "supertool")
    if (os.path.isfile(wrapper)
            and _modify_hint_wrapper_is_runnable(wrapper)):
        return "./supertool " + quoted
    if os.path.isfile(os.path.join(root, "supertool.py")):
        return _modify_hint_quoted_interpreter() + " supertool.py " + quoted
    return "(no runnable supertool found in " + root + " -- the op is " + quoted + ")"


def _read_edit_hint(path: str, body: str) -> str:
    """One-line nudge appended to a single-file read receipt: supertool's edit
    op bypasses the harness must-Read-first gate, so the file can be modified
    without a harness Read tool call (#309). Scoped to successful single-file
    reads only -- render_file errors get no hint, and grep/glob multi-file
    branches don't route through op_read."""
    if body.startswith("ERROR:"):
        return ""
    # `_flat_field`, for the reason #1019 flattened the `--- <op> ---` header
    # two lines above this one and the `edited …` line in `op_edit` — and this
    # footer was left raw, on the same op, in the same receipt (#1569). A
    # filename is whatever the filesystem accepted, `str.splitlines()` breaks
    # on ten separators (#886), and the tail of a forged name lands at column 0
    # inside what reads as a command to run. The name is disclosed rather than
    # censored: the hint is unrunnable either way for such a file, and one
    # naming a path that is not the one read would be worse than a broken one.
    op = f"edit:::OLD:::NEW:::{_flat_field(path, disclose_newline=True)}"
    return (f"{mark(chr(0x21B3))} to modify: {_modify_hint(op)}"
            f"  (or edit:@- ; no harness Read needed)\n")


_REGEX_METACHARS = re.compile(r"[()\[\]{}|.*+?^$\\]")


def _is_regexy(pattern: str) -> bool:
    """True if pattern holds regex metacharacters that could make a literal
    code fragment match the wrong thing — or nothing. Gates the zero-hit
    literal fallback so plain-word searches never pay for a second pass."""
    return bool(_REGEX_METACHARS.search(pattern))


def _literal_note(pattern: str, count: int) -> str:
    """One-line banner shown when a pattern found 0 regex hits but matched
    literally once metacharacters were escaped — tells the caller the search
    auto-corrected so they learn the pattern was regex-ambiguous."""
    return (f"(no regex match; showing {count} literal "
            f"match(es) for {pattern!r})\n")


# #1435 — quoting a phrase is what a shell user does with a pattern containing
# a space, and every pattern-taking op here searched the quote characters as
# literal text. `grep:'beta':q.txt` returned `0 results ... scanned 1 files` —
# the disclosure that says the op *looked* — so the zero read as an absence in
# the file rather than in the pattern.
_PATTERN_QUOTE_CHARS = ("'", chr(34), "`")


def _unwrapped_pattern(pattern: str) -> str:
    """A pattern's body with a matched surrounding quote pair removed, or "".

    Only a *pair* counts. `'zzz'|'yyy'` begins and ends with `'` and is not
    one; stripping its ends yields `zzz'|'yyy`, a pattern nobody typed. So any
    further occurrence of the quote character disqualifies it, as does an empty
    body — `''` unwraps to nothing, which is not a search.
    """
    if len(pattern) < 3:
        return ""
    quote = pattern[0]
    if quote not in _PATTERN_QUOTE_CHARS or pattern[-1] != quote:
        return ""
    inner = pattern[1:-1]
    if quote in inner:
        return ""
    return inner


def _quoted_pattern_note(pattern: str, inner: str,
                         inner_matches: bool) -> str:
    """Explain a zero that a quote pair may have produced (#1435).

    Nothing is stripped and nothing is refused, which is the whole point of
    this shape: a caller hunting a genuinely quoted phrase — a real pattern in
    a codebase full of quoted JSON and quoted payload bodies — typed exactly
    what they meant and keeps their result untouched. Only the silence after a
    zero changes.

    The probe is what stops the note being noise. Naming the quotes alone would
    send every deliberate quoted search off to re-run a query that comes back
    just as empty, so the unwrapped spelling is tried and the answer reported:
    three states, not two — the quotes hid it, the quotes are innocent and the
    absence is real, or the pattern was never a pair and there is no note.
    """
    quote = pattern[0]
    lead = (f"(the pattern {pattern!r} begins and ends with `{quote}`, and "
            f"both were searched as literal text rather than read as "
            f"quoting. ")
    if inner_matches:
        return lead + (f"Without them, {inner!r} DOES match here — this zero "
                       f"is about the quotes, not about what was scanned.)"
                       + chr(10))
    return lead + (f"Without them, {inner!r} matches nothing here either — "
                   f"the quotes are not why this is zero.)" + chr(10))


def _compile_lenient(pattern: str) -> "re.Pattern[str]":
    """Compile, falling back to the escaped literal — the reading every search
    helper in this file already applies (`_grep_recursive`, `_grep_count`,
    `_op_around`). A #1435 probe that compiled strictly instead would print the
    note on `grep` and swallow it on `around`, so an unwrapped pattern that is
    not a regex would answer differently depending on which op asked."""
    try:
        return re.compile(pattern)
    except re.error:
        return re.compile(re.escape(pattern))


def _quote_pair_note(pattern: str, probe: Callable[[str], object]) -> str:
    """`_quoted_pattern_note` plus its probe, for a result that came back zero.

    Each caller supplies its own `probe` rather than sharing one search: the
    note has to be about the same population the zero was about, and `grep`'s
    candidate list, `around`'s walk and `read`'s line window are three
    different populations. A probe that raises answers nothing and prints
    nothing — the unwrapped pattern is not guaranteed to compile.
    """
    inner = _unwrapped_pattern(pattern)
    if not inner:
        return ""
    try:
        matches = bool(probe(inner))
    except (re.error, OSError, UnicodeError):
        # Named rather than bare (PR review, #1435): the unwrapped pattern is
        # not guaranteed to compile and the probe touches the filesystem, so
        # those two are expected and print nothing. A bare `except Exception`
        # here would turn a genuine bug on this rarely-walked path into a
        # missing note, which is the silence this whole change is against.
        return ""
    return _quoted_pattern_note(pattern, inner, matches)


def _case_insensitive_note(pattern: str, probe: Callable[[str], object]) -> str:
    """Explain a zero that case sensitivity alone may have produced (#1777).

    grep is case-sensitive throughout supertool, and the instruction callers
    are given says to confirm a write a second way. Grepping back a sentence
    that IS on disk with different capitalisation returns `0 results` -- a
    false negative on a successful write, produced by the exact step that
    exists to catch a failed one. `0 results` is the one output where a
    case-insensitivity hint is worth printing, because it is the only one
    where the caller cannot tell a real absence from a spelling mismatch.

    Probed rather than asserted, the same shape as `_quote_pair_note`: an
    inline `(?i)` re-run settles whether case is the reason, so a genuine
    absence gets no extra noise and there is no second search dialect to
    maintain -- Python's own `re` already understands the prefix.

    Gated on the pattern actually holding a case-sensitive character before
    the probe ever touches the filesystem (review finding, #1777): a pattern
    with no letters at all -- a bare number, punctuation -- cannot be
    case-ambiguous, and `_quote_pair_note`'s own zero-result probe is skipped
    for the equivalent reason (no quote pair, no probe). Without this, every
    genuinely-absent, letter-free pattern paid for a second full-corpus walk
    the disclosure could never use -- the exact cost the comment above this
    function's call sites already warns against paying twice (PR review,
    #1435).
    """
    if not any(c.isalpha() for c in pattern):
        return ""
    try:
        matches = bool(probe("(?i)" + pattern))
    except (re.error, OSError, UnicodeError):
        # Same reasoning as `_quote_pair_note`: the probe touches the
        # filesystem and the pattern is not guaranteed to compile with the
        # prefix prepended, so those two are expected and print nothing.
        return ""
    if not matches:
        return ""
    # Never suggest the quoted form: `_quote_pair_note`/`_unwrapped_pattern`
    # (right above this function) exist because supertool's grep does NOT
    # strip a quote pair -- a quoted pattern is searched literally, quotes
    # and all. Wrapping the rerun in quotes here would send the caller
    # straight into that other zero, undisclosed (review finding, #1777).
    return (f"(grep is case-sensitive; {pattern!r} DOES match here when "
            f"searched case-insensitively -- this zero may be about "
            f"capitalisation, not absence. Re-run as "
            f"grep:(?i){pattern}:PATH for a case-insensitive search -- no "
            f"quotes around the pattern, which grep searches literally.)"
            + chr(10))


# Patterns whose meaning differs between Python's `re` and POSIX ERE (#987).
# The delegated path hands the pattern to the system grep, so anything matching
# this never leaves the native walker:
#   \X  — every escape EXCEPT the punctuation both dialects agree on
#         (`\. \$ \* \+ \? \( \) \[ \] \{ \} \| \\ \/ \-`). That covers Python-only
#         classes (\d \w \s \b \A) and backreferences, and also GNU's word
#         boundaries \< \>, which ERE honours and Python reads as `<` and `>`
#         — a divergence a `\<alnum>` rule silently let through.
#   (?  — lookaround, non-capturing groups, inline flags: Python only
#   *? +? ??  — non-greedy; ERE reads a second, stray quantifier
#   [: [. [=  — POSIX bracket classes, which Python reads literally
_ERE_UNSAFE = re.compile(r"\\[^.^$*+?()\[\]{}|\\/-]|\\$|\(\?|[*+?}]\?|\[[:.=]")


# #1120 — supertool rewrites bash-grep BRE alternation so `a\|b` behaves the way
# a caller's fingers expect. The rewrite is unconditional, and it cannot tell that
# `\| \{` was an ESCAPED LITERAL pipe: it produces `| \{`, whose left alternation
# branch is empty. An empty branch matches the empty string, so the pattern matches
# every line of every file — and `1000+ matches` renders identically to a search
# that genuinely found a lot. The `:`-tokenizer, the filed suspect, is innocent.
_BRE_ALT = "\\|"


def _bre_alternation_rewrite(pattern: str) -> Tuple[str, bool]:
    """Apply the BRE-alternation rewrite, reporting whether it changed anything."""
    if _BRE_ALT not in pattern:
        return pattern, False
    return pattern.replace(_BRE_ALT, "|"), True


def _top_level_branches(pattern: str) -> List[str]:
    """Split on `|` at nesting depth 0, outside character classes, unescaped.

    Depth matters: `colo(u|)r` has an empty branch and matches exactly two words,
    while a bare `colou|r` with an empty branch would match everything. A `|`
    inside `[...]` is an ordinary character and starts no alternation at all.
    """
    branches: List[str] = []
    depth = 0
    in_class = False
    start = 0
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == "\\":
            i += 2
            continue
        if in_class:
            if c == "]":
                in_class = False
        elif c == "[":
            in_class = True
        elif c == "(":
            depth += 1
        elif c == ")":
            depth = max(0, depth - 1)
        elif c == "|" and depth == 0:
            branches.append(pattern[start:i])
            start = i + 1
        i += 1
    branches.append(pattern[start:])
    return branches


# Probe strings for "does this branch match every line?" (#1314). A branch that
# matches the EMPTY string matches at position 0 of every line, so the whole
# alternation does — that is the property, and an empty branch is only its
# simplest spelling. `^`, `$`, `.*` and `z*` all have it and all sailed past the
# #1120 predicate, which tested for `b == ""`: the filed call
# `grep:^\|def op_:_supertool.py:5` reported 5 of "1000+ matches" for a pattern
# that matched every line of the file.
#
# The empty probe alone is not enough, and this is where the line is drawn.
# `^$` matches the empty string and NOT `x`, so `^$|alpha` is a real search
# ("blank lines or alpha") and refusing it would remove the op for a legitimate
# caller. A branch has to match every probe — including non-empty ones — before
# it is called saturating. Same reason `.` and `\b` stay out: neither matches a
# blank line, so neither makes the pattern match every line.
_SATURATION_PROBES = ("", "x", "supertool 42", "  ")


def _branch_matches_everything(branch: str) -> bool:
    """True when this one top-level branch matches every line there is."""
    if branch == "":
        return True
    try:
        regex = re.compile(branch)
    except re.error:
        # An uncompilable branch is not a saturation claim to make here; the
        # pattern's own compile (and its literal fallback) decides what happens.
        return False
    return all(regex.search(probe) is not None for probe in _SATURATION_PROBES)


def _saturating_branch(pattern: str) -> Optional[str]:
    """The first TOP-LEVEL alternation branch that matches every line, or None.

    Returns the branch rather than a bool because the refusal has to name it:
    `^|def op_` and `|def op_` are one keystroke apart and want different fixes,
    and a diagnosis that does not say which half saturated is not actionable.
    """
    if "|" not in pattern:
        return None
    branches = _top_level_branches(pattern)
    if len(branches) < 2:
        return None
    for branch in branches:
        if _branch_matches_everything(branch):
            return branch
    return None


def _saturates(pattern: str) -> bool:
    """True when a TOP-LEVEL alternation branch matches every line, i.e. the
    pattern matches every line. Not a search — a saturation."""
    return _saturating_branch(pattern) is not None


def _saturating_pattern_refusal(written: str, effective: str,
                                rewritten: bool) -> str:
    """Refuse a pattern that matches every line, naming the spelling that works.

    The three-state contract: `ok`, a finding, and — here — declining, because a
    saturated match is not an answer to the question that was asked and its
    report cannot be told apart from a real one. Nothing downstream can recover
    the distinction, so it has to be refused at the call.
    """
    branch = _saturating_branch(effective)
    if branch is None:
        return ""
    if branch == "":
        why = ("has an empty alternation branch, so it matches every line of "
               "every file scanned")
    else:
        why = (f"has an alternation branch `{branch}` that matches the empty "
               f"string, so the whole pattern matches every line of every "
               f"file scanned")
    # Backticks, not !r: repr() DOUBLES every backslash, and a backslash is the
    # one character this message exists to show. `'\\| \\{'` for a pattern the
    # caller typed as `\| \{` is the tool mangling its own diagnosis.
    lines = [
        f"ERROR: pattern `{effective}` {why}. That is a saturated pattern, not "
        f"a search, and its result count is indistinguishable from a search "
        f"that genuinely found a lot.",
    ]
    if rewritten:
        became = ("a bare `|` with nothing to its left" if branch == ""
                  else "a top-level `|` that split the pattern into branches")
        lines.append(
            f"  written as `{written}` — supertool rewrites bash-grep BRE "
            f"alternation, so `{_BRE_ALT}` became {became}.")
        lines.append(
            f"  for a literal `|`, use a character class: "
            f"`{written.replace(_BRE_ALT, '[|]')}`")
    else:
        lines.append(
            "  for a literal `|`, use a character class: `[|]`")
    return chr(10).join(lines) + chr(10)


def _bre_rewrite_note(written: str, effective: str, rewritten: bool) -> str:
    """Disclose the rewrite whenever it fired (#1120).

    An escape being eaten is invisible in a result set that looks plausible, and
    the same move — say which pattern actually ran — is what #1065 added for the
    ':' rejoin and what `scanned N files` added for the zero case.
    """
    if not rewritten:
        return ""
    return (f"(pattern rewritten to `{effective}` — `{_BRE_ALT}` is bash-grep "
            f"BRE alternation and became a plain `|`. For a literal `|`, use "
            f"`[|]`.)" + chr(10))


def _pattern_gate(
    pattern: str, check_saturation: bool = True
) -> Tuple[str, str, str]:
    """The one place a caller-supplied search pattern is normalised and judged.

    Returns `(effective, refusal, note)`. A non-empty `refusal` is the whole
    answer and the op must return it unchanged; otherwise `effective` is the
    pattern to run and `note` is the disclosure to print above the result.

    Single-sourced because it was not, and the cost was #1344: the rewrite and
    the refusal were wired route by route, so `read:PATH:::grep=` — added later
    and reached through a different parser branch — arrived with neither, and
    the same pattern meant three different things across four routes.

    Whether a filter on a bounded window should be refused at all is the
    decision #1344 asked for, and it is answered here rather than at each call:
    yes. `read`'s `grep=` returns whole-file output when it saturates, which
    looks exactly like `read:PATH` and therefore hides nothing loud — but what
    the caller takes away is that every one of those lines matched the pattern
    they typed, which is the same false belief #1314 was filed about, arrived
    at more quietly. Disclosing instead would leave the caller holding a file
    they already had a spelling for (`read:PATH`), paid for in context, under a
    note correcting the request they just made. Refusing costs nothing a
    caller meant: the predicate fires only on a top-level alternation with a
    branch that matches every probe, so `^$|alpha` and `colo(u|)r` still run.

    The #150 ReDoS backtracking guard (`_has_outer_wrapped_unbounded_group`,
    hardened by #1311/#2535) lived only inside `_op_grep` until #2547: every
    other route through this chokepoint -- `around`'s public wrapper and
    `read`'s `grep=` -- reached `re.compile`/match against real file content
    with the same adversarial shape (`(x(a+)+y)`) completely unrefused. Single-
    sourcing it here, ahead of the rewrite, is the fix `_pattern_gate`'s own
    reason for existing already argues for: a guard wired route by route is a
    guard that drifts, the same way the rewrite and the saturation refusal
    once did (#1344).

    `check_saturation=False` (#2573) exists for callers whose semantics are a
    single-match position search rather than a filtered count -- `op_vim`'s
    `/`, `?`, `n`/`N`, the inline `o`/`O` search-then-open reflex, the `:d
    /PAT/` address resolver and the operator motion forms. There, "the whole
    pattern matches every line" is not a meaningless result the way it is
    for `grep`/`around`: a bare `|` is a completely ordinary, previously-
    working vim search for a literal pipe character (`_saturating_branch`
    sees the empty alternation branch and refuses it), and vim has no result
    count for the refusal's own rationale to apply to. `op_vim`'s `:s` and
    `:g`/`:v` do NOT pass `check_saturation=False`, on the same reasoning in
    reverse: those two act on every match (substitute every occurrence,
    delete every matching line), so a saturating pattern is exactly as
    destructive there as it is for `grep`/`around` -- a bare `|` as `:s`'s
    PAT would silently interleave every character of the buffer with the
    replacement, and as `:g`'s PAT would silently delete the whole file. The
    length cap and the ReDoS backtracking guard still apply unconditionally
    everywhere -- this parameter only turns off the one check whose
    rationale does not transfer, and only where it does not transfer.
    `trap.d/2571.between-saturating-refusal.md` flagged the identical
    mismatch for `op_between_pattern`, left unresolved there; `op_vim` is the
    first call site to actually need the opt-out rather than merely note the
    mismatch.
    """
    if len(pattern) > 1000:
        return pattern, (
            f"ERROR: pattern too long ({len(pattern)} > 1000 chars)\n"
        ), ""
    if _has_outer_wrapped_unbounded_group(pattern):
        return pattern, (
            "ERROR: pattern contains nested unbounded quantifiers "
            f"({pattern!r}) — would risk catastrophic backtracking. "
            "Rewrite without `(...+)+`-style nesting.\n"
        ), ""
    effective, rewritten = _bre_alternation_rewrite(pattern)
    if check_saturation:
        refusal = _saturating_pattern_refusal(pattern, effective, rewritten)
        if refusal:
            return effective, refusal, ""
    return effective, "", _bre_rewrite_note(pattern, effective, rewritten)


def _pattern_read_as_note(pattern: str, path: str, op: str = "grep") -> str:
    """Name the pattern `op` actually ran, when a ':' made that a choice (#1065).

    `grep:re:Checks|failed:PATH` tokenizes to the pattern `re:Checks|failed`,
    and `|` binds looser than concatenation, so the first alternation branch is
    the literal `re:Checks` — which matches nothing. The op then reports three
    confident results for a question nobody asked, and `scanned 1 files` is
    both true and useless: it did look, at someone else's pattern.

    Nothing is refused here, because the tokenization is not ambiguous — it is
    documented, deterministic, and the payload route already covers what the
    colon CLI cannot express. What was missing is the disclosure. A ':' in the
    pattern is exactly the condition under which the rejoin happened, so that
    is when the effective pattern is echoed back.

    The path is named too (#1166). The split has two outputs and the note
    disclosed one: a receipt that is precise about the pattern and silent about
    which of the remaining tokens became the FILE reads as complete, which is
    exactly what stops a reader checking the half that moved.

    Parameterised on the op since #1821, which was filed against grep and is
    true of `around`. Both rejoin with `_split_arg`, both share
    `_colon_split_hint` for the PATH slot that does not exist — and where the
    slot DOES exist, only grep said which pattern it had settled on. `around`
    printed a plausible answer and nothing else, which is the same defect one
    step further along: not a caveat in the wrong place, no caveat. The op name
    is threaded through rather than hardcoded because the escape hatch and the
    `re:` sentence are both op-specific, and a note that tells an `around`
    caller about `grep:@-` sends them to a route they did not call.
    """
    if ":" not in pattern:
        return ""
    note = (f"(pattern read as {pattern!r}, path as {path!r} — the ':' is part "
            f"of the regex, not a separator. Use {op}:@- with a `pattern` key "
            "if the split was meant to fall elsewhere.)" + chr(10))
    if pattern.startswith("re:"):
        note += (f"({op} has no `re:` prefix — every {op} pattern is already a "
                 "regex, so `re:` is literal text and forms part of the first "
                 "alternation branch. `between:re:START:END:PATH` is the op "
                 "that has one.)" + chr(10))
    return note


def _count_lines(path: str, on_error: int = 0) -> int:
    """Count lines in a file cheaply, streaming in binary (#362).

    `on_error` is what an unreadable file counts as, because the callers want
    opposite things and one hardcoded answer is wrong for the other (#388). The
    glob:/grep: auto-read line cap passes `MAX_AUTOREAD_LINES + 1` so a file it
    cannot measure is treated as over-cap and left unread — failing closed.
    `map` and the workspace summary keep the default 0, since a sentinel would
    render as a wildly wrong line count in a listing.
    """
    try:
        count = 0
        last = b""
        with open(path, "rb") as fh:
            for chunk in iter(lambda: fh.read(65536), b""):
                count += chunk.count(b"\n")
                last = chunk
        if last == b"":
            return 0  # empty file
        # trailing line without a final newline
        if not last.endswith(b"\n"):
            count += 1
        return count
    except OSError:
        return on_error


# #1328 — `all` names the LIMIT slot and only that slot. Both neighbours are
# refusals rather than readings: `all` in the CONTEXT slot read as a limit runs
# a call nobody typed, and a third trailing token dropped on the floor (the
# parser peels every trailing digit and reads two) runs the default under a
# token the caller believes removed the cap.
_GREP_ALL_OUTSIDE_LIMIT_SLOT = (
    "ERROR: grep read `all` outside the LIMIT slot (grep:PATTERN:PATH:LIMIT:"
    "CONTEXT). `all` is a LIMIT — it removes the result cap so a sweep is "
    "complete; CONTEXT is a number of lines around each match and has no "
    "`all`, and nothing follows CONTEXT. Did you mean "
    "grep:PATTERN:PATH:all:CONTEXT?" + chr(10)
)

# `grep_around` is PATTERN:PATH:N:LIMIT — context FIRST, the opposite order to
# grep's LIMIT:CONTEXT. Copying `grep:PATTERN:PATH:all` across lands `all` in
# the N slot, where int() used to raise and the caller got the exception text.
_GREP_AROUND_ALL_IN_N_SLOT = (
    "ERROR: grep_around takes PATTERN:PATH:N:LIMIT — context first, the "
    "opposite order to grep's LIMIT:CONTEXT — so `all` landed in the N slot. "
    "Did you mean grep_around:PATTERN:PATH:N:all (e.g. "
    "grep_around:PATTERN:PATH:3:all), or grep:PATTERN:PATH:all:N?" + chr(10)
)


# #945 — `0` is the near-universal spelling of "no limit", and grep accepted it,
# ignored it, and quietly applied the default instead. Neither meaning is
# guessed: honouring it as unlimited would hand a caller who typed one character
# an unbounded dump into a shared output budget, and substituting the default
# means the number that ran was never the number that was typed.
# A function, not the constant it was until #1334. The refusal names two
# readings and used to give a spelling for neither, so a caller who meant either
# one paid a round-trip to find it — while the op has accepted BOTH since #1328.
# The default is resolved here rather than frozen at import, because
# `grep.max_results` is a per-project setting: naming MAX_GREP_RESULTS while a
# project's own cap was the one about to run is this repo's own defect, a number
# the tool produced being read as a number about the world.
def _grep_zero_limit() -> str:
    default = _get_op_int("grep", "max_results", MAX_GREP_RESULTS)
    return (
        'ERROR: grep LIMIT 0 is not "unlimited" here, and supertool will not '
        "guess which of the two it meant. Uncapped output would land in the "
        "caller's context before it could be declined, and silently "
        "substituting the default would mean the LIMIT that ran was never the "
        "LIMIT that was typed. Both readings have a spelling: "
        f"grep:PATTERN:PATH:{_GREP_ALL_TOKEN} for every match, or omit LIMIT "
        f"for the default of {default} (grep:PATTERN:PATH:200 for any other "
        "cap)." + chr(10)
    )


def op_grep(pattern: str, path: str = ".", limit: int = 0,
            context: int = 0, count_only: bool = False,
            no_exclude: bool = False, no_auto_read: bool = False,
            via_payload: bool = False, full: bool = False) -> str:
    """grep, prefixed by #1065's disclosure of the pattern that actually ran.

    `via_payload` is set by the @file/@- route (#1825): there, `pattern` is
    taken verbatim from a `pattern` key, so nothing was split on ':' and the
    colon-rejoin disclosure would send the caller back to the route they are
    already on. The positional-CLI route leaves it False and keeps the note.

    `full` (#1712) suppresses the per-line char cap for this call only — the
    default stays truncating for every call that does not ask, which is the
    protection #363 added against one pathological line drowning a batched
    multi-op result.
    """
    _effective, refusal, note = _pattern_gate(pattern)
    if refusal:
        return refusal
    prefix = "" if via_payload else _pattern_read_as_note(pattern, path, "grep")
    return (prefix
            + note
            + _op_grep(pattern, path, limit, context, count_only,
                       no_exclude, no_auto_read, full))


def _grep_limit_and_label(limit: int) -> Tuple[int, str]:
    """Resolve grep's LIMIT into (effective cap, what the count line says).

    `all` (#1328) arrives as the GREP_LIMIT_ALL sentinel and leaves as a cap
    nothing can reach, plus the label `all`. Printing the number instead would
    put `limit 9223372036854775807` on the line a reader uses to decide whether
    a sweep was complete — a cap they then have to recognise to interpret.
    """
    if limit == GREP_LIMIT_ALL:
        return sys.maxsize, _GREP_ALL_TOKEN
    if limit <= 0:
        limit = _get_op_int("grep", "max_results", MAX_GREP_RESULTS)
    return limit, str(limit)


def _has_outer_wrapped_unbounded_group(pattern: str) -> bool:
    """True if *pattern* has a `(...)` group followed by an outer `+`/`*`
    whose own content contains an unbounded quantifier (`+`/`*`) at ANY
    nesting depth (#1311 self-review finding).

    A single-level regex over `(...)` can only ever see the FIRST close-paren
    it reaches, so it cannot tell `((a+)?)+` -- where the real danger is the
    OUTER `+` wrapping a group whose own content is itself unbounded two
    levels down -- from `(a+)?` alone, which is safe. #1311's own fix
    narrowed a single-level regex from flagging every trailing `+`/`*`/`?` to
    only `+`/`*`, and that narrowing accidentally stopped catching
    `((a+)?)+` too: the old, over-eager regex only ever caught it as a side
    effect of blanket-refusing the INNER `(a+)?` fragment wherever it
    appeared, never because it understood the outer wrapping. Confirmed
    catastrophic: `((a+)?)+` against 25 `a`s and a non-matching trailer took
    several seconds on this machine.

    This is a small bracket-depth-aware scan instead: for every `(`, find
    its matching `)` by depth, note whether an unescaped `+`/`*` appeared
    ANYWHERE inside (at any nesting depth), and refuse only if the character
    immediately after that matching `)` is `+` or `*`.

    #2535 (gate-3 release-audit round 2): after resolving one group, the scan
    used to jump straight past it (`i = j`), so a nested group buried inside
    an UNQUANTIFIED outer group -- e.g. `(x(a+)+y)`, where the outer `( ... )`
    has no trailing `+`/`*` of its own but the inner `(a+)` does -- was never
    independently examined for its own trailing quantifier. The scan now
    advances one character at a time instead, so every `(` in the pattern,
    at any depth, gets its own matching-close-paren-plus-trailing-quantifier
    check, not only the outermost one at each position.

    Deliberately loose, like the check it replaces: character classes
    (`[...]`) are skipped so a literal `+`/`*`/`(`/`)` inside one is never
    mistaken for a quantifier or a grouping paren, and a backslash-escaped
    `(`/`)` is skipped as two characters so it never contributes to depth.
    Nothing here claims to be a real regex parser -- alternation, lookaround
    and non-capturing groups are not distinguished from a plain group, which
    only widens what gets refused, never what gets missed.
    """
    n = len(pattern)

    def _skip_class(k: int) -> int:
        """Index just past a `[...]` character class opened at *k* - 1."""
        if k < n and pattern[k] == "^":
            k += 1
        if k < n and pattern[k] == "]":
            k += 1
        while k < n and pattern[k] != "]":
            if pattern[k] == "\\":
                k += 1
            k += 1
        return k + 1

    i = 0
    while i < n:
        c = pattern[i]
        if c == "\\":
            i += 2
            continue
        if c == "[":
            i = _skip_class(i + 1)
            continue
        if c == "(":
            depth = 1
            j = i + 1
            has_unbounded = False
            while j < n and depth:
                cj = pattern[j]
                if cj == "\\":
                    j += 2
                    continue
                if cj == "[":
                    j = _skip_class(j + 1)
                    continue
                if cj == "(":
                    depth += 1
                elif cj == ")":
                    depth -= 1
                    if depth == 0:
                        j += 1
                        break
                elif cj in "+*":
                    has_unbounded = True
                j += 1
            if has_unbounded and j < n and pattern[j] in "+*":
                return True
            i += 1
            continue
        i += 1
    return False


def _op_grep(pattern: str, path: str = ".", limit: int = 0,
             context: int = 0, count_only: bool = False,
             no_exclude: bool = False, no_auto_read: bool = False,
             full: bool = False) -> str:
    """Search pattern recursively. Auto-reads small single file on match.

    When context > 0, emits N lines before/after each match in grep -C style:
      match lines:   path:lineno:content  (colon separator)
      context lines: path-lineno-content  (dash separator)
    Non-adjacent groups are separated by --.
    Auto-read is skipped when context > 0 (output already contains context).

    When count_only=True, returns match counts per file instead of content.

    When no_auto_read=True, suppresses the single-small-file auto-read so only
    the matching line(s) are emitted (parity with glob's :no-auto-read flag).

    When full=True (#1712), the per-line char cap (#363) is suppressed for
    both matched and context lines in this call — see `_cap_grep_line` and
    `_grep_disclosure_note`.
    """
    unlimited = limit == GREP_LIMIT_ALL
    limit, limit_label = _grep_limit_and_label(limit)
    if not pattern:
        return "ERROR: empty pattern\n"

    # #150 ReDoS guards. Python's stdlib `re` has no execution timeout, so
    # we reject patterns that are obvious candidates for catastrophic
    # backtracking before they touch any file content.
    if len(pattern) > 1000:
        return f"ERROR: pattern too long ({len(pattern)} > 1000 chars)\n"
    # Nested unbounded quantifiers like `(a+)+`, `(a*)*`, `(.+)*` — the
    # classic ReDoS shape. The OUTER quantifier is what makes it dangerous:
    # `+`/`*` can re-partition the same input across an unbounded number of
    # iterations, each iteration free to re-decide how much of the group's
    # own unbounded content it consumed. `?` bounds the group to at most ONE
    # repetition, so there is no re-partitioning to explore and no
    # catastrophic-backtracking risk -- `(a+)?` was refused here until #1311
    # even though it is bounded, on a pattern reported live: digits, a dot,
    # an alternation, an OPTIONAL group of a dot plus one-or-more
    # lowercase/hyphen characters, a dot, "md". The exception is scoped to
    # each matched group's own outer quantifier, not to the pattern as a
    # whole: `(a+)?b(c+)?` is two independently-bounded groups, and neither
    # one's risk depends on what quantifier the other carries, so both must
    # pass. The check is intentionally loose otherwise; users with a
    # legitimate need can split into simpler greps.
    if _has_outer_wrapped_unbounded_group(pattern):
        return (
            "ERROR: pattern contains nested unbounded quantifiers "
            f"({pattern!r}) — would risk catastrophic backtracking. "
            "Rewrite without `(...+)+`-style nesting.\n"
        )

    # Auto-convert bash grep BRE alternation (\|) to Python regex (|). Single-
    # sourced with op_grep/op_around so the rewrite and the refusal that guards
    # it (#1120) can never drift apart — two hand-written copies is how `around`
    # came to carry the same saturation bug that was filed against `grep`.
    pattern, _ = _bre_alternation_rewrite(pattern)

    # Early exit if path doesn't exist (don't silently return 0 results)
    if path != "." and not os.path.isfile(path) and not os.path.isdir(path):
        # Could be a glob pattern — check if it expands to anything
        from glob import glob as _glob
        if not _glob(path, recursive=True):
            # #1711: a plain PATTERN/PATH swap has no ':' anywhere and both
            # values are ordinary tokens, so `_colon_split_hint` (dispatch,
            # ahead of this) declines — this is the general check that
            # still catches it, off the same evidence `around` uses.
            _swap = _swap_suggest(
                "grep", "PATTERN:PATH", "pattern", pattern, path,
                f"grep:{path}:{pattern}")
            return _path_not_found(path, op="grep", suggest=_swap,
                                   call_prefix=f"grep:{pattern}")

    excl = _get_exclude_paths("grep", no_exclude)

    # RTK delegation — basic grep (no context, no count). Excludes are threaded
    # through as --exclude-dir AND --exclude for single-segment entries (.git/,
    # node_modules/, .env/) and re-applied to whatever comes back. Multi-segment
    # prefixes (e.g. "Dvsi/dvsi-private/libs/") can't be expressed as either;
    # fall through to the native walker in that case.
    # `-E` and the _ERE_UNSAFE gate together (#987). rtk shells out to the
    # system grep, which without `-E` reads a POSIX *BRE*: `|`, `+`, `?`, `(`
    # and `{` are ordinary characters there. `cc|dd` therefore came back as the
    # one line containing a literal pipe — a smaller, confident, wrong answer,
    # and only when the BRE reading happened to match at all, which is why it
    # survived (a BRE that matches nothing exits non-zero and falls through to
    # the native walker, where the result is right). `-E` closes the gap for
    # alternation, groups and quantifiers; the gate declines delegation for the
    # constructs ERE still cannot express, rather than translating them.
    # `all` never delegates (#1328): the delegated report cannot count what it
    # did not collect, so its truncation clause is `total not counted` — the one
    # state a completeness sweep must not come back in. The native walker is the
    # only engine that can say `all` and mean it.
    if (not count_only and context == 0 and not unlimited
            and _rtk_enabled() and _has_rtk()
            and not _ERE_UNSAFE.search(pattern)):
        _, multi = _split_exclude_prefixes(excl)
        if not multi and not _gitignore_residual(path, excl):
            # limit + 1 so the report can tell "exactly N" from "stopped at N"
            # (#448). The extra line is trimmed off before output.
            rtk_args = ["grep", "-rn", "-E", "-m", str(limit + 1)]
            rtk_args.extend(_grep_exclude_flags(excl))
            rtk_args.extend([pattern, path])
            rtk_out = _rtk_run(rtk_args)
            if rtk_out is not None and rtk_out.strip():
                rtk_out, rtk_dropped = _rtk_drop_excluded(rtk_out, excl)
                if not rtk_dropped:
                    # The census is a *callable*, not a value: it is a second
                    # full grep over the tree and must not be paid for on a
                    # complete result, which needs no total (#1771).
                    return _rtk_grep_report(
                        rtk_out, limit,
                        census=lambda: _rtk_grep_census(pattern, path, excl))
                # An excluded file came back anyway — expected whenever the
                # list carries a negation, since those wildcards are withheld
                # from the argv. Printing the filtered lines under the
                # delegated header would leave its count, its `limit + 1`
                # truncation probe and its `?` denominator all describing a
                # result set that no longer exists. Redo the walk natively
                # instead: same filter, honest report, and the two engines
                # answer identically in the one case where it matters (#691).
            # No RTK output — rtk failed, or it ran and matched nothing. Fall
            # through to the native walker either way (#414). A zero result is
            # the ambiguous case #407 exists for, so it must reach the walker
            # and come back with a real scanned count rather than the `?` the
            # delegated report carries. This also lets the zero-hit literal
            # fallback below run.

    # Resolved once and threaded through so a zero-result report can state how
    # many files were actually scanned (#407) — without it, "0 results" is
    # ambiguous between "searched everything, found nothing" and "path/glob
    # resolved to nothing, so nothing was searched".
    hidden_files: List[str] = []
    candidates = _grep_candidates(path, excl, hidden_files)
    scanned = len(candidates)
    hidden = _hidden_suffix(len(hidden_files))

    if count_only:
        counts = _grep_count(pattern, path, limit, excl, candidates=candidates)
        literal_note = ""
        if not counts and _is_regexy(pattern):
            counts = _grep_count(re.escape(pattern), path, limit, excl, candidates=candidates)
            if counts:
                literal_note = _literal_note(pattern, sum(counts.values()))
        total = sum(counts.values())
        file_count = len(counts)
        out = [literal_note,
               f"({total} total matches across {file_count} files{_scanned_suffix(scanned)}{hidden})\n"]
        if total == 0:
            out.append(_shim_facade_note(path))
            # `_grep_recursive`, not `_grep_count`: the probe asks whether the
            # unwrapped pattern matches at all, and `_grep_count` has no early
            # break — it counts every line of every candidate regardless of the
            # limit it is handed, which would make a disclosure cost a second
            # full count of the corpus (PR review, #1435).
            out.append(_quote_pair_note(pattern, lambda inner: _grep_recursive(
                inner, path, 1, excl, candidates=candidates)))
            out.append(_case_insensitive_note(pattern, lambda p: _grep_recursive(
                p, path, 1, excl, candidates=candidates)))
        # `PATH:N` is the shape every grep-like tool uses for PATH:LINE, so a
        # count of 30 read as "one match, at line 30" — the opposite of what
        # the op said, in the op you call *before* deciding whether to look
        # (#988). The unit makes the two unconfusable.
        for fp, cnt in sorted(counts.items()):
            out.append(f"{_fwd(fp)}: {cnt} match{'' if cnt == 1 else 'es'}" + chr(10))
        out.append("\n")
        return "".join(out)

    if context > 0:
        ceiling = _grep_count_ceiling(limit)
        groups = _grep_recursive_context(
            pattern, path, ceiling + 1, context, excl, candidates=candidates)
        literal = False
        if not groups and _is_regexy(pattern):
            groups = _grep_recursive_context(
                re.escape(pattern), path, ceiling + 1, context, excl, candidates=candidates)
            literal = bool(groups)
        total, capped = _grep_total(
            sum(1 for g in groups for line in g if line[2] == "match"), ceiling)
        groups, truncated = _trim_context_groups(groups, limit)
        count = sum(
            1 for g in groups for line in g if line[2] == "match"
        )
        literal_note = _literal_note(pattern, count) if literal else ""
        file_count = len({g[0][0] for g in groups if g})
        out = [literal_note, f"({count} results in {file_count} files{_scanned_suffix(scanned)}{hidden}, "
               f"limit {limit_label}, context {context}"
               f"{_truncation_suffix(truncated, total, capped)})\n"]
        if count == 0:
            out.append(_shim_facade_note(path))
            out.append(_quote_pair_note(
                pattern, lambda inner: _grep_recursive_context(
                    inner, path, 1, context, excl, candidates=candidates)))
            out.append(_case_insensitive_note(
                pattern, lambda p: _grep_recursive_context(
                    p, path, 1, context, excl, candidates=candidates)))
        current_file: str = ""
        first_group = True
        cut: List[Tuple[str, int]] = []
        for group in groups:
            group_file = group[0][0] if group else ""
            if group_file != current_file:
                current_file = group_file
                out.append(f"{current_file}\n")
                first_group = True  # reset separator for new file
            if not first_group:
                out.append("  --\n")
            first_group = False
            for _fp, lineno, kind, content in group:
                if len(content) > _grep_line_cap():
                    cut.append((_fp, lineno))
                capped = _cap_grep_line(content, full)
                if kind == "match":
                    out.append(f"  {lineno}:{capped}\n")
                else:
                    out.append(f"  {lineno}-{capped}\n")
        _note = _grep_full_note(cut) if full else _grep_cut_note(cut)
        if _note:
            out.insert(2, _note)
        out.append("\n")
        return _cap_context_window("".join(out), "grep_around")

    # ceiling + 1 (#448, #1073): a count that equals the limit is ambiguous
    # between "exactly N matches" and "stopped at N", and only looking past the
    # cap settles it. #448 looked exactly one past, which settled the yes/no and
    # left the scope unknown; the bound is the counting ceiling now, so the same
    # walk answers "how many" as well as "were there more".
    #
    # The walk itself is still already paid for — `candidates` above traversed
    # the whole tree to produce `scanned` — so this is never a second walk. What
    # it costs is reading file *contents* further: to the (limit+1)th match
    # before, to the (ceiling+1)th now. Measured on a 67,855-file tree, dense
    # pattern, limit 20: 0.0103s then, 0.05s now, against 10.3s for counting
    # everything and 4.3s for the traversal both of them sit on top of. On an
    # exact result neither stops early at all, which is what proving exactness
    # has always meant here.
    ceiling = _grep_count_ceiling(limit)
    hits = _grep_recursive(pattern, path, ceiling + 1, excl, candidates=candidates)
    literal = False
    if not hits and _is_regexy(pattern):
        hits = _grep_recursive(re.escape(pattern), path, ceiling + 1, excl, candidates=candidates)
        literal = bool(hits)
    truncated = len(hits) > limit
    total, capped = _grep_total(len(hits), ceiling)
    hits = hits[:limit]
    count = len(hits)
    literal_note = _literal_note(pattern, count) if literal else ""
    file_count = len({fp for fp, _, _ in hits})

    out = [literal_note,
           f"({count} results in {file_count} files{_scanned_suffix(scanned)}{hidden}, "
           f"limit {limit_label}{_truncation_suffix(truncated, total, capped)})\n"]
    if count == 0:
        out.append(_shim_facade_note(path))
        out.append(_quote_pair_note(pattern, lambda inner: _grep_recursive(
            inner, path, 1, excl, candidates=candidates)))
        out.append(_case_insensitive_note(pattern, lambda p: _grep_recursive(
            p, path, 1, excl, candidates=candidates)))
    current_file = ""
    cut: List[Tuple[str, int]] = []
    for fp, lineno, content in hits:
        if fp != current_file:
            current_file = fp
            out.append(f"{fp}\n")
        if len(content) > _grep_line_cap():
            cut.append((fp, lineno))
        out.append(f"  {lineno}:{_cap_grep_line(content, full)}\n")
    _note = _grep_full_note(cut) if full else _grep_cut_note(cut)
    if _note:
        out.insert(2, _note)
    out.append("\n")

    # Auto-read: single small file + at least one match → emit full file.
    # Gated on BOTH byte size and line count (#362): a file under the byte cap
    # but with many lines still overshoots context, so cap both dimensions.
    if (not no_auto_read
            and count > 0
            and os.path.isfile(path)
            and os.path.getsize(path) < _get_op_int("read", "max_bytes", MAX_READ_BYTES)):
        line_cap = _get_op_int("read", "max_autoread_lines", MAX_AUTOREAD_LINES)
        if _count_lines(path, on_error=MAX_AUTOREAD_LINES + 1) > line_cap:
            out.append(f"[auto-read skipped: > {line_cap} lines — "
                       f"read:{path}:full to see it]\n")
        else:
            out.append(f"[auto-read: single file < {_get_op_int('read', 'max_bytes', MAX_READ_BYTES)} bytes, "
                       "match found]\n")
            # The LIMIT here is this op's own default, never a bound anyone
            # typed — said out loud rather than left to be inferred from a
            # positive integer that looks identical either way (#1820).
            out.append(render_file(path, 0, _get_op_int("read", "max_lines", MAX_READ_LINES),
                                   limit_defaulted=True))

    return "".join(out)


_AROUND_DIR_SKIP = {".git", "node_modules", "__pycache__", ".venv", "venv", ".tox", "vendor"}
_AROUND_DIR_MAX_FILES = 20


def _grep_line_cap() -> int:
    return _get_op_int("grep", "max_line_chars", MAX_GREP_LINE_CHARS)


def _cap_grep_line(content: str, full: bool = False) -> str:
    """Truncate one grep output line to a char budget (#363).

    Files with pathological single lines (minified JS, a 25KB one-line
    `@extends` PHPDoc) turn a single hit into a screenful. Cap the line and
    say how much was dropped so the reader knows to widen deliberately.
    Configurable via builtin-ops.grep.max_line_chars or
    SUPERTOOL_GREP_MAX_LINE_CHARS.

    `full=True` (#1712) returns `content` untouched — the default cap stays
    the protection for every call that does not ask, and this is the opt-out
    for the one call that does. The caller is still responsible for deciding
    whether the line WOULD have been cut (see `_grep_line_cap`), because that
    is what the disclosure note needs regardless of which shape ran.
    """
    if full:
        return content
    cap = _grep_line_cap()
    if len(content) <= cap:
        return content
    return f"{content[:cap]}… (+{len(content) - cap} chars)"


def _grep_cut_note(cut: List[Tuple[str, int]]) -> str:
    """Name the read that recovers a line `grep` cut (#1489).

    `… (+191 chars)` says a line was cut and nothing about how to get the
    rest, which is what a caller wants precisely when the cut line is the
    `edit` anchor they came for. `read:PATH:N-N` returns it byte-exactly —
    measured against raw bytes on files from 500 to 20000 chars with tabs,
    trailing spaces and unicode (#1489, PR #1576) — so the remedy exists and
    was simply not written down where the truncation happens.

    Above the body rather than under it, for #945's reason: a note that
    arrives after the output it would have replaced is a round-trip late.
    """
    if not cut:
        return ""
    fp, lineno = cut[0]
    plural = "" if len(cut) == 1 else "s"
    return (f"note: {len(cut)} line{plural} cut at {_grep_line_cap()} chars — "
            f"read:PATH:LINE-LINE returns a cut line byte-exactly, e.g. "
            f"read:{fp}:{lineno}-{lineno}\n")


def _grep_full_note(cut: List[Tuple[str, int]]) -> str:
    """Disclosure counterpart to `_grep_cut_note` when `full=True` (#1712).

    Nothing was cut here — `full` suppressed it — so a note built out of
    `_grep_cut_note`'s wording would claim a truncation that did not happen,
    the same "absence read as absence" shape CLAUDE.md's house defect names.
    `cut` still names every line that WOULD have exceeded the cap without
    `full`, because that is the fact worth surfacing: the caller asked for
    the whole line and this says whether asking changed anything.

    Empty `cut` returns "" rather than a note claiming full mode ran for
    nothing — when no line was long enough to matter, `full` genuinely had no
    effect, and staying silent about a non-event is the honest read, not the
    "reads as clean when it did nothing" trap: there is no separate clean
    state to disclose because default output would have looked identical.
    """
    if not cut:
        return ""
    plural = "" if len(cut) == 1 else "s"
    return (f"note: full: {len(cut)} line{plural} would exceed "
            f"{_grep_line_cap()} chars and {'was' if len(cut) == 1 else 'were'} "
            f"returned in full, uncut, because full was requested\n")


def _cap_context_window(text: str, op_name: str) -> str:
    """Cap a context-window op's output at a byte budget (#241).

    around:/grep_around: with a large :N on a file of long (e.g. minified)
    lines can emit hundreds of KB in one op, blowing the caller's context.
    Truncate at the last line boundary within the cap and append a footer
    that points at the narrower tools. Configurable via
    builtin-ops.<op>.max_bytes or SUPERTOOL_<OP>_MAX_BYTES.
    """
    cap = _get_op_int(op_name, "max_bytes", MAX_AROUND_BYTES)
    encoded = text.encode("utf-8", errors="surrogateescape")
    if len(encoded) <= cap:
        return text
    clipped = encoded[:cap].decode("utf-8", errors="ignore")
    # Truncate at the last line boundary so we never cut mid-line. nl == -1
    # means a single line longer than the cap — nothing to trim to, pass the
    # partial through (the footer still flags it).
    nl = clipped.rfind("\n")
    if nl >= 0:
        clipped = clipped[:nl + 1]
    dropped = len(encoded) - len(clipped.encode("utf-8", errors="ignore"))
    return (clipped +
            f"… truncated (~{dropped} more bytes) — narrow context (:N) "
            f"or use between: for the whole symbol\n")


def _around_one_file(regex: "re.Pattern[str]", path: str, n: int) -> str:
    """Render the first match of regex in file at path with n lines context.

    Returns an empty string when the file has no match (caller filters these
    out so dir fan-out only shows hits).
    """
    try:
        with open(path, "rb") as f:
            raw_lines = f.read().splitlines(keepends=True)
    except OSError as e:
        return f"ERROR: could not read {path}: {e}\n"

    lines = []
    for raw in raw_lines:
        try:
            lines.append(raw.decode("utf-8", errors="replace"))
        except Exception:
            lines.append("<binary line>\n")

    match_lineno = None
    for i, line in enumerate(lines):
        if regex.search(line):
            match_lineno = i
            break

    if match_lineno is None:
        return ""

    total = len(lines)
    start = max(0, match_lineno - n)
    end = min(total, match_lineno + n + 1)

    out = [f"(match at line {match_lineno + 1}, showing lines {start + 1}–{end}, "
           f"{total} lines total)\n"]
    for i in range(start, end):
        marker = "→" if i == match_lineno else " "
        out.append(f"{i + 1:>6}{marker}{lines[i]}")
    out.append("\n")
    return "".join(out)


def op_around(pattern: str, path: str, n: int = 10,
               via_payload: bool = False) -> str:
    """around, guarded and disclosed exactly as op_grep is (#1120, #1821).

    Split from the body for the same reason op_grep is: the refusal and the
    rewrite disclosure belong to every caller of the op, and leaving `around`
    with only the refusal reproduced the original asymmetry one level down —
    a rewrite that merely changes the pattern was still invisible here.

    "exactly as op_grep is" was written in #1120 and was not true until #1821:
    the BRE-rewrite disclosure travelled and the `:`-rejoin disclosure did not,
    so `around:mode:.*remind|title:DIR` rejoined the pattern the same way grep
    does, found two files, and named neither half of the split it had just
    guessed at. The PATH slot that does NOT resolve was already refused by
    `_colon_split_hint` in dispatch; this is the other branch, where the guess
    succeeds and the answer is the plausible wrong one.

    `via_payload` mirrors `op_grep`'s (#1825): the @file/@- route takes
    `pattern` verbatim under a `pattern` key, so there is nothing to
    disclose and the note's own remedy names the route already in use.
    """
    _effective, refusal, note = _pattern_gate(pattern)
    if refusal:
        return refusal
    prefix = "" if via_payload else _pattern_read_as_note(pattern, path, "around")
    return (prefix
            + note
            + _op_around(pattern, path, n))


def _op_around(pattern: str, path: str, n: int = 10) -> str:
    """Show N lines before and after the first match of PATTERN in PATH.

    PATH can be a file (first match in that file) or a directory (first
    match per file, skipping files with no match, capped at
    _AROUND_DIR_MAX_FILES). Hidden and heavy dirs (.git, node_modules,
    vendor, …) are skipped during dir walk.
    """
    if not pattern:
        return "ERROR: empty pattern\n"
    # The rewrite is applied here as well as in op_around so a direct call to
    # the private body still runs the pattern the caller meant; the helper is
    # idempotent, and the refusal/disclosure live in the public wrapper.
    pattern, _ = _bre_alternation_rewrite(pattern)
    if not path:
        return "ERROR: empty path\n"

    try:
        regex = re.compile(pattern)
    except re.error:
        regex = re.compile(re.escape(pattern))

    if not os.path.isdir(path) and not os.path.isfile(path):
        # #734: `around` is PATTERN:PATH[:N] and its sibling `around_line`
        # is PATH:LINE[:N] — same op-name family, opposite argument order.
        # Swap them and PATH resolves to a line number, which is never a
        # real path but IS a plausible typo. `wrong CWD?` cannot be right
        # here (the cwd was fine), so name the actual mistake instead —
        # never redirect the call itself, only the advice.
        suggest = None
        # `pattern` becomes the PATH slot of the suggested `around_line:`
        # call, and this route reaches an unresolved `pattern` no colon-CLI
        # caller could: `around` was dropped from `_PATH_ARG_POSITIONS`
        # entirely (#1166 -- see `_around_line_delegation`'s own comment),
        # and the colon route's actual gate for this exact swapped-argument
        # shape is `_around_line_delegation`'s `_gate_paths([pattern])`,
        # which refuses `around:/etc/hosts:3` before `op_around` ever runs.
        # The `@payload`/`batch` route applies no containment to `pattern`
        # at all (it is a regex there, not a declared path), so it could
        # reach this branch with an out-of-bounds `pattern` and print a
        # suggestion the colon route's own gate refuses (#1146) -- the same
        # shape as the `git-checkout` hint in #850: never prescribe a
        # command the tool's own sibling rejects. `_containment_error`
        # mirrors the gate `_swap_suggest` (#1711) already applies to its
        # own candidate below.
        if _is_ascii_int(path) and _containment_error([pattern]) is None:
            suggest = (
                "`around` takes PATTERN:PATH[:N] — "
                f"'{path}' was read as the path. Did you mean: "
                f"around_line:{pattern}:{path}[:N]"
            )
        if suggest is None:
            # #1711: the int-path case above is around_line confusion, a
            # different mistake from a plain PATTERN/PATH swap — this is
            # the general case, reachable at any arity including the 3-arg
            # form the int check above cannot cover.
            suggest = _swap_suggest(
                "around", "PATTERN:PATH[:N]", "pattern", pattern, path,
                f"around:{path}:{pattern}[:N]")
        return _path_not_found(path, label="file", suggest=suggest,
                               op="around")

    def _render(rx: "re.Pattern[str]") -> Tuple[str, bool]:
        """Render the around-window for `rx`. Returns (output, matched) so the
        caller can decide whether to retry with an escaped literal pattern."""
        if os.path.isdir(path):
            hits: List[str] = []
            scanned = 0
            for root, dirs, files in os.walk(path):
                dirs[:] = [d for d in dirs
                           if not d.startswith(".") and d not in _AROUND_DIR_SKIP]
                for name in sorted(files):
                    if name.startswith("."):
                        continue
                    fpath = os.path.join(root, name)
                    scanned += 1
                    rendered = _around_one_file(rx, fpath, n)
                    if rendered and rendered.startswith("ERROR:"):
                        continue
                    if not rendered:
                        continue
                    rel = _fwd(_safe_relpath(fpath, path))
                    hits.append(f"=== {rel} ===\n{rendered}")
                    if len(hits) >= _AROUND_DIR_MAX_FILES:
                        break
                if len(hits) >= _AROUND_DIR_MAX_FILES:
                    break
            if not hits:
                return (f"(no match for {pattern!r} in {path}, "
                        f"scanned {scanned} file(s))\n\n", False)
            header = f"(matched {len(hits)} file(s) under {path}"
            if len(hits) >= _AROUND_DIR_MAX_FILES:
                header += f", capped at {_AROUND_DIR_MAX_FILES}"
            header += f", scanned {scanned})\n"
            return _cap_context_window(header + "".join(hits), "around"), True

        rendered = _around_one_file(rx, path, n)
        if not rendered:
            return (f"(no match for {pattern!r} in {path})\n"
                    + _shim_facade_note(path) + "\n"), False
        return _cap_context_window(rendered, "around"), True

    out_text, matched = _render(regex)
    if not matched and _is_regexy(pattern):
        lit_text, lit_matched = _render(re.compile(re.escape(pattern)))
        if lit_matched:
            return _literal_note(pattern, lit_text.count("=== ") or 1) + lit_text
    if not matched:
        # Above the window, like `_literal_note` — a note explaining a zero is
        # read only if it precedes the thing it explains (#1435).
        quote_note = _quote_pair_note(
            pattern, lambda inner: _render(_compile_lenient(inner))[1])
        if quote_note:
            return quote_note + out_text
    return out_text


def op_between_symbol(symbol: str, path: str) -> str:
    """Return the body of a named function/method/class via tree-sitter.

    SYMBOL is matched against definition node names. First match wins; the
    info line reports total match count when the name is ambiguous.
    """
    if not symbol:
        return "ERROR: empty symbol\n"
    if not path:
        return "ERROR: empty path\n"
    if os.path.isdir(path):
        return (f"ERROR: between only works on single files, not "
                f"directories: {path}\n")
    if not os.path.isfile(path):
        # #1711: same swap check as `grep`/`around` — SYMBOL:PATH shares
        # the shape, and a swap here has no ':' to be caught by dispatch's
        # `_colon_split_hint` either.
        _swap = _swap_suggest(
            "between", "SYMBOL:PATH", "symbol", symbol, path,
            f"between:{path}:{symbol}")
        if _swap:
            return f"ERROR: file not found: {path}\n  {_swap}\n"
        return f"ERROR: file not found: {path}\n"

    if not _has_tree_sitter():
        return ("ERROR: between symbol mode requires tree-sitter "
                "(install tree-sitter-language-pack). "
                "Use 'between:re:START:END:PATH' for regex line slicing.\n")

    ext = os.path.splitext(path)[1].lower()
    lang_name = _TS_LANG_MAP.get(ext)
    if not lang_name:
        return (f"ERROR: tree-sitter does not support extension {ext!r}. "
                "Use 'between:re:START:END:PATH' for regex line slicing.\n")

    found = _ts_find_node(path, lang_name, symbol)
    if found is None and lang_name in _TS_GRAMMAR_FAILED:
        return (f"ERROR: tree-sitter grammar for {ext!r} failed to load "
                f"({_TS_GRAMMAR_FAILED[lang_name]}) - cannot search for "
                f"symbols. Use 'between:re:START:END:PATH' for regex line "
                f"slicing.\n")
    # Retry with modifiers/parens stripped so a signature pasted from source
    # resolves like the bare name would (#363). Exact match still wins.
    normalized = _normalize_symbol_query(symbol)
    if found is None and normalized != symbol:
        found = _ts_find_node(path, lang_name, normalized)
        if found is not None:
            symbol = normalized
    if found is None:
        extra = "" if normalized == symbol else f" (also tried {normalized!r})"
        return (f"ERROR: symbol {symbol!r} not found in {path}{extra}\n"
                + _shim_facade_note(path))
    node, kind, total = found

    start_line = node.start_point[0]
    end_line = node.end_point[0]

    try:
        with open(path, "rb") as f:
            raw_lines = f.read().splitlines(keepends=True)
    except OSError as e:
        return f"ERROR: could not read {path}: {e}\n"

    total_lines = len(raw_lines)
    end_line = min(end_line, total_lines - 1)

    suffix = f", {total} matches (first shown)" if total > 1 else ""
    out = [f"({kind} {symbol!r}, lines {start_line + 1}–{end_line + 1}, "
           f"{end_line - start_line + 1} lines{suffix})\n"]
    for i in range(start_line, end_line + 1):
        try:
            line = raw_lines[i].decode("utf-8", errors="replace")
        except Exception:
            line = "<binary line>\n"
        marker = "→" if i == start_line else " "
        out.append(f"{i + 1:>6}{marker}{line}")
    out.append("\n")
    return "".join(out)


def op_between_pattern(start: str, end: str, path: str) -> str:
    """Return inclusive line slice from first line matching START to first
    subsequent line matching END (regex, language-agnostic).
    """
    if not start:
        return "ERROR: empty start pattern\n"
    if not end:
        return "ERROR: empty end pattern\n"
    if not path:
        return "ERROR: empty path\n"
    if os.path.isdir(path):
        return (f"ERROR: between only works on single files, not "
                f"directories: {path}\n")
    if not os.path.isfile(path):
        return f"ERROR: file not found: {path}\n"

    start, start_refusal, start_note = _pattern_gate(start)
    if start_refusal:
        return start_refusal
    end, end_refusal, end_note = _pattern_gate(end)
    if end_refusal:
        return end_refusal
    # _pattern_gate can silently rewrite the caller's pattern (e.g. bash-grep
    # BRE alternation \| -> a plain |), the same disclosure op_grep/op_around
    # print above their result -- carried through every return below so a
    # rewritten start/end is never a silent difference from what was typed.
    gate_notes = start_note + end_note

    try:
        start_re = re.compile(start)
    except re.error:
        start_re = re.compile(re.escape(start))
    try:
        end_re = re.compile(end)
    except re.error:
        end_re = re.compile(re.escape(end))

    try:
        with open(path, "rb") as f:
            raw_lines = f.read().splitlines(keepends=True)
    except OSError as e:
        return gate_notes + f"ERROR: could not read {path}: {e}\n"

    lines: List[str] = []
    for raw in raw_lines:
        try:
            lines.append(raw.decode("utf-8", errors="replace"))
        except Exception:
            lines.append("<binary line>\n")

    start_idx: int | None = None
    for i, line in enumerate(lines):
        if start_re.search(line):
            start_idx = i
            break
    if start_idx is None:
        return (gate_notes
                + f"ERROR: start pattern {start!r} not matched in {path}\n"
                + _shim_facade_note(path))

    end_idx: int | None = None
    for i in range(start_idx + 1, len(lines)):
        if end_re.search(lines[i]):
            end_idx = i
            break
    if end_idx is None:
        return (gate_notes
                + f"ERROR: end pattern {end!r} not matched after line "
                f"{start_idx + 1} in {path}\n")

    out = [gate_notes,
           f"(slice lines {start_idx + 1}–{end_idx + 1}, "
           f"{end_idx - start_idx + 1} lines)\n"]
    for i in range(start_idx, end_idx + 1):
        marker = "→" if i in (start_idx, end_idx) else " "
        out.append(f"{i + 1:>6}{marker}{lines[i]}")
    out.append("\n")
    return "".join(out)


def op_glob(pattern: str, no_exclude: bool = False, no_auto_read: bool = False) -> str:
    """Find files matching pattern. Auto-reads concrete file paths unless no_auto_read."""
    if not pattern:
        return "ERROR: empty pattern\n"
    # `glob` is the one path-taking op that does NOT expand `~` (#1300), and it
    # says so rather than answering `(0 files)` — a zero the tool manufactured,
    # indistinguishable from a real empty directory, which is this codebase's
    # house defect.
    #
    # Why refuse instead of expanding, when every other op now expands: the
    # expansion elsewhere is written back *behind* `_safe_path`, so it can only
    # name what the gate already cleared. `glob` is not in
    # `_PATH_ARG_POSITIONS` and resolves its own pattern, so the gate it sits
    # behind is the one below rather than dispatch's — and that gate reads the
    # pattern, not a path, so it cannot approve an expansion of one. Expanding
    # here would widen what the op reaches rather than fix what it says. The
    # honest half of #1300, kept deliberately after #1366.
    if pattern.startswith("~"):
        _eg = _fwd(os.path.join(os.path.expanduser("~"), "*.txt"))
        return ("ERROR: unsupported path form: glob does not expand `~` — "
                f"pass an absolute path (e.g. glob:{_eg}).\n")

    # Containment, first half: the pattern's own reach, before disk is touched
    # (#1366). Until this landed `glob` was outside the gate entirely, so
    # `glob:/tmp/x/*.txt` listed what `read:/tmp/x/f.txt` refused — filenames
    # rather than bytes, which is an existence oracle across the boundary
    # (#1135, #1142). It refuses rather than answering `(0 files)`, the zero
    # the tool manufactures.
    _pattern_err = _glob_pattern_containment_error(pattern)
    if _pattern_err:
        return _pattern_err

    # Auto-promote: concrete path with no wildcards that points to a file
    if not WILDCARD_CHARS.search(pattern) and os.path.isfile(pattern):
        if no_auto_read:
            return f"{pattern}\n"
        return ("[auto-read: concrete path, no wildcards]\n"
                + render_file(pattern, 0,
                              _get_op_int("read", "max_lines", MAX_READ_LINES),
                              limit_defaulted=True))

    excl = _get_exclude_paths("glob", no_exclude)
    # over_fetch=1 (#448): `(N files)` implies completeness the same way grep's
    # header did, and one file past the cap is what distinguishes "N matched"
    # from "N shown".
    cap = _get_op_int("glob", "max_results", MAX_GLOB_RESULTS)
    hidden_files: List[str] = []
    files = _glob_files(pattern, excl, over_fetch=1, hidden=hidden_files)
    # glob is CWD-relative — `glob.glob` and the `os.walk` branch both resolve
    # against `os.getcwd()`, and so does the containment gate above. (This
    # comment and the `reads.md` row said "repo root" until #1366; from a
    # subdirectory that is a different directory and the wrong answer.) So a
    # pattern naming a mid-path segment
    # (`SiBrief/**/*.php` for a dir nested under Dvsi/src2/) returns 0 while the
    # same segment works fine in grep. Retry once with a `**/` prefix so both
    # ops accept the same mental model (#363).
    midpath_note = ""
    # `~` is not in this tuple: a tilde pattern returns above and never
    # reaches the retry, so listing it here would be a guard for a case that
    # cannot arrive (#1300).
    if (not files and "/" in pattern
            and not pattern.startswith(("/", "**", "./", "../"))):
        retry = "**/" + pattern
        hidden_files = []
        files = _glob_files(retry, excl, over_fetch=1, hidden=hidden_files)
        if files:
            midpath_note = (f"[mid-path retry: no match under cwd for "
                            f"{pattern!r} — matched {retry!r}]\n")
    # Containment, second half: what the pattern could not predict (#1366). A
    # wildcard component can land on a symlink pointing out of the tree, so the
    # pattern is contained and the match is not. Checked BEFORE the cap, or a
    # cap-length prefix would decide whether the call is refused.
    #
    # And before the exclude-paths filter, which is the ordering half of #1392.
    # `_glob_files` drops excluded entries into `hidden_files`, so a pattern
    # that climbed out into `~/.ssh` had every match filtered away and the
    # containment check then saw an empty list: the call rendered as
    # `(0 files, 6 files hidden by exclude-paths)`, which is a refusal turned
    # into exact cardinality about a directory outside the boundary. The
    # excluded entries are checked too — being excluded is a reason not to
    # *print* a file, never a reason not to *gate* it.
    #
    # Refuses the whole call, names no file, and does not say how many (#1392).
    # Dropping the offending entries would hand back a narrowed list with an
    # honest-looking `(N files)` header — the population-narrowed-in-silence
    # defect this gate exists to prevent — printing them would disclose the
    # outside paths the refusal is about, and the count is the third form of
    # the same disclosure: `51 match(es)` and `2 match(es)` are two different
    # answers about a directory the caller may not read.
    if _glob_results_escape(files + hidden_files):
        return ("ERROR: path escapes cwd: " + repr(pattern) + " — at least "
                "one match resolves outside cwd, reached through a symlink "
                "the pattern does not name. Refusing the whole call: a list "
                "with those entries dropped would report a population it had "
                "silently narrowed, and how many there were is itself an "
                "answer about a directory outside the boundary. "
                + _ALLOW_OUTSIDE_HINT + chr(10))
    glob_truncated = len(files) > cap
    files = files[:cap]
    # Strip common directory prefix when 2+ files share one
    prefix = ""
    if len(files) >= 2:
        prefix = os.path.commonpath(files)
        if prefix and not prefix.endswith(os.sep):
            prefix += os.sep
        # Only strip if it saves something meaningful (> 10 chars)
        if len(prefix) <= 10:
            prefix = ""
    truncation = " — TRUNCATED, more files match" if glob_truncated else ""
    out = [midpath_note,
           f"({len(files)} files{_hidden_suffix(len(hidden_files))}{truncation})\n"]
    if prefix:
        fwd_prefix = _fwd(prefix)
        out.append(f"{fwd_prefix}\n")
        for f in files:
            out.append(f"  {_fwd(f[len(prefix):])}\n")
    else:
        for f in files:
            out.append(_fwd(f) + "\n")
    out.append("\n")

    # Auto-read: glob returned exactly 1 file — save the follow-up read round-trip.
    # Gated on BOTH byte size and line count (#362): see op_grep for rationale.
    if not no_auto_read and len(files) == 1 and os.path.getsize(files[0]) < _get_op_int("read", "max_bytes", MAX_READ_BYTES):
        line_cap = _get_op_int("read", "max_autoread_lines", MAX_AUTOREAD_LINES)
        if _count_lines(files[0], on_error=MAX_AUTOREAD_LINES + 1) > line_cap:
            out.append(f"[auto-read skipped: > {line_cap} lines — "
                       f"read:{files[0]}:full to see it]\n")
        else:
            out.append(f"[auto-read: glob returned 1 file]\n")
            out.append(render_file(files[0], 0,
                                   _get_op_int("read", "max_lines", MAX_READ_LINES),
                                   limit_defaulted=True))

    return "".join(out)


def op_ls(path: str = ".") -> str:
    if not os.path.isdir(path):
        return f"ERROR: not a directory: {path}\n"
    try:
        items = sorted(os.listdir(path))
    except OSError as e:
        return f"ERROR: could not list {path}: {e}\n"
    out = [f"({len(items)} items)\n"]
    for item in items:
        full = os.path.join(path, item)
        marker = "/" if os.path.isdir(full) else ""
        out.append(f"{item}{marker}\n")
    out.append("\n")
    return "".join(out)


def _probe_minified(probe: str) -> bool:
    """True when text overflows the byte cap AND holds a line long enough that
    line-based head/tail/wc return one giant useless line. Catches both pure
    single-line blobs and minified bodies behind a short leading comment
    (e.g. `/* license */\\n` + 300KB of minified JS), which a plain
    "no newline in the first chunk" test misses (#240).
    """
    if len(probe) <= MAX_READ_BYTES:
        return False
    longest = max((len(seg) for seg in probe.split("\n")), default=0)
    return longest >= MINIFIED_LINE_CHARS


def _looks_minified(path: str) -> bool:
    """Cheap minified-file detector: probes only the first MAX_READ_BYTES."""
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            probe = f.read(MAX_READ_BYTES + 1)
    except OSError:
        return False
    return _probe_minified(probe)


def _char_window(path: str, n_chars: int, from_end: bool = False) -> str:
    """First/last n_chars of a file as a character window, with a marker
    reporting total size. For minified files where line slicing is
    meaningless (#240).
    """
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        data = f.read()
    total = len(data)
    if from_end:
        window = data[-n_chars:]
        clipped = total - len(window)
        return (f"({total} chars, minified; showing last {len(window)}, "
                f"{clipped} clipped)\n… ({clipped} earlier chars)\n{window}\n")
    window = data[:n_chars]
    clipped = total - len(window)
    return (f"({total} chars, minified; showing first {len(window)})\n"
            f"{window}\n… ({clipped} more chars truncated)\n")


def op_tail(path: str, n: int = 20) -> str:
    if not path or not os.path.isfile(path):
        return f"ERROR: file not found: {path}\n"
    if _looks_minified(path):
        return _char_window(
            path, _get_op_int("tail", "char_window", CHAR_WINDOW_CHARS),
            from_end=True)
    with open(path, "rb") as f:
        raw_lines = f.read().splitlines(keepends=True)
    total = len(raw_lines)
    start = max(0, total - n)
    out = [f"({total} lines total, showing last {n})\n"]
    for i in range(start, total):
        try:
            line = raw_lines[i].decode("utf-8", errors="replace")
        except Exception:
            line = "<binary line>\n"
        out.append(f"{i + 1:>6}→{line}")
    out.append("\n")
    return "".join(out)


def op_head(path: str, n: int = 20) -> str:
    if not path or not os.path.isfile(path):
        return f"ERROR: file not found: {path}\n"
    if _looks_minified(path):
        return _char_window(
            path, _get_op_int("head", "char_window", CHAR_WINDOW_CHARS),
            from_end=False)
    with open(path, "rb") as f:
        raw_lines = f.read().splitlines(keepends=True)
    total = len(raw_lines)
    limit = min(n, total)
    out = [f"({total} lines total, showing first {limit})\n"]
    for i in range(limit):
        try:
            line = raw_lines[i].decode("utf-8", errors="replace")
        except Exception:
            line = "<binary line>\n"
        out.append(f"{i + 1:>6}→{line}")
    out.append("\n")
    return "".join(out)


def op_wc(path: str) -> str:
    if not path or not os.path.isfile(path):
        return f"ERROR: file not found: {path}\n"

    # RTK delegation
    if _rtk_enabled() and _has_rtk():
        rtk_out = _rtk_run(["wc", path])
        if rtk_out is not None:
            return rtk_out + "\n"

    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError as e:
        return f"ERROR: could not read {path}: {e}\n"
    text = data.decode("utf-8", errors="replace")
    lines = text.count("\n")
    words = len(text.split())
    chars = len(text)
    result = f"{lines} {words} {chars} {path}"
    if _probe_minified(text):
        result += f"  [minified — {chars} chars, {len(data)} bytes]"
    return result + "\n"


def op_check(preset: str, path: str) -> str:
    """Run a named validation check from the ops section of .supertool.json."""
    if not preset:
        return "ERROR: empty preset name\n"

    main_config = _load_config()
    ops = main_config.get("ops", {})
    if preset in ops:
        result = _resolve_custom_op(preset, ["check", path])
        if result is not None:
            return result

    if not ops:
        return "ERROR: no ops defined in .supertool.json\n"
    available = ", ".join(sorted(ops.keys()))
    return f"ERROR: unknown check {preset!r}. Available: {available}\n"


def op_diff(path1: str, path2: str) -> str:
    """Show unified diff between two files."""
    for p in (path1, path2):
        if not p:
            return "ERROR: diff requires two file paths\n"
        if not os.path.isfile(p):
            return f"ERROR: file not found: {p}\n"

    try:
        with open(path1, "r", errors="replace", encoding="utf-8") as f:
            lines1 = f.readlines()
        with open(path2, "r", errors="replace", encoding="utf-8") as f:
            lines2 = f.readlines()
    except OSError as e:
        return f"ERROR: could not read file: {e}\n"

    diff = list(difflib.unified_diff(
        lines1, lines2, fromfile=path1, tofile=path2, lineterm=""
    ))
    if not diff:
        return "files are identical\n"
    return "\n".join(diff) + "\n"


# git's way of saying "nothing here is version-controlled" — an answer, and
# the common one for a file outside any checkout. Every other non-zero exit
# (a held index lock, a dubious-ownership refusal, a corrupt object store) is
# a lookup that did not happen, and renders as PATH_META_UNKNOWN.
_NOT_A_REPO = "not a git repository"

# The third state of the working-tree marker (#705). `?`, `!` and `m` are
# answers; their joint absence used to mean both "this file matches the index"
# and "the lookup failed", which inverts the marker's whole job on the failure
# leg — a modified file reading as clean, on every `read`.
#
# It is a token rather than a punctuation mark on purpose. The field looks
# one character wide because its busiest members are, but it is a
# space-separated token list whose members already run to `non-utf8`, `crlf`
# and `->target broken`, so nothing was costing a character. A punctuation
# mark would have had to be one the reader has no meaning for yet — and every
# free character is free precisely because it says nothing, which is the
# wrong property for the token that has to say the most. `git?` names the
# check that declined and cannot be confused with the three answers it
# replaces, none of which mention git.
PATH_META_UNKNOWN = "git?"

# The fourth state, added for #1397: the repo-root walk (`_path_meta_repo_root`)
# already climbed from this path's own directory to the filesystem root and
# found no `.git` anywhere. A per-path `git status` spawn in that state can
# only ever answer "not a git repository" (a spawn that produced nothing) or
# fail (which would render as `PATH_META_UNKNOWN` above) -- so it is skipped
# outright rather than paid on every single-file read outside a repository.
#
# Skipping the spawn must not be confused with the spawn having answered
# "clean" (no marker at all): the walk has known gaps -- an unreadable `.git`
# (permissions), or a `GIT_DIR` that escaped the #714 scrub and points
# somewhere the walk never looks -- where git would actually disagree with
# it. `PATH_META_NOT_CONSULTED` says plainly "the walk found no repository;
# git was never asked", which is a claim about what this process *checked*,
# not a claim about the file's working-tree state. Never conflate it with
# `PATH_META_UNKNOWN` (git *was* asked and failed to answer) or with a clean
# answer (nothing appended, the marker's normal silence).
PATH_META_NOT_CONSULTED = "no-git"


# One `git status` answer per repo root, reused across the paths rendered in a
# single process (#1126). The filed shape was a memo keyed by path; that cannot
# help, because the case it exists for — a batched `read` of seven files — asks
# about seven *different* paths and every lookup would miss. What repeats is the
# spawn, not the question, so this coalesces the query instead of remembering
# the answer: 6 paths cost 2 spawns rather than 6.
#
# Values, three states rather than two, so "we did not look" stays distinct from
# "we looked and it was clean" (docs/validators.md, "Declining instead of
# guessing"):
#
#   "primed"    one per-path query has been paid here; the next path escalates.
#               A lone `read` — the overwhelmingly common call — therefore costs
#               exactly what it always did, with no bulk query bolted on.
#   "declined"  the repo-wide query timed out or failed. Stay on the per-path
#               route forever in this process rather than reading its silence
#               as a clean tree. A repo with a very large ignored subtree is the
#               expected way to land here.
#   dict        {"codes": …, "taken_ns": …} — servable.
#
# Three things invalidate it, and they are the whole answer to "what is the
# correct lifetime":
#
#   1. `_atomic_write` clears it — every mutating op passes through there, so an
#      `edit` between two `read`s cannot be answered from the older snapshot.
#   2. `dispatch` clears it after any op outside `_PARALLEL_SAFE_OPS` — that is
#      what catches an index change from a preset (`git-commit`), which moves no
#      file mtime and so is invisible to (3).
#   3. A path whose mtime is at or after the snapshot instant is not served from
#      it. This is the one that covers a writer outside supertool entirely.
#
# Residual: a file rewritten by another process within the same filesystem mtime
# tick as the snapshot. Accepted knowingly, and it is a marker one call stale,
# not a marker computed against the wrong repository.
_PATH_META_BULK: Dict[str, Any] = {}


def _path_meta_bulk_drop() -> None:
    """Invalidate every snapshot, keeping the `declined` verdicts.

    A snapshot describes a tree at an instant, so a write invalidates it. A
    `declined` does not describe the tree at all — it records that this repo's
    status query does not come back inside the budget, which is a property of
    the repository (a very large ignored subtree, most likely) and is just as
    true after the write as before it. Clearing it wholesale meant the second
    path after every single edit re-paid the full 2s timeout to rediscover the
    same fact, turning a one-off cost into a per-edit one.
    """
    for key in [k for k, v in _PATH_META_BULK.items() if v != "declined"]:
        del _PATH_META_BULK[key]


#: Historical hardcoded value for both `git status` spawns behind
#: `_path_meta_suffix` -- kept as the default so an unconfigured install
#: behaves exactly as before (#1398).
_PATH_META_GIT_TIMEOUT_DEFAULT = 2


def _path_meta_git_timeout() -> int:
    """The `git status` spawn budget for `_path_meta_suffix`, in seconds.

    Was a bare `timeout=2` at both spawn sites, with no config key (#1398).
    Parallel mode spawns several of these against that same fixed budget, so
    raising worker count raised the rate of honest `git?` declines (the token
    meaning "the working-tree lookup declined, state unknown") purely as a
    function of a constant nobody could tune.

    A flat, tunable budget rather than one that scales with worker count: the
    workers here are separate `supertool` invocations (often separate
    processes with no shared coordination point), so there is nothing this
    function could read to learn "how many others are inflight right now"
    without new cross-process machinery. Making the existing constant
    configurable lets a caller who *does* know their own concurrency (a CI
    job setting `-n auto`, a batch script) raise it once; it does not attempt
    to infer that number automatically.

    No retry-once-before-declining here either: it would double the worst
    case latency of every read on a genuinely slow tree, and the issue itself
    asks that be measured before being chosen rather than guessed at. Left
    as a follow-up.

    Routed through `_get_op_int`, so an explicit `0` is refused loudly and
    the default is used instead (#1332's lesson: a threshold's `0` must not
    be silently swallowed into the default with no trace).
    """
    return _get_op_int(
        "read", "git_timeout_seconds", _PATH_META_GIT_TIMEOUT_DEFAULT)


def _path_meta_bulk_fill(root: str) -> Optional[Dict[str, Any]]:
    """One repo-wide `git status`, parsed into {relpath: XY}. None = declined.

    `-z` rather than the quoting `--porcelain` default: with NUL separators git
    emits path bytes verbatim, so a filename with a quote, a newline or a
    non-UTF-8 byte survives instead of arriving backslash-escaped and failing to
    match the path we were asked about.

    `taken_ns` is sampled *before* the spawn, so a file written while git was
    still walking the tree compares as newer than the snapshot and is refused by
    the caller's mtime check rather than answered from it.
    """
    taken_ns = time.time_ns()
    try:
        r = subprocess.run(
            ["git", "status", "--porcelain", "-z", "--ignored=matching"],
            capture_output=True, timeout=_path_meta_git_timeout(), cwd=root,
        )
    except (subprocess.TimeoutExpired, OSError):
        return None
    if r.returncode != 0:
        return None
    codes: Dict[str, str] = {}
    fields = r.stdout.split(b"\x00")
    i = 0
    while i < len(fields):
        record = fields[i]
        i += 1
        if len(record) < 4:
            continue
        xy = record[:2].decode("ascii", errors="replace")
        name = record[3:].decode("utf-8", errors="surrogateescape")
        if xy[:1] in ("R", "C"):
            # A rename or copy is two fields: the new name, then the original.
            i += 1
        codes[name.rstrip("/")] = xy
    return {"codes": codes, "taken_ns": taken_ns}


_PATH_META_ROOT_CACHE: Dict[str, str] = {}


def _path_meta_repo_root(path: str) -> str:
    """Repo root for `path`, walking the path AS WRITTEN — links unresolved.

    Deliberately not `_dirs_up_to_repo_root`, which calls `os.path.realpath`
    first. That is correct for the formatter/validator machinery it was built
    for, where the question is which config governs the real file. It is the
    wrong question here, and measurably so: a symlink `link.txt` inside repo A
    pointing at a file in repo B resolved to **B's root**, so the marker beside
    a file in A was computed from a completely different repository's status.

    The per-path query this coalesces runs with `cwd=os.path.dirname(
    os.path.abspath(path))`, so climbing from that same directory is what keeps
    the two routes answering about the same repository.
    """
    start = os.path.dirname(os.path.abspath(path)) or os.sep
    cached = _PATH_META_ROOT_CACHE.get(start)
    if cached is not None:
        return cached
    current = start
    root = ""
    while True:
        if os.path.exists(os.path.join(current, ".git")):
            root = current
            break
        parent = os.path.dirname(current)
        if parent == current:
            break
        current = parent
    _PATH_META_ROOT_CACHE[start] = root
    return root


def _path_meta_bulk_code(codes: Dict[str, str], rel: str) -> str:
    """This path's status letters from a repo-wide snapshot, or "" for clean.

    Ancestors are consulted because a repo-wide `git status` collapses whole
    directories: an ignore rule of `build/` yields one `!! build/` record and
    nothing for the files under it, and an untracked directory collapses the
    same way. Asked per-path, git names the file itself — so without this walk
    a `read` of an ignored file would lose its `!` marker the moment the query
    was coalesced, which is a cheaper answer that is not the same answer.
    """
    code = codes.get(rel)
    if code:
        return code
    parts = rel.split("/")
    for depth in range(len(parts) - 1, 0, -1):
        code = codes.get("/".join(parts[:depth]))
        if code in ("!!", "??"):
            return code
    return ""


def _short_age(seconds: float) -> str:
    """Seconds as one short human token.

    Byte-identical to `presets/git/status.py::_age` (itself duplicated from
    `presets/git/worktrees.py::_age`) -- one number is what changes between a
    seconds-old file and an hours-old one, and every render in this tool that
    states an age should say it the same way rather than inventing a fourth
    spelling. Duplicated rather than imported for the same reason those two
    are: this module has no import path to `presets/git/status.py`, and a
    number this small does not earn one.
    """
    seconds = max(0.0, float(seconds))
    if seconds < 90:
        return f"{int(seconds)}s"
    if seconds < 5400:
        return f"{int(seconds // 60)}m"
    if seconds < 172800:
        return f"{int(seconds // 3600)}h"
    return f"{int(seconds // 86400)}d"


def _read_freshness_note(path: str) -> str:
    """', modified Xs/Xm/Xh/Xd ago' for a read/workspace header (#1379).

    `(N lines, N bytes)` and the `[complete file -- no more lines]` footer
    beside it are both true statements about the instant this op ran, and
    carry no signal about how long ago that instant was. A reader with no
    memory -- which is every agent in this loop -- cannot tell a fact it read
    a minute ago from one it read just now unless the render says so; without
    it, `[complete file]` reads as a standing fact rather than a claim with an
    expiry, which cost one session ~20 minutes of forensics reconciling a
    17-line read against a file that had grown to 35 lines a minute later.

    One extra `os.stat` -- `_path_meta_suffix` already pays this exact cost
    for the same path a few characters later in the same header line, so this
    is not a second file-system round trip class, only a second read of a
    value the op was already about to fetch.
    """
    try:
        mtime = os.stat(path).st_mtime
    except OSError:
        return ""
    return f", modified {_short_age(time.time() - mtime)} ago"


def _path_meta_suffix(path: str, sample: bytes = b"") -> str:
    """Compact suffix for read/workspace meta line. Empty when nothing notable.
    Tokens: ->target [broken] | bin | non-utf8 | ? | ! | m | x | crlf | Nd|Nw|Nmo
            | git? (the working-tree lookup declined — state unknown, not clean)
            | no-git (the repo-root walk found no `.git` at all — git was never
              asked, distinct from both a clean answer and git? (#1397))

    The `Nd|Nw|Nmo` token is a symlink-only fact as of #1379: it used to fire
    for any file over a week old, using `os.lstat`'s mtime, on the same line
    `_read_freshness_note` now prints right before this suffix using
    `os.stat`'s mtime (follows a symlink; `os.lstat` does not). For a plain
    file the two stats see the same mtime, so both used to say the identical
    age twice in two unlabeled spellings on one line -- `modified 20d ago)
    20d` -- confusable as two different facts rather than one restated.
    For a symlink they can genuinely disagree (the link's own mtime vs. the
    target's), which is a real fact worth keeping, not a duplicate to drop --
    a link's own age is exactly the kind of thing `->target` beside it is
    already disclosing. Gated on `os.path.islink` so the token now fires only
    where it says something the freshness note does not already say.
    """
    parts = []
    if sample:
        head = sample[:8192]
        if b"\x00" in head:
            parts.append("bin")
        else:
            try:
                head.decode("utf-8")
            except UnicodeDecodeError:
                parts.append("non-utf8")
            if b"\r\n" in head:
                parts.append("crlf")
            if b"<<<<<<< " in head or b"\n=======\n" in head:
                parts.append("cf!")
    if os.path.islink(path):
        try:
            target = os.readlink(path)
        except OSError:
            target = "?"
        broken = " broken" if not os.path.exists(path) else ""
        parts.append(f"->{target}{broken}")
    mtime_ns = None
    try:
        st = os.lstat(path)
        mtime_ns = st.st_mtime_ns
        if st.st_mode & 0o111 and not os.path.isdir(path):
            parts.append("x")
        # Symlink-only (#1379) — see the docstring above for why. `path` is
        # re-tested rather than reusing the earlier `os.path.islink` result:
        # both are cheap `lstat`-backed checks, and duplicating the syscall
        # is a smaller cost than threading a boolean an extra 20 lines.
        if os.path.islink(path):
            age_sec = max(0, int(time.time() - st.st_mtime))
            SEVEN_DAYS = 7 * 86400
            if age_sec > SEVEN_DAYS:
                days = age_sec // 86400
                if days < 30:
                    parts.append(f"{days}d")
                elif days < 365:
                    parts.append(f"{days // 7}w")
                else:
                    parts.append(f"{days // 30}mo")
    except OSError:
        pass

    # Answer from this process's repo-wide snapshot when there is one and it is
    # old enough to speak for this file (#1126). `code` stays None until
    # something has actually looked, so the per-path spawn below is skipped only
    # on a real answer and never on a missing one.
    code = None
    absolute = os.path.abspath(path)
    root = _path_meta_repo_root(path)
    if not root:
        # The walk climbed from this path's own directory to the filesystem
        # root and found no `.git` anywhere -- the per-path spawn below runs
        # with that exact same directory as its cwd, so it could only ever
        # report "not a git repository" too, or fail. Skip a spawn that
        # cannot produce information (#1397) and say so explicitly rather
        # than rendering as clean, which would silently paper over the
        # walk's own gaps (an unreadable `.git`, an escaped `GIT_DIR`).
        parts.append(PATH_META_NOT_CONSULTED)
        return (" " + " ".join(parts)) if parts else ""
    # A repo-wide status keys every record by the path as it sits in the tree.
    # If any component of this path is a link, the name we would look up is not
    # the name git recorded, the lookup misses, and a miss is indistinguishable
    # from clean — a modified or untracked file rendering as if it were neither.
    # One `realpath` compare is cheaper than being wrong, and the per-path query
    # below handles links correctly today.
    through_a_link = os.path.realpath(path) != absolute
    if root and not through_a_link:
        entry = _PATH_META_BULK.get(root)
        if entry is None:
            _PATH_META_BULK[root] = "primed"
        elif entry == "primed":
            filled = _path_meta_bulk_fill(root)
            entry = filled if filled is not None else "declined"
            _PATH_META_BULK[root] = entry
        servable = (
            isinstance(entry, dict)
            and mtime_ns is not None
            and mtime_ns < entry["taken_ns"]
        )
        if servable:
            try:
                rel = os.path.relpath(absolute, root)
            except ValueError:
                # Different drives on Windows. The walk said this path is under
                # `root`, so this should not happen; if it does, re-ask git
                # rather than invent a relative path.
                rel = ""
            if rel and not rel.startswith(os.pardir):
                code = _path_meta_bulk_code(entry["codes"], rel.replace(os.sep, "/"))

    if code is None:
        try:
            # The pathspec is the bare filename, not `path`: this runs with a
            # cwd of the file's own directory, so a path written relative with a
            # directory component in it (`sub/s.txt`, the form the CLI hands
            # over) was resolved a second time against that directory. git
            # warned on stderr, exited 0 with empty stdout, and the marker
            # silently vanished while the bulk arm answered correctly for the
            # same file — #1186. The cwd itself stays, because it is what keeps
            # this route and `_path_meta_repo_root` talking about the same
            # repository when a path crosses a repo boundary.
            #
            # `:(literal)` because a filename is not a pattern: a clean
            # `t[a].txt` globbed onto its modified sibling `ta.txt` and reported
            # that file's ` m` as its own. The bulk arm looks the name up in a
            # dict, so it was already literal — this is the same two-answers
            # divergence, in the direction that invents a marker rather than
            # losing one. The magic prefix and not the `--literal-pathspecs`
            # flag: that one has to precede the subcommand, and the shims the
            # decline tests install match on `$1` being `status` (#705). A flag
            # that silently un-shims a fixture is a test that stops testing.
            r = subprocess.run(
                ["git", "status", "--porcelain", "--ignored=matching", "--",
                 ":(literal)" + os.path.basename(absolute)],
                capture_output=True, text=True, timeout=_path_meta_git_timeout(),
                cwd=os.path.dirname(absolute) or ".", encoding="utf-8", errors="replace",
            )
            if r.returncode == 0:
                code = r.stdout[:2]
            elif _NOT_A_REPO not in r.stderr.lower():
                parts.append(PATH_META_UNKNOWN)
        except subprocess.TimeoutExpired:
            parts.append(PATH_META_UNKNOWN)
        except OSError:
            # No git on this machine, or the file's directory went away under us.
            # Nothing here was ever going to answer, so a decline that can never
            # resolve would be noise on every read (docs/validators.md,
            # "Declining instead of guessing").
            pass

    if code == "??":
        parts.append("?")
    elif code == "!!":
        parts.append("!")
    elif code and ("M" in code or "A" in code):
        parts.append("m")
    return (" " + " ".join(parts)) if parts else ""


def op_stat(path: str) -> str:
    """Show file/dir/symlink metadata: size, mtime, kind. Symlinks show target + broken flag."""
    if not path:
        return "ERROR: empty path\n"
    if not os.path.lexists(path):
        return f"ERROR: not found: {path}\n"

    try:
        st = os.lstat(path)
    except OSError as e:
        return f"ERROR: could not stat {path}: {e}\n"

    size = st.st_size
    modified = datetime.fromtimestamp(st.st_mtime).strftime("%Y-%m-%d %H:%M:%S")
    if os.path.islink(path):
        try:
            target = os.readlink(path)
        except OSError:
            target = "?"
        broken = " (broken)" if not os.path.exists(path) else ""
        return f"{size} {modified} symlink {path} -> {target}{broken}\n"
    kind = "dir" if os.path.isdir(path) else "file"
    return f"{size} {modified} {kind} {path}\n"


def op_around_line(path: str, line: int, n: int = 10) -> str:
    """Show N lines of context around a specific line number."""
    if not path or not os.path.isfile(path):
        return _path_not_found(path, label="file", op="around_line")
    if line < 1:
        return f"ERROR: line number must be >= 1, got {line}\n"

    try:
        with open(path, "r", errors="replace", encoding="utf-8") as f:
            lines = f.readlines()
    except OSError as e:
        return f"ERROR: could not read {path}: {e}\n"

    total = len(lines)
    if line > total:
        return f"ERROR: line {line} exceeds file length ({total} lines)\n"

    start = max(0, line - 1 - n)
    end = min(total, line + n)
    out = [f"({total} lines total, showing lines {start + 1}–{end})\n"]
    for i in range(start, end):
        marker = "→" if i == line - 1 else " "
        out.append(f"{i + 1:>6}{marker}{lines[i]}")
    if not lines[end - 1].endswith("\n"):
        out.append("\n")
    return "".join(out)


def op_tree(path: str, depth: int = 3,
            exclude_paths: Tuple[str, ...] = ()) -> str:
    """Show directory structure with depth limit."""
    if not path:
        path = "."
    if not os.path.isdir(path):
        return f"ERROR: not a directory: {path}\n"
    if depth < 1:
        return f"ERROR: depth must be >= 1, got {depth}\n"

    out: List[str] = []
    hidden: List[str] = []
    base = os.path.abspath(path)
    cwd = os.getcwd()

    def _walk(dir_path: str, prefix: str, current_depth: int) -> None:
        if current_depth > depth:
            return
        try:
            entries = sorted(os.listdir(dir_path))
        except OSError:
            return
        # Filter hidden files/dirs
        entries = [e for e in entries if not e.startswith(".")]
        dirs = [e for e in entries if os.path.isdir(os.path.join(dir_path, e))]
        files = [e for e in entries if not os.path.isdir(os.path.join(dir_path, e))]

        for f in files:
            if exclude_paths:
                rel_f = _safe_relpath(os.path.join(dir_path, f), cwd)
                if _is_excluded(rel_f, exclude_paths):
                    if _is_disclosable_exclusion(rel_f, exclude_paths):
                        hidden.append(f)
                    continue
            out.append(f"{prefix}{f}\n")
        for d in dirs:
            if exclude_paths:
                rel = _safe_relpath(os.path.join(dir_path, d), cwd)
                if _is_excluded(rel, exclude_paths):
                    continue
            out.append(f"{prefix}{d}/\n")
            if current_depth < depth:
                _walk(os.path.join(dir_path, d), prefix + "  ", current_depth + 1)

    out.append(f"{os.path.basename(base)}/\n")
    _walk(base, "  ", 1)
    if hidden:
        out.append(f"({len(hidden)} files hidden by exclude-paths)\n")
    return "".join(out)



# ---------------------------------------------------------------------------
# map — three-tier symbol extraction (tree-sitter → ctags → regex)
# ---------------------------------------------------------------------------

# Tree-sitter detection (lazy, cached)
# Supports two packages: tree-sitter-language-pack (newer, Python 3.10+)
# and tree-sitter-languages (older, Python 3.8-3.12)
_TS_CHECKED = False
_TS_AVAILABLE = False
_TS_PACKAGE: str = ""  # "pack" or "languages"


def _has_tree_sitter() -> bool:
    """Check if a tree-sitter language package is importable. Cached."""
    global _TS_CHECKED, _TS_AVAILABLE, _TS_PACKAGE
    if not _TS_CHECKED:
        _TS_CHECKED = True
        try:
            from tree_sitter_language_pack import get_parser  # noqa: F401
            _TS_AVAILABLE = True
            _TS_PACKAGE = "pack"
        except ImportError:
            try:
                from tree_sitter_languages import get_parser  # noqa: F401
                _TS_AVAILABLE = True
                _TS_PACKAGE = "languages"
            except ImportError:
                _TS_AVAILABLE = False
    return _TS_AVAILABLE


# ctags detection (lazy, cached)
_CTAGS_PATH: str | None = None
_CTAGS_CHECKED = False


def _has_ctags() -> str | None:
    """Return ctags binary path if available, None otherwise. Cached."""
    global _CTAGS_PATH, _CTAGS_CHECKED
    if not _CTAGS_CHECKED:
        _CTAGS_CHECKED = True
        # #2611: same class as _has_rtk()'s own fix above -- a raw which()
        # would resolve a repo-planted "ctags.exe" ahead of the real tool
        # on Windows, and the result is spawned by the caller below with
        # no cwd=.
        _CTAGS_PATH = _which_excluding_cwd("ctags")
    return _CTAGS_PATH


# Language extension → tree-sitter language name
_TS_LANG_MAP: Dict[str, str] = {
    ".php": "php", ".py": "python", ".js": "javascript", ".ts": "typescript",
    ".tsx": "tsx", ".jsx": "javascript", ".go": "go", ".rs": "rust",
    ".java": "java", ".rb": "ruby", ".c": "c", ".cpp": "cpp", ".h": "c",
    ".hpp": "cpp", ".cs": "c_sharp", ".swift": "swift", ".kt": "kotlin",
    ".scala": "scala", ".lua": "lua", ".sh": "bash", ".bash": "bash",
    ".md": "markdown", ".markdown": "markdown",
}

# Names that differ between the two supported packages for the same
# language. tree-sitter-languages (older) used "c_sharp"; the actively
# maintained tree-sitter-language-pack calls it "csharp" (#790). Keyed
# either direction — _ts_get_parser tries both the requested name and,
# if that fails, its counterpart here.
_TS_LANG_ALIASES: Dict[str, str] = {
    "c_sharp": "csharp",
}

# lang_name -> reason, populated the first time a grammar fails to load
# under either spelling. Lets callers report "grammar unavailable"
# distinctly from "parsed fine, file has no definitions" (#790) instead
# of a LookupError silently becoming an empty result.
_TS_GRAMMAR_FAILED: Dict[str, str] = {}


def _ts_get_parser(lang_name: str) -> Any:
    """Resolve a tree-sitter parser for lang_name, trying the other
    package's spelling before giving up (#790).

    Raises LookupError, with both attempted names in the message, when
    neither spelling resolves under the installed package. Failures are
    cached in _TS_GRAMMAR_FAILED so repeated calls for the same language
    (e.g. across every file of a map: run) don't re-attempt both names
    and so callers can distinguish this from a working grammar that
    simply found nothing.
    """
    if lang_name in _TS_GRAMMAR_FAILED:
        raise LookupError(_TS_GRAMMAR_FAILED[lang_name])

    if _TS_PACKAGE == "pack":
        from tree_sitter_language_pack import get_parser
    else:
        from tree_sitter_languages import get_parser

    try:
        return get_parser(lang_name)
    except LookupError as first_err:
        alt = _TS_LANG_ALIASES.get(lang_name)
        if alt is None:
            alt = next(
                (k for k, v in _TS_LANG_ALIASES.items() if v == lang_name), None)
        if alt is not None:
            try:
                return get_parser(alt)
            except LookupError as second_err:
                reason = (f"neither {lang_name!r} nor {alt!r} recognised by "
                          f"the installed tree-sitter package "
                          f"({first_err}; {second_err})")
                _TS_GRAMMAR_FAILED[lang_name] = reason
                raise LookupError(reason) from second_err
        reason = f"{lang_name!r} not recognised by the installed tree-sitter package ({first_err})"
        _TS_GRAMMAR_FAILED[lang_name] = reason
        raise LookupError(reason) from first_err

# Tree-sitter node types that represent definitions, per language family
_TS_DEF_NODES: Dict[str, Dict[str, str]] = {
    "php": {
        "class_declaration": "class", "interface_declaration": "interface",
        "trait_declaration": "trait", "enum_declaration": "enum",
        "method_declaration": "method", "function_definition": "function",
        "const_element": "const", "property_declaration": "property",
        "use_declaration": "use",
    },
    "python": {
        "class_definition": "class", "function_definition": "def",
    },
    "javascript": {
        "class_declaration": "class", "function_declaration": "function",
        "method_definition": "method", "arrow_function": "function",
    },
    "typescript": {
        "class_declaration": "class", "function_declaration": "function",
        "method_definition": "method", "interface_declaration": "interface",
        "type_alias_declaration": "type", "enum_declaration": "enum",
    },
    "go": {
        "type_declaration": "type", "function_declaration": "func",
        "method_declaration": "method",
    },
    "rust": {
        "struct_item": "struct", "enum_item": "enum", "trait_item": "trait",
        "function_item": "fn", "impl_item": "impl",
    },
    "java": {
        "class_declaration": "class", "interface_declaration": "interface",
        "method_declaration": "method", "enum_declaration": "enum",
    },
    "ruby": {
        "class": "class", "module": "module", "method": "def",
    },
}

# Shared fallback for languages not in the map
_TS_DEF_NODES_DEFAULT: Dict[str, str] = {
    "class_declaration": "class", "class_definition": "class",
    "function_declaration": "function", "function_definition": "function",
    "method_declaration": "method", "method_definition": "method",
    "interface_declaration": "interface",
}


# #1954: `map` used to render a class's name and line span and nothing about
# what it inherits from -- a subclass with two methods of its own and a
# parent that supplies the rest read as a small standalone class. Capped
# so a wide interface list cannot blow the line, and the cut is SAID
# ("+N more") rather than a shorter list that silently claims completeness.
_HIERARCHY_MAX_NAMES = 4

# Node types that wrap a class/interface's parent + interface names, across
# the grammars in the issue's own table. One neutral `<` separator for every
# language rather than a language-shaped `extends`/`implements`: cheaper and
# reads consistently on a mixed-language map, at the cost of not
# distinguishing a parent class from an interface on sight -- the trade the
# issue leaves as an open call, decided here in the cheaper direction.
_TS_HERITAGE_CONTAINER_TYPES = frozenset({
    "base_clause", "class_interface_clause",  # php
    "class_heritage",                          # js/ts classes (wraps extends_clause/implements_clause)
    "superclass", "super_interfaces",          # java classes, ruby
    "extends_interfaces",                      # java interfaces: `interface Sub extends A, B`
    "extends_type_clause",                     # ts/js interfaces: `interface Sub extends A, B`
})

# Node types whose text IS a name -- recursion into a heritage clause stops
# here rather than walking into the name's own (empty) children.
_TS_HIERARCHY_LEAF_TYPES = frozenset({
    "identifier", "type_identifier", "constant", "name",
    "scoped_identifier", "qualified_name",
})


def _ts_hierarchy_names(container: Any) -> List[str]:
    """Named leaves under a heritage/interface-list node, source order.

    Recurses through wrapper nodes a grammar interposes (TS/JS nests the
    real names one level down inside `extends_clause`/`implements_clause`;
    Java nests interface names inside a `type_list`) and skips a Python
    `keyword_argument` (`metaclass=Meta` is not a base class) entirely.
    """
    names: List[str] = []

    def _walk(node: Any) -> None:
        if node.type == "keyword_argument":
            return
        if node.type in _TS_HIERARCHY_LEAF_TYPES:
            text = node.text.decode("utf-8", errors="replace").strip()
            if text:
                names.append(text)
            return
        for child in node.named_children:
            _walk(child)

    for child in container.named_children:
        _walk(child)
    return names


def _ts_class_hierarchy(node: Any) -> List[str]:
    """Base class + interfaces named by a class/interface definition node's
    own heritage clauses (#1954). Node-type driven: the same information
    sits under a different child depending on grammar, so this asks each
    known shape rather than assuming one."""
    names: List[str] = []
    for child in node.children:
        if child.type in _TS_HERITAGE_CONTAINER_TYPES:
            names.extend(_ts_hierarchy_names(child))
        elif child.type == "argument_list" and node.type == "class_definition":
            # Python: `class Foo(Base, metaclass=Meta):` -- the base list is
            # the class_definition's own argument_list, not a named clause.
            names.extend(_ts_hierarchy_names(child))
    return names


def _format_hierarchy_suffix(names: List[str]) -> str:
    """`< A, B, C` (or `, +N more`) appended to a class's own map line."""
    if not names:
        return ""
    shown = names[:_HIERARCHY_MAX_NAMES]
    rest = len(names) - len(shown)
    suffix = ", ".join(shown)
    if rest > 0:
        suffix += f", +{rest} more"
    return f" < {suffix}"


# Keywords that appear in front of a symbol when it's copy-pasted out of source
# (`async function foo`, `public static function bar`, `class Baz`). `between:`
# used to reject those verbatim strings, so a caller who typed the signature the
# way it reads in the file fell back to grep+read (#363).
_SYMBOL_MODIFIER_WORDS = frozenset({
    "async", "function", "func", "fn", "def", "class", "interface", "trait",
    "enum", "struct", "type", "method", "public", "private", "protected",
    "static", "final", "abstract", "readonly", "export", "default", "const",
    "let", "var", "impl", "sub", "proc",
})


def _normalize_symbol_query(symbol: str) -> str:
    """Reduce a source-shaped symbol query to the bare definition name.

    `async function fillAndSubmit` -> `fillAndSubmit`
    `public static function getFoo` -> `getFoo`
    `fillAndSubmit(page)` -> `fillAndSubmit`

    A query that is *only* a keyword (`function`) is returned unchanged — it
    may legitimately be the name being looked for.
    """
    s = symbol.strip()
    if "(" in s:
        s = s.split("(", 1)[0].strip()
    tokens = [t for t in s.split() if t]
    if not tokens:
        return symbol.strip()
    while len(tokens) > 1 and tokens[0].lower() in _SYMBOL_MODIFIER_WORDS:
        tokens.pop(0)
    return tokens[0]


def _ts_parse(parser: Any, source_bytes: bytes) -> Any:
    """Parse source through tree-sitter, handling 0.25's str-only API."""
    try:
        return parser.parse(source_bytes)
    except TypeError:
        return parser.parse(source_bytes.decode("utf-8", errors="replace"))


def _ts_extract(path: str, lang_name: str) -> List[Tuple[str, str, int, int]]:
    """Extract symbols from a file using tree-sitter.

    Returns list of (kind, name, line, depth) tuples.
    depth: 0 = top-level, 1 = inside a class, 2 = nested deeper.
    """
    try:
        parser = _ts_get_parser(lang_name)
    except LookupError:
        # Grammar could not be loaded under either known spelling — recorded
        # in _TS_GRAMMAR_FAILED by _ts_get_parser. Returning [] keeps the
        # existing contract (ctags/regex tiers still get a chance below
        # this call), but the failure is now discoverable rather than
        # silently identical to "parsed fine, no definitions" (#790).
        return []

    try:
        with open(path, "rb") as f:
            source = f.read()
        tree = _ts_parse(parser, source)
    except (OSError, UnicodeDecodeError) as e:
        if os.environ.get("SUPERTOOL_DEBUG"):
            print(f"[supertool debug] _ts_extract failed for {path}: {e}",
                  file=__import__("sys").stderr)
        return []

    if lang_name == "markdown":
        return _ts_extract_markdown(source, tree)

    def_nodes = _TS_DEF_NODES.get(lang_name, _TS_DEF_NODES_DEFAULT)
    symbols: List[Tuple[str, str, int, int, int]] = []

    def _walk(node: Any, depth: int = 0) -> None:
        node_type = node.type
        if node_type in def_nodes:
            kind = def_nodes[node_type]
            name = _ts_node_name(node, lang_name)
            if kind in ("class", "interface"):
                hierarchy = _ts_class_hierarchy(node)
                if hierarchy:
                    name += _format_hierarchy_suffix(hierarchy)
            line = node.start_point[0] + 1  # 0-indexed → 1-indexed
            end_line = node.end_point[0] + 1
            symbols.append((kind, name, line, end_line, depth))
            # Recurse into class/struct/impl bodies for methods
            for child in node.children:
                _walk(child, depth + 1)
        else:
            for child in node.children:
                _walk(child, depth)

    _walk(tree.root_node)
    return symbols


_MD_HEADING_NODES = frozenset({"atx_heading", "setext_heading"})


def _ts_extract_markdown(source: bytes, tree: Any) -> List[Tuple[str, str, int, int, int]]:
    """Extract the heading tree from a parsed markdown document (#887).

    Headings are markdown's symbols, but they do not fit the generic walker:
    the level lives in a marker child (`atx_h2_marker`, `setext_h1_underline`)
    rather than in the node type, the name lives in an `inline` child rather
    than a `name` field, and nesting is by level rather than by containment.

    Returned as (kind, name, line, end_line, depth) with kind "h1".."h6" and
    depth = level - 1, so `## Foo` renders one step in from `# Foo`.
    """
    symbols: List[Tuple[str, str, int, int, int]] = []

    def _level(node: Any) -> int:
        for child in node.children:
            ctype = child.type
            if ctype.startswith("atx_h") and ctype.endswith("_marker"):
                return int(ctype[5:-7])
            if ctype.startswith("setext_h") and ctype.endswith("_underline"):
                return int(ctype[8:-10])
        return 1

    def _title(node: Any) -> str:
        for child in node.children:
            if child.type in ("inline", "paragraph", "heading_content"):
                return source[child.start_byte:child.end_byte].decode(
                    "utf-8", errors="replace").strip()
        raw = source[node.start_byte:node.end_byte].decode(
            "utf-8", errors="replace")
        return raw.splitlines()[0].lstrip("#").strip(" #").strip()

    def _walk(node: Any) -> None:
        if node.type in _MD_HEADING_NODES:
            level = _level(node)
            name = _title(node)
            if name:
                line = node.start_point[0] + 1
                symbols.append((f"h{level}", name, line, line, level - 1))
            return
        for child in node.children:
            _walk(child)

    _walk(tree.root_node)
    symbols.sort(key=lambda s: s[2])
    return symbols


def _ts_node_name(node: Any, lang_name: str) -> str:
    """Extract the name from a tree-sitter definition node.

    Tries the 'name' field first, then common field names per language.
    Falls back to the first identifier child.
    """
    # Direct name field (works for most declarations)
    name_node = node.child_by_field_name("name")
    if name_node:
        return name_node.text.decode("utf-8", errors="replace")

    # PHP const_element: name is the first child
    if node.type == "const_element" and node.children:
        return node.children[0].text.decode("utf-8", errors="replace")

    # PHP property_declaration (typed props since 7.4): nested
    # property_element → variable_name → $name. Walk down to find the variable.
    if node.type == "property_declaration":
        for child in node.children:
            if child.type == "property_element":
                for grandchild in child.children:
                    if grandchild.type == "variable_name":
                        # variable_name → "$" + name child; strip the leading $
                        text = grandchild.text.decode("utf-8", errors="replace")
                        return text.lstrip("$")

    # Fallback: first identifier-like child
    for child in node.children:
        if child.type in ("identifier", "name", "type_identifier",
                          "property_identifier"):
            return child.text.decode("utf-8", errors="replace")

    return "<anonymous>"


def _ts_find_node(
    path: str, lang_name: str, name: str
) -> Tuple[Any, str, int] | None:
    """Find first definition node by name. Returns (node, kind, total_matches) or None.

    total_matches lets callers warn when a name resolves to multiple definitions.
    """
    try:
        parser = _ts_get_parser(lang_name)
    except LookupError:
        # See _ts_extract: failure is recorded in _TS_GRAMMAR_FAILED so
        # op_between_symbol can report it instead of a misleading
        # "symbol not found" (#790).
        return None

    try:
        with open(path, "rb") as f:
            source = f.read()
        tree = _ts_parse(parser, source)
    except (OSError, UnicodeDecodeError) as e:
        if os.environ.get("SUPERTOOL_DEBUG"):
            print(f"[supertool debug] _ts_find_node failed for {path}: {e}",
                  file=__import__("sys").stderr)
        return None

    def_nodes = _TS_DEF_NODES.get(lang_name, _TS_DEF_NODES_DEFAULT)
    matches: List[Tuple[Any, str]] = []

    def _walk(node: Any) -> None:
        if node.type in def_nodes:
            if _ts_node_name(node, lang_name) == name:
                matches.append((node, def_nodes[node.type]))
        for child in node.children:
            _walk(child)

    _walk(tree.root_node)
    if not matches:
        return None
    node, kind = matches[0]
    return node, kind, len(matches)


def _ctags_extract(path: str) -> List[Tuple[str, str, int, str]]:
    """Extract symbols from a file using universal-ctags.

    Returns list of (kind_label, name, line, scope) tuples.
    scope is the parent class/function name or "" for top-level.
    """
    ctags = _has_ctags()
    if not ctags:
        return []

    try:
        result = subprocess.run(
            [ctags, "--output-format=json", "--fields=+nKS", "-f", "-", path],
            capture_output=True, text=True, timeout=15, encoding="utf-8", errors="replace"
        )
    except (subprocess.TimeoutExpired, OSError):
        return []

    symbols: List[Tuple[str, str, int, str]] = []
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        try:
            tag = json.loads(line)
        except json.JSONDecodeError:
            continue
        if tag.get("_type") != "tag":
            continue
        name = tag.get("name", "")
        kind = tag.get("kind", tag.get("kindFull", ""))
        lineno = tag.get("line", 0)
        scope = tag.get("scope", "")
        symbols.append((kind, name, lineno, scope))

    return symbols


# Regex patterns for symbol extraction (fallback when no tools available)
_REGEX_PATTERNS: Dict[str, List[Tuple[str, re.Pattern[str]]]] = {
    ".php": [
        ("class", re.compile(
            r"^\s*(?:abstract\s+|final\s+)?class\s+(\w+)", re.MULTILINE)),
        ("interface", re.compile(
            r"^\s*interface\s+(\w+)", re.MULTILINE)),
        ("trait", re.compile(
            r"^\s*trait\s+(\w+)", re.MULTILINE)),
        ("enum", re.compile(
            r"^\s*enum\s+(\w+)", re.MULTILINE)),
        ("function", re.compile(
            r"^\s*(?:abstract\s+)?(?:public|protected|private|static|\s)*\s*function\s+(\w+)",
            re.MULTILINE)),
        ("const", re.compile(
            r"^\s*(?:public|protected|private)?\s*const\s+(\w+)",
            re.MULTILINE)),
    ],
    ".py": [
        ("class", re.compile(r"^class\s+(\w+)", re.MULTILINE)),
        ("def", re.compile(r"^(\s*)def\s+(\w+)", re.MULTILINE)),
    ],
    ".js": [
        ("class", re.compile(r"^\s*(?:export\s+)?class\s+(\w+)", re.MULTILINE)),
        ("function", re.compile(
            r"^\s*(?:export\s+)?(?:async\s+)?function\s+(\w+)", re.MULTILINE)),
    ],
    ".ts": [
        ("class", re.compile(r"^\s*(?:export\s+)?class\s+(\w+)", re.MULTILINE)),
        ("interface", re.compile(
            r"^\s*(?:export\s+)?interface\s+(\w+)", re.MULTILINE)),
        ("type", re.compile(
            r"^\s*(?:export\s+)?type\s+(\w+)", re.MULTILINE)),
        ("function", re.compile(
            r"^\s*(?:export\s+)?(?:async\s+)?function\s+(\w+)", re.MULTILINE)),
        ("enum", re.compile(
            r"^\s*(?:export\s+)?enum\s+(\w+)", re.MULTILINE)),
    ],
    ".go": [
        ("type", re.compile(r"^type\s+(\w+)", re.MULTILINE)),
        ("func", re.compile(r"^func\s+(?:\([^)]+\)\s+)?(\w+)", re.MULTILINE)),
    ],
    ".rs": [
        ("struct", re.compile(
            r"^\s*(?:pub\s+)?struct\s+(\w+)", re.MULTILINE)),
        ("enum", re.compile(r"^\s*(?:pub\s+)?enum\s+(\w+)", re.MULTILINE)),
        ("trait", re.compile(r"^\s*(?:pub\s+)?trait\s+(\w+)", re.MULTILINE)),
        ("fn", re.compile(
            r"^\s*(?:pub\s+)?(?:async\s+)?fn\s+(\w+)", re.MULTILINE)),
        ("impl", re.compile(r"^\s*impl(?:<[^>]+>)?\s+(\w+)", re.MULTILINE)),
    ],
    ".java": [
        ("class", re.compile(
            r"^\s*(?:public|protected|private)?\s*(?:abstract\s+|final\s+)?class\s+(\w+)",
            re.MULTILINE)),
        ("interface", re.compile(
            r"^\s*(?:public|protected|private)?\s*interface\s+(\w+)",
            re.MULTILINE)),
        ("enum", re.compile(
            r"^\s*(?:public|protected|private)?\s*enum\s+(\w+)",
            re.MULTILINE)),
    ],
    ".rb": [
        ("class", re.compile(r"^\s*class\s+(\w+)", re.MULTILINE)),
        ("module", re.compile(r"^\s*module\s+(\w+)", re.MULTILINE)),
        ("def", re.compile(r"^\s*def\s+(\w+)", re.MULTILINE)),
    ],
}
# .tsx and .jsx share the TS/JS patterns
_REGEX_PATTERNS[".tsx"] = _REGEX_PATTERNS[".ts"]
_REGEX_PATTERNS[".jsx"] = _REGEX_PATTERNS[".js"]


# #1954, regex tier: same gap as tree-sitter's `_ts_node_name`, and this is
# the tier that actually runs whenever tree-sitter is unavailable -- the
# default in this repo's own test suite. `extends`/`implements` are
# keywords here, not grammar fields, so this is a header-text regex rather
# than a node walk; `re.DOTALL` matters because a wrapped declaration (the
# PHP example the issue was filed from) puts each interface on its own
# line.
_HEADER_HERITAGE_RE: Dict[str, Tuple[Optional[re.Pattern[str]], Optional[re.Pattern[str]]]] = {
    ".php": (re.compile(r"extends\s+([\w\\]+)"),
             re.compile(r"implements\s+(.+)", re.DOTALL)),
    ".java": (re.compile(r"extends\s+([\w.<>]+)"),
              re.compile(r"implements\s+(.+)", re.DOTALL)),
    ".js": (re.compile(r"extends\s+([\w.$]+)"), None),
    ".ts": (re.compile(r"extends\s+([\w.$]+)"),
            re.compile(r"implements\s+(.+)", re.DOTALL)),
}
_HEADER_HERITAGE_RE[".tsx"] = _HEADER_HERITAGE_RE[".ts"]
_HEADER_HERITAGE_RE[".jsx"] = _HEADER_HERITAGE_RE[".js"]

# 2000 chars comfortably covers any realistic wrapped extends/implements
# clause (the issue's own multi-line PHP example is under 150). Widened
# from 400 after a review measured a false "+N more" undercount on a
# synthetic 12-interface header that ran past the old window (#1954
# follow-up): the count was wrong, not just approximate, because
# `_format_hierarchy_suffix` had already lost the names past the cut.
_CLASS_HEADER_WINDOW = 2000


def _class_header_text(content: str, start: int) -> Tuple[str, bool]:
    """The declaration's own text from just past the class/interface name
    up to its opening `{`, and whether the scan window ran out first.

    Cutting at `{` keeps a later comment or method body that happens to say
    "implements" from being read as part of the header. When no `{` turns
    up inside the window, the header is truncated -- the caller must not
    report a name count computed from it as complete: better to decline
    the whole suffix than assert a number this function cannot back up.
    """
    chunk = content[start:start + _CLASS_HEADER_WINDOW]
    brace = chunk.find("{")
    if brace == -1:
        return chunk, True
    return chunk[:brace], False


def _split_top_level_commas(s: str) -> List[str]:
    """Split on `,` that is not nested inside `()`, `[]`, `{}` or `<>`.

    A Python base list can carry a parenthesized default
    (`class Foo(Base, x=(1, 2)):`) and a Java/TS interface list can carry a
    generic type argument (`implements Comparable<Foo, Bar>`) -- a plain
    `str.split(",")` cuts both in the middle and reports a garbled or
    truncated name instead of the real one.
    """
    parts: List[str] = []
    depth = 0
    current: List[str] = []
    opens = "([{<"
    closes = ")]}>"
    for ch in s:
        if ch in opens:
            depth += 1
        elif ch in closes:
            depth = max(0, depth - 1)
        if ch == "," and depth == 0:
            parts.append("".join(current))
            current = []
        else:
            current.append(ch)
    parts.append("".join(current))
    return parts


def _leading_balanced_parens(header: str) -> Optional[str]:
    """Content of the balanced `(...)` at the very start of `header` (after
    optional leading whitespace), or None if it does not start with one.

    A plain `[^)]*` regex stops at the FIRST `)`, which for
    `class Foo(Base, x=(1, 2)):` is the one closing the nested tuple
    literal -- the outer close-paren and anything after it (a later real
    base class) are silently lost. Balanced counting does not have that
    failure mode.
    """
    i = 0
    n = len(header)
    while i < n and header[i].isspace():
        i += 1
    if i >= n or header[i] != "(":
        return None
    depth = 0
    start = i
    for j in range(i, n):
        if header[j] == "(":
            depth += 1
        elif header[j] == ")":
            depth -= 1
            if depth == 0:
                return header[start + 1:j]
    return None  # unbalanced within the scanned window


def _header_hierarchy(ext: str, header: str) -> List[str]:
    """Base class + interfaces named in a class/interface declaration's own
    header (from the name to the opening `{`). Language-shaped, because the
    keywords are: PHP/Java/JS/TS name them with `extends`/`implements`,
    Python's base list is the parens right after the name, Ruby's is `<`.
    """
    if ext == ".py":
        inner = _leading_balanced_parens(header)
        if inner is None:
            return []
        names = []
        for part in _split_top_level_commas(inner):
            part = part.strip()
            if part and "=" not in part and not part.startswith("*"):
                names.append(part)
        return names
    if ext == ".rb":
        m = re.match(r"\s*<\s*([\w:]+)", header)
        return [m.group(1)] if m else []
    spec = _HEADER_HERITAGE_RE.get(ext)
    if not spec:
        return []
    names = []
    extends_re, implements_re = spec
    if extends_re:
        m = extends_re.search(header)
        if m:
            names.append(m.group(1).strip())
    if implements_re:
        m = implements_re.search(header)
        if m:
            names.extend(
                part.strip()
                for part in _split_top_level_commas(m.group(1))
                if part.strip()
            )
    return names


def _regex_extract(path: str) -> List[Tuple[str, str, int, int, int]]:
    """Extract symbols from a file using regex patterns.

    Returns list of (kind, name, line, end_line, depth) tuples.
    Regex can't reliably detect span; end_line == line.
    depth is always 0 except indented Python `def` → depth 1.
    """
    ext = os.path.splitext(path)[1].lower()
    patterns = _REGEX_PATTERNS.get(ext)
    if not patterns:
        return []

    try:
        with open(path, "r", errors="replace", encoding="utf-8") as f:
            content = f.read()
    except OSError:
        return []

    symbols: List[Tuple[str, str, int, int, int]] = []
    lines = content.split("\n")

    for kind, regex in patterns:
        for m in regex.finditer(content):
            line_num = content[:m.start()].count("\n") + 1
            if ext == ".py" and kind == "def":
                # Python: indented def → depth 1
                indent = m.group(1)
                name = m.group(2)
                depth = 1 if len(indent) > 0 else 0
            else:
                name = m.group(1)
                depth = 0
            if kind in ("class", "interface"):
                header, truncated = _class_header_text(content, m.end())
                # Python (`:`) and Ruby (no closing token at all) match right
                # at the head of the header regardless of where -- or
                # whether -- the scan window ran out; only the keyword-based
                # languages (`extends`/`implements` reached via .search()
                # over the WHOLE header) can have a real base class or
                # interface sitting past a truncated window.
                if truncated and ext not in (".py", ".rb"):
                    # #2002: a truncated window and a genuinely standalone
                    # class used to render identically -- "no hierarchy" is
                    # what BOTH an absent parent and an unread one look
                    # like once `hierarchy` is simply []. `_class_header_text`
                    # already tells the two apart (`truncated`); the marker
                    # says so instead of discarding that fact here.
                    name += " < ?"
                else:
                    hierarchy = _header_hierarchy(ext, header)
                    if hierarchy:
                        name += _format_hierarchy_suffix(hierarchy)
            symbols.append((kind, name, line_num, line_num, depth))

    # Sort by line number
    symbols.sort(key=lambda s: s[2])
    return symbols


def _format_map_symbols(
    symbols: List[Tuple[str, str, int, int, int]], path: str, line_count: int
) -> str:
    """Format extracted symbols as an indented tree string."""
    out = [f"{_fwd(path)} ({line_count} lines)\n"]
    for kind, name, line, end_line, depth in symbols:
        indent = "  " * (depth + 1)
        label = f"[{line}]" if line == end_line else f"[{line}-{end_line}]"
        out.append(f"{indent}{kind} {name}  {label}\n")
    return "".join(out)


def _format_ctags_symbols(
    symbols: List[Tuple[str, str, int, str]], path: str, line_count: int
) -> str:
    """Format ctags symbols as an indented tree string.

    Uses scope field to infer nesting (symbols with a scope → depth 1).
    """
    out = [f"{_fwd(path)} ({line_count} lines)\n"]
    for kind, name, line, scope in symbols:
        depth = 1 if scope else 0
        indent = "  " * (depth + 1)
        out.append(f"{indent}{kind} {name}  [{line}]\n")
    return "".join(out)


# Supported extensions for map scanning
_MAP_EXTENSIONS = frozenset(
    list(_TS_LANG_MAP.keys()) + list(_REGEX_PATTERNS.keys())
)


def _collect_files(
    path: str, exclude_paths: Tuple[str, ...],
    hidden: Optional[List[str]] = None,
) -> List[str]:
    """Collect files to map from a path (file or directory).

    For directories, walks recursively. Skips hidden dirs, vendor/, Generated/,
    .claude/, .max/, and any dirs matching exclude_paths prefixes.

    `exclude_paths` is required (not defaulted) because the universal classics
    (.git/, node_modules/, etc.) live in `_DEFAULT_EXCLUDE_PATHS` and must reach
    this function via `_get_exclude_paths("map", ...)`. A defaulted empty tuple
    here would silently re-walk node_modules.
    """
    skip_dirs = {"vendor", "Generated", ".claude", ".max"}

    if os.path.isfile(path):
        return [path]

    if not os.path.isdir(path):
        return []

    cwd = os.getcwd()
    files: List[str] = []
    for root, dirs, filenames in os.walk(path):
        rel_root = _safe_relpath(root, cwd)
        dirs[:] = sorted(
            d for d in dirs
            if d not in skip_dirs
            and not d.startswith(".")
            and not (exclude_paths and _is_excluded(os.path.join(rel_root, d), exclude_paths))
        )
        for fn in sorted(filenames):
            ext = os.path.splitext(fn)[1].lower()
            if ext not in _MAP_EXTENSIONS:
                continue
            rel_fn = os.path.join(rel_root, fn)
            if exclude_paths and _is_excluded(rel_fn, exclude_paths):
                if hidden is not None and _is_disclosable_exclusion(
                        rel_fn, exclude_paths):
                    hidden.append(os.path.join(root, fn))
                continue
            files.append(os.path.join(root, fn))
    return files


MAX_MAP_FILES = 100  # Cap to prevent overwhelming output

# Substring every "we could not look" render shares, so callers that key off
# map's output (`_abstract_map`) can recognise the third state without
# re-deriving which extensions have parsers.
_NO_PARSER_MARKER = "no symbol parser for "

# The fourth state (#1680). Same reason as the marker above: a caller keying
# off map's output has to be able to tell "no tier could look" from "no tier
# COULD BE RUN, because the bytes never arrived".
_UNREADABLE_MARKER = "could not read"


def _map_unreadable_reason(path: str) -> str:
    """Why no tier can look at PATH at all, or "" when they can (#1680).

    Established once, ahead of `_count_lines`, `_ts_extract` and
    `_regex_extract` — all three swallow this same `OSError` independently and
    each returns the shape of an empty answer, so `map` rendered `tier: regex`
    for a tier that read no bytes, `(0 lines)`, and `(no symbols)` for a file
    it had never opened.

    Composing the verdict out of the three instead was the other candidate and
    is not available: `_count_lines`'s `on_error` sentinel is contracted to
    differ per caller (#388), so a `0` arriving here cannot be told from a
    genuinely empty file, and the distinction is destroyed one layer down
    rather than merely unreported.

    One byte through `open`, not `os.access` or a `stat`: the question is
    whether this process can obtain the contents, and every other probe answers
    a neighbouring one. A mode that denies read, an ACL, a dangling symlink and
    a file removed between the walk and this call all arrive as `OSError` —
    which is why the reason is reported rather than classified.
    """
    try:
        with open(path, "rb") as fh:
            fh.read(1)
    except OSError as exc:
        return exc.strerror or str(exc)
    return ""


def _map_no_parser_reason(ext: str, use_ts: bool, ctags_ran: bool) -> str:
    """Why no tier could look at EXT, or "" when at least one could (#887).

    `map` had two renders for three facts: symbols, none found, and no parser
    for this file type. The third collapsed into the second, so a markdown
    file dense with headings reported `(no symbols)` — an absence produced by
    the tool, stated as an absence in the document. This computes the third
    state so the render can keep it separate; see docs/validators.md,
    "Declining instead of guessing".

    A tier counts as able to look when it has patterns or a grammar for EXT,
    not merely when it is installed. ctags is deliberately not treated as a
    parser here: the build on PATH may be BSD ctags, which cannot be queried
    for its language list — so a note is appended rather than a capability
    claimed.

    `ctags_ran` is whether ctags was actually invoked on THIS file, not
    whether a binary exists (#913). The note used to be appended from
    availability, which meant it could claim ctags "found nothing" on a run
    where ctags was never asked — the absence-produced-by-the-tool shape this
    repository keeps re-filing.
    """
    ts_lang = _TS_LANG_MAP.get(ext) if use_ts else None
    if ts_lang and ts_lang not in _TS_GRAMMAR_FAILED:
        return ""
    if ext in _REGEX_PATTERNS:
        return ""

    if not ext:
        ext = "(no extension)"
    if use_ts:
        detail = f"tree-sitter and the regex tier have no {ext} grammar"
    else:
        detail = (f"tree-sitter is not installed and the regex tier has no "
                  f"{ext} patterns")
    if ctags_ran:
        detail += "; ctags found nothing"
    return f"{_NO_PARSER_MARKER}{ext} - {detail}"


def _ts_tier_is_blind(ext: str, use_ts: bool) -> bool:
    """True when the tree-sitter tier cannot look at EXT at all (#913).

    Distinguishes "tier 1 has no grammar for this file" — where dropping to
    ctags is the documented cascade and the only way an installed ctags ever
    earns its keep — from "tier 1 parsed the file and it has no definitions",
    where ctags would re-read the same file in a subprocess to reach the same
    answer.

    That distinction is the whole cost argument. Measured on this repo at
    100 mapped files, 14 produced no tree-sitter symbols and all 14 were the
    second kind (changelog fragments, an empty `__init__.py`); a ctags call
    costs ~41ms each on macOS, of which ~33ms is bare process spawn. Falling
    back on emptiness would buy nothing and put a per-file subprocess on a hot
    path — the shape that has reddened Windows legs four times here (#1296,
    #1360, #1461, #1501).
    """
    if not use_ts:
        return True
    lang_name = _TS_LANG_MAP.get(ext)
    return not lang_name or lang_name in _TS_GRAMMAR_FAILED


def op_map(path: str, no_exclude: bool = False) -> str:
    """Generate a symbol map of a file or directory.

    Three tiers, per file:
      1. tree-sitter (if a tree-sitter language package is installed)
      2. ctags (if `ctags` is on PATH) — consulted only for a file tier 1
         cannot parse: no grammar for the extension, or a grammar that failed
         to load. A file tier 1 read and found nothing in does not fall
         through; see `_ts_tier_is_blind` for why (#913).
      3. regex fallback (always available for supported extensions)

    Output: indented tree of classes/functions/methods per file.
    """
    if not path:
        return "ERROR: empty path\n"
    if not os.path.exists(path):
        return _path_not_found(path, op="map", call_prefix="map")

    hidden_files: List[str] = []
    files = _collect_files(
        path, _get_exclude_paths("map", no_exclude), hidden_files)
    if not files:
        return f"(no supported files found in {path})\n"

    truncated = len(files) > MAX_MAP_FILES
    files = files[:MAX_MAP_FILES]

    # Detect available tier. ctags is probed per file rather than once here:
    # it is reachable whenever tier 1 is blind to a file, which `use_ctags =
    # not use_ts and _has_ctags()` made impossible for the entire run as soon
    # as tree-sitter imported (#913).
    use_ts = _has_tree_sitter()

    # tier label is computed after extraction to reflect what actually produced symbols
    actual_tier: str = "regex"
    unparsed = 0
    unreadable = 0

    out_files: List[str] = []

    for fpath in files:
        ext = os.path.splitext(fpath)[1].lower()
        # Readability is established before anything reports on this file, so
        # a line count and a tier name are only ever printed for a file whose
        # bytes were actually available (#1680).
        unreadable_why = _map_unreadable_reason(fpath)
        if unreadable_why:
            out_files.append(
                f"{_fwd(fpath)} (unreadable)\n"
                f"  ({_UNREADABLE_MARKER}: {unreadable_why} — no tier looked "
                f"at this file, so nothing here is a claim about its "
                f"contents)\n")
            unreadable += 1
            continue
        line_count = _count_lines(fpath)

        symbols_found = False

        if use_ts:
            lang_name = _TS_LANG_MAP.get(ext)
            if lang_name:
                symbols = _ts_extract(fpath, lang_name)
                if symbols:
                    out_files.append(_format_map_symbols(symbols, fpath, line_count))
                    symbols_found = True
                    actual_tier = "tree-sitter"

        ctags_ran = False
        if (not symbols_found and _ts_tier_is_blind(ext, use_ts)
                and _has_ctags()):
            ctags_ran = True
            symbols_ct = _ctags_extract(fpath)
            if symbols_ct:
                out_files.append(_format_ctags_symbols(
                    symbols_ct, fpath, line_count))
                symbols_found = True
                actual_tier = "ctags"

        if not symbols_found:
            symbols_rx = _regex_extract(fpath)
            if symbols_rx:
                out_files.append(_format_map_symbols(
                    symbols_rx, fpath, line_count))
                symbols_found = True

        if not symbols_found:
            no_parser = _map_no_parser_reason(ext, use_ts, ctags_ran)
            ts_lang = _TS_LANG_MAP.get(ext) if use_ts else None
            if no_parser:
                # No tier has a grammar or a pattern set for this extension.
                # Saying "(no symbols)" here would report the tool's blind
                # spot as a property of the file (#887).
                out_files.append(
                    f"{_fwd(fpath)} ({line_count} lines)\n  ({no_parser})\n")
                unparsed += 1
            elif ts_lang and ts_lang in _TS_GRAMMAR_FAILED:
                # Every tier came up empty AND tree-sitter's grammar never
                # loaded for this language — say so, rather than rendering
                # byte-identical to a file with genuinely zero definitions
                # (#790).
                out_files.append(
                    f"{_fwd(fpath)} ({line_count} lines)\n"
                    f"  (tree-sitter grammar unavailable for {ext}: "
                    f"{_TS_GRAMMAR_FAILED[ts_lang]} - no symbols from any tier)\n")
            else:
                # File exists but no symbols extracted — show it as empty
                out_files.append(f"{_fwd(fpath)} ({line_count} lines)\n  (no symbols)\n")

    if unparsed + unreadable == len(files):
        # Naming a tier that never had a pattern to try is the report line
        # telling the same lie the body used to (#887) — and a tier that never
        # received a byte is the same line telling it again (#1680).
        actual_tier = "none"
    out = [f"({len(files)} files{_hidden_suffix(len(hidden_files))}, tier: {actual_tier})\n"] + out_files
    # A map of the entry-point shim is the module's surface to whoever reads
    # it, and it is not (#1272). Fires on the shim named directly — a map of
    # the *directory* enumerates `_supertool.py` on the next line, so there is
    # nothing left to disclose and the gate's basename test declines it.
    out.append(_shim_facade_surface_note(path))
    if truncated:
        out.append(f"\n... (truncated at {MAX_MAP_FILES} files)\n")
    out.append("\n")
    return "".join(out)


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _rtk_grep_census(pattern: str, path: str,
                     exclude_paths: Tuple[str, ...]) -> Optional[Tuple[int, int]]:
    """`(total matches, files scanned)` for a delegated grep, or None (#1771).

    A second delegated pass — `grep -rc`, the same engine, the same argv minus
    the `-m` cap — because a truncated sweep with no total is the defect this
    whole file is otherwise careful about: a bounded presence read as a
    complete one. `grep` is the op a shipped `claude-jit-context` rule names as
    the replacement for the refused `Grep` tool, so every completeness sweep an
    agent runs lands here, and `(total not counted)` was the one state such a
    sweep must not come back in.

    **Why a count pass and not a re-walk.** #414 declined to compute the
    denominator because producing it meant walking the tree in Python, which is
    exactly what delegation exists to avoid. `-c` is not that walk: it is the
    same C engine over the same tree, and `-rc` names *every* file it scanned,
    zero-match ones included — so one call answers both the numerator and the
    denominator. Measured on this repo (1,159 files, dense pattern): 0.47s for
    the `-m`-capped match pass, 0.65s for the census. It is bought only when the
    match pass came back truncated, and `builtin-ops.grep.count_truncated: 0`
    declines it for a tree where that trade is wrong.

    **Excluded files are subtracted here, not left to the argv.** The default
    exclude list carries negations, and system grep cannot express one, so
    `_grep_exclude_flags` withholds every wildcard entry — a `server.pem` really
    is read by the census. Counting it would put matches in the total that the
    caller was told were not there, and a file in the denominator that nobody
    searched. `_is_excluded` is the same test the native walker applies.

    **Three states, and the third is the point.** Anything this cannot answer
    exactly returns None and the report says the total is unknown: rtk failing
    or timing out, a `-rc` output line that is not `path:N`, or a tree with no
    countable file left. A guessed total is worse than an admitted gap, because
    nothing downstream knows to distrust it.
    """
    if not _get_op_bool("grep", "count_truncated", True):
        return None
    # -H: with a single-file PATH, grep drops the `path:` prefix and the census
    # becomes unparseable — the one shape where declining would be an artefact
    # of the argv rather than of the tree.
    args = ["grep", "-rc", "-H", "-E"]
    args.extend(_grep_exclude_flags(exclude_paths))
    args.extend([pattern, path])
    out = _rtk_run(args)
    if out is None:
        return None
    cwd = os.getcwd()
    total = 0
    scanned = 0
    for line in out.splitlines():
        if not line.strip():
            continue
        fpath, sep, num = line.rpartition(":")
        num = num.strip()
        # _is_ascii_int, not str.isdigit: `int()` happily converts U+0662 and
        # friends, so `isdigit` would turn a line the parser does not actually
        # understand into a confident number (#1727, #1748). Declining is the
        # third state this whole helper exists to protect.
        if not sep or not fpath or not _is_ascii_int(num):
            return None
        if exclude_paths and _is_excluded(_safe_relpath(fpath, cwd), exclude_paths):
            continue
        scanned += 1
        total += int(num)
    if scanned == 0:
        return None
    return total, scanned


def _rtk_grep_report(rtk_out: str, limit: int,
                     census: Optional[Callable[[], Optional[Tuple[int, int]]]] = None
                     ) -> str:
    """Wrap rtk's delegated grep output in supertool's report line (#414).

    rtk emits bare ``path:lineno:content`` lines and no report line at all, so
    a delegated grep — `grep:PATTERN:PATH`, the plainest invocation there is —
    silently dropped the result count, the limit disclosure, and #407's
    scanned-file denominator together.

    The body is passed through verbatim: re-rendering it into supertool's
    grouped layout would mean re-parsing content that may itself contain
    colons, for a cosmetic gain.

    op_grep asks rtk for `limit + 1` matches, so this sees one line past the
    cap whenever more exist (#448). The extra line is dropped and the report
    says so, which keeps the delegated path's completeness disclosure identical
    to the native walker's.

    **The `?` denominator, and where it stopped being acceptable (#1771).** On a
    *complete* delegated result the `?` is not load-bearing and stays: rtk exits
    non-zero when it matches nothing and op_grep falls through on empty output,
    so a delegated report always carries at least one result — and with no
    TRUNCATED marker, every match there is is on the screen, which is the only
    thing a breadth question needed the denominator for. The ambiguous case,
    zero results, always reaches the native walker and a real count.

    On a *truncated* result it was load-bearing and wrong in both halves at
    once: an unknown numerator over an unknown denominator. So `census` — a
    callable, invoked only on truncation, so the complete path keeps the single
    pass it has always had. When it answers, the report carries the exact total
    and a real `scanned N files`, in the native walker's own vocabulary. When it
    declines, `_truncation_suffix` names the total as unknown rather than
    filing it as an aside.

    A census that does not exceed the rows printed under it is refused rather
    than printed. The two passes are separate reads of a tree that can change
    between them, and a total at or below the visible row count is not a
    smaller answer, it is an incoherent one.
    """
    lines = [ln for ln in rtk_out.splitlines() if ln.strip()]
    truncated = len(lines) > limit
    lines = lines[:limit]
    files = set()
    for ln in lines:
        m = re.match(r"^(.+?):\d+:", ln)
        if m:
            files.add(m.group(1))
    total: Optional[int] = None
    reason: Optional[str] = None
    scanned_clause = ", scanned ? files"
    if truncated and census is not None:
        counted = census()
        if counted is None:
            pass
        elif counted[0] <= len(lines):
            # The census ran and was refused. Saying it "returned no total"
            # here would be the same class of wrong receipt this whole change
            # is about, one field over — so the two declines say which.
            reason = (f"the delegated count came back at {counted[0]}, "
                      f"at or below the {len(lines)} rows shown, and was "
                      "refused as incoherent")
        else:
            total, scanned = counted
            scanned_clause = _scanned_suffix(scanned)
    header = (f"({len(lines)} results in {len(files)} files"
              f"{scanned_clause} — delegated to rtk"
              f", limit {limit}"
              f"{_truncation_suffix(truncated, total, reason=reason)})\n")
    return header + "".join(ln + "\n" for ln in lines) + "\n"


def _truncation_suffix(truncated: bool, total: Optional[int] = None,
                       capped: bool = False,
                       reason: Optional[str] = None) -> str:
    """Report format's truncation disclosure (#448, #1073).

    `(1 results in 1 files, scanned 118353 files, limit 1)` reads as an
    exhaustive answer and is not one, which is how a coverage audit concluded a
    class had no test when the test was sitting one match past the cap. The
    marker is only ever emitted when a match past the limit was actually seen,
    so its absence is a positive statement: this count is exact.

    `more matches exist` said the answer was partial without saying how partial
    (#1073). 21 matches and 500 matches produced identical bytes and warrant
    opposite next actions, so the scope is now part of the marker — in three
    states that must not collapse into each other:

    * `N matches total`                  — counted, and this is all of them;
    * `N+ matches total (count capped…)` — counting stopped at the ceiling, so
      the number is a floor rather than a total;
    * `more matches exist, total unknown (…)` — nothing counted, and the
      reason. "We did not count" must not render as "we counted and there are
      some", and it must not render as an aside either (#1771): a caller told
      the answer is partial and not how partial has an unquantified answer, so
      the gap belongs in the sentence rather than in a trailing parenthesis.

    Only the delegated rtk path can reach the third state, and since #1771 it
    reaches it only when the `grep -rc` census could not answer. `reason` says
    which way, because "it never ran" and "it ran and I refused its answer" are
    two different things to do next, and one sentence for both would be a
    receipt misreporting its own mechanism — the defect class this marker was
    built to close, aimed at the marker. The default covers every path on which
    no total came back at all: rtk absent, failing or timing out; output that is
    not `path:N`; a non-ASCII decimal `int()` would have converted; or the pass
    switched off with `builtin-ops.grep.count_truncated: 0`. The caller passes
    its own when the census answered and was rejected.

    The delegated total is exact rather than capped when it arrives: `-c` counts
    in C, so there is no walker to stop early and nothing to clamp.
    """
    if not truncated:
        return ""
    if total is None:
        return (" — TRUNCATED, more matches exist, total unknown ("
                + (reason or "the delegated count pass returned no total")
                + ")")
    if capped:
        return (f" — TRUNCATED, {total}+ matches total "
                f"(count capped at {total})")
    return f" — TRUNCATED, {total} matches total"


def _trim_context_groups(
    groups: List[List[Tuple[str, int, str, str]]], limit: int
) -> Tuple[List[List[Tuple[str, int, str, str]]], bool]:
    """Cut context-mode groups back to `limit` matches; report whether any were cut.

    The over-fetched match may share a group with the last kept one (matches
    within 2*context+1 lines merge into a single window), so the cut has to
    happen inside the group rather than by dropping whole groups — dropping the
    group would take the limit-th match with it. A group left holding only
    context lines is dropped: context without its match is noise.
    """
    kept: List[List[Tuple[str, int, str, str]]] = []
    seen = 0
    truncated = False
    for group in groups:
        lines: List[Tuple[str, int, str, str]] = []
        stopped = False
        for entry in group:
            if entry[2] == "match":
                if seen >= limit:
                    stopped = True
                    break
                seen += 1
            lines.append(entry)
        if any(e[2] == "match" for e in lines):
            kept.append(lines)
        if stopped:
            truncated = True
            break
    return kept, truncated


def _hidden_suffix(hidden: int) -> str:
    """Report format's ", N files hidden by exclude-paths" clause (#691).

    An exclusion that leaves no trace in the output is indistinguishable from a
    file that was not there — the same silent-failure shape the `scanned N`
    denominator and the TRUNCATED marker were both added to close. Credential
    files are the reason the list exists, but "your search skipped something"
    is the caller's to know, and the way back (`no-exclude`) is one flag away.

    Which exclusions count is decided by `_is_disclosable_exclusion`, not by
    file-versus-directory: built-in noise entries stay out of the number so it
    reads zero on the ordinary call. A counter that is never zero is one a
    reader learns to skip, and then the call that fires because a real `.env`
    was hidden looks like all the others.
    """
    if hidden <= 0:
        return ""
    return f", {hidden} files hidden by exclude-paths"


def _grep_count_ceiling(limit: int) -> int:
    """How many matches grep will count before it stops counting (#1073).

    Never below the caller's own LIMIT: a ceiling under the limit would cap the
    total below the number of rows printed underneath it, which is a worse
    render than the one this replaces.
    """
    return max(_get_op_int("grep", "count_ceiling", MAX_GREP_COUNT_CEILING),
               limit)


def _grep_total(seen: int, ceiling: int) -> Tuple[int, bool]:
    """`(total, capped)` for a walk that stopped once it had `ceiling + 1`.

    `seen` may overshoot by more than one in context mode, where matches are
    collected a window at a time — so the reported floor is clamped rather than
    passed through, and a number printed as exact is always one that is.
    """
    return min(seen, ceiling), seen > ceiling


def _scanned_suffix(scanned: int) -> str:
    """Report format's ", scanned N files" clause (#407).

    A zero scanned count means the path/glob resolved to nothing, so the
    zero-result report above it must not read like a completed search.
    """
    if scanned == 0:
        return ", scanned 0 files — nothing matched the path/glob"
    return f", scanned {scanned} files"


def _grep_count(
    pattern: str, path: str, limit: int,
    exclude_paths: Tuple[str, ...] = (),
    candidates: Optional[List[str]] = None,
) -> Dict[str, int]:
    """Return match counts per file as {filepath: count}."""
    try:
        regex = re.compile(pattern)
    except re.error:
        regex = re.compile(re.escape(pattern))

    counts: Dict[str, int] = {}
    if candidates is None:
        candidates = _grep_candidates(path, exclude_paths)

    for file_path in candidates:
        cnt = 0
        try:
            with open(file_path, "rb") as f:
                for raw in f:
                    try:
                        line = raw.decode("utf-8", errors="replace")
                    except Exception:
                        continue
                    if regex.search(line):
                        cnt += 1
        except OSError:
            continue
        if cnt > 0:
            counts[file_path] = cnt
    return counts


def _grep_candidates(
    path: str, exclude_paths: Tuple[str, ...] = (),
    hidden: Optional[List[str]] = None,
) -> List[str]:
    """Return list of file paths to search for a given path argument.

    When exclude_paths is provided, directories whose path-relative-to-cwd
    starts with one of the prefixes are pruned at the walk boundary (dirs[:]
    mutation) so their subtrees are never opened. Gitignored directories are
    pruned at the same boundary (#449) — and because the pruning happens
    before the files are collected, the returned length is what op_grep reports
    as `scanned N`, so #407's denominator shrinks with the walk instead of
    counting agent worktrees six times over.

    **Files are filtered too** (#691). This loop used to test the extension and
    nothing else, so `.env` — on the default exclude list since #146 — was read
    and printed like any other file. Excluded files are appended to `hidden`
    when a list is passed, rather than merely counted: op_grep discloses how
    many there were, and anyone questioning that number needs the names.

    A `path` that IS an excluded file is still searched. Naming it is a
    deliberate act and `read` never gated it, so gating it here would buy
    nothing and break the case someone meant.
    """
    candidates: List[str] = []
    if os.path.isfile(path):
        candidates.append(path)
    elif os.path.isdir(path):
        exts = _grep_file_includes()  # None = all files
        cwd = os.getcwd()
        ignored = _git_ignored_dirs(path) if exclude_paths else frozenset()
        for root, dirs, files in os.walk(path):
            rel_root = _safe_relpath(root, cwd) if exclude_paths else ""
            if exclude_paths:
                dirs[:] = [
                    d for d in dirs
                    if not _is_excluded(os.path.join(rel_root, d), exclude_paths)
                    and not _is_git_ignored(rel_root, d, ignored)
                ]
            for name in files:
                if exts is not None and not any(
                        name.endswith(ext.lstrip("*")) for ext in exts):
                    continue
                rel_name = os.path.join(rel_root, name)
                if exclude_paths and _is_excluded(rel_name, exclude_paths):
                    if hidden is not None and _is_disclosable_exclusion(
                            rel_name, exclude_paths):
                        hidden.append(os.path.join(root, name))
                    continue
                candidates.append(os.path.join(root, name))
    return candidates


def _grep_recursive(
    pattern: str, path: str, limit: int,
    exclude_paths: Tuple[str, ...] = (),
    candidates: Optional[List[str]] = None,
) -> List[Tuple[str, int, str]]:
    """Return up to `limit` matches as (file_path, lineno, content) tuples.

    Filters by common code/doc extensions when walking directories.
    Always searches when `path` is a single file. file_path is normalised
    to forward slashes; the colon in a Windows drive letter (`C:/...`)
    would break a string-joined return shape on path:lineno:content split.
    """
    try:
        regex = re.compile(pattern)
    except re.error:
        # Fall back to literal substring
        regex = re.compile(re.escape(pattern))

    results: List[Tuple[str, int, str]] = []
    if candidates is None:
        candidates = _grep_candidates(path, exclude_paths)

    for file_path in candidates:
        if len(results) >= limit:
            break
        try:
            with open(file_path, "rb") as f:
                for lineno, raw in enumerate(f, start=1):
                    try:
                        line = raw.decode("utf-8", errors="replace")
                    except Exception:
                        continue
                    if regex.search(line):
                        results.append((_fwd(file_path), lineno, line.rstrip()))
                        if len(results) >= limit:
                            break
        except OSError:
            continue
    return results


def _grep_recursive_context(
    pattern: str, path: str, limit: int, context: int,
    exclude_paths: Tuple[str, ...] = (),
    candidates: Optional[List[str]] = None,
) -> List[List[Tuple[str, int, str, str]]]:
    """Return match groups with surrounding context lines.

    Each group is a list of (file_path, lineno, kind, content) tuples where
    kind is 'match' or 'context'. Groups represent adjacent/overlapping windows
    of lines. Non-adjacent groups are separated in output by --.

    Stops collecting new match groups once `limit` matches have been found.
    """
    try:
        regex = re.compile(pattern)
    except re.error:
        regex = re.compile(re.escape(pattern))

    if candidates is None:
        candidates = _grep_candidates(path, exclude_paths)
    groups: List[List[Tuple[str, int, str, str]]] = []
    match_count = 0

    for file_path in candidates:
        if match_count >= limit:
            break
        try:
            with open(file_path, "rb") as f:
                raw_lines = f.read().splitlines(keepends=True)
        except OSError:
            continue

        lines = []
        for raw in raw_lines:
            try:
                lines.append(raw.decode("utf-8", errors="replace").rstrip("\n").rstrip("\r"))
            except Exception:
                lines.append("<binary line>")

        # Collect match indices
        match_indices = [
            i for i, line in enumerate(lines) if regex.search(line)
        ]
        if not match_indices:
            continue

        # Merge overlapping windows into groups
        # A window is [match - context, match + context]
        windows: List[Tuple[int, int]] = []  # (start_idx, end_idx) inclusive
        for mi in match_indices:
            w_start = max(0, mi - context)
            w_end = min(len(lines) - 1, mi + context)
            if windows and w_start <= windows[-1][1] + 1:
                # Overlapping or adjacent — extend
                windows[-1] = (windows[-1][0], max(windows[-1][1], w_end))
            else:
                windows.append((w_start, w_end))

        # Build groups from windows
        match_set = set(match_indices)
        for w_start, w_end in windows:
            if match_count >= limit:
                break
            group: List[Tuple[str, int, str, str]] = []
            for i in range(w_start, w_end + 1):
                kind = "match" if i in match_set else "context"
                group.append((_fwd(file_path), i + 1, kind, lines[i]))
                if kind == "match":
                    match_count += 1
            groups.append(group)

    return groups


def _glob_files(
    pattern: str, exclude_paths: Tuple[str, ...] = (), over_fetch: int = 0,
    hidden: Optional[List[str]] = None,
) -> List[str]:
    """Glob matching files, supports ** recursive. Returns up to MAX_GLOB_RESULTS.

    `over_fetch` raises the internal cap by that many files without changing
    the cap callers are told about. op_glob passes 1 so it can tell a list that
    happens to be cap-length from one that was cut short (#448).

    When exclude_paths is provided and the pattern contains '**', uses an
    os.walk-based implementation that prunes excluded directories at the walk
    boundary (never opens them).  For non-recursive patterns, falls back to
    glob.glob and filters results post-hoc (no subtree to prune anyway).

    Both halves filter *files* against exclude_paths (#691). Only the glob.glob
    half ever did, so one op gave two answers: `glob:.env*` hid `.env` and
    `glob:**/.env*` listed it. Excluded files land in `hidden` when a list is
    passed, so op_glob can say how many it dropped.
    """
    max_results = _get_op_int("glob", "max_results", MAX_GLOB_RESULTS) + over_fetch

    # Brace expansion: `*.{json,xml}` → fan out + dedupe. Shell/fd semantics.
    expanded = _expand_braces(pattern)
    if expanded != [pattern]:
        seen: set = set()
        results: List[str] = []
        for sub_pattern in expanded:
            for f in _glob_files(sub_pattern, exclude_paths, over_fetch, hidden):
                if f not in seen:
                    seen.add(f)
                    results.append(f)
                    if len(results) >= max_results:
                        return results
        return results

    if exclude_paths and "**" in pattern and pattern.count("**") == 1:
        # Walk-based implementation for recursive globs with exclusions.
        # Only safe when pattern has a single `**` — multi-`**` patterns
        # (`**/X/**/Y`) need full glob semantics on every segment, which
        # fnmatch can't express. Fall through to glob.glob + post-filter.
        # Split on the first '**' to get the root dir and the tail pattern.
        import fnmatch
        star_idx = pattern.index("**")
        root_part = pattern[:star_idx].rstrip("/").rstrip(os.sep) or "."
        tail = pattern[star_idx + 2:].lstrip("/").lstrip(os.sep)
        if not os.path.isdir(root_part):
            root_part = "."
            tail = pattern.lstrip("/").lstrip(os.sep)

        cwd = os.getcwd()
        ignored = _git_ignored_dirs(root_part)
        files: List[str] = []
        for root, dirs, filenames in os.walk(root_part):
            rel_root = _safe_relpath(root, cwd)
            dirs[:] = sorted(
                d for d in dirs
                if not _is_excluded(os.path.join(rel_root, d), exclude_paths)
                and not _is_git_ignored(rel_root, d, ignored)
            )
            for name in sorted(filenames):
                full = os.path.join(root, name)
                # Match the tail pattern against the relative path from root_part
                rel_from_root = _safe_relpath(full, root_part)
                if not tail or fnmatch.fnmatch(name, tail) or fnmatch.fnmatch(rel_from_root, tail):
                    if os.path.isfile(full):
                        rel_full = _safe_relpath(full, cwd)
                        if _is_excluded(rel_full, exclude_paths):
                            if hidden is not None and (
                                    _is_disclosable_exclusion(
                                        rel_full, exclude_paths)):
                                hidden.append(full)
                            continue
                        files.append(full)
                        if len(files) >= max_results:
                            return files
        return files

    from glob import glob
    # When exclude_paths is empty, the caller explicitly opted out of
    # exclusions (no_exclude=True) — include dotfiles too so they actually
    # see ".git/" / "node_modules/" etc. Python 3.11+ supports the kwarg;
    # older versions silently skip dotfiles regardless.
    glob_kwargs: Dict[str, Any] = {"recursive": True}
    if not exclude_paths and sys.version_info >= (3, 11):
        glob_kwargs["include_hidden"] = True
    matches = sorted(glob(pattern, **glob_kwargs))
    files_out = [m for m in matches if os.path.isfile(m)]
    if exclude_paths:
        cwd = os.getcwd()
        # No walk boundary to prune at on this path, so gitignored hits are
        # filtered out of the result instead (#449).
        ignored = _git_ignored_dirs(_glob_ignore_root(pattern))
        if hidden is not None:
            hidden.extend(
                m for m in files_out
                if _is_disclosable_exclusion(
                    _safe_relpath(m, cwd), exclude_paths)
            )
        files_out = [
            m for m in files_out
            if not _is_excluded(_safe_relpath(m, cwd), exclude_paths)
            and not _under_git_ignored(_safe_relpath(m, cwd), ignored)
        ]
    return files_out[:max_results]


def _glob_ignore_root(pattern: str) -> str:
    """Directory a glob pattern starts from, for the gitignore lookup (#449).

    The literal head of the pattern — everything before the first wildcard —
    is what decides whether the caller deliberately entered an ignored tree.
    `glob:.claude/worktrees/foo/*.php` must keep working; `glob:**/*.php` must
    not drag six worktrees in.
    """
    head = re.split(r"[*?\[]", pattern, maxsplit=1)[0]
    directory = head if head.endswith(("/", os.sep)) else os.path.dirname(head)
    return directory if directory and os.path.isdir(directory) else "."


# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------

_DRIVE_LETTER = re.compile(r"^@?[A-Za-z]\Z")  # \Z, not $ — #1188
_URL_SCHEMES = ("http", "https", "ftp", "ftps", "ssh", "git", "file", "ws", "wss")
# Numeric port, optionally followed by '/path' or '?query' or end — used to
# absorb 'https://host' + ':8080/path' fragments that arose from `:`-splitting.
_URL_PORT = re.compile(r"^\d+(?:[/?#].*)?\Z")  # \Z, not $ — #1188


# NUL-bracketed marker for the two-pass `\\` protection in _decode_escapes.
# NUL is extremely unlikely in CLI args, and pass 3 replaces it with a literal
# backslash so it never reaches output.
_DECODE_ESCAPES_SENTINEL = "\x00BS\x00"


def _decode_escapes(s: str) -> str:
    r"""Decode shell-style escape sequences in mutating-op arguments.

    Used by `replace`, `replace_dry`, `edit`, `replace_lines`, `vi` so callers
    can pass multi-line OLD/NEW/CONTENT via CLI without literal `\n` polluting
    file contents.

    Decoded sequences:
      `\n` `\t` `\r`           → newline / tab / CR
      `\\`                     → literal `\`
      `\<punctuation>`         → drop `\` (shell-style defensive escape:
                                  `\)`, `\(`, `\$`, `\"`, `\'`, `\ `, `\!`...
                                  Kevin's defensive `\)` becomes `)`).
      `\<letter|digit>`        → preserved as-is. PHP namespace `\Foo`,
                                  regex char classes `\d`/`\w`/`\s`, and
                                  `:s` backrefs `\1`..`\9` all survive.

    A two-pass sentinel keeps `\\` (literal backslash) intact across the
    other substitutions.
    """
    if "\\" not in s:
        return s
    out = s.replace("\\\\", _DECODE_ESCAPES_SENTINEL)
    out = out.replace("\\n", "\n").replace("\\t", "\t").replace("\\r", "\r")
    # `\xHH` (two hex digits) → single char. Useful inside TEXT to embed
    # bytes like `\x27` (single quote) without bash single-quote nesting.
    out = re.sub(
        r"\\x([0-9A-Fa-f]{2})",
        lambda m: chr(int(m.group(1), 16)),
        out,
    )
    # Drop `\` before punctuation/symbols (defensive shell escapes).
    out = re.sub(r"\\([^A-Za-z0-9])", r"\1", out)
    out = out.replace(_DECODE_ESCAPES_SENTINEL, "\\")
    return out


def _split_arg(arg: str) -> List[str]:
    """Split 'op:arg1:arg2:arg3' by ':' but reassemble drive letters and URLs.

    Splits on every ':' (no limit) then merges:
      - Single-letter pieces followed by slash/backslash → Windows drive letter
      - URL-scheme pieces (http, https, ftp, ssh, git, file, ws...) followed
        by '//...' → URL. Scheme detection looks at the LAST '|'-separated
        segment of the piece, so URLs work when embedded as one of several
        '|'-separated args (e.g. publish ops with TITLE|FILE|URL|TAGS|COVER).
      - URLs with a host already absorbed, followed by a numeric port
        (optionally with a path) → URL with port.

    Examples:
        'read:foo.py'                          → ['read', 'foo.py']
        'read:C:\\Users\\file.py'              → ['read', 'C:\\Users\\file.py']
        'grep:pat:C:/src:20'                   → ['grep', 'pat', 'C:/src', '20']
        'op:T|F|https://x.com/a|tag'           → ['op', 'T|F|https://x.com/a|tag']
        'op:T|F|https://a.com|t|https://b'     → ['op', 'T|F|https://a.com|t|https://b']
        'op:T|https://example.com:8080/path|x' → ['op', 'T|https://example.com:8080/path|x']
    """
    raw = arg.split(":")  # Full split — drive letters and URLs rejoined below
    tokens: List[str] = []
    i = 0
    while i < len(raw):
        piece = raw[i]
        # Greedily absorb next pieces if current looks like a drive letter or URL scheme
        while i + 1 < len(raw):
            next_piece = raw[i + 1]
            last_seg = piece.rsplit("|", 1)[-1]
            # Drive-letter detection also splits on ',' so a comma-joined
            # multi-path keeps reassembling each member's drive letter
            # (e.g. 'C:\a.php,C' + '\b.php' → 'C:\a.php,C:\b.php' for the
            # validate list form). The drive letter is the last ','/'|'-segment.
            drive_seg = last_seg.rsplit(",", 1)[-1]
            # #1972 (CI, windows-latest): a `KEY=` prefix (#1690's own
            # `path=`/`file=` keyword) puts the drive letter after the '='
            # rather than at the start of the piece -- 'path=C' fails the
            # single-letter check below whole, so the reassembly this
            # function already promises for a bare drive letter (and that
            # .supertool.json's own `validate` description documents: "Drive
            # letters are reassembled") never fired for it. One shared
            # tokenizer, extended once, rather than a second reassembly
            # pass downstream in `_extract_path_kw` re-deriving what this
            # function already knows how to do.
            _kw_match = re.match(r"^[A-Za-z_][A-Za-z0-9_]*=(.*)\Z", drive_seg)
            if _kw_match:
                drive_seg = _kw_match.group(1)
            is_drive = (
                _DRIVE_LETTER.match(drive_seg) is not None
                and next_piece
                and next_piece[0] in ("/", "\\")
            )
            is_url = (
                last_seg.lower() in _URL_SCHEMES
                and next_piece.startswith("//")
            )
            # Port absorption: piece already has '://' (URL host absorbed last
            # iteration), and next piece is purely numeric or numeric+path.
            # 'https://example.com' + '8080/path' → 'https://example.com:8080/path'.
            is_url_port = (
                "://" in last_seg
                and bool(_URL_PORT.match(next_piece))
            )
            if not (is_drive or is_url or is_url_port):
                break
            piece = f"{piece}:{next_piece}"
            i += 1
        tokens.append(piece)
        i += 1
    return tokens


# The last colon slot each op actually reads. A non-empty token past it is
# refused rather than dropped (#1582, #1345).
#
# Measured on 2c8eaf9, twelve read ops probed with one junk token appended:
# twelve dropped it and answered. `read:CLAUDE.md:::lines=66-76` returned all
# 102 lines — 13549 bytes where ~1500 were asked for — because the unknown key
# landed past every slot the branch indexes. That is the worst shape the class
# has: **an ignored narrowing returns MORE than was asked for, and more always
# reads as a superset of correct**, so nothing in the render distinguishes it
# from a call that did what was typed.
#
# `read` is deliberately absent and handled by `_extra_colon_tokens` directly:
# its tail is variadic by design (`read:PATH:::grep=PATTERN` is the documented
# spelling, and the `:::` yields two empty parts before it), so a slot number
# cannot express what it accepts.
#
# `grep`, `around` and `between` are absent for the reason they are absent from
# `_PATH_ARG_POSITIONS`: none of them keeps its arguments in fixed slots — a
# ':' anywhere in the PATTERN moves everything right. grep's own trailing slack
# is closed at its parser instead (`_grep_peeled_extras`); `around` and
# `between` already fail loudly, absorbing the extra token into the PATH slot
# and reporting `path not found`.
#
# Only NON-EMPTY tokens count. `ls:C:` tokenizes to ['ls', 'C', ''] on the
# Windows drive-letter path that _split_arg declines to rejoin (no slash
# follows), and refusing it would be a platform-only behaviour change bought
# for nothing.
_MAX_COLON_SLOTS: Dict[str, int] = {
    "head": 2, "tail": 2, "tree": 2, "diff": 2, "glob": 2,
    "wc": 1, "ls": 1, "stat": 1, "map": 1,
    # #2238: dispatched via `body = op_payload_lint(parts[1] if len(parts) > 1
    # else "")` -- only parts[1] (the @file/@- reference) is ever read, same
    # single-slot shape as wc/ls/stat/map. Missing from this table meant
    # `payload-lint:@somefile:extra:more` silently dropped `extra`/`more`
    # instead of refusing, exactly what #1582 named for every other op.
    "payload-lint": 1,
    "around_line": 3,
    "grep_around": 4,
}


def _op_syntax(op: str) -> str:
    """The op's own syntax line from the registry, or "" when it has none.

    Quoted rather than restated, so a refusal cannot drift from the op the way
    a hand-copied grammar does. Returns "" rather than raising: a refusal that
    cannot find the registry is still a refusal, and one line shorter.
    """
    try:
        config = _load_config()
    except Exception:
        return ""
    for section in ("builtin-ops", "ops", "aliases"):
        entry = config.get(section, {})
        if isinstance(entry, dict) and isinstance(entry.get(op), dict):
            return str(entry[op].get("syntax", "") or "")
    return ""


def _extra_colon_tokens(op: str, parts: List[str]) -> List[str]:
    """Non-empty colon tokens this op will peel and never read (#1582).

    `read` is scanned rather than indexed: the filter can land in any trailing
    slot (parts[4] for `read:PATH:::grep=`, parts[3] when a range consumed only
    one), so the rule is "one grep=, empties, nothing else" rather than a slot
    count. A SECOND `grep=` is an extra too — the scan takes the first and
    breaks, so the second was silently the one that did not apply.
    """
    if op == "read":
        extra: List[str] = []
        # parts[3] is a slot the read branch reads for itself — `full`/`raw`, a
        # LIMIT, or the FIRST `grep=` when a range or a bare offset consumed
        # only one slot — so the scan starts at parts[4]. It still has to know
        # whether parts[3] took the grep=: without that, a second `grep=` one
        # slot along was read as the first and allowed through, which is the
        # exact drop this function exists to close.
        seen_grep = len(parts) > 3 and parts[3].startswith("grep=")
        for tok in parts[4:]:
            if not tok:
                continue
            if tok.startswith("grep=") and not seen_grep:
                seen_grep = True
                continue
            extra.append(tok)
        return extra
    last = _MAX_COLON_SLOTS.get(op)
    if last is None:
        return []
    return [tok for tok in parts[last + 1:] if tok]


def _extra_colon_tokens_refusal(op: str, extra: List[str],
                                remedy: str = "") -> str:
    """Refuse the tokens rather than run the call they were removed from.

    A refusal, not a note beside the answer: the answer is to a question the
    caller did not ask, and printing it under a warning is how #1582 was read
    as "conditional, not unimplemented" by the agent that hit it twice.
    """
    nl = chr(10)
    them = "them" if len(extra) > 1 else "it"
    lines = [
        f"ERROR: {op}: {len(extra)} argument"
        f"{'s' if len(extra) > 1 else ''} past the last slot {op} reads — "
        f"{', '.join(repr(t) for t in extra)}.",
        f"  Dropped rather than refused before #1582, so the call ran without "
        f"{them}: a narrowing that was ignored returns MORE than was asked "
        f"for, and nothing in the result says so.",
    ]
    syntax = _op_syntax(op)
    if syntax:
        lines.append(f"  Syntax: {syntax}")
    if remedy:
        lines.append(f"  {remedy}")
    fields = _READ_OP_AT_FIELDS.get(op)
    if fields:
        lines.append(
            f"  A value that contains ':' cannot be spelled on the colon CLI "
            f"— use {op}:@- (fields: {', '.join(fields)}).")
    return nl.join(lines) + nl


def _extra_token_remedy(op: str, parts: List[str], extra: List[str]) -> str:
    """The one-line repair, when the tokens say what was meant (#1582).

    `lines=` is the spelling a reader reaches for after seeing `START-END` in
    the syntax string, so it gets the call spelled out rather than a bare
    rejection. Everything else gets nothing: guessing at a token nobody
    recognises is how the drop happened in the first place.
    """
    if op != "read" or len(parts) < 2:
        return ""
    for tok in extra:
        if tok.startswith("lines=") and _READ_RANGE_RE.fullmatch(tok[6:]):
            # `_flat_field`, not the raw token: this is the one place the
            # refusal echoes a caller-supplied string UNQUOTED, so that the
            # repair can be copied and run. A path is whatever the caller
            # typed, `str.splitlines()` breaks on ten separators (#886), and a
            # forged `[result]` line at column 0 inside a refusal is the same
            # defect the header already guards against.
            return (f"For a line range use the syntax form: "
                    f"read:{_flat_field(parts[1], disclose_newline=True)}"
                    f":{tok[6:]}")
    return ""


def _grep_peel_trailing(parts: List[str]) -> Tuple[List[str], List[str],
                                                   bool, bool, bool]:
    """The two right-to-left peels grep's colon form does, in one place.

    Shared so that "how many trailing tokens were there" and "which two did the
    op read" are answered by the same code. They were not, and #1345 is the gap:
    the parser knew it had peeled three and read two, and nothing compared the
    numbers.

    Returns (args, trailing, count_only, no_auto_read, full) — `args` being
    what is left for the PATTERN and PATH slots. `full` (#1712) joins the
    same word-flag peel as `count` and `no-auto-read`: it is order-independent
    with them and with LIMIT/CONTEXT, which sit in the still-numeric `trailing`
    slots peeled afterwards.
    """
    args = parts[1:]
    count_only = False
    no_auto_read = False
    full = False
    while args and args[-1] in ("count", "no-auto-read", "full"):
        if args[-1] == "count":
            count_only = True
        elif args[-1] == "no-auto-read":
            no_auto_read = True
        else:
            full = True
        args = args[:-1]
    trailing: List[str] = []
    while len(args) >= 3 and (_is_ascii_int(args[-1])
                              or args[-1] == _GREP_ALL_TOKEN):
        trailing.insert(0, args[-1])
        args = args[:-1]
    return args, trailing, count_only, no_auto_read, full


def _grep_peeled_extras(parts: List[str]) -> List[str]:
    """Trailing tokens grep peeled off and never read (#1345).

    `grep:PAT:PATH:5:3:2` peels three and reads two, so the `2` vanished with
    no refusal and no note: a well-formed answer to a slightly different
    question, which is the house defect in its quietest form.

    Returns [] when `all` sits outside the LIMIT slot, because #1328's
    `_GREP_ALL_OUTSIDE_LIMIT_SLOT` says strictly more about that same call —
    which token it is, and where it belongs.
    """
    if not parts[1:]:
        return []
    _args, trailing, _count, _no_auto, _full = _grep_peel_trailing(parts)
    if _GREP_ALL_TOKEN in trailing[1:]:
        return []
    return trailing[2:]


def _swap_suggest(op: str, sig: str, other_key: str, other_value: str,
                  missing_value: str, call_template: str) -> Optional[str]:
    """Suggest a positional swap when the value in the OTHER slot resolves
    to a real file/dir and the missing one does not (#1711).

    `_colon_split_hint` already answers "your PATTERN has a ':' in it and
    swallowed the PATH slot" — a different mistake, and the one arity that
    reaches it (4+ tokens) is not the one a swap usually lands on. A swap
    needs no ':' anywhere: both values are ordinary tokens, just in the
    wrong slots, and `_colon_split_hint` declines on exactly that shape
    (`":" not in leading and _looks_like_path(path)` is true for a plain
    identifier in the path slot). This closes that gap generically rather
    than per-op: whenever the slot that failed to resolve sits next to a
    slot that resolved to an actual file, that is a positive, checkable
    signal — not a guess from shape alone — and every op in the read family
    can ask it the same way.

    Deliberately does NOT fire on `missing_value == other_value`: pointing
    someone at swapping two identical arguments explains nothing.

    Gates `other_value` through `_gate_paths` before ever stat-ing it
    (self-review caught this): the same "a stat of an outside file is
    itself the existence oracle this gate exists to close" hazard that
    every OTHER call site in this file gates against applies here too —
    `os.path.isfile('/etc/passwd')` on the PATTERN/SYMBOL slot would leak
    whether an arbitrary host path exists through a diagnostic message
    that was never supposed to touch anything outside cwd. A value that
    fails containment is silently treated as "does not resolve" — same
    as a value that is simply missing — rather than surfaced as its own
    kind of refusal, so this stays a hint and never a second gate with its
    own wording to keep in sync.
    """
    if not other_value or other_value == missing_value:
        return None
    _err, (_expanded,) = _gate_paths([other_value])
    if _err:
        return None
    if not (os.path.isfile(_expanded) or os.path.isdir(_expanded)):
        return None
    other_value = _expanded
    return (
        f"`{op}` takes {sig} — '{other_value}' looks like the path and "
        f"'{missing_value}' looks like the {other_key}. Did you mean: "
        f"{call_template}"
    )


def _extract_path_kw(parts: List[str]) -> Tuple[List[str], Optional[str]]:
    """Pull a `path=VALUE`/`file=VALUE` token out of a read op's args (#1690).

    `grep`, `around` and `grep_around` all take PATTERN:PATH, `read` takes
    PATH first -- internally consistent per op, but the four disagree with
    each other, and only a multi-op call surfaces that. Direction 1 from
    #1690: a caller who does not want to remember which slot the path goes
    in can name it instead, rather than at the fixed position each op
    otherwise requires.

    Purely additive. `parts[0]` (the op name) is never a candidate, so it is
    always returned untouched at index 0. Exactly one match is required —
    zero leaves `parts` untouched (ordinary positional parsing runs exactly
    as before), and two or more is left in place rather than picking one:
    an ambiguous call should fail the way it always did, not have this
    silently resolve it.

    `parts[1]` is ALSO never a candidate, and that is deliberate rather than
    an oversight (self-review caught the gap, #1711/#1690's own review): the
    PATTERN slot always sits at `parts[1]` for every op this is wired into,
    and a legitimate search for the literal string `path=` or `file=` —
    plausible in any codebase that assigns those variable names — would
    otherwise have its own pattern silently reinterpreted as the keyword.
    Restricting the scan to `parts[2:]` still closes the gap #1690 exists
    for (which slot PATH goes in past the mandatory leading PATTERN) while
    leaving the one slot every caller unconditionally controls alone.
    """
    matches = [i for i, p in enumerate(parts)
               if i > 1 and (p.startswith("path=") or p.startswith("file="))]
    if len(matches) != 1:
        return parts, None
    i = matches[0]
    value = parts[i].split("=", 1)[1]
    if not value:
        return parts, None
    return parts[:i] + parts[i + 1:], value


def _parse_grep_args(parts: List[str]) -> tuple:
    """Parse grep tokens, handling '::' in patterns (e.g. Class::CONST).

    Format: grep:PATTERN:PATH:LIMIT:CONTEXT:count
    The challenge: PATTERN may contain ':' (PHP ::, URL schemes, etc.).
    Strategy: parse known trailing fields (count, context, limit) from the
    right, then the path, and rejoin everything left as the pattern.

    A third trailing token is not this function's business to refuse — it
    returns a 7-tuple and has no error channel — so dispatch asks
    `_grep_peeled_extras` the same question off the same peel (#1345).

    The 7th field, `full` (#1712), is a word flag peeled alongside `count`
    and `no-auto-read` — order-independent with them and with LIMIT/CONTEXT —
    rather than a new positional slot, so `grep:PAT:PATH:LIMIT:CTX:full` and
    every existing caller's arity both parse unchanged.
    """
    # parts[0] is 'grep', work with parts[1:]
    if not parts[1:]:
        return ("", ".", _get_op_int("grep", "max_results", MAX_GREP_RESULTS), 0, False, False, False)

    # Peel the trailing LIMIT[:CONTEXT] slots: format is ...PATH:LIMIT:CONTEXT.
    # Two trailing tokens = limit + context; one = limit only. `all` (#1328) is
    # accepted in the LIMIT slot alongside the digits — before this it was not a
    # digit, so it fell through to the PATH slot and `grep:PAT:PATH:all` searched
    # a directory called `all`.
    context = 0
    limit = _get_op_int("grep", "max_results", MAX_GREP_RESULTS)
    args, trailing, count_only, no_auto_read, full = _grep_peel_trailing(parts)
    if len(trailing) == 1:
        limit = (GREP_LIMIT_ALL if trailing[0] == _GREP_ALL_TOKEN
                 else int(trailing[0]))
    elif len(trailing) >= 2:
        limit = (GREP_LIMIT_ALL if trailing[0] == _GREP_ALL_TOKEN
                 else int(trailing[0]))
        if _GREP_ALL_TOKEN in trailing[1:]:
            # `all` is a LIMIT. Reading it as one here would run a call nobody
            # typed (limit `all` with the caller's number silently demoted to
            # context), and ignoring it would run the default under a token the
            # caller believes changed something. `trailing[1:]` rather than
            # `trailing[1]` because the peel takes every trailing token and the
            # read takes two: a third one is dropped, and a dropped `all` is
            # exactly the silent-completeness bug this token exists to close.
            limit = GREP_LIMIT_ALL_MISPLACED
        else:
            context = int(trailing[1])

    # Now args should be [pattern_parts..., path]
    # The path is the last element; everything before it is the pattern
    if len(args) >= 2:
        path = args[-1] if args[-1] else "."
        pattern = ":".join(args[:-1])
    else:
        # Single token: pattern only, no path
        pattern = args[0] if args else ""
        path = "."

    return (pattern, path, limit, context, count_only, no_auto_read, full)


def _parse_around_args(parts: List[str]) -> tuple:
    """Parse around tokens, handling '::' in patterns.

    Format: around:PATTERN:PATH:N
    Strategy: peel trailing int (N) from right, then path, rejoin rest as pattern.
    """
    args = parts[1:]
    if not args:
        return ("", "", 10)

    # Peel N (int) from right
    n = 10
    if len(args) >= 3 and _is_ascii_int(args[-1]):
        n = int(args[-1])
        args = args[:-1]

    # Last token is path, everything before is pattern
    if len(args) >= 2:
        path = args[-1] if args[-1] else ""
        pattern = ":".join(args[:-1])
    else:
        # Single token: pattern only, no path
        pattern = args[0] if args else ""
        path = ""

    return (pattern, path, n)


def _around_line_delegation(pattern: str, path: str, n: int) -> str:
    """Answer `around:PATH:LINE[:N]` as `around_line`, and say so (#1086).

    `around` takes PATTERN:PATH[:N] and `around_line` takes PATH:LINE[:N] — the
    same op family, the same output, opposite argument order, and nothing in
    either name says which. Four agents in one session picked wrong; every one
    recovered off the error message, which is why it stayed unfiled and also why
    a better error was never going to be the fix.

    Gated so it only ever converts a call that ALREADY FAILS into an answer: the
    numeric argument must not name a real file (a file called `1160` is a path,
    not a line), the argument in front of it must pass cwd containment, and it
    must resolve. No call that works today changes meaning, and the
    `:`-tokenizer is not touched — this is post-parse recovery inside the op.

    `between:PATH:START:END` is deliberately NOT given the same treatment: its
    redirect target is `read`, a different op, and #983 decided that `between`
    should keep doing exactly one thing rather than grow a fourth spelling of a
    range read. Its error already carries the fully-substituted `read` command.

    #1154 asked whether this should refuse rather than substitute, on the
    grounds the caller's intent is genuinely ambiguous. It is not: the
    `os.path.exists(path)` check above is exactly what keeps this from ever
    guessing between two real readings. When the numeric token names an
    entry `os.path.exists` reports as present, that call falls straight
    through to a literal `around` and this function returns "" —
    delegation only fires on a call whose literal reading was already
    unanswerable, so there is exactly one answer left, not a choice among
    several. (A dangling symlink is the one case `os.path.exists` reports
    as absent though the entry is really there — but a literal `around`
    against a symlink that resolves nowhere cannot answer either, so the
    same "only one reading answers" argument still holds; it is a looser
    proxy for "answerable", not a strict `os.path.exists` synonym.) #1154
    also claimed the substitution was disclosed only after the answer it
    substituted; the `note + chr(10) + op_around_line(...)` order below has
    been disclosure first since this function was written for #1086, so
    that half of the report does not reproduce here.
    `tests/test_around_line_delegation_order_1154.py` pins both — including
    that a genuinely existing numeric-named file must be spelled BARE
    (relative to cwd) to actually exercise this guard, since an absolute
    `tmp_path`-rooted name fails `_is_ascii_int` on its slashes before
    `os.path.exists` is ever reached (self-review caught the first draft's
    version of this test doing exactly that).
    """
    if not _is_ascii_int(path) or os.path.exists(path):
        return ""
    line = int(path)
    if line < 1:
        return ""
    # The promotion happens HERE and nowhere else: past this point `pattern` has
    # stopped being a pattern and is a filename. Dispatch already ran containment
    # on the path the parser computed, which in THIS reading is the numeric
    # token — so parts[1] arrives unchecked, and `around:/etc/hosts:3` read a
    # file that `around:localhost:/etc/hosts:1` — the same file, named in the
    # slot the parser does treat as a path — refuses (#1135).
    #
    # The check is here rather than at the dispatch guard because parts[1] is a
    # PATTERN in every other reading, and a pattern is not a path: gating it
    # unconditionally would refuse `around:/etc/passwd:code.py`, i.e. searching
    # a repo for an absolute path string. The dispatch guard answers "the path
    # this call resolved"; this slot only becomes a path conditionally, so the
    # guard has to be conditional too. (#1166 dropped `around` from
    # `_PATH_ARG_POSITIONS` entirely — the table gated a fixed slot the parser
    # did not necessarily use — but that changed nothing here: the promoted slot
    # was never in it.)
    _contained, (pattern,) = _gate_paths([pattern])
    if _contained:
        return _contained
    if not pattern or not os.path.isfile(pattern):
        return ""
    return (
        f"(read as around_line:{pattern}:{line}:{n} — `around` takes "
        f"PATTERN:PATH[:N], so {path!r} was the path, which is not a file. "
        f"Its sibling `around_line` takes PATH:LINE[:N], which is the only "
        f"reading that answers.)" + chr(10)
        + op_around_line(pattern, line, n)
    )


def _between_numeric_hint(parts: List[str]) -> str:
    """Error text for `between:PATH:START:END` and `between:PATH:LINE` (#983).

    `between` is SYMBOL:PATH, so a trailing line number is tokenized as the
    path and the call fails with `path not found: '20'` — a filesystem
    complaint about a number, which is the tool's own mis-split wearing the
    shape of an absence on disk. Three agents in one evening read that as
    "supertool cannot do this" and fell back to `sed` or the harness Read.

    The redirect names the op that already answers, rather than growing a
    fourth spelling of the same read: `read:PATH:START-END` is an inclusive
    1-based range and has been since 0.19.0, and `around_line:PATH:LINE[:N]`
    covers the single-line case. `between` is left doing exactly one thing.

    Returns "" whenever the shape is not unambiguously a line range — the
    numeric token must not name a real path (a file called `12` is a range
    nobody asked for), and the path in front of it must resolve, or this
    would be guessing at a plain typo.

    That resolve is a filesystem probe on parts[1], and parts[1] is a SYMBOL in
    every other reading of `between` — so `_PATH_ARG_POSITIONS["between"] =
    (2, 4)` does not cover it and dispatch's gate has already passed on a slot
    this call did not use as a path. Unguarded, the two answers below differ by
    whether the file is there, which is an existence oracle for anything the
    process can stat (#1142):

        between:/etc/hosts:3:5   -> the range redirect
        between:/etc/nope:3:5    -> path not found: '5'

    Contained here rather than in the table, the shape #1135 established: the
    slot only becomes a path conditionally, so the guard has to be conditional
    too — widening the table would refuse `between:/etc/passwd:code.py`, a
    perfectly ordinary symbol lookup. And it refuses rather than falling
    silent, because the redirect this hint would print is `read:PATH:START-END`
    on a path `read` itself refuses: advice whose remedy is refused is worse
    than the refusal. `_containment_error` never stats, so the refusal reads
    the same whether or not the file exists.
    """
    if len(parts) not in (3, 4):
        return ""
    nums = parts[2:]
    # `read:` takes both `PATH:OFFSET:LIMIT` and `PATH:START-END`, so both
    # spellings arrive here from the same muscle memory. Only the colon one used
    # to be caught; the dash one fell through to `file not found: '1-30'` — a
    # filesystem complaint about a line range, which is the exact mis-split this
    # hint exists to translate, one spelling later (#1234).
    if len(nums) == 1 and nums[0].count("-") == 1 and not os.path.exists(nums[0]):
        _a, _b = nums[0].split("-")
        if _is_ascii_int(_a) and _is_ascii_int(_b):
            nums = [_a, _b]
    if not all(_is_ascii_int(t) and not os.path.exists(t) for t in nums):
        return ""
    path = parts[1]
    if not path:
        return ""
    _contained, (path,) = _gate_paths([path])
    if _contained:
        return _contained
    if not os.path.isfile(path):
        return ""
    lines = [
        f"ERROR: between does not take line ranges — it is between:SYMBOL:PATH"
        f" (or between:re:START:END:PATH), and {parts[-1]!r} was read as the"
        f" path.",
    ]
    if len(nums) == 2:
        start, end = int(nums[0]), int(nums[1])
        if end < start:
            start, end = end, start
        lines.append(f"  For lines {start}-{end} use: read:{path}:{start}-{end}"
                     f"  (inclusive, 1-based)")
    else:
        line = int(nums[0])
        lines.append(f"  For the lines around {line} use: "
                     f"around_line:{path}:{line}[:N]")
        lines.append(f"  For an explicit span use: read:{path}:START-END"
                     f"  (inclusive, 1-based)")
    return chr(10).join(lines) + chr(10)


def _comma_path_list_suggest(op: str, path: str) -> str:
    """Hint for a `PATH,PATH,...` list handed to an op that takes one path.

    `git-resolve` accepts a comma list, so reaching for it elsewhere is the
    spelling the operator was already taught. Joined into one filename it
    fails, and the generic `wrong CWD?` advice then names the one thing that
    provably did not cause it: every entry resolves from the current
    directory. Following it produces the same error a second time (#921).

    Returns "" unless at least one entry exists — a path with a literal comma
    that is simply absent is an ordinary typo, and inventing a list there
    would trade one misreport for another. The count is stated rather than
    implied, so the caller can tell "all of these exist" from "some do".
    """
    if "," not in path:
        return ""
    entries = [e for e in path.split(",") if e]
    if len(entries) < 2:
        return ""
    # Containment before the stat, not after: the loop below is an existence
    # probe on every entry, and dispatch only ever gated the comma-JOINED
    # string — `a.py,/etc/shadow` resolves under the cwd because its first
    # character does, so the tally leaked whether the second entry existed
    # (#1142, the same oracle #1135 closed for `around`).
    _entry_err, entries = _gate_paths(entries)
    if _entry_err:
        return ""
    found = [e for e in entries if os.path.exists(e)]
    if not found:
        return ""
    tally = (f"all {len(entries)}" if len(found) == len(entries)
             else f"{len(found)} of {len(entries)}")
    return (f"a comma-separated list is not accepted here — {op} takes ONE "
            f"path, and the whole list was read as a single filename "
            f"({tally} of its entries exist, so the cwd is not the problem). "
            f"Pass one path, a directory, or one {op} op per file — several "
            f"ops batch into a single call.")


#: Entry-point shims and the sibling that holds the code they stand for. A
#: named pair, not a general "facade" test. A general one — a small module
#: that re-exports a bigger sibling — would fire on every `__init__.py` in a
#: package and still not be the thing anyone greps by mistake; this pair is
#: the one the rename created (#931) and it fires every time.
_SHIM_CORE = {"supertool.py": "_supertool.py"}


def _shim_core_beside(path: str) -> str:
    """The core file name, if PATH is the entry-point shim with it on disk.

    The gate both facade notes share. Gated on the pair actually being on disk
    together: a lone file named `supertool.py` in someone else's tree is an
    ordinary file, and a note there would be a guess.
    """
    if not path:
        return ""
    core = _SHIM_CORE.get(os.path.basename(path))
    if not core or not os.path.isfile(path):
        return ""
    if not os.path.isfile(os.path.join(os.path.dirname(os.path.abspath(path)),
                                       core)):
        return ""
    return core


def _shim_facade_surface_note(path: str) -> str:
    """Disclose the facade beside a result that is CORRECT but partial (#1272).

    `map:supertool.py` returns the shim's two real symbols. Small, correct,
    positive — and misleading in exactly the way #1259's zero was, because the
    reader concludes they have seen the module's surface. It is the harder half:
    an absence at least looks like nothing, whereas an answer-shaped answer
    gives nobody a reason to make the second call.

    So the wording is not #1259's. That note says the result is evidence about
    the shim rather than about supertool, and sends the caller to re-run —
    right, because there the result was empty. Here the listed symbols really
    are the shim's and the list really is complete for that file, so a note
    that read as a correction would be false about a true result. This one
    affirms the result, then says the surface is next door and offers a second
    call to ADD, never a re-run to replace.
    """
    core = _shim_core_beside(path)
    if not core:
        return ""
    return (f"(note: {os.path.basename(path)} is only the entry point — "
            f"supertool's implementation lives in {core} beside it (#931). "
            f"The symbols above are the shim's own and this map is complete "
            f"for that file; supertool's own surface is next door. Add "
            f"map:{core} to see it.)" + chr(10))


def _shim_facade_note(path: str) -> str:
    """Disclose that an empty result came from an entry-point shim (#1259).

    `grep:SYMBOL:supertool.py` scans a file that by construction holds almost
    nothing and reports `0 results in 0 files, scanned 1 files`. Every clause
    is true and the three-state contract is working — `scanned 1 files` proves
    the op looked. What it cannot say is that the file it looked at is a
    facade, so the zero is byte-identical to a zero from the core, and every
    instinct to grep `supertool.py` has landed here since the split.

    Disclosure, never redirect. Scanning `_supertool.py` for a caller who
    named `supertool.py` would answer a question nobody asked and report it
    as the answer to the one they did — a quieter wrong answer than the one
    it replaced.

    Gated by `_shim_core_beside` on the pair being on disk together. Only ever
    called where the result is already empty, so a *hit* — which IS evidence
    about the shim — is left alone by this one. A hit that claims to be the
    whole file's surface is a third case, and #1272 gives it its own wording in
    `_shim_facade_surface_note`: the note there may not read as a correction.
    """
    core = _shim_core_beside(path)
    if not core:
        return ""
    return (f"(note: {os.path.basename(path)} is only the entry point — "
            f"supertool's implementation lives in {core} beside it (#931). "
            f"An empty result here is evidence about the shim, not about "
            f"supertool. Re-run against {core}.)" + chr(10))


def _multi_path_suggest(op: str, path: str,
                        call_prefix: Optional[str] = None) -> str:
    """Hint for `PATH PATH ...` handed to an op that takes one path (#1261).

    `grep PATTERN a.py b.py` is the shell spelling every caller already has.
    Written into the colon CLI the whole argument list lands in the single
    PATH slot and the call fails as one missing filename. What answered
    before was the `:`-split hint, and its prescribed repair is a payload —
    where `path` is a scalar too, so following it reproduces the failure one
    form further along. The op can positively tell the two apart: the value
    it could not resolve contains whitespace and its parts each exist.

    Returns "" unless EVERY part exists. A partial match is a genuinely
    missing path, and stacking a second diagnosis on the first would trade
    one misreport for another — the three-state rule, `docs/validators.md`.

    Returns "" as well when any part fails containment, and that check runs
    BEFORE the existence loop rather than after it: the loop is a stat on
    each part, and dispatch upstream only ever gated the whitespace-JOINED
    string, which resolves under the cwd whenever its first part does. Left
    unguarded the disclosure is an existence oracle for anything the process
    can reach (#1142).

    No new syntax on purpose. Accepting a whitespace list would make a
    filename containing a space unrepresentable in the one slot that must be
    able to name any file — and the tree already has a delimiter for the ops
    that do take lists (`validate:a.py,b.py`, `git-resolve`), so a second one
    would mean two spellings for one idea. Batching is the tool's premise and
    it already buys the round-trip the caller was reaching for.
    """
    parts = path.split()
    if len(parts) < 2:
        return ""
    _multi_err, parts = _gate_paths(parts)
    if _multi_err:
        return ""
    if not all(os.path.exists(p) for p in parts):
        return ""
    n = len(parts)
    word = {2: "TWO", 3: "THREE", 4: "FOUR"}.get(n, str(n))
    lines = [
        f"this looks like {word} paths — {op} takes ONE path (a file, or a "
        f"directory it walks), and the whole string was read as a single "
        f"filename (all {n} parts exist, so the cwd is not the problem)."
    ]
    if call_prefix:
        calls = " ".join("'" + f"{call_prefix}:{p}" + "'" for p in parts)
        lines.append("    Batch instead — several ops run in ONE call, which "
                     "is the round-trip you were reaching for:")
        lines.append(f"      ./supertool {calls}")
    else:
        lines.append("    Pass one path, or the directory they share — and "
                     "batch several ops into one call.")
    return chr(10).join(lines)


# A drive letter that sits after a SPACE (rather than after ',' or '|', the
# two separators `_split_arg` already rejoins across). `_split_arg` never
# looks across whitespace when deciding whether the piece it is holding ends
# in a bare drive letter, so 'grep:pat:file.py C:\Users\x.py' tokenizes to
# leading='pat:file.py C' + path='\Users\x.py' instead of rejoining the
# drive letter into the path (#1271).
#
# Deliberately NOT fixed in `_split_arg` itself: widening the rejoin to look
# across whitespace would change tokenization for a call that works today --
# a pattern containing a space, immediately followed by an absolute path,
# currently parses as pattern-with-space plus path and would silently become
# one token on POSIX, where nothing is broken. This repair instead runs only
# once a path has already failed to resolve, which is the one place that
# cannot break a call that currently succeeds.
_DRIVE_LETTER_AFTER_SPACE = re.compile(r"\s([A-Za-z])\Z")


def _drive_letter_swap_suggest(op: str, leading: str, path: str) -> str:
    """Recognise a drive letter split off `leading` by a preceding space.

    Fires only when rejoining the trailing letter of `leading` with `path`
    (as LETTER:path) produces a path that actually exists -- the same
    "positively checkable, not a guess from shape alone" bar every sibling
    suggest function in this file uses. Returns "" otherwise, including when
    the candidate fails containment: a value that cannot be gated is treated
    as "does not resolve", never surfaced as its own refusal (`_swap_suggest`
    follows the same rule for the same reason).

    Takes `op` rather than the caller's own `call_prefix`: that prefix is
    built from the UNFIXED `leading` (`f"{op}:{leading}"`, for `_multi_path_
    suggest`'s own repair), and appending to it here would print the broken
    leading twice -- once inside the prefix, once as `fixed_leading`.
    """
    if not path or path[0] not in ("/", "\\"):
        return ""
    m = _DRIVE_LETTER_AFTER_SPACE.search(leading)
    if not m:
        return ""
    letter = m.group(1)
    candidate = f"{letter}:{path}"
    _err, (expanded,) = _gate_paths([candidate])
    if _err or not os.path.exists(expanded):
        return ""
    fixed_leading = leading[:m.start(1) - 1]
    return (
        f"this looks like a Windows absolute path that got split on its own "
        f"drive letter: {leading!r} + {path!r} is really {fixed_leading!r} + "
        f"{candidate!r} (the drive letter followed a space, and the "
        f"tokenizer only rejoins one after ',' or '|', never after "
        f"whitespace -- #1271).\n"
        f"    {op}:{fixed_leading}:{candidate}"
    )


def _looks_like_path(tok: str) -> bool:
    """Could *tok* plausibly be a path the caller typed?

    Only used to decide whether a not-found path is more likely a typo or the
    tail of a `:`-split pattern. Whitespace, quotes, pipes and regex punctuation
    are what a spilled pattern carries; a path the caller meant has none.
    """
    if not tok or tok != tok.strip():
        return False
    return not any(c in tok for c in " \t\"'()|<>*?")


def _absorbed_pattern_segments(leading: str) -> List[str]:
    """The pattern's `:`-segments, tokenized the way dispatch tokenized them.

    `_split_arg` is what produced `leading` in the first place, and it merges a
    Windows drive letter back together (`C:\\src` is ONE token, not `C` plus
    `\\src`). A plain `leading.split(":")` here would re-fragment exactly the
    absorbed path this check exists to recognise, and it would do it only on
    the platform CI runs and the author does not.

    The op name is a throwaway: `_split_arg` splits a whole `op:arg:arg` call
    and the caller only wants the args.
    """
    return _split_arg("x:" + leading)[1:]


def _absorbed_path_hint(op: str, leading: str, path: str,
                        keys: Tuple[str, ...] = ("pattern",)) -> str:
    """Refuse a `:`-split that swallowed the PATH and widened the scan (#1417).

    `grep:_FLAGS|def main:presets/github/issues.py:::40` rejoins to the pattern
    `_FLAGS|def main:presets/github/issues.py:` with path `.`, then scans the
    whole tree (934 files when it was reported) and returns hits. The `|` is
    incidental — `grep:PAT:PATH:` does the same with no alternation in it. The
    trigger is the empty PATH token, which `_parse_grep_args` turns into `.`.

    **Why this refuses where `around_line` auto-corrects.** `around:FILE:232:12`
    is redirected to `around_line` and disclosed, and that is safe for one
    reason only: the reading it replaces is a hard failure (`path not found:
    232`), so there is nothing to lose and one candidate answer to gain. Here
    the reading it would replace is a *successful* whole-tree sweep, so a silent
    redirect swaps one answer nobody typed for another. Two live candidates and
    no way to rank them is the shape that has to decline instead of guess.

    **grep only, deliberately.** `_colon_split_hint` is shared with `around`
    and `between`, and wiring this in there looked free and is not. `around`
    and `between` never *default* a path to `.` — an empty slot becomes `""`
    and fails loudly — so `.` there is always a value the caller typed. Worse,
    `between:re:START:END:PATH` has three caller-supplied arguments before the
    path, so `between:re:START:code.py:.` is an ordinary tree-wide range search
    whose END happens to name a file; treating that as an absorbed path is a
    false refusal, and the repair it printed dropped the `re:` marker that
    selects the mode. One op's parser defect does not generalise to a family.

    Gated hard, because the re-read is normally right: measured over the 165
    distinct `grep:` spellings written down in this repo, 39 hit the `:` rejoin
    and **none** of them is declined here. The refusal needs a segment of the
    rejoined pattern to name an existing file or directory, and needs it to sit
    after the first segment — the PATH slot follows the pattern, so a leading
    segment that happens to name a file is a pattern.

    Containment is checked per segment, and a segment that fails it is skipped
    rather than reported. Dispatch gates the PATH slot before calling this
    (#1166) so the stat below is safe; a segment of the PATTERN arrives
    unchecked, and confirming `/etc/shadow` back to the caller would be exactly
    the existence oracle that gate closes.
    """
    if path != "." or ":" not in leading:
        return ""
    segments = _absorbed_pattern_segments(leading)
    found = -1
    for i, segment in enumerate(segments):
        if i == 0 or not segment or segment == ".":
            continue
        contained, (expanded,) = _gate_paths([segment])
        if contained:
            continue
        if os.path.exists(expanded):
            found = i
    if found < 0:
        return ""
    named = segments[found]
    meant = ":".join(segments[:found])
    q = chr(39) * 3
    fields = chr(10).join(f"    {k} = {q}<{k}, colons and all>{q}" for k in keys)
    nl = chr(10)
    return (
        f"ERROR: {op} would have scanned the whole tree, not the file you "
        f"named (#1417).{nl}"
        f"  Read as {keys[0]}={leading!r} + path='.' — {named!r} stayed inside "
        f"the {keys[0]}, and the PATH slot resolved to the repo root (an empty "
        f"slot and a literal '.' both produce it).{nl}"
        f"  Nothing would have failed: that scan succeeds, over every file, "
        f"for a {keys[0]} you did not write. So it is declined rather than "
        f"corrected — both readings are live and neither is guessable.{nl}"
        f"  If you meant that file:{nl}"
        f"    {op}:{meant}:{named}{nl}"
        f"  If you did mean the whole tree, a payload says where the {keys[0]} "
        f"ends and the colon CLI cannot:{nl}"
        f"    ./supertool '{op}:@-' <<'EOF'{nl}"
        f"{fields}{nl}"
        f'    path = "."{nl}'
        f"    EOF{nl}"
        f"  (or {op}:@file.toml — same shape the mutating ops use.){nl}"
    )


# Which grep_around slot each numeric position is, for the refusal below, and
# whether `all` is a value that slot takes. It is a LIMIT and only a LIMIT
# (#1328), so `grep_around:PAT:PATH:N:all` is a shipped spelling the refusal
# must not swallow — caught by `test_grep_around_takes_all_too` while #1826 was
# being written, which is the same "a guard deleted a guard" failure the
# docstring below argues a right-to-left rejoin would cause. In the N slot
# `all` never reaches here: `_GREP_AROUND_ALL_IN_N_SLOT` returns first with a
# message that names the slot order, which is more specific than this one.
_GREP_AROUND_NUMERIC_SLOTS = ((3, "N", False), (4, "LIMIT", True))


def _grep_around_numeric_refusal(parts: List[str], pattern: str,
                                 path: str) -> str:
    """Refuse a grep_around whose N or LIMIT slot is not a number (#1826).

    `grep_around` is the one op in this family that keeps PATTERN and PATH in
    **fixed** slots, and that is deliberate rather than an oversight in need of
    the `_parse_grep_args` rejoin. Three shipped guards are built on it:
    `_PATH_ARG_POSITIONS["grep_around"] = (2,)` gates the path statically,
    `_GREP_AROUND_ALL_IN_N_SLOT` reads `all` out of slot 3, and #1345's
    fifth-token refusal counts slots. A right-to-left rejoin peels trailing
    integers, so `grep_around:PAT:PATH:all` would take `all` for the PATH and
    the first two guards would be gone — which is why this is a refusal and not
    a parse change.

    What the fixed slots cost is that a `:` in the PATTERN puts its own tail in
    a numeric slot. Until now that surfaced as `ERROR: argument parsing:
    invalid literal for int() with base 10: 'CONST'` — the interpreter talking
    about the caller's search term. It also means #1065's `pattern read as`
    disclosure, extended to `around` in #1821, can never fire here:
    `_colon_split_hint` needs a `:` in the *leading* argument and `parts[1]`
    cannot hold one. So this refusal carries the disclosure itself.

    Returns "" when both slots are absent, empty or numeric — every call that
    worked before still reaches `op_grep` unchanged.
    """
    for index, slot, takes_all in _GREP_AROUND_NUMERIC_SLOTS:
        if len(parts) <= index:
            return ""
        token = parts[index]
        if not token or _is_ascii_int(token):
            continue
        if takes_all and token == _GREP_ALL_TOKEN:
            continue
        q = chr(39) * 3
        nl = chr(10)
        return (
            f"ERROR: grep_around: the {slot} slot takes a number and got "
            f"{token!r}.{nl}"
            f"  Read as pattern={pattern!r} + path={path!r} — grep_around keeps "
            f"both in fixed slots (PATTERN:PATH:N:LIMIT) and does not rejoin a "
            f"':' back into the pattern, unlike grep and around.{nl}"
            f"  If your pattern contains ':', that is the likely cause, and a "
            f"payload says where it ends:{nl}"
            f"    ./supertool 'grep_around:@-' <<'EOF'{nl}"
            f"    pattern = {q}<pattern, colons and all>{q}{nl}"
            f'    path = "<path>"{nl}'
            f"    n = 3{nl}"
            f"    limit = 10{nl}"
            f"    EOF{nl}"
            f"  (or grep_around:@file.toml — same shape the mutating ops "
            f"use.){nl}"
        )
    return ""


def _colon_split_hint(op: str, leading: str, path: str,
                      keys: Tuple[str, ...] = ("pattern",),
                      call_prefix: Optional[str] = None,
                      swap_fallback: bool = True) -> str:
    """Error text for a read op whose PATH does not exist and probably should.

    A read op that mis-tokenizes must never read as an absence in the world.
    grep/around/between already fail loudly on a missing path rather than
    returning a bare zero — this makes the failure NAME the cause and carry
    the escape, so the next caller does not re-derive it from scratch (#625).

    Returns "" when the missing path is an ordinary typo (no ':' in the
    leading argument and the path token still looks like a path) — crying
    wolf on every wrong path would make the advice worthless.

    `swap_fallback` must be False for a caller with no `_swap_suggest`
    fallback of its own downstream (#1972 review caught this): declining
    here is only safe when returning "" hands the call to code that will
    say something else instead. `between:re:START:END:PATH` shares this
    function but calls `op_between_pattern`, which has no swap-suggest
    branch at all -- declining there for `leading` a colon-joined
    `START:END` was a silent zero-diagnostic regression, not a wash, the
    first time this shipped.
    """
    if not path or path == "." or os.path.exists(path):
        # (#1271 follow-up, CI: windows-latest) On a single-drive Windows
        # machine -- virtually every real install, and every windows-latest
        # CI runner observed so far -- a path missing its drive letter
        # (e.g. "\Users\x.py") is NOT a broken path: it resolves against
        # the current drive, and since there is only one drive, that
        # resolution names the EXACT SAME FILE the full "C:\Users\x.py"
        # would have. `os.path.exists(path)` therefore returns True for
        # BOTH a genuinely correct drive-relative call and a mis-tokenized
        # one that dropped its drive letter -- the two are indistinguishable
        # from here, because on such a machine they resolve to the same
        # thing. A version of this function that fired anyway (tried and
        # reverted, see the PR history) turned a working call into a false
        # "path not found" whenever a caller's own pattern coincidentally
        # ended in whitespace plus the drive letter -- worse than the bug it
        # was chasing. This one specific shape is therefore an accepted
        # limitation, not a gap to close here: the diagnosis below still
        # fires whenever the naive path genuinely does not resolve (a
        # multi-drive machine, or a target that does not exist under the
        # current drive either), which is the only case it can safely tell
        # apart from a call that already works.
        return ""
    if ":" not in leading and _looks_like_path(path):
        return ""
    # #1972 (CI, windows-latest): the check above declines only when
    # `leading` has NO colon at all -- true for an ordinary swap on POSIX,
    # false on Windows, where an absolute path always carries one from its
    # own drive letter (`C:\Users\...`). That platform difference must not
    # change which diagnosis fires: `leading` resolving as a real file is
    # the SAME positive, checkable evidence `_swap_suggest` uses downstream
    # (in `op_around`/`op_grep`/`op_between_symbol`'s own fallback, reached
    # once this returns "") -- ONLY for the callers that have that
    # fallback, which is what `swap_fallback` gates. Gated through
    # `_gate_paths` for the same reason `_swap_suggest` is: a bare
    # `os.path.isfile` on caller-controlled text would make this an
    # existence oracle for paths outside the containment boundary.
    if swap_fallback:
        _leading_err, (_leading_expanded,) = _gate_paths([leading])
        if not _leading_err and (os.path.isfile(_leading_expanded)
                                  or os.path.isdir(_leading_expanded)):
            return ""
    # Ahead of the `:` diagnosis, not after it. A value that whitespace-splits
    # into parts which all exist is positively a different mistake, and the
    # colon advice points at a payload whose `path` is a scalar as well — a
    # repair that fails identically one form further along (#1261).
    if call_prefix is None:
        call_prefix = f"{op}:{leading}"
    _drive = _drive_letter_swap_suggest(op, leading, path)
    if _drive:
        return _path_not_found(path, suggest=_drive)
    _multi = _multi_path_suggest(op, path, call_prefix)
    if _multi:
        return _path_not_found(path, suggest=_multi)
    original = f"{leading}:{path}"
    q = chr(39) * 3
    fields = "\n".join(f"    {k} = {q}<{k}, colons and all>{q}" for k in keys)
    return (
        f"ERROR: path not found: {path!r} (cwd: {os.getcwd()})\n"
        f"  Read as {'+'.join(keys)}={leading!r} + path={path!r}"
        f" — i.e. {original!r} split on ':'.\n"
        f"  If your {keys[0]} contains ':', that split is the likely cause. "
        f"The colon CLI cannot tell where the {keys[0]} ends; a payload can:\n"
        f"    ./supertool '{op}:@-' <<'EOF'\n"
        f"{fields}\n"
        f"    path = \"<path>\"\n"
        f"    EOF\n"
        f"  (or {op}:@file.toml — same shape the mutating ops use.)\n"
    )


def op_replace(old: str, new: str, path: str = ".", dry: bool = False) -> str:
    """Find and replace text across files. Supports dry-run preview.

    Searches recursively through `path` (respecting grep file includes),
    finds all occurrences of `old`, and either previews (dry=True) or
    executes (dry=False) the replacement.

    Output format:
      - Dry mode: diff-style preview (- old / + new) per occurrence
      - Execute mode: compact receipt (files modified, counts)
    """
    if not old:
        return "ERROR: empty search pattern\n"
    if old == new:
        return "ERROR: old and new strings are identical\n"
    if not path:
        return "ERROR: empty path\n"

    # Validate path exists
    if path != "." and not os.path.isfile(path) and not os.path.isdir(path):
        return _path_not_found(path, op="replace", creates=True)

    candidates = _grep_candidates(path, _get_exclude_paths("replace"))
    if not candidates:
        return "(0 files to search)\n"

    # Collect matches via whole-file scan so multi-line `old` patterns work.
    # Line-by-line matching would silently miss any pattern containing '\n'.
    # (filepath, [match_start_offsets], effective_old, effective_new). The two
    # effective strings are carried rather than recomputed: this pass and the
    # write pass below used to read the same file with different newline
    # settings, so on a CRLF file one found an LF `old` and the other did not.
    # The write became a no-op and the receipt reported *this* pass's number —
    # `(2 replacements in 2 files)` over two unchanged files (#1049).
    file_matches: List[Tuple[str, List[int], str, str]] = []
    total_count = 0
    for file_path in candidates:
        try:
            with open(file_path, "rb") as f_bin:
                head = f_bin.read(4096)
            if b"\x00" in head:
                # Binary file — skip. Avoids regex-sub corrupting git internals,
                # images, compiled blobs, etc. (recovered cost: a `.git/index`
                # walked into by a stray relative path arg.)
                continue
            with open(file_path, "r", encoding="utf-8",
                      errors="surrogateescape", newline="") as f:
                content = f.read()
        except OSError:
            continue
        positions: List[int] = []
        eff_old, eff_new = old, new
        for nl, cand in _newline_variants(old):
            start = 0
            found: List[int] = []
            while True:
                idx = content.find(cand, start)
                if idx == -1:
                    break
                found.append(idx)
                start = idx + len(cand)
            if found:
                positions = found
                eff_old = cand
                eff_new = _retermed(new, nl) if nl else new
                break
        if positions:
            file_matches.append((file_path, positions, eff_old, eff_new))
            total_count += len(positions)

    if total_count == 0:
        # The one no-op receipt in the tool that does not say ERROR, so it
        # never reached the exit code either (#680). A preview finding nothing
        # is a truthful preview, not a decline — only the real op declines.
        if not dry:
            _bump_counter(_SKIP_COUNT, "cnt_skip")
        return f"(0 occurrences of '{old}' found)\n"

    if dry:
        out: List[str] = [f"({total_count} occurrences in {len(file_matches)} files)\n"]
        # Derived the same way the execute-mode receipt derives it (see the
        # comment above `retermed` in the write branch below): `eff_old !=
        # old` is exactly "a re-terminated variant matched", so this is the
        # same disclosure one branch earlier, over the preview rather than
        # the write (#1069). Per file, not a blanket summary line, for the
        # same reason: a note true of the run and false of one of its files
        # is the failure #1057 already rejected in this op's own execute
        # branch.
        retermed: Dict[str, str] = {}
        for filepath, positions, eff_old, eff_new in file_matches:
            # splitlines, not split("\n"): the effective strings may be CRLF or
            # CR terminated, and a split on "\n" leaves a trailing \r on every
            # preview line.
            old_lines = eff_old.splitlines() or [eff_old]
            new_lines = eff_new.splitlines() or [eff_new]
            if eff_old != old:
                retermed[filepath] = ("CRLF" if "\r\n" in eff_old
                                      else "CR" if "\r" in eff_old else "LF")
            tag = f" [{retermed[filepath]}]" if filepath in retermed else ""
            out.append(f"\n{_fwd(filepath)}{tag}\n")
            try:
                with open(filepath, "r", encoding="utf-8",
                          errors="surrogateescape", newline="") as f:
                    content = f.read()
            except OSError:
                continue
            for pos in positions:
                start_line = _line_number_at(content, pos)
                end_line = start_line + len(old_lines) - 1
                label = f"L{start_line}" if start_line == end_line else f"L{start_line}-L{end_line}"
                out.append(f"  {label}:\n")
                for ol in old_lines:
                    out.append(f"    - {ol}\n")
                for nl in new_lines:
                    out.append(f"    + {nl}\n")
        if retermed:
            # Only where a choice would be made if this ran for real — a
            # uniform file whose `old` matched literally gets no tag and no
            # mention, matching the execute-mode note this mirrors.
            out.append(f"\n  {mark('↳')} line endings: the text you supplied "
                       f"does not match {len(retermed)} of these files byte "
                       f"for byte and would be re-terminated to the "
                       f"convention marked above to make it match — every "
                       f"untouched line would be unchanged\n")
        out.append(f"\nSummary: {total_count} replacements in {len(file_matches)} files (DRY RUN — no files modified)\n")
        return "".join(out)

    # Execute mode
    files_modified: Dict[str, int] = {}
    vanished: List[str] = []
    # Per-file count of occurrences that were already sitting inside a prior
    # application of this same edit (#938, the residual #701 left open:
    # `edit` gained this disclosure, `replace` shared the silent double-apply
    # and had none of it — confirmed live in the issue's own follow-up
    # comment). `_count_already_applied` runs the same positional test
    # `op_edit` uses, batched across every occurrence in one file rather than
    # per-occurrence (see its own docstring for why that batching is not
    # optional), against the PRE-write content — a later occurrence's index
    # would otherwise be read against text this same write already shifted.
    reapplied_counts: Dict[str, int] = {}
    for file_path, _scan_positions, eff_old, eff_new in file_matches:
        try:
            # newline="": see op_edit / op_append. Without it every line of a
            # CRLF file was rewritten to LF by a replace that matched one
            # string (#1049). The scan's positions are deliberately unused
            # here — recounting against the bytes about to be written is the
            # whole point.
            with open(file_path, "r", encoding="utf-8",
                      errors="surrogateescape", newline="") as f:
                content = f.read()
        except OSError:
            continue
        # Counted here, from the bytes about to be written, never from the scan
        # pass. A number taken from the scan survived the write matching
        # nothing and reported replacements that had not happened (#1049).
        hits = content.count(eff_old)
        if not hits:
            vanished.append(file_path)
            continue
        _n_reapplied = _count_already_applied(content, eff_old, eff_new)
        if _n_reapplied:
            reapplied_counts[file_path] = _n_reapplied
        new_content = content.replace(eff_old, eff_new)
        try:
            _atomic_write(file_path, new_content)
            files_modified[file_path] = hits
        except OSError as e:
            return f"ERROR: failed to write {file_path}: {e}\n"

    total = sum(files_modified.values())
    # `_newline_note` states the invariant this discloses: "re-writing the
    # caller's own endings is always disclosed". `op_edit` and
    # `op_replace_lines` call it; `replace` did the same `_newline_variants`
    # re-termination and said nothing, so a CRLF replace rewrote the caller's
    # block in silence (#1049, third pass).
    #
    # `_newline_note` itself is not reusable here and is deliberately not
    # called: it writes one sentence about one file, and `replace` is
    # multi-file with a different answer per file — a summary line true of the
    # run would be false of every file that matched literally. So the fact goes
    # on the file's own line and the sentence is said once.
    #
    # Derived from `eff_old`, not carried out of the scan: `_newline_variants`
    # drops any candidate equal to the literal, so `eff_old != old` is exactly
    # "a re-terminated variant matched", and the resolved scan/write pair above
    # stays untouched.
    retermed: Dict[str, str] = {}
    for _fp, _positions, _eff_old, _eff_new in file_matches:
        if _fp in files_modified and _eff_old != old:
            retermed[_fp] = ("CRLF" if "\r\n" in _eff_old
                             else "CR" if "\r" in _eff_old else "LF")
    # #938: disclose, never refuse — same posture #701 took for `edit`. Bumped
    # once per occurrence found sitting inside a prior application of this
    # same edit, so the shared `[result]` footer's `K re-applied` (see
    # `_result_line`) is honest for `replace` too, not only for `edit`.
    _total_reapplied = sum(reapplied_counts.values())
    if _total_reapplied:
        _bump_counter(_REAPPLY_COUNT, "cnt_reapply", _total_reapplied)
    out = [f"({total} replacements in {len(files_modified)} files)\n"]
    for fp, cnt in sorted(files_modified.items()):
        tag = f" [{retermed[fp]}]" if fp in retermed else ""
        if fp in reapplied_counts:
            tag += f" [{reapplied_counts[fp]} re-applied]"
        out.append(f"  {_fwd(fp)} ({cnt}){tag}\n")
    if reapplied_counts:
        out.append(
            f"\n  {mark('↳')} re-applied: the text this edit produces was "
            f"already present around the anchor in "
            f"{len(reapplied_counts)} file"
            f"{'' if len(reapplied_counts) == 1 else 's'} — this is a SECOND "
            f"application, not a repeat of the first\n"
        )
    if retermed:
        # Only where a choice was made. A uniform file whose `old` matched
        # literally is not marked and produces no line at all — on Windows
        # every file is CRLF, and a note that fires on every call is the noise
        # #1049's second pass removed.
        out.append(f"  {mark('↳')} line endings: the text you supplied did not "
                   f"match {len(retermed)} of these files byte for byte and "
                   f"was re-terminated to the convention marked above to make "
                   f"it match — every untouched line is unchanged\n")
    if vanished:
        # Matched during the scan, gone by the time the write read it back.
        # Dropping these silently is how the count and the disk disagree.
        out.append(f"\n{len(vanished)} file(s) matched during the scan and no "
                   f"longer matched when the write read them back — NOT "
                   f"modified:\n")
        for fp in sorted(vanished):
            out.append(f"  {_fwd(fp)}\n")
    out.append(f"\nDone: '{old}' → '{new}'\n")
    return "".join(out)


def _write_target(path: str) -> str:
    """The path a write to *path* actually lands on — a symlink followed (#1136).

    `_atomic_write` resolves a symlink before `os.replace` so the real file is
    written rather than clobbered by a regular file. Anything that has to reason
    about what that write did to the filesystem — above all the rollback, which
    deletes — has to ask the same question of the same path, or it decides
    identity on an object the writer never touched. One expression, two callers.
    """
    return os.path.realpath(path) if os.path.islink(path) else path


def _write_target_display(path: str) -> str:
    """`_write_target(path)`, spelled the way `path` itself is displayed (#1146).

    `_write_target` uses `os.path.realpath`, which canonicalises every
    symlinked ANCESTOR directory along the way, not only the leaf symlink —
    macOS routes every `/tmp` path through `/private/tmp`. The receipt lines
    that quote `path` back (the success line `_receipt_head` retracts, the
    `[rolled back]`/`[left on disk]` subject) never canonicalise ancestors —
    they use `os.path.abspath`. So a retraction of a write through a symlink
    named the SAME directory two different ways: `/private/var/…/target.py`
    for the resolved target, `/var/…/link.py` for the link the success line
    named, and a reader had to work out the two prefixes were one place.

    Rewritten to agree with `path`'s own spelling wherever the divergence is
    ONLY that ancestor-canonicalisation — i.e. the write target and `path`'s
    directory resolve (via realpath) to the very same directory, and differ
    only in which of the two equivalent spellings was used for it. A target
    that genuinely lives elsewhere (chained symlinks pointing well outside
    `path`'s own directory) is returned exactly as `_write_target` found it —
    this only removes a cosmetic mismatch, never the disclosure that the
    write landed somewhere else.
    """
    target = _write_target(path)
    if target == path:
        return target
    path_dir = os.path.dirname(os.path.abspath(path))
    target_dir = os.path.dirname(target)
    if path_dir != target_dir and os.path.realpath(path_dir) == os.path.realpath(target_dir):
        return os.path.join(path_dir, os.path.basename(target))
    return target


def _process_umask() -> int:
    """The process umask, read once at import.

    CPython offers no getter: the mask has to be set and put back, and the two
    syscalls are a window in which another thread would create a file under the
    wrong mask. Read at import, before this module can have started a thread,
    so the window is never open while one exists.
    """
    cur = os.umask(0o022)
    os.umask(cur)
    return cur


#: What a file `paste`/`append` brings into existence is created at (#1275).
#: `0666 & ~umask` is what `open`, `>`, `tee`, `cp` and every editor produce;
#: the `0600` that reached disk before was `tempfile.mkstemp`'s, an artefact of
#: the temp file rather than a default anybody chose, and it was never a
#: guarantee either -- an overwrite has always kept the target's own mode
#: (#259), so the tight bit applied only to files that were not there before.
#: A caller wanting owner-only files sets `umask 077`, which is what the mask
#: is for, and the receipt states the mode so the widening is not silent.
_NEW_FILE_MODE = 0o666 & ~_process_umask()


def _atomic_write(path: str, content: str) -> None:
    """Write content to path atomically — temp file + os.replace.

    Enforces _safe_path containment (closes #146) — the resolved path must
    live under cwd unless SUPERTOOL_ALLOW_OUTSIDE_CWD=1 is set. Single
    chokepoint for all mutation ops (paste/edit/replace_lines/vim/replace).

    If `path` is a symlink, follow it to the real target — otherwise
    os.replace would clobber the symlink with a regular file, leaving the
    real file untouched (silent data divergence). The symlink target itself
    is checked against cwd containment — a symlink in the repo pointing at
    /etc/hosts is rejected.

    Crash-safe: if interrupted mid-write, the original file is preserved
    (the temp file is incomplete but the target path still has old data).

    Uses surrogateescape encoding so any bytes that round-tripped through
    read(errors='surrogateescape') survive the write unchanged — protects
    files containing illegal UTF-8 sequences (binary blobs, partial encodes).
    """
    import tempfile
    # Containment check happens against the symlink target (real path) so a
    # symlinked write doesn't escape cwd via the symlink itself.
    _safe_path(path)
    # #1147: a pinned target beats re-deriving one, keyed on the very string
    # `_run_with_validators` sampled `_write_target` against -- BEFORE
    # `_expand_home` below can change what `path` spells, so the key matches
    # what the pin was set with rather than a rewritten copy of it.
    _pinned = getattr(_DISPATCH_STATE, "pinned_write_target", None)
    _use_pin = _pinned is not None and _pinned[0] == path
    # Behind that check, and for the same reason as `render_file` (#1300): a
    # direct internal caller must not write to `<cwd>/~/x` after the gate
    # approved the home path.
    path = _expand_home(path)
    # Every mutating op passes through here, which makes it the one place that
    # can promise a coalesced `git status` snapshot never outlives a write
    # (#1126). Cleared before the write rather than after: an exception on the
    # way out would otherwise leave a snapshot describing a tree that has
    # already partly moved.
    _path_meta_bulk_drop()
    # Byte-pattern warnings a syntax validator structurally cannot catch, raised
    # at the one place every mutating op passes through (#380).
    _warn = _sh_backslash_warning(path, content)
    _key = os.path.abspath(path)
    # The sampled value if one is pinned for this exact path (#1147) -- never
    # re-asking `_write_target` a question whose answer may have moved since
    # `_run_with_validators` asked it. Any other caller (a bare internal write,
    # `op_replace`'s own per-file loop) has no pin keyed to its `path` and
    # resolves exactly as before.
    real_path = _pinned[1] if _use_pin else _write_target(path)
    target_dir = os.path.dirname(os.path.abspath(real_path)) or "."
    # Preserve the original file's mode (#259). mkstemp creates the temp file
    # with 0600; os.replace would then clobber the target's mode, silently
    # dropping the executable bit on scripts/git hooks. Capture the existing
    # mode and re-apply it to the temp file before the rename.
    #
    # A brand-new file used to keep mkstemp's 0600 (#1275). That is not a
    # default anybody chose — it is the temp file's own mode leaking through a
    # rename — and it made supertool the only file-creating tool on the box
    # that ignores the umask. It gets `_NEW_FILE_MODE` instead, which never
    # carries an executable bit, so #259's "no spurious +x" still holds.
    # Three states, not two. `FileNotFoundError` is "there is no file here",
    # which is the create. Any other OSError means the mode could not be read
    # from a file that may well exist, and applying a create's default there
    # would rewrite a mode nobody asked about — mkstemp's own is left alone
    # instead, which is what happened before #1275 in every case.
    try:
        orig_mode = stat.S_IMODE(os.stat(real_path).st_mode)
    except FileNotFoundError:
        orig_mode = _NEW_FILE_MODE
    except OSError:
        orig_mode = None
    fd, tmp_path = tempfile.mkstemp(
        prefix=".supertool-", suffix=".tmp", dir=target_dir
    )
    try:
        # Open in binary mode + encode manually so Windows text-mode doesn't
        # translate `\n` → `\r\n` (which corrupts mixed-line-ending content,
        # binary blobs, and any caller that round-tripped through
        # `read(errors='surrogateescape')`).
        with os.fdopen(fd, "wb") as f:
            f.write(content.encode("utf-8", errors="surrogateescape"))
        if orig_mode is not None:
            os.chmod(tmp_path, orig_mode)
        os.replace(tmp_path, real_path)
    except Exception:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise
    # Only past the rename: the counter says "bytes reached disk", and the
    # warning queue must describe what is on disk. A write that raised did
    # neither, and counting it would let dispatch treat a failed op as a
    # successful one.
    _bump_counter(_WRITE_COUNT, "cnt_write")
    # A rollback rewrites the same path, so drop any stale entry for it first.
    _drop_write_warnings(path)
    if _warn:
        _WRITE_WARNINGS.append((_key, _warn))
    # A `.py`-only advisory seeded at payload-parse time (#2493), for a
    # doubled-backslash escape sequence the payload's own author already
    # exempted from the write refusal via `literal_backslashes` -- popped
    # (not read) so it cannot outlive the one write it describes.
    _py_advice = _PAYLOAD_PY_ESCAPE_ADVISORY.pop(_key, "")
    if _py_advice:
        _WRITE_WARNINGS.append((_key, _py_advice))


_BRANCH_CACHE: List[Optional[Tuple[str, str]]] = [None]

# Above this, the nearest-line scan is skipped — the diagnostic is a courtesy
# on a failure path and must never become the slow part of a failed edit.
_EDIT_DIAG_MAX_LINES = 20000

_GIT_TIMEOUT_DEFAULT = 5


def _git_timeout() -> int:
    """Budget for the git calls supertool makes about itself (#650).

    Overridable per environment for the same reason SUPERTOOL_LINT_TIMEOUT is
    (#553): a loaded runner occasionally needs room, and that is a fact about
    the runner, never a decision about the product. The shipped default does
    not move — pinned by test_the_suite_budget_does_not_move_the_product_default.
    """
    return _env_int("SUPERTOOL_GIT_TIMEOUT", _GIT_TIMEOUT_DEFAULT, minimum=1)


def _branch_reading() -> Tuple[str, str]:
    """`(branch, why_unavailable)` — three states, not two (#650).

    `("my-feature", "")` git answered and named a branch; `("", "")` git
    answered and there is no branch to name; `("", why)` git did not answer.

    The third state used to be the second. Both were `""`, and `_branch_line()`
    renders `""` as silence, so a receipt whose branch lookup timed out was
    byte-identical to one taken outside a repo — an absence the tool produced,
    read as an absence in the world (docs/validators.md, "Declining instead of
    guessing"). It is the wrong direction to be wrong in: the footer exists to
    catch right-file-wrong-branch, so it fell silent on exactly the run where
    the caller had least idea what state the repo was in.

    A missing git binary stays in the middle state deliberately. Nothing on
    that machine was ever going to name a branch, which is the one honest
    silence — the same line `_vim_render_lint` draws for an uninstalled checker.

    Cached for the process: a single supertool invocation cannot change branch
    mid-call, and a batch of edits would otherwise pay a subprocess each. The
    decline is cached with it — a stalled read is the expensive one to repeat.
    """
    if _BRANCH_CACHE[0] is None:
        branch = ""
        why = ""
        budget = _git_timeout()
        try:
            # symbolic-ref, not rev-parse: it resolves an *unborn* branch (a
            # fresh `git init` before the first commit), where rev-parse fails
            # with "ambiguous argument 'HEAD'". It exits non-zero on a detached
            # HEAD, which is the one case worth a second call.
            r = subprocess.run(
                ["git", "symbolic-ref", "--short", "-q", "HEAD"],
                capture_output=True, text=True, timeout=budget,
                encoding="utf-8", errors="replace",
            )
            if r.returncode == 0:
                branch = r.stdout.strip()
            else:
                d = subprocess.run(
                    ["git", "rev-parse", "--short", "HEAD"],
                    capture_output=True, text=True, timeout=budget,
                    encoding="utf-8", errors="replace",
                )
                if d.returncode == 0 and d.stdout.strip():
                    branch = f"detached HEAD at {d.stdout.strip()}"
        except FileNotFoundError:
            pass
        except subprocess.TimeoutExpired as exc:
            cmd = " ".join(str(a) for a in (exc.cmd or ["git"]))
            why = f"`{cmd}` did not answer within {budget}s"
        except OSError as exc:
            why = f"`git symbolic-ref` could not be run — {exc}"
        _BRANCH_CACHE[0] = (branch, why)
    return _BRANCH_CACHE[0]


def _current_branch() -> str:
    """Current git branch, or "" when there isn't one to report.

    The plain-string contract every caller but the receipt wants; *why* the
    string is empty is `_branch_reading()`'s second value.
    """
    return _branch_reading()[0]


def _branch_line() -> str:
    """`[branch: X]` footer for a mutating op (#381).

    Two near-misses in one session were the same shape — right file, wrong
    branch — and supertool is the thing that knows. A handful of tokens per
    call, against a class of mistake that is otherwise silent until commit time.
    """
    branch, why = _branch_reading()
    if branch:
        return f"[branch: {branch}]\n"
    # A read that failed is not a repo without a branch (#650). Silence is
    # reserved for the second; the first says so and names what stalled.
    if why:
        return f"[branch: UNKNOWN — {why}]\n"
    return ""


def _result_line(ops: int, writes: int, skipped: int = 0,
                 reapplied: int = 0,
                 not_checked: Optional[Sequence[str]] = None,
                 rolled_back: int = 0,
                 validated: Optional[Sequence[Tuple[str, bool, bool]]] = None,
                 left_on_disk: int = 0) -> str:
    """`[result] N ops run, M writes[, K skipped][, K rolled back][, K re-applied]` (#621),
    or, for a read-only `validate:` run, `[result] N files, M with findings,
    K not checked` (#990).

    The receipt a mutating op prints sits ABOVE the `[validators]` block, and a
    long validators block is exactly when a reader reaches for `| tail -4`. So
    the last thing on screen was `git-status : ok` — which describes the
    validators and reads as though it described the edit. A no-match and an
    11-file replace were indistinguishable that way, twice, at real cost: once a
    teammate was told files were unfixed when they had been fixed, once an agent
    reported a no-matched batch edit as landed and sent a broken branch to CI.

    The invariant this pins is stronger than "print the summary last": an op
    which changed nothing must not END with output that looks like an op which
    did. So this is a footer, not a move — the detailed receipt stays where
    positional readers and every existing ordering test expect it, and one
    honest line is repeated below the noise.

    Both numbers come from counters, never from re-reading the prose receipt.
    `ops` is `_MUTATION_ATTEMPTS` (bumped when a mutating op runs, outcome
    unknown); `writes` is `_WRITE_COUNT` (bumped at `_atomic_write`, decremented
    by `_retract_write`), so a rolled-back edit correctly reports 0. In a batch
    that is precisely "requested" vs "applied", which is the single line that
    would have caught the #634 incident: one no-match among five successes.

    `ops == 0` means no mutating op was accounted for and the state cannot be
    determined — this declines rather than guessing a tidy `0 writes`, per the
    three-state contract in docs/validators.md.

    `skipped` names the third state for the ops themselves (#680). `ops` vs
    `writes` already carried the information, but only as a subtraction the
    reader had to perform while suspicious: a batch that reported
    `6 ops run, 4 writes` had dropped two edits, and the branch went to CI.
    A count you must diff is not a signal; a word is. So the word appears
    whenever an op declined, and never otherwise — `0 skipped` on the green
    path is exactly the kind of number a reader learns to stop seeing, which
    is how `4 writes` failed in the first place.

    `re-applied` names a fourth state (#701): the op wrote, and what it wrote
    was already there. Re-running a payload whose anchor survives its own edit
    applies the edit a SECOND time, and pre-fix the two runs differed only by a
    line range — so an identical footer read as "the same thing happened" when
    what happened was another mutation. It is a separate word from `skipped`
    deliberately: a skipped op left the disk alone, a re-applied one did not,
    and collapsing them would degrade `skipped` into "something was odd".

    It is also NOT a failure. `_SKIP_COUNT` drives the exit code so a `&&` chain
    stops on a half-applied batch; a re-apply is a legitimate outcome (appending
    a second repeated element has exactly this shape), so it discloses and exits
    0. Refusing would be guessing at intent, which is the line #680 drew too.

    `not_checked` names a fifth state, and it IS a failure (#665). It is about
    the checkers rather than the op: the edit landed, and a validator the
    operator named in `$SUPERTOOL_REQUIRE_VALIDATORS` produced no verdict about
    the file. Before this, that case reached the reader as
    `1 err  (pre-existing — not from this edit)` in the block above and as
    `1 op run, 1 write` here, and exited 0 — so the one knob that exists to
    stop "the gate is not running" from reading as a pass read as a pass. The
    validators are named on the line rather than counted, because the line has
    to be actionable on its own for `| tail -1` to be the documented read.

    It is also the one state that can reach a reader with `ops == 0`, and so it
    is the one exception to the bail below (#969). `validate:` mutates nothing,
    so it had no footer at all: its non-verdict was visible in the row and in
    the exit code, and absent from the line the docs tell readers to trust. The
    counts stay off that line — there was no op to count.

    `validated` is what makes that footer unconditional for `validate:` (#990).
    #979 emitted it only on a decline, so a clean run still ENDED on the last
    file's own row — a per-file verdict standing where a whole-run one belongs,
    on a multi-file run the same defect as #970's forged row. `0 ops run,
    0 writes` remains the wrong summary of a read-only op (#621), so this branch
    reports what a `validate:` run actually produced instead:

    ```
    [result] 3 files, 1 with findings, 0 not checked
    ```

    File counts, and they do not partition — one file can hold a finding AND a
    checker that declined. `not checked` counts a file where at least one
    validator returned no verdict, `skipped` included: #665 refused to
    *escalate* an optional tool nobody installed, and disclosing it on a count
    line escalates nothing. It is shown as a `0` rather than suppressed, which
    is the opposite of the rule `skipped` follows above and deliberately so — on
    a line whose entire content is counts, the not-checked slice is the one a
    reader must be able to find without knowing whether it fired, and a run that
    could not check something has to say so whether or not anything failed.

    `NOT RUN` stays absent from a clean run. It is the token consumers grep for,
    and rendering `0 validators NOT RUN` would put it in the output of every
    green validate — #621's zero-nobody-reads with a live tripwire attached. The
    #979 clause is appended after the counts when it fires, not instead of them.

    `rolled_back` names a sixth state (#952): the op matched, wrote, failed a
    validator and was reverted. `writes` already excluded it — `_retract_write`
    decrements — but a count is only a signal when the reader is already
    suspicious. In the single-op case the exclusion rendered as a sentence
    (`0 writes — nothing changed on disk`); in a batch where other ops did
    write it rendered as `3 ops run, 2 writes`, an arithmetic mismatch the
    reader has to notice AND explain. It is not `skipped`: a skipped op
    declined and left the disk alone, a rolled-back one wrote and had the write
    undone, and the remedies differ (fix the anchor vs fix the code). It is not
    folded into `nothing changed on disk` either, because a no-match prints
    exactly that too — the two most confusable outcomes on this path.

    `left_on_disk` names a seventh state and it is `rolled_back`'s opposite
    number (#1320): the op CREATED a file, a validator reported a finding on it,
    and no validator that found anything was configured to roll back — so the
    refused artefact is in the tree. Every other outcome of a create was already
    distinguishable here and this one was not: it printed `1 op run, 1 write`,
    the same line a clean create prints, while the block above showed a red row.
    A reader piping to the footer — the documented read — got the write and not
    the refusal, and a reader who saw the refusal had no way to learn the file
    survived it. Counted rather than named, unlike `NOT RUN`: the actionable
    identifier is the path, the path is already on the `[left on disk]` line
    above with the validator that refused it, and a footer that grows by a
    filesystem path per op stops being one line.
    """
    if ops <= 0:
        names = list(dict.fromkeys(not_checked or ()))
        files = list(validated or ())
        if files:
            n = len(files)
            with_findings = sum(1 for _p, f, _nv in files if f)
            unchecked = sum(1 for _p, _f, nv in files if nv)
            line = (f"[result] {n} file{'' if n == 1 else 's'}, "
                    f"{with_findings} with findings, {unchecked} not checked")
            if names:
                line += (f" — {len(names)} validator"
                         f"{'' if len(names) == 1 else 's'} "
                         f"NOT RUN ({', '.join(names)}) — those validators "
                         f"returned no verdict, so the file was NOT checked")
            return line + chr(10)
        if not names:
            return ""
        return (f"[result] {len(names)} validator{'' if len(names) == 1 else 's'} "
                f"NOT RUN ({', '.join(names)}) — those validators returned no "
                f"verdict, so the file was NOT checked" + chr(10))
    line = (f"[result] {ops} {'op' if ops == 1 else 'ops'} run, "
            f"{writes} {'write' if writes == 1 else 'writes'}")
    if skipped > 0:
        line += f", {skipped} skipped"
    if rolled_back > 0:
        line += f", {rolled_back} rolled back"
    if left_on_disk > 0:
        line += f", {left_on_disk} left on disk"
    if reapplied > 0:
        line += f", {reapplied} re-applied"
    files = list(validated or ())
    if files:
        # A `validate:` op inside a batch that also mutated something. Its
        # counts have nowhere else to go — an inner op is at dispatch depth > 1
        # and never renders a footer of its own — so #990's guarantee would
        # have a hole exactly where a reader is least likely to notice it.
        line += (f", validated {len(files)} file"
                 f"{'' if len(files) == 1 else 's'} "
                 f"({sum(1 for _p, f, _nv in files if f)} with findings, "
                 f"{sum(1 for _p, _f, nv in files if nv)} not checked)")
    names = list(dict.fromkeys(not_checked or ()))
    if names:
        line += (f", {len(names)} validator{'' if len(names) == 1 else 's'} "
                 f"NOT RUN ({', '.join(names)})")
    tails = []
    if writes == 0 and left_on_disk == 0:
        # A rolled-back write is not a second application of anything, so this
        # clause wins: the bytes complained about are no longer on disk.
        #
        # Not when a create was left on disk (#1320). In a batch that both
        # reverted one write and kept a refused create, `writes` can net to zero
        # while a refused file is sitting in the tree, and "nothing changed on
        # disk" would then be flatly false about the one path the reader most
        # needs to act on.
        tails.append("nothing changed on disk")
    elif reapplied > 0:
        tails.append("an edit already present in the file was applied again")
    if rolled_back > 0:
        tails.append(
            f"{rolled_back} edit{'' if rolled_back == 1 else 's'} "
            f"{'was' if rolled_back == 1 else 'were'} reverted after "
            f"validation and did NOT land")
    if left_on_disk > 0:
        tails.append(
            f"{left_on_disk} created file{'' if left_on_disk == 1 else 's'} a "
            f"validator refused {'was' if left_on_disk == 1 else 'were'} NOT "
            f"removed and {'is' if left_on_disk == 1 else 'are'} still on disk")
    if names:
        tails.append("those validators returned no verdict, so the file was "
                     "NOT checked")
    if tails:
        line += " — " + "; ".join(tails)
    return line + "\n"


def _normalise_ws(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


def _edit_miss_diagnostic(old: str, content: str, new: str = "",
                          path: str = "") -> str:
    """Why `old` didn't match (#380).

    `ERROR: old string not found` was the whole message, so the natural next
    move was a `read` round-trip — the one the payload route exists to save.
    These are the ways a payload comes back close but not exact, ranked by how
    often each was the real cause.
    """
    hints: List[str] = []

    # 0. The replacement is ALREADY in the file — consistent with (but not
    #    proof of) a re-run of a payload that already landed. #701 covers the
    #    case where `new` contains `old` (the anchor survives and the edit
    #    applies a second time); this is the other half, where it does not,
    #    and the second run reports a bare no-match that is character-for-
    #    character what a genuinely wrong anchor prints (#984).
    #
    #    A substring search cannot tell a genuine re-run (the whole
    #    replacement sitting where the edit targeted) from a coincidental
    #    match elsewhere in the file — one relayed report found a line that
    #    merely resembled the replacement, reported it as "this looks like a
    #    re-run", and the reader concluded there was nothing to do when the
    #    anchor was in fact simply missing (#2118). The two explanations have
    #    opposite remedies — one is done, the other needs a new anchor — and
    #    stating one as settled collapses the case where the tool genuinely
    #    cannot tell.
    #
    #    A located fact, not a verdict: the ERROR stands, the exit code stands,
    #    the op is still counted as skipped. Downgrading a failure to a note
    #    because it is probably benign is how a loud bug becomes a quiet one.
    if new and new.strip() and new in content:
        at = content.count("\n", 0, content.index(new)) + 1
        hints.append(
            f"the replacement text is ALREADY present at line {at} — this "
            f"may be a re-run of an edit that already applied, but it could "
            f"also be a coincidental match; if line {at} is not where you "
            f"meant to edit, the anchor is likely just missing"
        )

    # 1. Doubled backslashes, in EITHER direction. TOML literal strings
    #    ('''...''') do not process escapes, so `\\302` in a payload is
    #    backslash-backslash-3-0-2 and can never match a file holding `\302`
    #    -- and the reverse: a file written earlier with two literal
    #    backslashes (e.g. via `literal_backslashes = true`) can never match
    #    a payload's `old` carrying one. #380 named only the first direction;
    #    the second produced a bare nearest-match percentage with no mention
    #    of backslashes at all, which is the "fails quietly" half of #985.
    if "\\\\" in old and old.replace("\\\\", "\\") in content:
        hints.append(
            "the file matches with SINGLE backslashes — TOML literal strings "
            "('''...''') do not process escapes, so `\\\\` in the payload is "
            "two literal backslashes"
        )
    elif "\\" in old and old.replace("\\", "\\\\") in content:
        hints.append(
            "the file matches with DOUBLE backslashes — TOML literal strings "
            "('''...''') do not process escapes, so a single `\\` in the "
            "payload can only match one literal backslash, not two"
        )

    lines = content.splitlines()
    if len(lines) > _EDIT_DIAG_MAX_LINES:
        return "".join(f"  {mark('↳')} {h}\n" for h in hints)

    # 2. Whitespace. Indentation drift is the other half of "close but not
    #    exact", and it is invisible in a diff read by eye.
    if not hints:
        norm_old = _normalise_ws(old)
        if norm_old and "\n" not in old.strip():
            for i, ln in enumerate(lines, 1):
                if _normalise_ws(ln) == norm_old:
                    hints.append(
                        f"line {i} matches ignoring whitespace: {ln.strip()!r} "
                        f"— check indentation"
                    )
                    break

    # 3. Nearest line. Even one line of "closest is line 142: ..." turns a
    #    three-call debug loop into one — when it is right about which line.
    if not hints:
        near = _edit_nearest_hint(old, lines, path)
        if near:
            hints.append(near)

    return "".join(f"  {mark('↳')} {h}\n" for h in hints)


# Below this the hint is withheld: not close enough to be worth a look.
_EDIT_NEAR_FLOOR = 0.6
# Two candidates within this much of each other are a tie, not a ranking. The
# run that filed #1489 got 68% twice, ~800 lines apart, and the difference
# between the two was noise the score could not carry.
_EDIT_NEAR_TIE = 0.02
# Windows char-scored per block anchor. The line-level pass ranks first and is
# O(file); this second pass is O(window²) each, so it is bounded rather than
# left to the corpus.
_EDIT_NEAR_WINDOWS = 20
# `difflib.SequenceMatcher.ratio()` is O(len(a) × len(b)), and
# `_EDIT_DIAG_MAX_LINES` bounds this scan by LINE COUNT — the one dimension a
# minified file is small in. Measured: 60 lines of 40 KB, one anchor of 39 KB,
# 220s for a SINGLE comparison and over 30 minutes for the file. Two bounds,
# because either alone leaves the other open: each comparison is clipped, and
# the total is capped in cells so a file of many long lines cannot spend the
# saving line by line.
_EDIT_NEAR_MAX_CHARS = 1000
_EDIT_NEAR_BUDGET = 20_000_000


def _nearest_clip(text: str) -> str:
    return text[:_EDIT_NEAR_MAX_CHARS]


def _nearest_line_candidates(
        needle: str,
        lines: List[str]) -> Tuple[List[Tuple[float, int]], float, bool]:
    """Every line scoring within `_EDIT_NEAR_TIE` of the best, the best, and
    whether the cost budget ran out before the file did.

    The prefilter bar is `best - tie`, not `best`: a rival that merely EQUALS
    the leader has to be computed, because withholding on a tie is the whole
    point and a skipped line cannot be seen to tie. Identical lines are scored
    once and cached — a file of repeated boilerplate is exactly the input this
    is for, and it is also the one that would otherwise re-score every line.

    An exhausted budget is returned rather than swallowed: what has been
    scored so far is a best-of-a-prefix, and reporting it as the file's
    nearest match is the confidently-wrong hint this whole function is about.
    """
    best = 0.0
    scored: List[Tuple[float, int]] = []
    seen: Dict[str, float] = {}
    needle = _nearest_clip(needle)
    spent = 0
    matcher = difflib.SequenceMatcher(a=needle, autojunk=False)
    for i, ln in enumerate(lines, 1):
        ratio = seen.get(ln)
        if ratio is None:
            bar = best - _EDIT_NEAR_TIE
            clipped = _nearest_clip(ln)
            matcher.set_seq2(clipped)
            if matcher.real_quick_ratio() < bar or matcher.quick_ratio() < bar:
                # The bar only rises, so a line hopeless now stays hopeless.
                seen[ln] = -1.0
                continue
            spent += len(needle) * len(clipped)
            if spent > _EDIT_NEAR_BUDGET:
                return [], best, True
            ratio = matcher.ratio()
            seen[ln] = ratio
        elif ratio < 0:
            continue
        if ratio > best:
            best = ratio
        scored.append((ratio, i))
    return [(r, i) for r, i in scored if r >= best - _EDIT_NEAR_TIE], best, False


def _nearest_block_candidates(
        anchor: List[str],
        lines: List[str]) -> Tuple[List[Tuple[float, int]], float, bool, int]:
    """The same, for a multi-line anchor, scored on the WHOLE block (#1489).

    Scoring the first non-blank line only — what this did until #1489 — reads
    `def handler(request):` and reports whichever copy of that boilerplate
    comes first, at a percentage that is a fact about one line of an anchor
    the caller wrote several lines of. Two passes:

    1. A sliding multiset of whitespace-normalised lines over every window of
       the anchor's height, O(file), which ranks windows by how many of the
       anchor's lines they contain at all. Order-insensitive and exact-match,
       so it locates rather than scores: a real near-miss differs in one line
       and lands at (n-1)/n while boilerplate lands far below it.
    2. The character ratio, on the top-ranked windows only, so the percentage
       printed is comparable with the single-line hint's and the second pass
       is bounded by `_EDIT_NEAR_WINDOWS` regardless of file size.
    """
    n = len(anchor)
    if n > len(lines):
        return [], 0.0, False, 0
    want: Dict[str, int] = {}
    for ln in anchor:
        key = _normalise_ws(ln)
        want[key] = want.get(key, 0) + 1
    norm = [_normalise_ws(ln) for ln in lines]
    have: Dict[str, int] = {}
    matched = 0
    best_hits = 0
    tops: List[int] = []
    top_count = 0
    for i, key in enumerate(norm):
        have[key] = have.get(key, 0) + 1
        if have[key] <= want.get(key, 0):
            matched += 1
        if i >= n:
            gone = norm[i - n]
            if have[gone] <= want.get(gone, 0):
                matched -= 1
            have[gone] -= 1
        if i < n - 1:
            continue
        start = i - n + 2  # 1-based first line of this window
        if matched > best_hits:
            best_hits, tops, top_count = matched, [start], 1
        elif matched == best_hits and matched > 0:
            top_count += 1
            if len(tops) < _EDIT_NEAR_WINDOWS:
                tops.append(start)
    if best_hits <= 0:
        # Not one line of the anchor occurs anywhere. There is no block to
        # point at, and the first line's own score has already been measured
        # to carry no information about the block — so say nothing rather
        # than name a line at a number that looks like evidence.
        return [], 0.0, False, 0
    anchor_text = _nearest_clip("\n".join(anchor))
    matcher = difflib.SequenceMatcher(a=anchor_text, autojunk=False)
    scored: List[Tuple[float, int]] = []
    best = 0.0
    spent = 0
    for start in tops:
        window = _nearest_clip("\n".join(lines[start - 1:start - 1 + n]))
        spent += len(anchor_text) * len(window)
        if spent > _EDIT_NEAR_BUDGET:
            return [], best, True, 0
        matcher.set_seq2(window)
        ratio = matcher.ratio()
        if ratio > best:
            best = ratio
        scored.append((ratio, start))
    near = [(r, i) for r, i in scored if r >= best - _EDIT_NEAR_TIE]
    # More windows tied on the line pass than were char-scored, and every one
    # that WAS scored is still tied: the tie count is a floor, and the hint
    # says "at least N". Returned as its own number rather than smuggled into
    # the candidate list as a negative line — that spelling sorted ahead of
    # every real candidate and was printed as the nearest line (PR review).
    floor = top_count if top_count > len(tops) and len(near) == len(tops) else 0
    return near, best, False, floor


def _nearest_pct(ratio: float, identical: bool) -> str:
    """The percentage, never rounded up into a claim of identity (#1855).

    `f"{r:.0%}"` renders 0.998 as `100%`, and the hint that carries it is
    printed directly under `old string not found`. Two sentences a caller
    cannot both believe: measured on a twelve-line block differing by three
    trailing spaces, `SequenceMatcher.ratio()` is 0.9976209357652657 and the
    receipt said the match was exact.

    Nothing is normalising anything -- the metric is honest and the render was
    not -- so this is fixed where the lie is made rather than in the matcher.
    A near miss reports `>99%`, which is true, is not `100%`, and cannot be
    read as "these strings are the same".
    """
    if not identical and round(ratio * 100) >= 100:
        return ">99%"
    return f"{ratio:.0%}"


def _nearest_diff_kind(anchor: List[str], window: List[str]) -> str:
    r"""Name WHAT KIND of difference the near miss is, or say nothing (#1855).

    The reported cost of the bare percentage was one extra read call spent
    finding a one-line difference the scan had already measured and thrown
    away. The caller's question is never "how close" -- it is "what do I look
    for", and the two answers below send them to different places:

    * `differs only in whitespace` -- indentation drift or a trailing space,
      invisible in a diff read by eye, and the one class where re-reading the
      file tells you nothing at all.
    * `differs in N of M lines` -- an anchor whose CONTENT is wrong, which is
      what an invented or misremembered line looks like.

    Three states, not two, and the third is the one #1855 is actually about.
    Where the compared LINES are equal the percentage is a true 100% -- and a
    bare `100%` under `old string not found` is exactly the self-contradiction
    filed. It is reachable: `splitlines()` drops line endings, and the hint
    strips blank lines off both ends of the anchor, so an anchor can be equal
    line-for-line to a window the byte comparison rejected. Saying nothing
    there would leave the reported defect alive in the one case where the
    number really is 100. So it is NAMED as what it is -- the difference is
    outside the text that was compared -- rather than left to read as identity.
    """
    if anchor == window:
        return ("identical line-for-line, so the difference is outside the "
                "compared text: blank or whitespace-only lines at the ends of "
                "`old`, or line endings")
    if [_normalise_ws(ln) for ln in anchor] == [_normalise_ws(ln) for ln in window]:
        return "differs only in whitespace"
    if len(anchor) == 1:
        # The one case where this says nothing. A single-line hint already
        # prints the file's line verbatim beside the percentage, so
        # "differs in 1 of 1 lines" is the only count arithmetic allows and
        # the reader can see the difference in the text next to it.
        return ""
    same = sum(block.size for block
               in difflib.SequenceMatcher(a=anchor, b=window,
                                          autojunk=False).get_matching_blocks())
    # Anchor lines matched NOWHERE in the window, not lines differing at their
    # own index: a one-line insertion shifts every line after it and a
    # positional count would call that eleven differences. The clamp cannot
    # fire today -- `window` is sliced to `len(anchor)`, so `same ==
    # len(anchor)` implies equality and the branch above already returned --
    # and it is kept because `differs in 0 of 12 lines` under `old string not
    # found` would be this issue again, one rewrite later.
    differing = max(1, len(anchor) - same)
    # #1794 -- naming the count still left a real case costing a second
    # round-trip: two lines that read as identical at a glance (a doubled
    # backslash escaping a quote inside a TOML literal block, invisible to
    # the eye) but differ at one byte. When exactly one line differs AND
    # the two blocks are the same height -- no insertion or deletion
    # shifted anything, so "index i in anchor" and "index i in window"
    # name the same line -- the offset of the first character where that
    # one line diverges is cheap to compute and turns "which of these 12
    # lines" into "which byte of this one line". Left unnamed when heights
    # differ: an insertion could make every positional pair after it
    # differ, and a byte offset picked from the wrong pairing would be
    # confidently wrong, which costs more than saying nothing
    # (docs/validators.md).
    if differing == 1 and len(anchor) == len(window):
        _diff_at = [i for i in range(len(anchor)) if anchor[i] != window[i]]
        if len(_diff_at) == 1:
            _i = _diff_at[0]
            _off = _first_diff_offset(anchor[_i], window[_i])
            return (f"differs in {differing} of {len(anchor)} lines -- "
                    f"first byte diverges at line {_i + 1}, offset {_off}")
    return f"differs in {differing} of {len(anchor)} lines"


def _first_diff_offset(a: str, b: str) -> int:
    """0-based UTF-8 BYTE index of the first byte where *a* and *b* diverge.

    A CHARACTER index would be wrong the moment either line holds a
    multi-byte character before the divergence point -- named as a "byte
    offset" in the hint that calls this (#1794 asked for one explicitly),
    so it has to actually be one rather than a character count that happens
    to coincide with it on ASCII, which is all the tests that shipped
    alongside the first version of this function covered.

    Where one is a prefix of the other, the divergence IS the length of the
    shorter encoded string -- the point past its last byte, which is where a
    caller re-anchoring the line would need to look. `surrogatepass` rather
    than the default strict encoder: a line read back through `read` can
    carry a lone surrogate from an upstream decode-with-replacement, and this
    is a diagnostic computing a position, not a write -- raising here would
    turn "cannot show WHERE" into "cannot show anything at all" for the one
    kind of file that most needs a byte offset instead of a character count.
    """
    ab = a.encode("utf-8", errors="surrogatepass")
    bb = b.encode("utf-8", errors="surrogatepass")
    for _idx, (_ca, _cb) in enumerate(zip(ab, bb)):
        if _ca != _cb:
            return _idx
    return min(len(ab), len(bb))


def _edit_nearest_hint(old: str, lines: List[str], path: str = "") -> str:
    """One line naming where `old` nearly matched — or that it cannot say.

    Three states, not two (docs/validators.md, "Declining instead of
    guessing"): a location, nothing at all, and `cannot suggest` when several
    places score the same. A confidently wrong line number costs more than no
    line number — the caller reads the wrong 30 lines and re-anchors against
    them — so a tie is reported as a tie rather than resolved by file order.
    """
    anchor = old.splitlines()
    while anchor and not anchor[0].strip():
        anchor.pop(0)
    while anchor and not anchor[-1].strip():
        anchor.pop()
    if not anchor:
        return ""
    if len(anchor) == 1:
        cands, best, exhausted = _nearest_line_candidates(anchor[0], lines)
        tie_floor = 0
    else:
        cands, best, exhausted, tie_floor = _nearest_block_candidates(
            anchor, lines)
    if exhausted:
        return ("cannot suggest a nearest match: comparing these lines cost "
                "more than the scan's budget, so what it had found is a "
                "best-so-far and not a best. Anchor on a shorter, more "
                "distinctive snippet")
    if not cands or best < _EDIT_NEAR_FLOOR:
        return ""
    n = len(anchor)
    cands.sort(key=lambda c: (-c[0], c[1]))
    best_i = cands[0][1]
    # Overlapping windows describe one neighbourhood, not two candidates.
    rivals = [i for _r, i in cands[1:] if abs(i - best_i) >= n]
    # `tie_floor` is its own trigger, not a modifier on `rivals` (#1614). It
    # means more windows tied on the line pass than were char-scored at all,
    # and every one that WAS scored is still tied — so the unscored ones are
    # unlocated, and the leader is one sample of a set the tool never saw. For
    # an anchor taller than `_EDIT_NEAR_WINDOWS` all 20 sampled starts sit
    # inside one `n`-line neighbourhood by construction, so `rivals` is empty
    # for arithmetic reasons and gating on it made the floor dead code for
    # exactly the long-anchor case #1489 was filed about.
    if rivals or tie_floor:
        total = tie_floor if tie_floor > 1 + len(rivals) else 1 + len(rivals)
        at_least = "at least " if total > 1 + len(rivals) else ""
        picked = ([best_i] + rivals)[:3]
        shown = ", ".join(str(i) for i in picked)
        # Against what was actually listed, not against a hardcoded 3: with
        # `rivals` empty only the leader is named, and `total - 3` then
        # undercounts the withheld places by two.
        extra = total - len(picked)
        more = f" and {extra} more" if extra > 0 else ""
        # `identical=False` unconditionally: this arm names SEVERAL places, so
        # there is no one window to be identical to, and a bare 100% here would
        # claim every one of them is the anchor.
        return (f"cannot suggest a nearest match: {at_least}{total} places "
                f"score the same ({_nearest_pct(best, False)}) — lines "
                f"{shown}{more}. The anchor does not tell them apart; "
                f"re-anchor on a longer or more distinctive block")
    # The window the percentage was computed against, so the difference can be
    # NAMED rather than left as a number the caller has to go and interpret
    # (#1855). Taken here rather than inside the scorer because the scorer
    # compares a 1000-character clip and this classification wants the whole
    # lines -- and because `identical` is what stops the render claiming 100%.
    window = lines[best_i - 1:best_i - 1 + n]
    kind = _nearest_diff_kind(anchor, window)
    pct = _nearest_pct(best, anchor == window)
    detail = f", {kind}" if kind else ""
    if n == 1:
        return (f"nearest match at line {best_i} ({pct}{_nearest_clip_note(anchor, lines, best_i, n)}{detail}): "
                f"{_elide(lines[best_i - 1], _EDIT_NEAR_MAX_CHARS)!r}")
    end = best_i + n - 1
    where = f": read:{path}:{best_i}-{end}" if path else ""
    return (f"nearest match at lines {best_i}-{end} "
            f"({pct}{_nearest_clip_note(anchor, lines, best_i, n)}{detail}){where}")


def _nearest_clip_note(anchor: List[str], lines: List[str],
                       start: int, n: int) -> str:
    """Say so when the percentage is about a prefix rather than the whole text.

    A number computed over the first 1000 characters of a 40 KB line is not
    wrong, but read as a score for the line it is a claim nobody made."""
    longest = max([len(ln) for ln in anchor]
                  + [len(ln) for ln in lines[start - 1:start - 1 + n]])
    if n > 1:
        longest = max(longest, len("\n".join(anchor)))
    if longest <= _EDIT_NEAR_MAX_CHARS:
        return ""
    return f", scored on the first {_EDIT_NEAR_MAX_CHARS} characters"
# A mutating op prints its full arguments in the section header and then the
# diff underneath, so for a content-heavy edit the old and new strings appear
# twice. Above this many characters the header is rebuilt from the parsed
# fields instead — the diff below is the useful part and already shows what
# changed. Short ops keep their verbatim header (#384).
_HEADER_ARG_MAX = 160
_HEADER_ANCHOR_MAX = 60

_SH_SUFFIXES = (".sh", ".bash", ".zsh", ".ksh")
# A run of backslashes at end of line, plus any whitespace between it and the
# newline. Two ways this is not the continuation it looks like:
#   - PARITY: bash consumes backslashes pairwise from the left, so an even run
#     is all escaped backslashes and the line genuinely ends; an odd run leaves
#     one over to continue it. Only even runs are the bug.
#   - TRAILING WHITESPACE: a backslash followed by spaces or tabs never
#     continues the line, whatever the parity — the escape applies to the
#     space. Invisible in a diff, and it silently ends a command.
_TRAILING_BACKSLASH_RUN = re.compile(r"(\\+)([ \t]*)\r?\n")

# Warnings raised at the write chokepoint, drained by dispatch onto the
# receipt. Keyed by path so a rollback can retract the warning for the
# content it just reverted — the bytes complained about are no longer on
# disk, and a warning about them would be worse than none.
_WRITE_WARNINGS: List[Tuple[str, str]] = []

# One `.py` write-chokepoint advisory per target path, seeded at PAYLOAD
# PARSE time (#2493) and consumed by `_atomic_write` the moment that exact
# path is next written. Not `_WRITE_WARNINGS` itself: that queue is DROPPED
# and re-populated by `_atomic_write` on every write to a path (see
# `_drop_write_warnings` there), which would silently discard an entry
# seeded before dispatch ever reaches the op. A separate dict, popped rather
# than read, means a write that never happens (the op errors before
# `_atomic_write`, or targets a different path than the payload named)
# leaves nothing stuck here for a later, unrelated write to inherit — the
# depth<=1 sweep in `dispatch` clears any leftover the same way
# `_PAYLOAD_WARNINGS` is drained, as a backstop against exactly that.
_PAYLOAD_PY_ESCAPE_ADVISORY: Dict[str, str] = {}

# Bumped when a mutating op RUNS, before its outcome is known — the branch
# footer's signal. A write counter cannot serve that role: `_retract_write`
# decrements on rollback and a failed edit never reaches `_atomic_write` at all,
# so keying the footer on bytes-that-landed silently drops the two cases where a
# wrong-branch hypothesis is most useful. Read once per call by dispatch; never
# decremented.
_MUTATION_ATTEMPTS: List[int] = [0]

# How the running dispatch frame separated its fields — ':::', ':', or '' when
# the fields arrived structured through a payload and nothing was tokenized.
# Read by `_resolve_custom_op`, which is several frames down and sees only the
# already-split `parts`, and exported to the preset subprocess as
# SUPERTOOL_ARG_SEP. A preset that reconstructs the caller's input for a
# refusal has to know which separator to rejoin on: git-commit rejoined on ':'
# whatever the route, so a ':::' inside a message came back as a ':' and the
# suggested repair, pasted, committed bytes the caller never wrote (#946).
_ARG_SEP: List[str] = [":"]

# Exit status of the last custom/preset op run in the current frame, or None
# when none ran. A preset writes no file through `_atomic_write`, so the write
# counter below cannot answer "did it succeed"; this is recorded at the
# subprocess rather than parsed back out of its receipt, for the same reason
# `_result_line`'s counts are.
_CUSTOM_OP_OK: List[Optional[bool]] = [None]

# One entry per preset op that answered with a declared exit value it does not
# declare clear to proceed (#1705), as "op exited N". Read by `_main` as a
# per-call delta, for the same warm-daemon reason as `_SKIP_COUNT` beside it.
# A plain list rather than a dispatch-frame accumulator: custom ops are outside
# `_PARALLEL_SAFE_OPS`, and the reader is the call's exit code rather than any
# one op's footer, so nothing here has to stay attributable to a single op.
_UNCLEAN_VALUE_EXITS: List[str] = []

# Bumped by _atomic_write. Lets dispatch ask 'did this op actually write?'
# instead of sniffing the receipt for an ERROR prefix — receipts are prose
# and not every no-op failure says ERROR (op_replace's zero-match returns
# "(0 occurrences of 'x' found)").
_WRITE_COUNT: List[int] = [0]

# Bumped where a mutating op DECLINES: it ran, it could have written, and it
# deliberately left the disk alone (#680). The third state docs/validators.md
# already defines for validators — `ok`, a finding, `skipped` — applied to the
# ops themselves.
#
# Declared at the decline, never inferred from `attempts - writes`. That
# subtraction looks equivalent and is not: a multi-file `replace` writes more
# times than it was attempted, `replace_dry` writes nothing by design, and a
# validator rollback retracts a write that was genuinely made. Each would be
# mis-reported as a decline, and a skip count that is sometimes wrong is worse
# than none — it is the same absence-read-as-fact this counter exists to stop.
_SKIP_COUNT: List[int] = [0]

# Bumped where a mutating op wrote text the file ALREADY contained at that spot
# (#701) — the fourth state, and the only one that is not a decline. See
# `_edit_already_applied` for why the test is positional rather than
# `new in content`, and `_result_line` for why it is not folded into
# `_SKIP_COUNT`. Never decremented on rollback: `_retract_write` is per-path and
# this counter is not, so a batch rollback could retract the wrong op's
# disclosure. The `writes == 0` clause in `_result_line` covers that case
# honestly instead — "nothing changed on disk" is the stronger statement.
_REAPPLY_COUNT: List[int] = [0]

# Bumped where a write is REVERTED after the fact (#952): the op matched, the
# bytes landed, a validator with `rollback_on_fail` regressed, and the previous
# content was restored. The sixth state, and the one that had no name — see
# `_result_line` for why it is neither `skipped` nor covered by `writes`.
#
# Bumped inside `_retract_write`, which is the single chokepoint both rollback
# paths (formatter and validator) already pass through. Bumping at the two call
# sites instead would make a third rollback path added later silently invisible,
# which is the shape of defect this counter exists to close.
_ROLLBACK_COUNT: List[int] = [0]

# Bumped where a mutating op CREATED a file, a validator reported a finding on
# it, and nothing undid the write (#1320). The seventh state, and the mirror
# image of `_ROLLBACK_COUNT`: same red row above, opposite outcome on disk.
#
# It is not a bug that no rollback fired. `rollback_on_fail` is per-validator
# and four of this repo's own eight set it false on purpose — `ruff`,
# `lsp-diag`, `git-status` and `changelog-fragment` are advisory, and reverting
# an author's bytes over a lint nit is the trade this repo ranks below
# misreporting. What was wrong is that the receipt for that outcome was
# byte-identical to a clean create: `[result] 1 op run, 1 write`, with the
# refused artefact sitting in the tree for `git status`, test collection and
# every later read to find (#1320).
#
# Only a create. An overwrite's leftover bytes are in a file the caller already
# owned and the `edited` line above states that truthfully; a create announced a
# path into existence that a checker then refused, and nothing else on the
# receipt says it is still there.
_LEFT_ON_DISK_COUNT: List[int] = [0]

# Validators that ran and returned no verdict about the file (#665). The state
# `skipped` covers a checker that declined before running; this covers one that
# was asked to run, could not, and had only an `adapter` error to say so with.
#
# Names, not a count, because the reader's next action is installing a tool:
# `2 validators NOT RUN` alone sends them back up to the block this footer
# exists to save them from re-reading.
#
# Appended through `_acc_not_checked()`, which routes to the running op's own
# dispatch frame and reaches this list only when the frame unwinds (#1109). So
# what accumulates here is the whole CALL, which is exactly the scope the exit
# code below wants: the warm daemon reuses the process, so `main` reads a
# per-call delta and truncates back, or one ungated edit would poison the exit
# code of every later call in the same worker (#680). The FOOTER's scope is one
# op, and it is built from the frame instead — a `len()` snapshot here was only
# ever per-op while a single op was appending, which stopped being true the day
# `validate` joined `_PARALLEL_SAFE_OPS`.
_NOT_CHECKED: List[str] = []

# One entry per file a `validate:` op rendered a block for, as
# `(path, had_finding, had_non_verdict)` — the material for the whole-run
# verdict `validate:` had no line for at all on the clean path (#990).
#
# Recorded here rather than re-derived from the rendered rows, for the reason
# `_result_line`'s counts already are: a footer parsed back out of the prose it
# is summarising can only ever agree with the prose, which is exactly the thing
# under suspicion when a reader reaches for it.
#
# Per-call, and reached through the dispatch frame, like `_NOT_CHECKED` above
# and for the same two reasons — the warm daemon reuses the process, and the
# footer's scope is one op rather than one call (#1109).
_VALIDATED_FILES: List[Tuple[str, bool, bool]] = []


def _drop_write_warnings(path: str) -> None:
    """Retract queued warnings for `path` — its write was rolled back."""
    key = os.path.abspath(path)
    _WRITE_WARNINGS[:] = [w for w in _WRITE_WARNINGS if w[0] != key]


def _retract_write(path: str) -> None:
    """A rollback reverted a write: un-count it and drop its warnings.

    Both rollback paths restore the previous bytes with a raw write that never
    reaches `_atomic_write`, so without this the op still looks like it wrote.
    That matters beyond tidiness: the compact header is gated on the counter,
    and a change that did not stick leaves no diff to read it from — the same
    reproducibility gap the header rule exists to avoid.
    """
    _drop_write_warnings(path)
    _bump_counter(_ROLLBACK_COUNT, "cnt_rollback")
    _bump_counter(_WRITE_COUNT, "cnt_write", by=-1)


def _rollback_action(pre_existed: bool, pre_content: Optional[bytes]) -> str:
    """`restore` | `unlink` | `refuse` — what undoing this write actually means.

    Three states, because the two the rollback loop used to have were "we have
    prior bytes" and "we do not", and it read the second as "there is nothing to
    do" (#1088). A created file has no prior bytes and still has an undo: unlink.
    So a `paste` of a new file whose content did not parse printed the red row,
    printed no retraction, and left the artifact — the receipt saying the write
    did not survive validation while the filesystem said it had.

    `unlink` is a delete, so it is gated on provenance rather than on the
    absence of a baseline. `pre_existed` is sampled before the op runs and is
    the only thing that can tell "a path this call brought into being" from "a
    path that was here and got overwritten". Deleting the second would turn a
    rollback into destruction of work the call never wrote, which is the one
    outcome this repository ranks below misreporting.

    The third state is the file that existed and whose bytes could not be read.
    Neither undo is available and there is no safe guess, so the caller is told
    rather than left with a silent skip that reads as "nothing needed doing".
    """
    if not pre_existed:
        return "unlink"
    if pre_content is not None:
        return "restore"
    return "refuse"


def _receipt_head(body: object) -> str:
    """The op's own success line — the first non-blank line of its receipt.

    Shared by the two markers that talk about that line rather than about the
    file: `[rolled back]` retracts it, `[left on disk]` confirms it. One
    implementation, because a filtered read has to find the same string in both
    cases and two copies of "first non-blank line" would drift.
    """
    if isinstance(body, str):
        for ln in body.splitlines():
            if ln.strip():
                return _flat_cell(ln.strip())
    return ""


def _note_left_on_disk() -> None:
    """A refused create stood. Single chokepoint for the counter (#1320).

    Separate from the renderer for the reason `_retract_write` is: a second
    disclosure path added later must not be able to print the marker without
    moving the number the footer reads.
    """
    _bump_counter(_LEFT_ON_DISK_COUNT, "cnt_left_on_disk")


def _left_on_disk_line(names: Sequence[str], path: str, body: object,
                       target: str = "") -> str:
    """`[left on disk]` — the create nothing undid, said in words (#1320).

    The mirror of `_retraction_line`, and deliberately built the same way. It
    quotes the receipt's own `created …` line back so that a filtered read which
    caught the claim catches its qualification adjacent to it — an agent greps
    for `created|ERROR`, and "created, and a checker refused it, and it is still
    there" arrived as three lines that shared no token.

    It CONFIRMS rather than retracts, which is the whole distinction from the
    rollback marker: the file exists, the path is real, and the reader's next
    action is to delete or fix it rather than to re-run the write.

    Why this is not solved by turning `rollback_on_fail` on everywhere: four of
    this repo's eight validators set it false on purpose. `ruff` and `lsp-diag`
    are advisory about style and semantics, `git-status` is not about the file's
    content at all, and `changelog-fragment` refuses shapes an author routinely
    iterates on. Unlinking there would trade a misreport for the destruction of
    a write the caller asked for — the one outcome ranked below misreporting.

    Symlink-aware for the same reason `_retraction_line` is (#1136): the write
    landed on the target, so that is the path still holding the refused bytes.
    """
    head = _receipt_head(body)
    quoted = f' — confirms "{head}"' if head else ""
    subject = _flat_cell(path)
    via = ""
    if target and os.path.abspath(target) != os.path.abspath(path):
        subject = _flat_cell(target)
        via = (f" ({_flat_cell(path)} is a symlink, so the write landed on its "
               f"target and that is the file still holding these bytes)")
    who = ", ".join(_flat_cell(n) for n in names)
    return (f"[left on disk] {who} reported a finding on {subject}, and no "
            f"validator that found something sets rollback_on_fail, so nothing "
            f"undid the write{via}{quoted}; the created file is STILL THERE — "
            f"delete it or fix it before the next read")


def _retraction_line(name: str, verb: str, path: str, body: object,
                     created: bool = False, target: str = "") -> str:
    """Retract a receipt's own success line where a FILTERED read will see it.

    `[rolled back] <tool> regressed; file restored` shares no token with the
    `edited <file> (line N)` printed above it, so `grep -E 'edited|ERROR'` —
    the reported way this output is read — returned the claim and not the undo
    (#952). Quoting the retracted line back means any filter that caught the
    claim catches the retraction, adjacent to it and in the same stream
    position.

    Deliberately NOT by suppressing the claim. An absent line makes "written,
    then reverted" indistinguishable from "never ran", which is the same
    absence-read-as-fact defect wearing different clothes.

    Separator-agnostic: the path is echoed as the op received it, so a Windows
    `pkg\\x.py` renders as the caller typed it. Both interpolated strings go
    through `_flat_cell` because this is a column-0 marker line — the rule
    docs/validators.md states for `[validators]` rows applies verbatim here,
    and a path is attacker-influenceable input.

    Plain double quotes rather than `repr()` around the retracted line: repr
    doubles every backslash, so a Windows receipt would retract
    `'edited pkg\\\\x.py (line 2)'` — text that no longer matches the line it
    is retracting, which defeats the whole point of quoting it.
    """
    head = _receipt_head(body)
    quoted = f' — retracts "{head}"' if head else ""
    # `removed` / `NOT created` on the create path (#1088). "restored" names an
    # earlier state, and a file this call brought into being has none — a reader
    # deciding what to do next needs to know the path is now absent, not that it
    # went back to something.
    undo = "removed" if created else "restored"
    tail = "created" if created else "edited"
    # A write through a symlink lands on the target, so the undo does too
    # (#1136). Saying "link.py removed" was true only while the rollback was
    # deleting the wrong object; now that it deletes the right one, the same
    # sentence would tell a reader their symlink is gone when it is intact.
    subject = _flat_cell(path)
    via = ""
    if target and os.path.abspath(target) != os.path.abspath(path):
        subject = _flat_cell(target)
        via = (f" ({_flat_cell(path)} is a symlink, so the write landed on its "
               f"target and that is what was undone; the link is intact)")
    return (f"[rolled back] {name} {verb}; {subject} {undo}{via}{quoted}"
            f"; the file was NOT {tail}")


def _elide(s: str, limit: int) -> str:
    """One-line, length-capped rendering of an op argument for a header.

    Reports the elided character count rather than trailing off — a silent
    truncation reads as "that was the whole argument".
    """
    s = s.replace("\r\n", "⏎").replace("\n", "⏎")
    if len(s) <= limit:
        return s
    return f"{s[:limit]}… (+{len(s) - limit} chars)"


def _commit_header_arg(parts: List[str]) -> str:
    """`git-commit`'s header, for a commit that LANDED (#946, #1235).

    Here the argument is also the artifact: after a successful commit
    `git log -1` hands the message back, so replaying it above a receipt
    whose whole job is to prove the commit landed is a second copy of
    something already retrievable. Commit messages in this repo are long by
    convention, so that echo routinely outweighs the receipt it introduces.

    Success only, and that is the point rather than a detail. On a refusal
    nothing was committed and this header is the ONLY surviving copy of a
    message the caller composed — eliding it there would cause precisely the
    loss #1235 was filed about. The swap in `_dispatch_impl` is gated on the
    op having succeeded for that reason.

    Subject plus a body line COUNT, never a body sample. A sample reads as
    the message and is not; the count is what tells the reader the tool
    received the lines they sent, which is the whole job of an echo.
    """
    msg = parts[1] if len(parts) > 1 else ""
    paths = [p for p in parts[2:] if p]
    # CRLF normalised first: `split` on the newline alone leaves a trailing
    # CR on every line, and `_elide` only collapses the pair — so a message
    # composed on Windows would put a stray CR inside the quoted subject.
    lines = msg.replace(chr(13) + chr(10), chr(10)).split(chr(10))
    out = 'git-commit: "' + _elide(lines[0], _HEADER_ANCHOR_MAX) + '"'
    if len(lines) > 1:
        out += f" +{len(lines) - 1} more message lines"
    if paths:
        out += (f" → {len(paths)} path(s): "
                + _elide(", ".join(paths), _HEADER_ANCHOR_MAX))
    else:
        out += " → no paths (commits the index)"
    return out


def _compact_header_arg(op: str, parts: List[str], sep: str = ":") -> str:
    """Identifying header for a content-heavy mutating op, or "" to keep the
    verbatim one. Each op keeps whatever identifies the *target* — path, line
    range, anchor — and drops the content the diff is about to show anyway.

    *sep* is how this call's fields were split. It gates `git-commit` only:
    under single-colon tokenization `parts[1]` is a fragment of the message
    rather than the message, so a summary built from it would state a subject
    the caller never wrote.
    """
    def _p(i: int) -> str:
        return parts[i] if len(parts) > i else ""

    if op == "git-commit":
        return _commit_header_arg(parts) if sep == ":::" else ""
    if op in ("edit", "replace", "replace_dry"):
        return f'{op}: "{_elide(_p(1), _HEADER_ANCHOR_MAX)}" → {_p(3)}'
    if op == "replace_lines":
        return f"{op}: {_p(1)} lines {_p(2)}-{_p(3)}"
    if op in ("paste", "append"):
        content = ":".join(parts[2:])
        return f"{op}: {_p(1)} ({len(content)} chars)"
    if op == "vim":
        return f"{op}: {_p(1)} {_elide(':'.join(parts[2:]), _HEADER_ANCHOR_MAX)}"
    return ""


def _payload_header_arg(op: str, target: str) -> str:
    """Header for a sub-op that arrived through an @payload, not the colon CLI.

    A batch sub-op used to be echoed back as its fields joined on ':'. The
    payload route exists *because* the content contains ':', so that join does
    not merely lose information — it produces a string that parses as a
    DIFFERENT op. `replace` on `time: 10:30` rendered as

        --- replace:time: 10:30:time: 11:45:/tmp/h.txt ---

    which, pasted back, sends the dispatcher looking for a file named `30`.
    A header is the thing a reader trusts to reconstruct what happened, and in
    a bug report it is often the only surviving record. Inviting them to run an
    op that touches a path nobody named is worse than telling them nothing.

    So this does not attempt a faithful one-line colon rendering — for a
    payload op there isn't one. It names the ROUTE and the TARGET, which is
    what identifies the step, and the `@payload` reference does not resolve to
    a file, so pasting it fails loudly instead of quietly doing something else.
    That is the invariant: a header must never be a runnable string that runs
    something other than what ran; if it cannot be re-runnable it must not look
    re-runnable. Same family as #621 — output presenting itself as a faithful
    account of an operation and not being one. #644.
    """
    return f"{op}:@payload" + (f" → {target}" if target else "")


# Positional colon-argument order for batch sub-ops that have no @payload
# route of their own. Ordering here mirrors the `syntax` strings in
# .supertool.json.
#
# A single-argument op does not need an entry to be ORDERED — but it needs one
# to be CHECKED. Without it the fallback below places whichever lone key the
# payload happened to carry, under no name at all, so a wrong field name is
# indistinguishable from the right one (#1407). Declare the single field
# wherever getting the name wrong produces a plausible-looking run rather than
# an obvious failure.
_BATCH_POSITIONAL_FIELDS: Dict[str, Tuple[str, ...]] = {
    "head":        ("path", "n"),
    "tail":        ("path", "n"),
    "tree":        ("path", "depth"),
    "around_line": ("path", "line", "n"),
    "diff":        ("path1", "path2"),
    # `batch` takes one argument, so the single-field fallback below would have
    # placed it — but that fallback places whatever key happens to be there,
    # under no name. `file = "inner.toml"` therefore ran as `batch:inner.toml`
    # and was refused for the missing `@`, never for the wrong field (#1407).
    # Declaring the single field turns the key itself into something that can
    # be checked.
    "batch":       ("path",),
}


def _ordered_batch_fields(op: str, item: Dict[str, Any]) -> Tuple[List[str], str]:
    """Positional colon fields for a batch sub-op with no @payload route.

    Returns (fields, error) — exactly one is non-empty.

    This replaces `sorted(item)`, which ordered the payload's fields
    ALPHABETICALLY and is not any op's argument order. That was not a header
    defect: it is the arg that gets dispatched. `{"op": "tree", "path": "src/",
    "depth": 2}` ran as `tree:2:src/`, and `between` with `symbol` + `path` ran
    as `between:<path>:<symbol>` — silently searching for the file inside the
    symbol name.

    Where the order is declared it is used; where it is not, this declines
    rather than inventing one. Guessing is how the original defect happened.
    #644.
    """
    lower = {str(k).lower(): v for k, v in item.items() if str(k).lower() != "op"}
    if not lower:
        return [], ""
    order = _BATCH_POSITIONAL_FIELDS.get(op)
    if order is None:
        if len(lower) == 1:
            return [str(next(iter(lower.values())))], ""
        return [], (
            f"ERROR: batch sub-op '{op}' takes its arguments positionally and has "
            f"no declared payload field order, so {_flat_keys(sorted(lower))} "
            f"cannot be placed. Ordering them alphabetically is a guess, and a "
            f"wrong guess dispatches a different op — so this declines instead. "
            f"Use the colon form for '{op}', or an op with an @payload route.\n"
        )
    unknown = sorted(k for k in lower if k not in order)
    if unknown:
        return [], (
            f"ERROR: unknown field(s) {_flat_keys(unknown)} in batch '{op}' "
            f"— accepted: {', '.join(order)}\n"
        )
    fields: List[str] = []
    for name in order:
        if name not in lower:
            break
        fields.append(str(lower[name]))
    skipped = [n for n in order[len(fields):] if n in lower]
    if skipped:
        return [], (
            f"ERROR: batch '{op}' payload sets {', '.join(skipped)} without the "
            f"earlier positional field(s) {', '.join(order[len(fields):order.index(skipped[0])] or order[:1])} "
            f"— colon arguments cannot be sparse.\n"
        )
    return fields, ""


def _sh_backslash_warning(path: str, content: str) -> str:
    """Flag `\\\\` at end-of-line in a shell script (#380).

    The trap is that getting the escaping wrong does not always fail to match —
    sometimes it writes. `FOO=$(cmd \\\\` + newline is syntactically valid bash
    (an escaped backslash, then a new command), passes `bash -n`, passes the
    bash-check validator, and does something entirely different from what was
    meant. The validator cannot see it; only the byte pattern can.
    """
    if not path.endswith(_SH_SUFFIXES):
        return ""
    trailing_ws = False
    even_run = False
    for m in _TRAILING_BACKSLASH_RUN.finditer(content):
        if m.group(2):
            trailing_ws = True
        elif len(m.group(1)) % 2 == 0:
            even_run = True
    if not (trailing_ws or even_run):
        return ""
    if trailing_ws and not even_run:
        return (
            f"{mark('⚠')} {path}: a line ends with a backslash followed by "
            f"whitespace. That is not a line continuation — the backslash "
            f"escapes the space, the command ends there, and the difference "
            f"is invisible in a diff.\n"
        )
    return (
        f"{mark('⚠')} {path}: a line ends with `\\\\`. In bash that is an "
        f"escaped backslash, not a line continuation — it parses cleanly and "
        f"runs differently. This is a note and not a refusal: these bytes "
        f"have no second spelling here, so blocking them would strand the "
        f"caller who meant them. A literal payload block refuses the same "
        f"pattern, because there a second spelling exists (#835).\n"
    )


def _edit_already_applied(content: str, old: str, new: str, idx: int) -> bool:
    """Is the `old` at `idx` sitting INSIDE text this same edit already made?

    The re-run case (#701): `new` contains `old`, so the anchor survives its own
    edit and matches again on a second run. `content[idx:idx+len(old)]` is then
    literally a substring of an occurrence of `new` that a previous run wrote.

    Positional containment, not `new in content`. The issue floated the simpler
    test and it has a real failure mode: `new` may legitimately pre-exist
    somewhere unrelated (an edit inserting `return None` into a file that
    already has a `return None` elsewhere), and a signal that fires on a first
    application is noise — which is how a footer count stops being read. Asking
    instead whether the anchor being replaced is bracketed by an existing copy
    of `new` is the literal statement "this edit's result is already here".

    Deliberately says nothing about intent. An append of a second repeated
    element is indistinguishable from an accidental re-run and must stay
    allowed; the caller decides, the tool discloses.
    """
    if len(new) <= len(old) or old not in new:
        return False
    end = idx + len(old)
    j = content.find(new)
    while j != -1 and j <= idx:
        if end <= j + len(new):
            return True
        j = content.find(new, j + 1)
    return False


def _count_already_applied(content: str, old: str, new: str) -> int:
    """`replace`'s own version of `_edit_already_applied` (#938), batched.

    `op_edit` only ever has ONE occurrence of `old` in play — more than one
    is refused as ambiguous before this code runs — so a `content.find(new)`
    scan per call was a single O(n) pass. `replace` is replace-all by design
    and can have many occurrences of `old` in one file; calling
    `_edit_already_applied` once per occurrence repeats that O(n) scan for
    EVERY occurrence, which is O(n·m) over a file with m occurrences of a
    short `old` — quadratic in the file's own size once occurrence count
    scales with it, and paid even on a plain first application, since the
    O(n) part runs before the function can tell there is nothing to find.

    Same positional-containment test, answered once per file instead of once
    per occurrence: every occurrence of `old` and every occurrence of `new`
    are each found in one linear pass (`str.find` in a loop, not the
    windowed scan a naive re-implementation would reach for), then `bisect`
    answers "is there a `new` occurrence starting in
    `[old_end - len(new), old_idx]`" — the same interval
    `_edit_already_applied` searches by hand — in O(log k) against the
    ascending list, k being how many times `new` already occurs. Total cost
    O(n + m·log k), not O(n·m).
    """
    if len(new) <= len(old) or old not in new:
        return 0
    old_idxs: List[int] = []
    start = 0
    while True:
        idx = content.find(old, start)
        if idx == -1:
            break
        old_idxs.append(idx)
        start = idx + len(old)
    if not old_idxs:
        return 0
    new_idxs: List[int] = []
    start = 0
    while True:
        idx = content.find(new, start)
        if idx == -1:
            break
        new_idxs.append(idx)
        start = idx + 1
    if not new_idxs:
        return 0
    count = 0
    for old_idx in old_idxs:
        lo = old_idx + len(old) - len(new)
        # The rightmost `new` occurrence at or before `old_idx` is the
        # strongest candidate — a later start covers further right for the
        # same length — so only that one needs checking; if it clears `lo`
        # it satisfies both ends of the interval `_edit_already_applied`
        # searches by hand, and if it does not, no earlier one (a smaller
        # start, the same length) can either.
        pos = bisect.bisect_right(new_idxs, old_idx) - 1
        if pos >= 0 and new_idxs[pos] >= lo:
            count += 1
    return count




def _newline_census(text: str) -> Tuple[int, int, int]:
    """`(crlf, lf, cr)` — how many of each line ending the text actually has.

    Bare counts, not a verdict. Callers that need one say in their own receipt
    what they did with it; nothing here decides on their behalf (#1049).
    """
    crlf = text.count("\r\n")
    lf = text.count("\n") - crlf
    cr = text.count("\r") - crlf
    return crlf, lf, cr


def _newline_used(text: str) -> str:
    """The ending convention a block carries, CRLF-first, "" if it carries none.

    CRLF-first because a block holding both is a caller's own mixture written
    verbatim, and naming the two-byte ending is the one that cannot be read as
    a bare LF.
    """
    for nl in ("\r\n", "\r", "\n"):
        if nl in text:
            return nl
    return ""


def _newline_note(content: str, wrote: str = "", retermed: bool = False) -> str:
    """One receipt line, emitted only where the ending used had more than one
    defensible answer.

    `content` is the file **as it will be on disk** — not as it was found.
    Asking the pre-write bytes meant the mixed branch below could only fire on
    a file that was *already* mixed, so a write that CREATED the mixedness
    reached nothing and shipped in silence (#1075). The census printed with it
    describes the file that now exists, which is the one the reader is about to
    open.

    `wrote` is the convention the op used for text it supplied, "" when it
    supplied none. `retermed` says that text was the *caller's own*, rewritten
    to match the file.

    The first cut of this fired on every successful edit of a CRLF file — where
    nothing had been decided, every byte outside the match was unchanged, and
    the line said so at length. On Windows every file is CRLF, so a marker
    meaning "I made a choice you did not" appeared on every call ever made,
    which is how a disclosure becomes noise and then becomes ignored. It also
    collided with `test_successful_edit_has_no_diagnostic`, which reads `↳` as
    "a diagnostic was emitted" and was right to.

    So: a mixed file has no single answer and is always disclosed; re-writing
    the caller's own endings is always disclosed; supplying a trailing newline
    in the one convention a uniform file uses is not a choice and is silent.
    """
    if not wrote:
        return ""
    names = {"\r\n": "CRLF", "\n": "LF", "\r": "CR"}
    name = names.get(wrote, repr(wrote))
    crlf, lf, cr = _newline_census(content)
    if len([n for n in (crlf, lf, cr) if n]) > 1:
        return (f"  {mark('↳')} line endings: file is mixed ({crlf} CRLF / "
                f"{lf} LF / {cr} CR) — every line this op did not touch kept "
                f"its own; text this op supplied uses {name}\n")
    if not retermed:
        return ""
    return (f"  {mark('↳')} line endings: file is {name}, so the text you "
            f"wrote with LF was re-terminated to {name} to match — every "
            f"untouched line is unchanged\n")


def _newline_variants(text: str) -> List[Tuple[str, str]]:
    """`(newline, text)` candidates for a match, most faithful first.

    A caller composing a payload types LF, so an `old` string describing lines
    of a CRLF file arrives LF-terminated and matches nothing once the read
    stops flattening the file. Refusing there would trade a silent whole-file
    rewrite for a hard `old string not found` — a different bug, not a fix. The
    literal text is therefore tried first and the re-terminated forms only
    after it, so a file that matches exactly is never reinterpreted.
    """
    flat = text.replace("\r\n", "\n").replace("\r", "\n")
    out: List[Tuple[str, str]] = [("", text)]
    for nl in ("\r\n", "\r", "\n"):
        cand = flat.replace("\n", nl)
        if cand != text:
            out.append((nl, cand))
    return out


def _retermed(text: str, nl: str) -> str:
    """`text` with every line ending replaced by `nl`."""
    return text.replace("\r\n", "\n").replace("\r", "\n").replace("\n", nl)


def _line_number_at(text: str, end: Optional[int] = None) -> int:
    """1-based line number of position `end`, counting CR, LF and CRLF alike.

    `text.count("\\n")` is zero at *every* position in a CR-only file, so a
    receipt built on it named line 1 wherever the match actually was. That
    arithmetic was correct only because the read used to translate `\\r` to
    `\\n` before it ran; `newline=""` removed the translation and left the
    count behind (PR #1057 review).

    Counted rather than sliced: `count` takes a range, so this stays
    allocation-free on the dry-run path that calls it once per match.
    """
    return (text.count("\n", 0, end)
            + text.count("\r", 0, end)
            - text.count("\r\n", 0, end)) + 1


def _local_newline(lines: List[str], idx: int) -> str:
    """The line ending in force at `lines[idx]`, scanning backwards for one.

    A mixed file has no single answer, so `replace_lines` does not vote on the
    whole file: the block it writes takes the ending of the line it replaces
    (or, for an insert, of the line above it). A file-wide majority would
    rewrite the caller's own line to the other convention, which is the same
    silent normalisation one line wide.

    The backwards scan is the answer whenever it finds one. When it does not —
    `idx` is at or past the only terminated line, or every line above it is
    unterminated — the search continues *forwards* over the whole file, so a
    file whose endings all sit below `idx` still gets its own convention.
    Falls back to LF only when no line anywhere in the file is terminated.
    """
    for i in range(min(idx, len(lines) - 1), -1, -1):
        line = lines[i]
        for nl in ("\r\n", "\r", "\n"):
            if line.endswith(nl):
                return nl
    for line in lines:
        for nl in ("\r\n", "\r", "\n"):
            if line.endswith(nl):
                return nl
    return "\n"


def op_edit(old: str, new: str, path: str) -> str:
    """Single-file, single-occurrence edit — mirrors native Edit semantics.

    Errors on 0 or >1 matches. For replace_all, use the `replace` op.
    Returns a receipt with ±2 lines of context around the change.
    """
    if not old:
        return "ERROR: empty old string\n"
    if old == new:
        return "ERROR: old and new strings are identical\n"
    if not path:
        return "ERROR: empty path\n"
    if not os.path.isfile(path):
        # Through the shared helper, not a bare f-string. Until #1334 this arm
        # printed the path and nothing else, so `edit` had neither the `tried:`
        # line #1300 added nor the cwd-drift branch — the two things that make
        # naming a creating op safe rather than a guess.
        return _path_not_found(path, label="file", op="edit", creates=True)

    try:
        # surrogateescape: lone bytes that aren't valid UTF-8 round-trip via
        # _atomic_write back to their original byte values. Prevents silent
        # corruption of bytes outside the match window (CVE-class data loss
        # on files with mixed encodings or partial binary content).
        # newline="": no universal-newline translation, so a CRLF file is not
        # silently rewritten to LF throughout — the contract op_append already
        # states. Without it a one-line edit changed every line in the file,
        # under a receipt that named one (#1049).
        with open(path, "r", encoding="utf-8", errors="surrogateescape",
                  newline="") as f:
            content = f.read()
    except OSError as e:
        return f"ERROR: failed to read {path}: {e}\n"

    wrote = ""
    count = content.count(old)
    if count == 0:
        for nl, cand in _newline_variants(old)[1:]:
            n = content.count(cand)
            if n:
                old, new, wrote, count = cand, _retermed(new, nl), nl, n
                break
    if count == 0:
        _bump_counter(_SKIP_COUNT, "cnt_skip")
        return (f"ERROR: old string not found in {path}\n"
                + _edit_miss_diagnostic(old, content, new, path))
    if count > 1:
        _bump_counter(_SKIP_COUNT, "cnt_skip")
        return (
            f"ERROR: old string found {count} times in {path} — ambiguous. "
            f"Use a larger snippet to make it unique, or use replace for "
            f"replace_all semantics.\n"
        )

    retermed = bool(wrote)
    if not wrote and ("\n" in new or "\r" in new):
        # `old` matched literally, so nothing above resolved a convention --
        # but `new` carries one of its own, and writing it verbatim splices LF
        # into a CRLF file and leaves it mixed, silently.
        #
        # The defect this closes is an inconsistency, not just a silence: an
        # `old` that spanned a line boundary went through `_newline_variants`
        # and had `new` re-terminated with whatever matched, while a
        # single-line `old` did not. Two edits expressing the same intent
        # produced different bytes depending on that accident (PR #1057
        # review). Only reachable since this branch stopped flattening every
        # write to LF, which is why it is this branch's regression to fix.
        crlf, lf, cr = _newline_census(content)
        used = [n for n, c in (("\r\n", crlf), ("\n", lf), ("\r", cr)) if c]
        if len(used) == 1 and _retermed(new, used[0]) != new:
            # One convention, and `new` disagrees: match the file and say so.
            # This is the caller's own text rewritten, which `_newline_note`
            # promises is never silent.
            new, wrote, retermed = _retermed(new, used[0]), used[0], True
        elif len(used) > 1:
            # Mixed: no single convention to match, so the caller's bytes stand
            # as typed -- the same answer `replace_lines` gives. Still a
            # decision, and `_newline_note`'s mixed branch discloses it.
            wrote = _newline_used(new)

    idx = content.index(old)
    reapplied = _edit_already_applied(content, old, new, idx)

    new_content = content.replace(old, new, 1)
    try:
        _atomic_write(path, new_content)
    except OSError as e:
        return f"ERROR: failed to write {path}: {e}\n"

    if reapplied:
        _bump_counter(_REAPPLY_COUNT, "cnt_reapply")

    # Receipt — locate the change and show ±2 lines context
    start_line = _line_number_at(content, idx)
    # `_line_number_at` counts LF/CR/CRLF; the receipt's own line list has to
    # count the same ones or the context block is indexed against a numbering
    # the `line N` above it was never built from (#1060).
    new_lines = _split_lines(new_content)
    new_block_line_count = _line_number_at(new)
    end_line = start_line + new_block_line_count - 1
    ctx_start = max(1, start_line - 2)
    ctx_end = min(len(new_lines), end_line + 2)

    # The path is flattened for the same reason the op header above it is
    # (#1019): this line is the receipt's own success claim, and a name
    # carrying a line separator put `[rolled back] …` at column 0 underneath
    # it — a retraction the reader's anchored grep believes, for a file that
    # was in fact written. Disclosed, never stripped: `_flat_field` leaves the
    # name readable in full so the operator can still go and look at it.
    out = [f"edited {_flat_field(path, disclose_newline=True)} (line {start_line}"]
    if end_line != start_line:
        out.append(f"-{end_line}")
    out.append(")\n")
    _nl_note = _newline_note(new_content, wrote, retermed=retermed)
    if _nl_note:
        out.append(_nl_note)
    # Attached to the claim it qualifies, not only to the footer: `edited a.py
    # (line 2-3)` is a true sentence that reads as a first application, and the
    # reader who is about to trust it is looking here. The footer carries the
    # same signal for the reader who is piping to `tail` (#621).
    if reapplied:
        out.append(
            f"  {mark('↳')} re-applied: the text this edit produces was already "
            f"present around the anchor — this is a SECOND application, not a "
            f"repeat of the first\n"
        )
    for ln in range(ctx_start, ctx_end + 1):
        marker = "→" if start_line <= ln <= end_line else " "
        out.append(f"  {ln:>5} {marker} {new_lines[ln - 1]}\n")
    return "".join(out)


def op_json_set(path: str, fields: Dict[str, Any]) -> str:
    """Set one or more fields in a JSON file by dotted key path, in one write
    (#1822).

    Closes the gap between `paste` (whole file) and `edit` (exact-string,
    single occurrence): a JSON report with ~100 fields where 8 changed had
    no proportional route — every re-send was the full 22 KB. This op takes
    a small `fields` mapping (`{"tests.green.result": "..."}`) and does the
    whole-file work internally: parse, set each leaf on the in-memory
    document, re-serialize.

    Never guesses at structure. Three refusals, none of them silent:
      - the file does not parse as JSON at all — this is not a text patch,
        it needs a real document to walk;
      - a dotted path's leading segment does not resolve to an existing
        object — `json-set` sets fields, it does not fabricate the objects
        that would contain them (use `paste` for a new structure);
      - a value TOML can produce that JSON cannot represent (a date/time
        literal) — refused before anything is written, not coerced.

    Because the write is always a full valid re-serialization of a
    document this function itself parsed, a well-formed call cannot land
    syntactically invalid JSON on disk — unlike `edit`/`vim`'s raw text
    patches, which is why `edit` needs the same-shape rollback guarantee
    and this op inherits it structurally. It is still routed through
    `_run_with_validators`/`jsonlint` (`rollback_on_fail: true`) like every
    other write op, so a validator this repo has not yet configured — a
    schema check, say — gets the identical safety net for free.
    """
    if not path:
        return "ERROR: empty path\n"
    if not fields:
        return "ERROR: empty set — nothing to change\n"
    if not os.path.isfile(path):
        return _path_not_found(path, label="file", op="json-set")
    try:
        with open(path, "r", encoding="utf-8") as f:
            raw = f.read()
    except OSError as e:
        return f"ERROR: failed to read {path}: {e}\n"
    try:
        doc = json.loads(raw)
    except json.JSONDecodeError as e:
        return (f"ERROR: {path} does not parse as JSON — json-set refuses to "
                f"guess at a document it cannot read: {e}\n")
    if not isinstance(doc, dict):
        return (f"ERROR: {path}'s top level is a {type(doc).__name__}, not a "
                f"JSON object — json-set only sets fields inside an object\n")

    changes: List[Tuple[str, bool, Any, Any]] = []
    for dotted_key, new_value in fields.items():
        if not isinstance(dotted_key, str) or not dotted_key:
            return (f"ERROR: json-set field name must be a non-empty string, "
                     f"got {dotted_key!r}\n")
        segs = dotted_key.split(".")
        if any(not s for s in segs):
            return (f"ERROR: {dotted_key!r} is not a valid dotted field path "
                     f"(empty segment)\n")
        cur: Any = doc
        walked: List[str] = []
        for seg in segs[:-1]:
            if not isinstance(cur, dict) or seg not in cur:
                return (
                    f"ERROR: {dotted_key!r} — "
                    f"{'.'.join(walked + [seg])} does not exist in {path}; "
                    f"json-set will not create missing intermediate objects. "
                    f"Use paste for a new structure.\n"
                )
            cur = cur[seg]
            walked.append(seg)
        leaf = segs[-1]
        if not isinstance(cur, dict):
            return (
                f"ERROR: {dotted_key!r} — {'.'.join(walked) or '(top level)'} "
                f"in {path} is a {type(cur).__name__}, not an object; cannot "
                f"set a field inside it\n"
            )
        existed = leaf in cur
        old_value = cur.get(leaf)
        cur[leaf] = new_value
        changes.append((dotted_key, existed, old_value, new_value))

    try:
        new_content = json.dumps(doc, indent=2, ensure_ascii=False) + "\n"
    except (TypeError, ValueError) as e:
        return f"ERROR: a value for json-set is not JSON-serializable: {e}\n"

    try:
        _atomic_write(path, new_content)
    except OSError as e:
        return f"ERROR: failed to write {path}: {e}\n"

    out = [f"set {len(changes)} field(s) in "
           f"{_flat_field(path, disclose_newline=True)}\n"]
    for dotted_key, existed, old_value, new_value in changes:
        verb = "changed" if existed else "added"
        old_disp = json.dumps(old_value) if existed else "(absent)"
        new_disp = json.dumps(new_value)
        out.append(f"  {dotted_key}: {old_disp} -> {new_disp} ({verb})\n")
    return "".join(out)


_PASTE_BACKUP_KIND = "paste-backup"

# A copy on every overwrite is a resource claim, so it is bounded — and the
# bound is NOT the trigger #1650 argued about. It does not decide whether the
# outgoing bytes are worth keeping; it decides how much disk supertool is
# willing to spend keeping them. Which is exactly why crossing it is said out
# loud in the receipt: it lands on the largest files, where the loss is worst,
# and an unbacked overwrite that reads like a backed one is this repo's
# recurring defect. 8 MB clears every text file this tool is aimed at —
# `_supertool.py` is 1.2 MB and `CHANGELOG.md` 1.8 MB, the two largest files
# in this tree.
_PASTE_BACKUP_MAX_BYTES = 8 * 1024 * 1024


def _paste_snapshot(path: str, new_content: str) -> Tuple[str, str]:
    """Copy `path`'s current bytes aside before `paste` replaces them (#1650).

    Returns `(snapshot_path, why_not)` — three states, not two. `("/x", "")`
    the bytes are kept and here is where; `("", "")` there was nothing to keep,
    because the file already holds exactly what is about to be written; and
    `("", why)` the copy could not be made, which the receipt has to say out
    loud. A store that fails silently is this repo's recurring defect wearing a
    backup's clothes.

    Why a copy and not a refusal. `paste` over an existing file is documented,
    ordinary and usually right, so a guard that stops it has to offer a `force`
    token, and a `force` token that gets typed by reflex is the guard deleting
    itself (the `misdirects` class). A copy refuses nothing, so there is no
    case it was not written for: the write the caller asked for happens either
    way, and the only cost of a false positive is one reaped cache file.

    Why `paste` alone. Every other mutating op fails on a path that is not
    there: `edit` and `replace` match a string, and `vim` and `replace_lines`
    both return `file not found`. Only `paste` succeeds either way. That is the
    whole of the claim — NOT that nothing else destroys bytes, because plenty
    does: `vim` empties a file completely with `ggdG`, and `replace_lines`
    clamps an end of `total + 1` rather than refusing it, so `1:total+1` takes
    the file down to one block. What none of them can do is destroy a file the
    caller believes is not there, and that belief is the #1642 mechanism: 8922
    bytes overwritten by an agent creating what it thought was a new note.

    Why no size threshold. #1650 proposes a shrink ratio or a byte-loss floor.
    Both are blind to 8922 bytes replaced by 9000 different ones, which loses
    just as much. `paste` replaces the entire file by definition, so the
    trigger is the op's own semantics and there is no number to tune.
    """
    try:
        with open(path, "rb") as fh:
            old = fh.read()
    except OSError as e:
        return "", f"could not read the outgoing bytes ({type(e).__name__})"
    if old == new_content.encode("utf-8", errors="surrogateescape"):
        # Nothing is lost, so nothing is stored, and the receipt stays quiet.
        return "", ""
    if len(old) > _PASTE_BACKUP_MAX_BYTES:
        return "", (
            f"{len(old)} bytes is over the {_PASTE_BACKUP_MAX_BYTES}-byte "
            f"copy limit"
        )
    # The mode the copy has to land at, decided BEFORE the store is touched
    # (#1685). A bare `open(dest, "wb")` writes at `0666 & ~umask` — 0644 on a
    # stock box — whatever the source was, so a `paste` over a 0600 `.env`,
    # `id_rsa` or `.netrc` left the secret group- and world-readable under
    # `~/.cache/supertool` for the whole seven-day retention window. The copy
    # is not redacted, correctly, because it is a backup; what has to hold is
    # that reading the copy is no easier than reading the original.
    #
    # Three states, not two. A mode that could not be read is not a mode of
    # 0644: the fallback is owner-only, which is never wider than whatever the
    # source turns out to have been. The opposite trade — declining to snapshot
    # a mode-restricted file — would close the disclosure by deleting the
    # data-loss net #1650 exists to be, which is choosing a different failure
    # rather than removing one.
    try:
        snap_mode = stat.S_IMODE(os.stat(path).st_mode)
    except OSError:
        snap_mode = 0o600
    store = _cache_root() / _PASTE_BACKUP_KIND
    # Flat, and a regular file: `_gc_sweep_kind` is non-recursive and unlinks
    # nothing else, so a snapshot in a subdirectory would be counted `skipped`
    # forever — a reaped-looking store that only grows.
    dest = store / "{}-{}.bak".format(
        hashlib.sha1(
            os.path.abspath(path).encode("utf-8", errors="surrogateescape")
        ).hexdigest()[:16],
        time.time_ns(),
    )
    # `mkdir(exist_ok=True)` succeeds on a symlink that points at a directory,
    # and the write that follows lands wherever it points. The `time_ns()` leaf
    # is unpredictable, so nobody can name the file in advance — but the
    # directory is a fixed name under a shared cache root, so one planted
    # symlink redirects every later snapshot. Refused out loud rather than
    # followed, which keeps it a declared `why_not` instead of a copy the
    # receipt claims is somewhere it is not.
    #
    # This defends the leaf only. A symlink at `_cache_root()` itself, or the
    # `XDG_CACHE_HOME` read that chooses it with no shape check, is the same
    # class one level up and is deliberately not fixed here (#1685 item 2).
    if store.is_symlink():
        return "", f"{store} is a symlink, not a directory"
    # That check alone is check-then-act, so it is the message and not the
    # guarantee: where the platform has them, the store is then *opened* with
    # O_DIRECTORY | O_NOFOLLOW and the leaf is created relative to that
    # descriptor, which refuses a symlink swapped in after the check rather
    # than resolving through it. Windows has neither, and no POSIX mode bits
    # to disclose either, so it keeps the path-based open.
    use_dir_fd = hasattr(os, "O_DIRECTORY") and os.open in os.supports_dir_fd
    dir_fd = None
    try:
        store.mkdir(parents=True, exist_ok=True)
        if use_dir_fd:
            dir_fd = os.open(
                str(store), os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW
            )
        # os.open, not open(): the mode has to be on the file from the moment
        # it exists rather than chmod-ed onto it a syscall later, or the bytes
        # are world-readable for that window. O_EXCL so an existing leaf is
        # never written through, O_NOFOLLOW so a symlink at the leaf is not
        # either, and O_BINARY because on Windows a text-mode fd would rewrite
        # every LF in the backup — a copy that does not match what it copied.
        flags = (
            os.O_WRONLY | os.O_CREAT | os.O_EXCL
            | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_BINARY", 0)
        )
        fd = os.open(
            dest.name if dir_fd is not None else str(dest),
            flags,
            snap_mode,
            dir_fd=dir_fd,
        )
        with os.fdopen(fd, "wb") as fh:
            # The umask subtracts from the mode passed to os.open, so a 0640
            # source under a 0022 umask would land at 0620 — narrower, but a
            # different fact from the one the receipt states. On the open
            # descriptor and before the bytes, never `os.chmod(dest, ...)`
            # after the handle is closed: a chmod by path re-resolves the name
            # and would hand back the symlink window O_NOFOLLOW just shut.
            if hasattr(os, "fchmod"):
                os.fchmod(fh.fileno(), snap_mode)
            fh.write(old)
    except OSError as e:
        return "", f"{store} is not writable ({type(e).__name__})"
    finally:
        if dir_fd is not None:
            os.close(dir_fd)
    return str(dest), ""


def _snapshot_mode_suffix(snapshot: str) -> str:
    """What the receipt says about the mode of a `paste` snapshot (#1685).

    `_created_mode_note` states the mode of a file `paste` has just created,
    because that is a new fact about a new file. This is the other half and it
    is a weaker claim: the snapshot is a copy of bytes the caller already owns,
    so the mode is not news — what is news is that a second copy of those bytes
    now exists somewhere else, and whether reading it is any easier than
    reading the original. So it rides on the line that already names the copy
    rather than taking one of its own.

    Read back off disk, never from the mode that was requested: `os.open`'s
    mode argument is subtracted by the umask, and a receipt that quoted the
    request would be stating a permission the file may not have. If the stat
    fails the suffix is empty — the copy exists and its mode is unknown, and
    there is no fact to disclose. Nothing is printed on Windows, for the same
    reason `_created_mode_note` prints nothing there: `st_mode` reads back
    0o666 whatever was asked for.
    """
    if os.name == "nt":
        return ""
    try:
        mode = stat.S_IMODE(os.stat(snapshot).st_mode)
    except OSError:
        return ""
    return " (mode {0:04o}, the file's own)".format(mode)


def _created_mode_note(path: str, content: str) -> str:
    """What `paste` says about the mode of a file it has just created (#1275).

    It states the mode and stops there. `paste` does NOT infer the executable
    bit — not from the shebang, not from the modes of the file's neighbours,
    not from an `+x` flag — because each of those is a guess whose wrong answer
    is silent in one direction and destructive in the other: an inferred `+x`
    on a payload-written file is a permission nobody asked for, and a missing
    one is a script that does not run. Disclosure has no wrong answer, and the
    caller already knows which of the two they wrote.

    What it does add, for the case that produced the issue, is the fact and the
    one command: content beginning `#!` is a script, and a script without an
    executable bit is a broken artefact whose first symptom arrives after the
    merge. Naming `chmod +x` is not inference — the mode on disk is unchanged
    either way.

    **Nothing is printed on Windows.** There is no executable bit there and
    `os.chmod` honours only the read-only flag, so `st_mode` reads back 0o666
    whatever was asked for. A mode line would be noise at best and a false
    statement about the file's access at worst.
    """
    if os.name == "nt":
        return ""
    try:
        mode = stat.S_IMODE(os.stat(path).st_mode)
    except OSError:
        # The write succeeded and the stat did not, so the mode is unknown.
        # Saying nothing is right here: this note exists to disclose a fact,
        # and there is no fact to disclose.
        return ""
    note = "  ↳ mode {0:04o}, from the process umask\n".format(mode)
    if content.startswith("#!") and not (mode & 0o111):
        note += (
            "  ↳ starts with `#!` but is not executable — "
            "`chmod +x {0}` to run it\n".format(path)
        )
    return note


def op_paste(path: str, content: str) -> str:
    """Replace entire file with content. Atomic. Creates file (and parent dirs)
    if missing.

    Overwriting an EXISTING file copies its outgoing bytes to
    `~/.cache/supertool/paste-backup/` first and names the copy in the receipt
    — see `_paste_snapshot` for why that is a copy and not a refusal (#1650).
    The copy carries the source's own mode, so a 0600 file does not get a
    world-readable backup, and the receipt states the mode it landed at
    (#1685).

    Use for full-file rewrites — no vim macro gymnastics, no `:r` insert-after
    off-by-one cuts (e.g. `<?php` eaten), no `:::` separator abuse. CONTENT
    arrives via triple-colon separator so it can hold any chars (`:`, quotes,
    braces, newlines).
    """
    if not path:
        return "ERROR: empty path\n"
    # Containment check BEFORE makedirs — otherwise a path like
    # `../../tmp/evil/foo` would create directories outside cwd before
    # _atomic_write's own _safe_path check rejects the write itself.
    try:
        safe_resolved = _safe_path(path)
    except SecurityError as e:
        return f"ERROR: {e}\n"
    parent = os.path.dirname(safe_resolved)
    if parent and not os.path.isdir(parent):
        try:
            os.makedirs(parent, exist_ok=True)
        except OSError as e:
            return f"ERROR: failed to create parent dir {parent}: {e}\n"
    # Ensure trailing newline (POSIX text files)
    if content and not content.endswith("\n"):
        content += "\n"
    existed = os.path.isfile(path)
    old_size = os.path.getsize(path) if existed else 0
    # Snapshot BEFORE the write, because the receipt cannot help after it
    # (#1650). A create has no prior bytes, so it pays nothing.
    snapshot_note = ""
    if existed and old_size > 0:
        snap, why = _paste_snapshot(path, content)
        if snap:
            snapshot_note = (
                f"  ↳ previous contents kept at {snap}"
                + _snapshot_mode_suffix(snap)
                + "\n"
            )
        elif why:
            snapshot_note = (
                f"  ↳ no backup of the previous contents — {why}\n"
            )
    try:
        _atomic_write(path, content)
    except OSError as e:
        return f"ERROR: failed to write {path}: {e}\n"
    new_size = len(content.encode("utf-8"))
    new_lines = content.count("\n")
    verb = "rewrote" if existed else "created"
    return (
        f"{verb} {path} ({new_lines} lines, {old_size} → {new_size} bytes)\n"
        + snapshot_note
        + ("" if existed else _created_mode_note(path, content))
    )


_APPEND_RECEIPT_LINES = 10


def op_append(path: str, content: str) -> str:
    """Append content to the end of a file. Atomic. Creates it if missing.

    Appending used to need two calls: `wc:PATH` to learn the line count, then
    `replace_lines` with `start = N+1, end = N` — the inverted-range insert
    form. That is a round-trip spent computing an argument, and `887:886` reads
    like a typo to whoever reviews the command later.

    A file whose last line has no trailing newline gets one first, so the
    appended block always starts on its own line; the receipt says so, since
    silently touching a byte the caller did not ask about is worth a word.
    """
    if not path:
        return "ERROR: empty path\n"
    if not content:
        return "ERROR: empty content — nothing to append\n"
    # Containment check BEFORE makedirs, same ordering as op_paste: a path like
    # `../../tmp/evil/foo` must not create directories outside cwd.
    try:
        safe_resolved = _safe_path(path)
    except SecurityError as e:
        return f"ERROR: {e}\n"
    if os.path.isdir(path):
        # Explicit, unlike op_paste which lets _atomic_write's OSError surface.
        # `append` is the op most likely to be aimed at a directory by mistake
        # — a notes/ or logs/ path with the filename left off — and saying so
        # beats an mkstemp errno.
        return f"ERROR: {path} is a directory\n"
    parent = os.path.dirname(safe_resolved)
    if parent and not os.path.isdir(parent):
        try:
            os.makedirs(parent, exist_ok=True)
        except OSError as e:
            return f"ERROR: failed to create parent dir {parent}: {e}\n"

    existed = os.path.isfile(path)
    orig = ""
    if existed:
        try:
            # surrogateescape: lone non-UTF-8 bytes round-trip through
            # _atomic_write instead of being mangled to U+FFFD — same contract
            # as op_edit / op_replace_lines.
            # newline="": no universal-newline translation, so a CRLF file is
            # not silently rewritten to LF throughout. An append touches the
            # end of the file; every other byte must come back out unchanged.
            with open(path, "r", encoding="utf-8", errors="surrogateescape",
                      newline="") as f:
                orig = f.read()
        except OSError as e:
            return f"ERROR: failed to read {path}: {e}\n"

    # The file's own convention, scanned backwards from EOF -- the same
    # `_local_newline` helper `replace_lines` uses for the terminator it has
    # to invent (#1073/#1075). Falls back to LF when the file does not exist
    # or has no terminated line to read a convention off.
    orig_lines = _split_lines_keepends(orig) if orig else []
    conv = _local_newline(orig_lines, len(orig_lines) - 1) if orig_lines else "\n"

    newline_hint = ""
    if orig and not orig.endswith(("\n", "\r")):
        # Match the file's own convention rather than imposing a file-wide
        # majority guess -- same helper as above, so this and the block's own
        # invented terminator never disagree.
        orig += conv
        newline_hint = " [added the missing trailing newline first]"

    # The caller's own text goes in verbatim, endings and all -- rewriting an
    # explicit choice would be the same silent normalisation pointed the other
    # way (see `replace_lines`'s identical contract). The one ending this op
    # *invents* is the trailing one, when content carries none at all; that
    # takes the file's convention, not a hardcoded LF (#1085).
    block = content if content.endswith(("\n", "\r")) else content + conv

    old_size = len(orig.encode("utf-8", errors="surrogateescape")) if existed else 0
    new_content = orig + block
    try:
        _atomic_write(path, new_content)
    except OSError as e:
        return f"ERROR: failed to write {path}: {e}\n"

    all_lines = _split_lines(new_content)
    # Not `block.count("\n")`: that undercounts (or zeroes) whenever `block`
    # is terminated with the file's own CR-only convention -- a leftover from
    # when this was always LF-terminated, so counting "\n" was always exact.
    # `_split_lines_keepends` is the same line definition the receipt below
    # and `all_lines` above are already built from (#1085).
    added = len(_split_lines_keepends(block))
    start_line = len(all_lines) - added + 1
    new_size = len(new_content.encode("utf-8", errors="surrogateescape"))
    verb = "appended to" if existed else "created"
    out = [
        f"{verb} {path}: {added} lines at {start_line}-{len(all_lines)} "
        f"({old_size} → {new_size} bytes){newline_hint}\n"
    ]
    # Computed from the file as written, not as it was found -- the same
    # post-write basis #1075 fixed `replace_lines` onto, and for the same
    # reason: the pre-write bytes can never show mixedness this write itself
    # created (#1085).
    _nl_note = _newline_note(new_content, _newline_used(block))
    if _nl_note:
        out.append(_nl_note)
    if not existed:
        # `append` is the other op that brings a file into existence, so the
        # umask default of #1275 reaches it through the same chokepoint — and
        # a widening nobody is told about is the exact shape that fix removes.
        # Disclosed here rather than only in `paste`.
        out.append(_created_mode_note(path, new_content))
    # Receipt shows 2 lines of preceding context so the caller can see what the
    # block landed after, then the block itself — capped, because append is the
    # op you reach for with a long changelog entry and echoing it back in full
    # is pure token cost on content the caller already had.
    ctx_start = max(1, start_line - 2)
    shown_end = min(len(all_lines), start_line + _APPEND_RECEIPT_LINES - 1)
    for ln in range(ctx_start, shown_end + 1):
        marker = "→" if ln >= start_line else " "
        out.append(f"  {ln:>5} {marker} {all_lines[ln - 1]}\n")
    if shown_end < len(all_lines):
        out.append(f"  … (+{len(all_lines) - shown_end} more appended lines)\n")
    return "".join(out)


def op_replace_lines(path: str, start: int, end: int, content: str) -> str:
    """Replace lines [start, end] (1-indexed, inclusive) with content.

    Modes (all via the same op):
      insert  — end < start (e.g. 42:41) inserts CONTENT before line `start`
      replace — end >= start, swap range with CONTENT
      delete  — empty CONTENT, removes lines in range

    Returns receipt with new line numbers + ±2 context.
    """
    if not path:
        return "ERROR: empty path\n"
    if not os.path.isfile(path):
        return _path_not_found(path, label="file", op="replace_lines",
                               creates=True)
    if start < 1:
        return f"ERROR: start ({start}) must be >= 1\n"
    if end < 0:
        return f"ERROR: end ({end}) must be >= 0\n"

    try:
        # surrogateescape (not 'replace'): round-trip lone non-UTF-8 bytes
        # via _atomic_write. 'replace' would silently mutate them to U+FFFD
        # in untouched regions — same bug fix as op_edit / op_replace.
        # newline="": the lines this op does not name must come back out byte
        # for byte, CRLF included (#1049).
        with open(path, "r", encoding="utf-8", errors="surrogateescape",
                  newline="") as f:
            orig = f.read()
    except OSError as e:
        return f"ERROR: failed to read {path}: {e}\n"

    # The shared definition (#1060): `str.splitlines` breaks on eight more
    # characters than the byte-level split `read` renders with, so a file
    # holding one of them was numbered one way for the reader and another way
    # for this write. Both sides go through `_split_lines_keepends` now.
    orig_lines = _split_lines_keepends(orig)
    total = len(orig_lines)

    if start > total + 1:
        return f"ERROR: start ({start}) > file length ({total}) + 1\n"

    insert_only = end < start
    # Off-by-one autocorrect: END == total + 1 — Kevin guessed line count, clearly
    # meant "through EOF". Clamp + flag in receipt. END > total+1 = real mistake.
    clamped_hint = ""
    if not insert_only and end == total + 1:
        clamped_hint = f" [autocorrect: end ({end}) clamped to file length ({total})]"
        end = total
    if not insert_only and end > total:
        return f"ERROR: end ({end}) > file length ({total})\n"

    # The caller's content goes in verbatim, mixed endings and all: the
    # endings inside the block they typed are their choice, and rewriting an
    # explicit choice is the same silent normalisation #1049 is about pointed
    # the other way. `test_mixed_line_endings_preserved` states this contract
    # and predates the issue.
    #
    # The one ending this op has to *invent* is the trailing one, when the
    # block does not end a line at all. That takes the ending of the line it
    # lands on — not LF and not a file-wide majority, which on a mixed file
    # would rewrite the caller's own line to the other convention.
    block_nl = _local_newline(orig_lines, start - 1)
    new_block = content
    if new_block and not new_block.endswith(("\n", "\r")):
        new_block += block_nl
    new_block_lines = _split_lines_keepends(new_block) if new_block else []

    if insert_only:
        before = orig_lines[: start - 1]
        after = orig_lines[start - 1:]
        removed = 0
    else:
        before = orig_lines[: start - 1]
        after = orig_lines[end:]
        removed = end - start + 1

    new_lines = before + new_block_lines + after
    new_content = "".join(new_lines)
    try:
        _atomic_write(path, new_content)
    except OSError as e:
        return f"ERROR: failed to write {path}: {e}\n"

    added = len(new_block_lines)
    new_start = start
    new_end = start + added - 1 if added > 0 else start - 1

    if added == 0:
        verb = f"deleted lines {start}-{end}"
    elif insert_only:
        verb = f"inserted {added} lines before line {start}"
    else:
        verb = f"replaced lines {start}-{end} with lines {new_start}-{new_end}"
    out = [f"{verb} in {path} (Δ {added - removed:+d}){clamped_hint}\n"]
    # The block as written, not merely the ending this op had to invent: a
    # block that already ended a line invented nothing, left `wrote` empty, and
    # short-circuited the note before it ever reached the census — the same
    # mixed file under the same silence (#1075).
    _nl_note = _newline_note(new_content,
                             _newline_used(new_block) if added else "")
    if _nl_note:
        out.append(_nl_note)

    ctx_start = max(1, new_start - 2)
    ctx_end = min(len(new_lines), max(new_end, new_start) + 2)
    for ln in range(ctx_start, ctx_end + 1):
        marker = "→" if added > 0 and new_start <= ln <= new_end else " "
        # rstrip("\r\n"), not rstrip("\n"): on a CRLF file the latter leaves
        # the carriage return inside the receipt, shipping a stray CR into the
        # caller's terminal and logs on every context line (PR #1057 review).
        text = new_lines[ln - 1].rstrip("\r\n")
        out.append(f"  {ln:>5} {marker} {text}\n")
    return "".join(out)














